-- Coach-quality Spanish instructions (Cleaned)
UPDATE public.exercises SET instructions_es = 'Recostate en el suelo y fijá los pies con las rodillas flexionadas.\nColocá las manos detrás o a los lados de la cabeza en la posición inicial.\nFlexioná la cadera y la columna para elevar el torso hacia las rodillas.\nSubí hasta que el torso quede perpendicular al suelo y bajá solo tres cuartas partes del recorrido.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = '3/4 Sit-Up';
UPDATE public.exercises SET instructions_es = 'Recostate boca arriba con una pierna totalmente extendida.\nFlexioná la cadera y la rodilla de la otra pierna a 90 grados como posición inicial.\nExtendé la pierna hacia arriba, hacé una breve pausa y volvé a la posición inicial.\nRepetí de 10 a 20 repeticiones y cambiá de pierna.' WHERE name_en = '90/90 Hamstring';
UPDATE public.exercises SET instructions_es = 'Seleccioná un peso liviano, sentate en la máquina de abdominales, ubicá los pies bajo los rodillos y sujetá los agarres superiores con los brazos a 90 grados.\nFlexioná el torso y elevá las piernas al mismo tiempo de forma lenta y controlada mientras exhalás.\nHacé una pausa de un segundo y volvé lentamente a la posición inicial mientras inhalás.\nRepetí el movimiento durante la cantidad de repeticiones indicadas.' WHERE name_en = 'Ab Crunch Machine';
UPDATE public.exercises SET instructions_es = 'Agarrá la rueda abdominal con ambas manos y apoyá las rodillas en el suelo.\nApoyá la rueda frente a vos en la posición inicial.\nRodá lentamente hacia adelante extendiendo el cuerpo sin tocar el suelo e inhalá.\nPausá un segundo y volvé a la posición inicial contrayendo el abdomen mientras exhalás.' WHERE name_en = 'Ab Roller';
UPDATE public.exercises SET instructions_es = 'Recostate boca abajo con una pierna sobre el rodillo de espuma.\nGirá la pierna para apoyar la cara interna del muslo sobre el rodillo y descargá peso sobre él.\nDeslizá el rodillo entre la cadera y la rodilla manteniendo los puntos de tensión entre 10 y 30 segundos, luego repetí con la otra pierna.' WHERE name_en = 'Adductor';
UPDATE public.exercises SET instructions_es = 'Recostate boca arriba con las piernas elevadas hacia el techo.\nPedile a tu compañero que sostenga tus tobillos y abrí las piernas al máximo en la posición inicial.\nApretá las piernas hacia adentro durante 10 segundos mientras tu compañero genera resistencia.\nRelajá los músculos mientras tu compañero abre tus piernas para profundizar el estiramiento de forma segura.' WHERE name_en = 'Adductor/Groin';
UPDATE public.exercises SET instructions_es = 'Llevá la pesa rusa por encima de la cabeza con un brazo totalmente extendido.\nGirá los pies a 45 grados en dirección opuesta, colocá el otro brazo detrás de la espalda y empujá la cadera hacia el lado de la pesa.\nBajá el torso lo más que puedas manteniendo el brazo bloqueado arriba.\nHacé una pausa de un segundo y volvé a la posición inicial.' WHERE name_en = 'Advanced Kettlebell Windmill';
UPDATE public.exercises SET instructions_es = 'Recostate boca arriba con la zona lumbar apoyada, las manos al lado de la cabeza y los hombros elevados.\nFlexioná las rodillas a 90 grados dejando las pantorrillas paralelas al suelo.\nPedaleá extendiendo la pierna derecha mientras llevás el codo derecho hacia la rodilla izquierda y exhalás.\nInhalá al volver levemente al centro.\nGirá al lado opuesto llevando el codo izquierdo hacia la rodilla derecha y exhalá.\nContinuá alternando lados hasta completar las repeticiones indicadas.' WHERE name_en = 'Air Bike';
UPDATE public.exercises SET instructions_es = 'Colocate en cuadrupedia, levantá una pierna del suelo y sujetá el pie con la mano.\nMantené la rodilla completamente flexionada sujetando el pie o tobillo para estirar cuádriceps y flexores de cadera.\nEmpujá la cadera hacia el suelo extendiéndola bien. Mantené la posición entre 10 y 20 segundos y cambiá de lado.' WHERE name_en = 'All Fours Quad Stretch';
UPDATE public.exercises SET instructions_es = 'Parate erguido con una mancuerna en cada mano a los lados del cuerpo y los codos pegados al torso.\nOrientá las palmas hacia tu cuerpo para fijar la posición inicial.\nSin mover la parte superior del brazo, flexioná el codo derecho al exhalar y subí la mancuerna hasta la altura del hombro apretando el bíceps un segundo.\nBajá la mancuerna lentamente a la posición inicial mientras inhalás.\nRepetí el movimiento con el brazo izquierdo para completar una repetición.\nContinuá alternando lados hasta completar las repeticiones indicadas.' WHERE name_en = 'Alternate Hammer Curl';
UPDATE public.exercises SET instructions_es = 'Acostate boca arriba con las rodillas flexionadas, los pies apoyados a la anchura de los hombros y los brazos extendidos a los lados.\nElevá e incliná el torso hacia la derecha hasta tocar el talón derecho con la mano mientras exhalás y mantené la contracción un segundo.\nVolvé lentamente a la posición inicial mientras inhalás.\nElevá e incliná el torso hacia la izquierda hasta tocar el talón izquierdo exhalando, y volvé a la posición inicial inhalando para completar una repetición.\nContinuá alternando lados hasta terminar la serie de repeticiones.' WHERE name_en = 'Alternate Heel Touchers';
UPDATE public.exercises SET instructions_es = 'Sentate en un banco inclinado sosteniendo una mancuerna en cada mano con los brazos extendidos y codos pegados al torso.\nSin mover la parte superior del brazo, flexioná el codo derecho mientras girás la palma hacia arriba y exhalás hasta llevar la mancuerna al hombro.\nBajá la mancuerna lentamente a la posición inicial mientras inhalás.\nRepetí el movimiento con el brazo izquierdo para completar una repetición.\nContinuá alternando brazos hasta finalizar las repeticiones recomendadas.' WHERE name_en = 'Alternate Incline Dumbbell Curl';
UPDATE public.exercises SET instructions_es = 'Ubicate de pie con un pie ligeramente por delante del otro.\nEmpujá con la pierna delantera elevando la rodilla opuesta lo más alto posible antes de aterrizar en un salto lateral.\nBuscá cubrir la mayor distancia lateral posible en cada salto.\nRepetí la secuencia iniciando con la otra pierna.' WHERE name_en = 'Alternate Leg Diagonal Bound';
UPDATE public.exercises SET instructions_es = 'Colocá las poleas en la parte inferior de la torre y seleccioná el peso adecuado.\nSujetá los agarres a la altura de los hombros con las palmas mirando hacia adelante.\nMantené la cabeza y el pecho erguidos, y extendé un codo para empujar el agarre por encima de la cabeza.\nHacé una pausa arriba, volvé a la posición inicial y repetí con el otro lado.' WHERE name_en = 'Alternating Cable Shoulder Press';
UPDATE public.exercises SET instructions_es = 'Parate erguido sosteniendo una mancuerna en cada mano a los lados del cuerpo.\nCon los codos ligeramente flexionados, elevá las mancuernas hacia el frente hasta la altura de los hombros sin balancear el cuerpo.\nBajá las mancuernas a la posición inicial.\nEn la siguiente repetición, elevá las mancuernas de manera lateral hasta la altura de los hombros.\nVolvé a la posición inicial y continuá alternando elevaciones frontales y laterales.' WHERE name_en = 'Alternating Deltoid Raise';
UPDATE public.exercises SET instructions_es = 'Acostate boca arriba en el suelo con dos pesas rusas al lado de tus hombros.\nAcomodá una pesa rusa sobre tu pecho y después la otra, sujetándolas por la manija con las palmas mirando hacia adelante.\nExtendé ambos brazos manteniendo las pesas rusas arriba del pecho.\nBajá una pesa rusa hacia tu pecho mientras girás la muñeca hacia el brazo extendido.\nEmpujá la pesa rusa hacia arriba y repetí el movimiento con el lado opuesto.' WHERE name_en = 'Alternating Floor Press';
UPDATE public.exercises SET instructions_es = 'Colocá dos pesas rusas entre tus pies. Llevá la cadera hacia atrás y mirá hacia el frente para la posición inicial.\nCargá una pesa rusa al hombro extendiendo piernas y cadera mientras girás la muñeca. Mantené la otra pesa colgada al costado.\nBajá la pesa rusa a la posición inicial y cargá la pesa del otro lado. Repetí el movimiento.' WHERE name_en = 'Alternating Hang Clean';
UPDATE public.exercises SET instructions_es = 'Cargá dos pesas rusas a los hombros extendiendo piernas y cadera mientras girás las muñecas.\nEmpujá una pesa hacia arriba extendiendo el codo y girá la palma hacia adelante. Mantené la otra pesa inmóvil en el hombro.\nBajá la pesa a la posición inicial y empujá inmediatamente con el otro brazo.' WHERE name_en = 'Alternating Kettlebell Press';
UPDATE public.exercises SET instructions_es = 'Colocá dos pesas rusas delante de tus pies. Flexioná levemente las rodillas, llevá la cadera bien atrás y tomá ambas pesas por las manijas.\nRemá una pesa rusa hacia tu abdomen o costillas flexionando el codo y retrayendo la escápula. Sostené la otra pesa en el suelo.\nBajá la pesa al suelo y repetí el movimiento con el otro brazo.' WHERE name_en = 'Alternating Kettlebell Row';
UPDATE public.exercises SET instructions_es = 'Colocá dos pesas rusas en el suelo al ancho de hombros. Ponete en posición de flexión de brazos, apoyando las manos en las manijas y manteniendo el cuerpo recto. Separá los pies si necesitás más estabilidad.\nEmpujá una pesa contra el suelo y remá la otra hacia tu costado, flexionando el codo y retrayendo la escápula.\nBajá la pesa al suelo y repetí el remo con el brazo opuesto. Repetí durante varias repeticiones.' WHERE name_en = 'Alternating Renegade Row';
UPDATE public.exercises SET instructions_es = 'Sostenete de un objeto firme como una jaula de sentadillas.\nLevantá la pierna derecha a unos centímetros del suelo y dibujá un círculo grande en el aire con el dedo gordo. Respirá con normalidad durante el movimiento. Cada círculo equivale a una repetición.\nAl terminar con la pierna derecha, repetí el ejercicio con la pierna izquierda.' WHERE name_en = 'Ankle Circles';
UPDATE public.exercises SET instructions_es = 'Acostate boca arriba, flexioná las rodillas y apoyá los pies en el suelo.\nApoyá el tobillo de un pie sobre la rodilla opuesta.\nAgarrá el muslo o la rodilla de la pierna de apoyo y llevá ambas piernas hacia el pecho. Relajá el cuello y los hombros. Mantené de 10 a 20 segundos y cambiá de lado.' WHERE name_en = 'Ankle On The Knee';
UPDATE public.exercises SET instructions_es = 'Sentate en el suelo con las piernas flexionadas y los pies apoyados.\nUsá un rodillo de masaje para presionar los músculos laterales de la tibia. Deslizalo desde abajo de la rodilla hasta arriba del tobillo, haciendo pausas de 10 a 30 segundos en los puntos de tensión. Repetí en la otra pierna.' WHERE name_en = 'Anterior Tibialis-SMR';
UPDATE public.exercises SET instructions_es = 'Ubicá una barra en el suelo detrás de la cabecera de un banco inclinado.\nAcostate boca abajo en el banco. Tomá la barra con agarre en pronación, flexioná los codos en curl invertido y llevá la barra cerca del pecho para la posición inicial.\nEmpujá la barra hacia adelante por encima de la cabeza extendiendo los codos. Mantené los brazos paralelos al suelo durante todo el movimiento.\nVolvé a la posición inicial y repetí hasta completar la serie.' WHERE name_en = 'Anti-Gravity Press';
UPDATE public.exercises SET instructions_es = 'Parate derecho y extendé los brazos hacia los costados.\nMantené los brazos paralelos al suelo y perpendiculares al torso. Esta es la posición inicial.\nHacé círculos de unos 30 centímetros de diámetro con cada brazo extendido. Respirá con normalidad durante el movimiento.\nMantené el movimiento circular durante diez segundos. Invertí el sentido del giro hacia el lado opuesto.' WHERE name_en = 'Arm Circles';
UPDATE public.exercises SET instructions_es = 'Sentate en un banco con respaldo y sostené dos mancuernas a la altura del pecho. Mantené las palmas mirando hacia tu cuerpo, los codos flexionados y los brazos pegados al torso. Esta es la posición inicial.\nSubí las mancuernas rotando las palmas hacia adelante.\nContinuá elevando las mancuernas hasta extender los brazos sobre la cabeza. Exhalá al subir.\nPausá un segundo arriba y bajá las mancuernas a la posición inicial rotando las palmas hacia vos. Inhalá al bajar.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'Arnold Dumbbell Press';
UPDATE public.exercises SET instructions_es = 'Acostate en un banco plano sosteniendo una mancuerna en cada mano con las palmas hacia el techo. Mantené los brazos paralelos al suelo, pegados a los muslos y con los codos ligeramente flexionados. Esta es la posición inicial.\nMové las mancuernas formando un semicírculo hasta llevarlas por encima de la cabeza. Mantené los brazos paralelos al suelo en todo momento. Inhalá al realizar el movimiento.\nInvertí el movimiento para volver a la posición inicial mientras exhalás.' WHERE name_en = 'Around The Worlds';
UPDATE public.exercises SET instructions_es = 'Este ejercicio fortalece la levantada de piedra Atlas utilizando una barra cargada o caño pesado.\nCargá el peso deseado en la barra. Ubicate sobre la barra, abrazá el peso y flexioná las caderas.\nLevantá el peso superando las rodillas extendiendo las caderas. Apoyá el peso sobre los muslos, sentate levemente y abrazalo fuerte contra el pecho.\nFinalizá el movimiento extendiendo caderas y rodillas para elevar el peso lo más alto posible. Volvé a apoyar el peso en los muslos o en el suelo para las siguientes repeticiones.' WHERE name_en = 'Atlas Stone Trainer';
UPDATE public.exercises SET instructions_es = 'Ubicá la piedra Atlas entre tus pies. Flexioná las caderas para rodear la piedra verticalmente con los brazos e intentá meter los dedos por debajo.\nPegá la piedra al torso y empujá con los talones para despegarla del suelo.\nCuando la piedra supere las rodillas, apoyala sobre los muslos sentándote hacia atrás.\nSentate bien bajo, subí la piedra al pecho y acomodá el agarre por encima. Ponete de pie extendiendo las caderas, acercate a la plataforma y llevá la cadera hacia adelante para elevar la piedra lo más alto posible.' WHERE name_en = 'Atlas Stones';
UPDATE public.exercises SET instructions_es = 'Acercate a la barra hasta que quede centrada sobre tus pies, separados al ancho de caderas. Flexioná las caderas y agarrá la barra al ancho de hombros con agarre mixto o prono.\nInhalá profundo, bajá las caderas y flexioná las rodillas hasta que las espinillas toquen la barra. Mantené la mirada al frente, el pecho arriba, la espalda neutra y empujá con los talones para subir la barra.\nCuando la barra supere las rodillas, tirá hacia atrás y juntá las escápulas mientras llevás las caderas hacia la barra.\nBajá la barra flexionando las caderas y guiándola de forma controlada hacia el suelo.' WHERE name_en = 'Axle Deadlift';
UPDATE public.exercises SET instructions_es = 'Enganchá una banda de resistencia a un poste fijo o rack de sentadillas.\nAgarrá las manijas y da unos pasos hacia atrás para generar tensión en la banda.\nExtendé los brazos hacia adelante a la altura del pecho, paralelos al suelo. Separá los pies al ancho de hombros. Esta es la posición inicial.\nExhalá y abrí los brazos hacia los costados y hacia atrás. Mantené los brazos extendidos y paralelos al suelo hasta llegar a los costados.\nPausá un segundo e inhalá mientras volvés a la posición inicial.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'Back Flyes - With Bands';
UPDATE public.exercises SET instructions_es = 'Cargá el trineo con el peso deseado y enganchá una soga o correas para sujetarlo.\nArrancá el ejercicio caminando hacia atrás. Incliná el torso hacia atrás y realizá pasos cortos y explosivos para moverte lo más rápido posible.' WHERE name_en = 'Backward Drag';
UPDATE public.exercises SET instructions_es = 'Hacé este ejercicio con un compañero o lanzá la pelota contra una pared.\nParate a unos metros de tu compañero, ambos mirando en la misma dirección, con la pelota entre las piernas.\nHacé una sentadilla, empujá con fuerza hacia arriba y lanzá la pelota por encima de tu cabeza hacia tu compañero.\nPedile que te la devuelva rodando y repetí las repeticiones deseadas.' WHERE name_en = 'Backward Medicine Ball Throw';
UPDATE public.exercises SET instructions_es = 'Ubicá una tabla de equilibrio frente a vos.\nSubite y buscá mantener el equilibrio.\nSostené la posición durante el tiempo deseado.' WHERE name_en = 'Balance Board';
UPDATE public.exercises SET instructions_es = 'Recostate boca arriba con las piernas extendidas y los tobillos sobre la pelota.\nEsta será tu posición inicial.\nLevantá la cadera del suelo manteniendo el peso sobre las escápulas y los pies.\nFlexioná las rodillas trayendo la pelota hacia vos y contrayendo los isquiotibiales.\nHacé una breve pausa y volvé a la posición inicial.' WHERE name_en = 'Ball Leg Curl';
UPDATE public.exercises SET instructions_es = 'Enganchá la banda elástica en el centro de la barra de dominadas.\nTirá de la banda hacia abajo, colocá una rodilla flexionada en el bucle y tomá la barra con un agarre medio a ancho.\nSubí contrayendo los dorsales y flexionando los codos hacia tus costados hasta pasar el mentón por encima de la barra.\nHacé una breve pausa y volvé de forma controlada a la posición inicial.' WHERE name_en = 'Band Assisted Pull-Up';
UPDATE public.exercises SET instructions_es = 'Pisá un extremo de la banda elástica separando un poco los pies y pasá el otro extremo por detrás de tu cuello flexionando la cadera.\nMantené las piernas rectas y extendé la cadera hasta quedar en posición vertical.\nEvitá encorvar la espalda al bajar de nuevo a la posición inicial.' WHERE name_en = 'Band Good Morning';
UPDATE public.exercises SET instructions_es = 'Enganchá la banda a un poste y pasá el otro extremo por tu cuello, sosteniéndola con las manos.\nFlexioná la cadera llevando los glúteos hacia atrás y el torso hacia adelante a 90 grados, con la espalda plana y las rodillas apenas flexionadas.\nEmpujá con la cadera para volver a la posición inicial de pie.' WHERE name_en = 'Band Good Morning (Pull Through)';
UPDATE public.exercises SET instructions_es = 'Anclá una banda elástica a un poste firme.\nParate con tu lado izquierdo mirando al poste y colocá la banda en el tobillo derecho.\nMantenete erguido y sujetate del poste si lo necesitás.\nCon la rodilla extendida, elevá la pierna derecha hacia el costado lo más alto que puedas.\nVolvé a la posición inicial, repetí las repeticiones deseadas y cambiá de lado.' WHERE name_en = 'Band Hip Adductions';
UPDATE public.exercises SET instructions_es = 'Iniciá con los brazos extendidos al frente sosteniendo la banda con ambas manos.\nAbrí los brazos hacia los lados realizando un vuelo invertido hasta llevar la banda al pecho.\nMantené los codos extendidos y los hombros hacia atrás durante todo el movimiento.\nHacé una pausa al completar el movimiento y volvé a la posición inicial de forma controlada.' WHERE name_en = 'Band Pull Apart';
UPDATE public.exercises SET instructions_es = 'Fijá una banda elástica a la base del rack o del banco.\nRecostate en el banco alineando la banda con tu cabeza.\nTomá la banda y elevá los codos hasta que los brazos queden perpendiculares al suelo.\nExtendé los codos para estirar los brazos manteniendo los brazos fijos.\nPausá un segundo arriba y volvé lentamente a la posición inicial.' WHERE name_en = 'Band Skull Crusher';
UPDATE public.exercises SET instructions_es = 'Ponete en posición de flexión de brazos apoyando las manos sobre una barra olímpica cargada.\nElevá la cadera y rodá la barra hacia tus pies mientras exhalás.\nMantené la zona media contraída, los glúteos arriba y los brazos perpendiculares al suelo.\nPausá un segundo arriba sintiendo la contracción abdominal.\nRodá la barra hacia adelante volviendo lentamente a la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'Barbell Ab Rollout';
UPDATE public.exercises SET instructions_es = 'Arrodillate en el suelo y sostené una barra olímpica frente a vos.\nApoyá la barra en el piso alineada con tus hombros.\nRodá la barra hacia adelante lentamente extendiendo el cuerpo sin tocar el suelo mientras inhalás.\nMantené los abdominales contraídos y pausá un segundo en máxima extensión.\nVolvé a la posición inicial tirando de la barra mientras exhalás.' WHERE name_en = 'Barbell Ab Rollout - On Knees';
UPDATE public.exercises SET instructions_es = 'Recostate en un banco plano y tomá la barra con un agarre medio.\nDesenganchá la barra y sostenela extendida sobre tu pecho.\nBajá la barra lentamente hasta tocar el centro del pecho mientras inhalás.\nHacé una breve pausa abajo.\nEmpujá la barra hacia arriba contrayendo el pecho mientras exhalás.\nPausá un segundo arriba y volvé a bajar lentamente.\nRepetí las repeticiones indicadas y colocá la barra en el soporte al finalizar.' WHERE name_en = 'Barbell Bench Press - Medium Grip';
UPDATE public.exercises SET instructions_es = 'Parate erguido y sujetá la barra a la anchura de los hombros con las palmas mirando hacia adelante.\nPegá los codos al torso y mantené los brazos fijos.\nFlexioná los antebrazos hacia arriba contrayendo los bíceps mientras exhalás.\nSubí la barra hasta la altura de los hombros y apretá los bíceps durante un segundo.\nBajá la barra lentamente a la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'Barbell Curl';
UPDATE public.exercises SET instructions_es = 'Apoyá el pecho sobre un banco inclinado dejando colgar los brazos con la barra.\nMantené los brazos fijos sin balancear el cuerpo.\nFlexioná los antebrazos llevando la barra lo más alto posible mientras exhalás.\nContraé los bíceps durante un segundo en el punto máximo.\nBajá la barra lentamente hasta extender completamente los brazos mientras inhalás.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'Barbell Curls Lying Against An Incline';
UPDATE public.exercises SET instructions_es = 'Parate frente a la barra cargada.\nFlexioná rodillas y caderas manteniendo la espalda recta para tomar la barra a la anchura de los hombros.\nEmpujá con las piernas y erguí el torso simultáneamente mientras exhalás.\nLlevá los hombros hacia atrás y sacá el pecho al quedar erguido.\nBajá la barra flexionando caderas y rodillas manteniendo la espalda recta hasta tocar el suelo.\nRepetí las repeticiones programadas.' WHERE name_en = 'Barbell Deadlift';
UPDATE public.exercises SET instructions_es = 'Ajustá la barra en el rack a la altura de tus hombros.\nUbícate debajo de la barra y apoyala sobre la parte posterior de tus hombros.\nTomá la barra firmemente, empujá con las piernas y desenganchala.\nDa un paso atrás y posicioná los pies a la anchura de los hombros con las puntas levemente hacia afuera.\nBajá lentamente flexionando rodillas y caderas con la espalda recta mientras inhalás.\nEmpujá el suelo desde los talones para subir extendiendo piernas y cadera mientras exhalás.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'Barbell Full Squat';
UPDATE public.exercises SET instructions_es = 'Sentate en el suelo con una barra cargada sobre tus piernas y usá una almohadilla para mayor comodidad.\nHacé rodar la barra sobre tus caderas y recostate boca arriba en el suelo.\nIniciá el movimiento empujando con los talones y extendé las caderas hacia arriba apoyando el peso en la espalda alta.\nExtendé las caderas lo máximo posible y bajá de forma controlada a la posición inicial.' WHERE name_en = 'Barbell Glute Bridge';
UPDATE public.exercises SET instructions_es = 'Agarrá la barra con un ancho medio, sacala del soporte y mantenela extendida sobre tu cuello.\nInhalá y bajá la barra lentamente hasta que quede a un par de centímetros de tu cuello.\nPausá un segundo y exhalá mientras empujás la barra hacia arriba usando los pectorales. Contraé el pecho arriba un segundo y bajá controladamente al doble de tiempo de lo que subís.\nRepetí el movimiento durante las repeticiones indicadas.\nAl terminar, volvé a colocar la barra en el soporte.' WHERE name_en = 'Barbell Guillotine Bench Press';
UPDATE public.exercises SET instructions_es = 'Parate derecho sosteniendo una barra por detrás del cuerpo al ancho de tus hombros y con las palmas mirando hacia atrás.\nMantené la espalda recta y la mirada al frente mientras bajás en sentadilla hasta que los muslos queden paralelos al suelo e inhalá.\nEmpujá con los talones y contraé los muslos para subir mientras exhalás.\nRepetí el movimiento durante las repeticiones recomendadas.' WHERE name_en = 'Barbell Hack Squat';
UPDATE public.exercises SET instructions_es = 'Sentate en el suelo con un banco detrás tuyo y una barra cargada sobre tus piernas. Usá una almohadilla para evitar molestias.\nHacé rodar la barra sobre tus caderas y apoyá las escápulas cerca del borde superior del banco.\nEmpujá con los pies y extendé las caderas hacia arriba manteniendo el apoyo en las escápulas y los pies. Extendé al máximo y bajá de forma controlada a la posición inicial.' WHERE name_en = 'Barbell Hip Thrust';
UPDATE public.exercises SET instructions_es = 'Recostate en un banco inclinado, sujetá la barra con un agarre medio y desenganchala manteniendo los brazos extendidos arriba.\nInhalá y bajá lentamente la barra hasta tocar la parte superior del pecho.\nPausá un segundo y exhalá mientras empujás la barra con la fuerza del pecho. Contraé el pecho arriba un segundo y bajá al doble de tiempo de subida.\nRepetí el movimiento durante las repeticiones indicadas.\nAl terminar, colocá la barra nuevamente en el soporte.' WHERE name_en = 'Barbell Incline Bench Press - Medium Grip';
UPDATE public.exercises SET instructions_es = 'Recostate en un banco inclinado, tomá la barra con un agarre apenas más ancho que tus hombros y sostenela con los brazos extendidos.\nMantené los brazos rectos y empujá la barra hacia arriba despegando las escápulas del banco mientras exhalás.\nInhalá y bajá la barra regresando los hombros al banco a la posición inicial.\nRepetí durante la cantidad de repeticiones indicadas.' WHERE name_en = 'Barbell Incline Shoulder Raise';
UPDATE public.exercises SET instructions_es = 'Ajustá la barra en la jaula a la altura de tus hombros, ubicate debajo y apoyala sobre la parte superior de la espalda.\nSujetá la barra con ambas manos, empujá con las piernas para desengancharla y da un paso hacia afuera.\nDa un paso hacia adelante con la pierna derecha y bajá las caderas manteniendo el torso erguido. Inhalá al bajar sin pasar la punta del pie con la rodilla.\nEmpujá principalmente con el talón delantero para volver a la posición inicial mientras exhalás.\nRealizá las repeticiones indicadas y repetí el movimiento con la pierna izquierda.' WHERE name_en = 'Barbell Lunge';
UPDATE public.exercises SET instructions_es = 'Parate erguido sujetando una barra con agarre prono y más ancho que la distancia de tus hombros.\nFlexioná levemente las rodillas e incliná el torso hacia adelante manteniendo la curvatura natural de la espalda hasta quedar casi paralelo al suelo. Abrí los codos hacia los lados formando una "T".\nTirá de la barra hacia la parte superior del pecho mientras exhalás y apretás los deltoides posteriores sin usar la fuerza de los bíceps.\nInhalá y bajá lentamente la barra a la posición inicial.\nRepetí durante la cantidad de repeticiones indicadas.' WHERE name_en = 'Barbell Rear Delt Row';
UPDATE public.exercises SET instructions_es = 'Ubicá una barra cargada en el suelo, cerca de un extremo del banco.\nArrodillate sobre el banco y agarrá la barra con un agarre medio a estrecho.\nExtendé la cadera para hacer rodar la barra lentamente hacia adelante.\nElevá los brazos por encima de la cabeza a medida que avanzás.\nMantené los brazos extendidos durante todo el recorrido.\nVolvé a la posición inicial de forma controlada.' WHERE name_en = 'Barbell Rollout from Bench';
UPDATE public.exercises SET instructions_es = 'Colocá un bloque a unos 30 cm delante de un banco plano.\nSentate en el banco y apoyá las puntas de los pies sobre el bloque.\nPedile a un compañero que coloque la barra sobre tus muslos, arriba de las rodillas.\nElevá los talones lo más alto posible mientras contraés los gemelos y exhalás.\nMantené la contracción un segundo y bajá lentamente para estirar el músculo.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'Barbell Seated Calf Raise';
UPDATE public.exercises SET instructions_es = 'Sentate en un banco con respaldo dentro de la jaula de sentadillas.\nAjustá la barra a una altura justo por encima de tu cabeza.\nTomá la barra con un agarre prono al ancho de tus hombros.\nEmpujá la barra hacia arriba hasta extender los brazos por completo.\nBajá la barra lentamente hacia tus hombros mientras inhalás.\nEmpujá la barra de vuelta hacia arriba mientras exhalás.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'Barbell Shoulder Press';
UPDATE public.exercises SET instructions_es = 'Parate derecho con los pies al ancho de tus hombros.\nSostené la barra al frente con agarre prono y las manos un poco más abiertas que los hombros.\nElevá los hombros lo más alto posible mientras exhalás.\nMantené la contracción durante un segundo sin doblar los codos.\nBajá lentamente a la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'Barbell Shrug';
UPDATE public.exercises SET instructions_es = 'Parate derecho con los pies al ancho de tus hombros.\nSostené la barra por detrás de la espalda con un agarre prono.\nElevá los hombros lo más alto posible mientras exhalás.\nMantené la contracción durante un segundo sin flexionar los brazos.\nBajá lentamente a la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'Barbell Shrug Behind The Back';
UPDATE public.exercises SET instructions_es = 'Parate derecho con la barra apoyada sobre la parte alta de la espalda.\nUbicá los pies al ancho de tus hombros.\nMantené la espalda recta e inclinate únicamente hacia la derecha mientras inhalás.\nMantené un segundo abajo y volvé a la posición inicial mientras exhalás.\nRepetí el movimiento inclinándote hacia la izquierda.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'Barbell Side Bend';
UPDATE public.exercises SET instructions_es = 'Parate derecho con la barra apoyada sobre la parte alta de la espalda.\nSepará bien los pies y girá ligeramente hacia afuera la punta del pie líder.\nFlexioná la rodilla y la cadera de esa pierna para bajar el cuerpo mientras inhalás.\nMantené la pierna opuesta extendida durante el descenso.\nEmpujá con la pierna flexionada para volver arriba mientras exhalás.\nCompletá las repeticiones y repetí con la otra pierna.' WHERE name_en = 'Barbell Side Split Squat';
UPDATE public.exercises SET instructions_es = 'Ajustá la barra en la jaula a la altura de tus hombros.\nUbicate debajo de la barra y apoyala sobre la parte alta de la espalda.\nAgarrá la barra, empujá con las piernas para desengancharla y dá un paso atrás.\nUbicá los pies al ancho de hombros con las puntas ligeramente hacia afuera.\nMantené la espalda recta y flexioná rodillas y cadera para bajar lentamente mientras inhalás.\nBajá hasta que tus muslos queden paralelos al suelo.\nEmpujá el suelo con los talones para volver a subir mientras exhalás.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'Barbell Squat';
UPDATE public.exercises SET instructions_es = 'Colocá un banco o cajón detrás tuyo dentro de la jaula de sentadillas.\nAjustá la barra a la altura adecuada, cargá el peso y ubicate debajo apoyándola en la parte alta de la espalda.\nAgarrá la barra con firmeza, empujá con las piernas y extendé el torso para sacarla del soporte.\nDa unos pasos hacia atrás y separá los pies al ancho de hombros.\nMantené la espalda recta y la mirada al frente.\nInhalá y bajá lentamente llevando la cadera hacia atrás hasta tocar apenas el banco.\nEvitá que las rodillas superen la punta de los pies.\nExhalá y empujá desde los talones para volver a la posición inicial.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'Barbell Squat To A Bench';
UPDATE public.exercises SET instructions_es = 'Parate erguido detrás de una plataforma con una barra apoyada en la parte alta de la espalda.\nApoyá el pie derecho sobre la plataforma.\nEmpujá con el talón derecho y extendé la pierna para subir todo el cuerpo, apoyando también el pie izquierdo.\nExhalá al hacer la fuerza arriba.\nInhalá y bajá primero el pie izquierdo flexionando la pierna derecha.\nLlevá el pie derecho al suelo para volver a la posición inicial.\nCompletá las repeticiones con una pierna y luego cambiá de lado.' WHERE name_en = 'Barbell Step Ups';
UPDATE public.exercises SET instructions_es = 'Parate con los pies al ancho de hombros y sostené la barra sobre la parte alta de la espalda.\nDa un paso largo hacia adelante y flexioná ambas rodillas para bajar la cadera.\nBajá hasta que la rodilla trasera casi toque el suelo, manteniendo el torso erguido.\nMantené la rodilla delantera alineada con el pie.\nEmpujá desde el talón delantero para extender las piernas y levantar el cuerpo.\nAvanzá con la pierna trasera y repetí la estocada con la otra pierna.' WHERE name_en = 'Barbell Walking Lunge';
UPDATE public.exercises SET instructions_es = 'Sostené un extremo de la soga de entrenamiento en cada mano con los brazos extendidos.\nFlexioná ligeramente las rodillas y mantené el torso firme.\nLevantá un brazo hacia la altura del hombro lo más rápido posible.\nBajá ese brazo mientras levantás el opuesto al mismo tiempo.\nAlterná ambos brazos a máxima velocidad creando ondas continuas.' WHERE name_en = 'Battling Ropes';
UPDATE public.exercises SET instructions_es = 'Enganchá la cadena del trineo a un arnés o cinturón dando la espalda al peso.\nApoyá las manos y las puntas de los pies en el suelo con la espalda plana y rodillas flexionadas.\nAvanzá empujando con las piernas de forma alternativa.\nUsá las manos para mantener el equilibrio y ayudar en el avance.\nMantené la espalda recta durante todo el recorrido.' WHERE name_en = 'Bear Crawl Sled Drags';
UPDATE public.exercises SET instructions_es = 'Sentate erguido en el suelo con tu compañero detrás tuyo.\nColocá las manos detrás de la cabeza y llevá los codos hacia atrás.\nPedile a tu compañero que sostenga tus codos en esa posición.\nHacé fuerza intentando llevar los codos hacia adelante durante 10 segundos mientras tu compañero resiste el movimiento.\nRelajá los músculos y dejá que tu compañero lleve suavemente tus codos más hacia atrás.\nAvisale cuando sientas el estiramiento adecuado para evitar lesiones.' WHERE name_en = 'Behind Head Chest Stretch';
UPDATE public.exercises SET instructions_es = 'Ubicá un banco detrás tuyo y apoyá las palmas en el borde al ancho de hombros.\nExtendé las piernas hacia adelante formando un ángulo recto con el torso.\nInhalá y bajá el cuerpo lentamente flexionando los codos hasta alcanzar un ángulo cercano a 90 grados.\nMantené los codos cerrados y apuntando hacia atrás.\nEmpujá con los tríceps para extender los brazos y volver a la posición inicial.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'Bench Dips';
UPDATE public.exercises SET instructions_es = 'Parate frente a un banco o cajón con los pies separados al ancho de hombros.\nHacé una media sentadilla rápida e impulsá los brazos hacia atrás.\nExtendé caderas, rodillas y tobillos para saltar alto llevando los brazos hacia arriba.\nSuperá el banco y aterrizá flexionando las rodillas para amortiguar el impacto.\nGirate de frente al banco y repetí el salto en sentido contrario.' WHERE name_en = 'Bench Jump';
UPDATE public.exercises SET instructions_es = 'Recostate en el banco pasando la cabeza levemente por debajo de la barra. Llevá los pies hacia atrás y arqueá la espalda. Levantá los hombros del banco, retraelos juntando las escápulas y apoyá firmemente los trapecios usando el empuje de las piernas. Mantené esta tensión durante todo el movimiento.\nAsegurá un agarre que cubra la marca del anillo de la barra. Sacá la barra del soporte sin perder la retracción escapular. Apretá la barra firmemente y simulá querer romperla hacia los lados.\nBajá la barra hacia la parte baja del pecho o alta del abdomen. Mantené alineados la barra, las muñecas y los codos en todo momento.\nHacé una pausa cuando la barra toque tu torso y empujala hacia arriba con la máxima fuerza posible. Mantené los codos hacia adentro hasta completar el bloqueo.' WHERE name_en = 'Bench Press - Powerlifting';
UPDATE public.exercises SET instructions_es = 'Fijá una banda elástica debajo de la pata del banco plano más cercana a tu cabeza.\nAgarrá los agarres de la banda y recostate sobre el banco.\nExtendé los brazos sosteniendo los agarres frente a vos al ancho de los hombros.\nRotá las muñecas hacia adelante para que las palmas queden mirando al frente en la posición inicial.\nBajá los agarres lentamente hasta que los codos formen un ángulo de 90 grados manteniendo el control.\nExhalá y empujá los agarres hacia arriba contrayendo los pectorales. Sostené la contracción un segundo arriba y bajá lentamente en el doble de tiempo que la subida.\nRepetí el movimiento hasta completar las repeticiones indicadas.' WHERE name_en = 'Bench Press - With Bands';
UPDATE public.exercises SET instructions_es = 'Ajustá la cadena guía al largo deseado y colocá las cadenas en los extremos de la barra.\nRecostate en el banco, llevá los pies hacia atrás y arqueá la espalda. Retraé las escápulas clavando los trapecios en el banco y mantené esa tensión corporal. Cubrí las marcas de la barra con tu agarre.\nDesenganchá la barra sin perder la retracción escapular y apretala con fuerza. Bajá la barra hacia el pecho bajo manteniendo alineados muñecas, codos y barra.\nPausá al tocar el torso y empujá la barra hacia arriba con máxima potencia hasta el bloqueo manteniendo los codos cerrados.' WHERE name_en = 'Bench Press with Chains';
UPDATE public.exercises SET instructions_es = 'Parate de pie y apoyá un pie sobre un banco o caja con el talón cerca del borde.\nEmpujá con la pierna de arriba extendiendo la cadera y la rodilla por completo.\nAterrizá apoyando el pie opuesto arriba del banco y bajá el pie inicial a la posición de origen.\nContinuá alternando ambas piernas hasta completar la serie.' WHERE name_en = 'Bench Sprint';
UPDATE public.exercises SET instructions_es = 'Recostate en un banco plano sosteniendo la barra con un agarre al ancho de los hombros.\nMantené la barra sobre tu pecho con los brazos ligeramente flexionados en la posición inicial.\nInhalá y bajá la barra lentamente dibujando un arco por detrás de tu cabeza hasta sentir el estiramiento en el pecho.\nExhalá y regresá la barra a la posición inicial realizando el mismo recorrido curvo.\nMantené la posición un segundo arriba y repetí el movimiento las repeticiones indicadas.' WHERE name_en = 'Bent-Arm Barbell Pullover';
UPDATE public.exercises SET instructions_es = 'Ubicá una mancuerna parada sobre un banco plano.\nColocate de forma perpendicular al banco apoyando solo los hombros, con las caderas abajo, las rodillas flectadas y los pies firmes en el suelo.\nSostené la mancuerna sobre tu pecho con ambas manos abrazando un extremo y mantené los codos ligeramente flexionados. Asegurate de que los discos estén firmes.\nInhalá y bajá la mancuerna lentamente en arco por detrás de tu cabeza hasta sentir el estiramiento pectoral.\nExhalá y volvé a subir la mancuerna a la posición inicial siguiendo el mismo arco.\nSostené el peso un segundo arriba y repetí hasta completar las repeticiones fijadas.' WHERE name_en = 'Bent-Arm Dumbbell Pullover';
UPDATE public.exercises SET instructions_es = 'Acostate boca arriba en el suelo con los brazos extendidos a los lados del cuerpo.\nFlexioná las rodillas a unos 75 grados y despegá los pies a pocos centímetros del suelo.\nExhalá y llevá las rodillas hacia tu pecho activando los abdominales inferiores hasta despegar la cadera del suelo.\nApretá el abdomen arriba durante un segundo e inhalá mientras regresás lentamente a la posición inicial con movimiento controlado.\nRepetí la secuencia hasta cumplir con las repeticiones de la serie.' WHERE name_en = 'Bent-Knee Hip Raise';
UPDATE public.exercises SET instructions_es = 'Sostené una barra con agarre prono, flexioná levemente las rodillas e incliná el torso recto hacia adelante hasta quedar casi paralelo al suelo. Dejá colgar la barra verticalmente.\nExhalá y llevá la barra hacia tu abdomen manteniendo el torso fijo y los codos pegados al cuerpo. Apretá la espalda en la cima del movimiento.\nInhalá y bajá la barra lentamente hasta la posición inicial de forma controlada.\nRepetí la ejecución durante todas las repeticiones indicadas.' WHERE name_en = 'Bent Over Barbell Row';
UPDATE public.exercises SET instructions_es = 'Parate derecho con una mancuerna en cada mano y un banco inclinado enfrente tuyo.\nMantené la espalda recta con su curvatura natural e inclinate hacia adelante hasta apoyar la frente en el banco. Dejá colgar los brazos perpendiculares al piso con las palmas enfrentadas y el torso casi paralelo al suelo. Esa es tu posición inicial.\nMantené el torso firme y los codos ligeramente flexionados. Elevá las mancuernas hacia los lados hasta que los brazos queden paralelos al piso mientras exhalás. Evitá balancear el torso o llevar los brazos hacia atrás.\nSostené la contracción arriba un segundo y bajá las mancuernas lentamente a la posición inicial.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'Bent Over Dumbbell Rear Delt Raise With Head On Bench';
UPDATE public.exercises SET instructions_es = 'Seleccioná el peso y agarrá el agarre de la polea baja con la mano derecha.\nFlexioná la cadera hasta que el torso quede casi paralelo al piso. Mantené las rodillas ligeramente flexionadas y apoyá la mano izquierda sobre el muslo izquierdo. Dejá colgar el brazo derecho con el codo apenas flexionado. Esa es tu posición inicial.\nElevá el brazo derecho hacia el costado hasta que quede paralelo al piso y alineado con tu oreja mientras exhalás.\nBajá el peso lentamente a la posición inicial mientras inhalás.\nRepetí las repeticiones recomendadas y cambiá de brazo.' WHERE name_en = 'Bent Over Low-Pulley Side Lateral';
UPDATE public.exercises SET instructions_es = 'Cargá peso en un extremo de una barra olímpica. Trancá el otro extremo en una esquina o sujetalo con un objeto pesado para que no se deslice.\nInclinate hacia adelante hasta tener el torso lo más paralelo posible al piso y flexioná un poco las rodillas.\nAgarrá la barra con una mano justo detrás de los discos y apoyá la otra mano en la rodilla. Esa es tu posición inicial.\nRemá llevando la barra hacia arriba pegando el codo al cuerpo hasta tocar la parte baja del pecho mientras exhalás. Contraé la espalda arriba durante un segundo. Evitá balancear el torso y mové únicamente el brazo.\nBajá la barra lentamente a la posición inicial estirando el dorsal. No dejes que los discos toquen el piso y usá discos chicos para tener mayor rango de movimiento.\nRepetí las repeticiones indicadas y cambiá de brazo.' WHERE name_en = 'Bent Over One-Arm Long Bar Row';
UPDATE public.exercises SET instructions_es = 'Cargá peso en un extremo de una barra olímpica. Asegurá el otro extremo en una esquina o con un objeto pesado para evitar que se deslice.\nInclinate hacia adelante manteniendo las rodillas flexionadas y el torso casi paralelo al piso.\nAgarrá la barra con ambas manos justo detrás de los discos (podés usar un agarre doble tipo estribo debajo de la barra). Esa es tu posición inicial.\nMantené los codos pegados al cuerpo y tirá de la barra hacia arriba hasta tocar la parte baja del pecho mientras exhalás. Apreta la espalda arriba durante un segundo.\nBajá la barra lentamente a la posición inicial sintiendo el estiramiento en los dorsales sin apoyar los discos en el piso. Usá discos chicos para no limitar el recorrido.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'Bent Over Two-Arm Long Bar Row';
UPDATE public.exercises SET instructions_es = 'Agarrah una mancuerna en cada mano con las palmas mirando hacia el torso, flexioná ligeramente las rodillas e inclinate manteniendo la espalda recta hasta estar casi paralelo al piso. Mantené la cabeza alineada y los brazos colgando perpendiculares al suelo. Esa es tu posición inicial.\nMantené el torso firme y subí las mancuernas hacia los costados pegando los codos al cuerpo mientras exhalás. Apreta los músculos de la espalda arriba y sostené la contracción un segundo.\nBajá el peso lentamente a la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'Bent Over Two-Dumbbell Row';
UPDATE public.exercises SET instructions_es = 'Sostené una mancuerna en cada mano con las palmas enfrentadas, flexioná las rodillas e inclinate con la espalda recta hasta que el torso quede casi paralelo al piso. Mirá hacia el frente y dejá colgar los brazos perpendiculares al suelo. Esa es tu posición inicial.\nMantené el torso quieto y subí las mancuernas hacia los costados mientras exhalás y juntás las escápulas. Pausá un segundo arriba apretando la espalda.\nBajá el peso lentamente a la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Bent Over Two-Dumbbell Row With Palms In';
UPDATE public.exercises SET instructions_es = 'Cargá una pesa rusa (kettlebell) al hombro empujando con las piernas y la cadera mientras rotás la muñeca. Esa es tu posición inicial.\nInclinate hacia el lado opuesto a la pesa rusa hasta tocar el piso con la mano libre sin perder de vista la pesa. Al mismo tiempo, empujá la pesa hacia arriba extendiendo el codo hasta que el brazo quede perpendicular al suelo.\nVolvé a la posición erguida con la pesa sobre la cabeza. Bajá la pesa al hombro y repetí las repeticiones deseadas.' WHERE name_en = 'Bent Press';
UPDATE public.exercises SET instructions_es = 'Sentate en la bicicleta y ajustá el asiento a tu altura.' WHERE name_en = 'Bicycling';
UPDATE public.exercises SET instructions_es = 'Sentate en la bicicleta y ajustá el asiento a tu altura.\nPedaleá o presioná la pantalla para encender la consola.\nSeleccioná el modo manual o un programa predeterminado.\nIngresá tu edad y peso para calcular las calorías quemadas.\nCambiá el nivel de resistencia a lo largo del entrenamiento.\nTomá los sensores del manillar para controlar tu frecuencia cardíaca.' WHERE name_en = 'Bicycling, Stationary';
UPDATE public.exercises SET instructions_es = 'Recostate en el banco con la cabeza alineada respecto a la barra.\nColocá las tablas sobre tu pecho sujetas por un compañero o con bandas elásticas.\nLlevá los pies hacia atrás, arqueá la espalda y juntá las escápulas contra el banco.\nMantené esta postura firme durante todo el movimiento.\nTomá la barra al ancho de hombros o con agarre tradicional manteniendo alineados muñeca y codo.\nSacá la barra del soporte sin perder la retracción escapular.\nBajá la barra hasta tocar las tablas.\nEmpujá la barra con fuerza hasta extender los brazos manteniendo los codos hacia adentro.' WHERE name_en = 'Board Press';
UPDATE public.exercises SET instructions_es = 'Colocate en posición de plancha apoyando antebrazos y puntas de pie en el suelo.\nMantené el torso recto y los antebrazos al ancho de hombros.\nApoyá las palmas con firmeza y extendé los codos para elevar el cuerpo.\nMantené el torso rígido durante todo el recorrido.\nBajá lentamente flexionando los codos hasta apoyar los antebrazos nuevamente.\nRepetí el movimiento.' WHERE name_en = 'Body-Up';
UPDATE public.exercises SET instructions_es = 'Ubicá una barra en el rack a la altura del pecho.\nAgarrá la barra al ancho de hombros y da unos pasos hacia atrás.\nMantené los pies juntos, los brazos extendidos y el cuerpo inclinado apoyado en la barra.\nFlexioná los codos para bajar el cuerpo hacia la barra.\nHacé una breve pausa y extendé los codos para regresar a la posición inicial.\nSumá cadenas sobre tus hombros para aumentar la dificultad.' WHERE name_en = 'Body Tricep Press';
UPDATE public.exercises SET instructions_es = 'Ubicá dos barras EZ cargadas con el mismo peso una al lado de la otra en el suelo.\nAsegurate de que puedan rodar con facilidad.\nAdoptá posición de flexión de brazos apoyando las manos sobre las barras.\nAlejá las manos de la línea media del cuerpo rodando las barras hacia afuera e inhalá.\nJuntá las barras nuevamente para volver a la posición inicial y exhalá.' WHERE name_en = 'Bodyweight Flyes';
UPDATE public.exercises SET instructions_es = 'Tomá la barra de dominadas con agarre prono a un ancho medio o amplio.\nColgate, llevá las rodillas al pecho e inclinate hacia atrás pasando las piernas por encima de la barra.\nCon los brazos extendidos, flexioná los codos y juntá las escápulas para subir el cuerpo.\nSubí hasta que tus piernas entren en contacto con la barra.\nPausá un segundo y bajá con control a la posición inicial.' WHERE name_en = 'Bodyweight Mid Row';
UPDATE public.exercises SET instructions_es = 'Parate con los pies al ancho de hombros y colocá las manos detrás de la cabeza.\nIniciá el movimiento flexionando rodillas y caderas hacia atrás.\nBajá todo lo posible manteniendo el pecho erguido y las rodillas apuntando hacia afuera.\nExtendé las piernas con rapidez para volver a la posición inicial.' WHERE name_en = 'Bodyweight Squat';
UPDATE public.exercises SET instructions_es = 'Parate con los pies al ancho de hombros y las manos en la cadera.\nDa un paso adelante y flexioná las rodillas para bajar la cadera.\nBajá hasta que la rodilla trasera casi toque el suelo, manteniendo el torso erguido.\nMantené la rodilla delantera alineada con el pie.\nEmpujá con el talón delantero para extender las piernas y volver a subir.\nAvanzá con el otro pie y repetí la estocada.' WHERE name_en = 'Bodyweight Walking Lunge';
UPDATE public.exercises SET instructions_es = 'Conectá un agarre individual en la posición más baja de cada lado de la máquina de poleas.\nUbicá un Bosu al frente y en el centro de la máquina.\nRecostate sobre el Bosu apoyando la zona lumbar curvada sobre la superficie, manteniendo los glúteos cerca del suelo sin tocarlo.\nEstirá las manos hacia atrás y agarrá la manija de cada polea.\nSepará los pies a lo ancho de los hombros y extendé los brazos hacia adelante entre tus rodillas a la altura de las mismas.\nMantené los brazos firmes siguiendo el ángulo del cable y elevá el torso realizando un crunch abdominal.\nMantené los brazos rígidos y bajá despacio a la posición inicial hasta estirar los abdominales.\nRepetí el movimiento hasta llegar al fallo muscular.\nAl llegar al fallo, mantené el abdomen contraído y elevá el torso despegando la espalda del Bosu.\nBajá los brazos a los lados de tu cuerpo y realizá inclinaciones laterales alternadas intentando tocar tus talones para trabajar los oblicuos.' WHERE name_en = 'Bosu Ball Cable Crunch With Side Bends';
UPDATE public.exercises SET instructions_es = 'Parate erguido sosteniendo una pesa rusa en una mano.\nBalanceá la pesa rusa con fuerza hacia atrás y revertí el movimiento con potencia.\nApretá el agarre con fuerza y elevá la pesa rusa hasta la altura de tu hombro.' WHERE name_en = 'Bottoms-Up Clean From The Hang Position';
UPDATE public.exercises SET instructions_es = 'Recostate boca arriba en el suelo con las piernas extendidas y los brazos a los lados del cuerpo.\nLlevá las rodillas hacia el pecho flexionando la cadera.\nExtendé las piernas verticalmente hacia el techo de forma perpendicular al suelo.\nElevá la pelvis despegando los glúteos del piso.\nPausá un segundo arriba y volvé de forma controlada a la posición inicial.' WHERE name_en = 'Bottoms Up';
UPDATE public.exercises SET instructions_es = 'Parate frente al cajón o plataforma a la distancia de un brazo con las rodillas ligeramente flexionadas.\nImpulsate con los brazos y saltá hacia arriba y adelante.\nAterrizá con ambos pies al mismo tiempo sobre la plataforma.\nBajá inmediatamente del cajón de un salto o paso y repetí la secuencia.' WHERE name_en = 'Box Jump (Multiple Response)';
UPDATE public.exercises SET instructions_es = 'Alineá varios cajones separados por unos dos metros y medio de distancia.\nUbicate frente al primer cajón con una pierna ligeramente retrasada.\nEmpujá con la pierna trasera para ganar la mayor altura posible con la cadera.\nAl aterrizar sobre el cajón, impulsá la otra pierna hacia adelante y arriba para saltar fuera de él.\nCaé entre los dos primeros cajones con la misma pierna que pisó el primer cajón.\nAvanzá hacia el siguiente cajón y repetí la secuencia.' WHERE name_en = 'Box Skip';
UPDATE public.exercises SET instructions_es = 'Colocá un cajón a la altura deseada detrás tuyo dentro de la jaula de potencia.\nUbicate debajo de la barra y apoyala sobre la parte superior de la espalda.\nJuntá las escápulas, llevá los codos hacia adelante y sacá la barra del soporte manteniendo el torso firme.\nDa un paso atrás y ajustá la apertura de los pies según el objetivo deseado.\nMantené la mirada al frente, la espalda recta y el abdomen contraído.\nIniciá la bajada llevando la cadera hacia atrás y las rodillas hacia afuera hasta sentarte en el cajón.\nMantené las tibias perpendiculares al suelo y pausá un segundo relajando los flexores de cadera sin rebotar.\nEmpujá desde los talones, llevá la cabeza hacia arriba y subí con potencia manteniendo la tensión corporal.' WHERE name_en = 'Box Squat';
UPDATE public.exercises SET instructions_es = 'Ubicá un cajón a la altura adecuada dentro de la jaula de potencia.\nFijá las bandas elásticas en los extremos de la barra y aseguralas a la base del soporte o a mancuernas pesadas para generar tensión.\nUbicate debajo de la barra, apoyala en la espalda y desenganchala manteniendo el torso firme.\nDa un paso atrás y acomodá la apertura de tus pies según el objetivo.\nFlexioná la cadera y rodillas hacia afuera hasta sentarte por completo en el cajón.\nPausá un instante en el cajón con las tibias perpendiculares al suelo sin rebotar.\nEmpujá con fuerza desde los talones hacia arriba manteniendo todo el cuerpo tenso.\nVolvé a guardar la barra en el soporte con cuidado.' WHERE name_en = 'Box Squat with Bands';
UPDATE public.exercises SET instructions_es = 'Ubicá un cajón detrás tuyo en la jaula de potencia a la altura deseada.\nEnganchá las cadenas pesadas a los extremos de la barra ajustando la longitud para que algunos eslabones toquen el suelo arriba.\nUbicate bajo la barra, apoyala sobre tus hombros, juntá las escápulas y sacala del soporte.\nDa unos pasos atrás y acomodá los pies según los músculos que quieras priorizar.\nMantené el torso tenso, llevá la cadera atrás y bajá hasta sentarte en el cajón.\nPausá brevemente con las tibias verticales sin perder la tensión ni rebotar.\nEmpujá con los talones y subí con potencia manteniendo la postura firme de pies a cabeza.' WHERE name_en = 'Box Squat with Chains';
UPDATE public.exercises SET instructions_es = 'Recostate de lado apoyando la parte externa del brazo sobre el rodillo de espuma.\nElevá la cadera del suelo sosteniendo el peso con el brazo y los pies.\nMantené la posición entre 10 y 30 segundos y cambiá de lado.' WHERE name_en = 'Brachialis-SMR';
UPDATE public.exercises SET instructions_es = 'Sentate en un banco militar y tomá la barra a la altura de los hombros con agarre prono.\nLevantá la barra por encima de la cabeza extendiendo los brazos por completo.\nBajá la barra lentamente por detrás de la cabeza mientras inhalás.\nEmpujá la barra hacia arriba a la posición inicial mientras exhalás.\nRepetí el movimiento hasta completar las repeticiones indicadas.' WHERE name_en = 'Bradford/Rocky Presses';
UPDATE public.exercises SET instructions_es = 'Colocate en posición de flexión apoyando los antebrazos con los codos a 90 grados.\nArqueá ligeramente la espalda hacia arriba.\nElevá los glúteos hacia el techo contrayendo fuerte el abdomen y exhalá.\nBajá lentamente a la posición inicial mientras inhalás sin dejar caer la cadera.\nRepetí hasta completar las repeticiones indicadas.' WHERE name_en = 'Butt-Ups';
UPDATE public.exercises SET instructions_es = 'Acostate boca arriba con los brazos a los lados y las rodillas flexionadas.\nEmpujá con los talones y elevá la cadera manteniendo la espalda recta mientras exhalás.\nSostené la posición un segundo arriba.\nBajá lentamente a la posición inicial mientras inhalás.' WHERE name_en = 'Butt Lift (Bridge)';
UPDATE public.exercises SET instructions_es = 'Sentate en la máquina apoyando la espalda firme sobre el respaldo.\nTomá los agarres manteniendo los brazos paralelos al suelo.\nEmpujá los agarres hacia el centro contrayendo el pecho y exhalá.\nSostené la contracción un segundo en el centro.\nVolvé lentamente a la posición inicial mientras inhalás hasta estirar el pecho.\nRepetí las repeticiones indicadas.' WHERE name_en = 'Butterfly';
UPDATE public.exercises SET instructions_es = 'Ajustá el peso, sentate y tomá los agarres con el pecho erguido y codos a 90 grados.\nEmpujá los agarres hacia adelante extendiendo los codos con las escápulas retraídas.\nPausá en máxima extensión y volvé lentamente a la posición inicial sin perder tensión.\nRepetí el movimiento según las repeticiones indicadas.' WHERE name_en = 'Cable Chest Press';
UPDATE public.exercises SET instructions_es = 'Colocá las poleas en posición alta y tomá un agarre con cada mano.\nDá un paso hacia adelante inclinando levemente el torso con las manos juntas al frente.\nAbrí los brazos hacia los lados en un arco amplio con codos semi-flexionados e inhalá.\nJuntá los brazos de vuelta a la posición inicial mientras exhalás.\nMantené un segundo la posición inicial y repetí las repeticiones indicadas.' WHERE name_en = 'Cable Crossover';
UPDATE public.exercises SET instructions_es = 'Arrodillate frente a una polea alta equipada con soga.\nAgarrá la soga y bajá las manos hasta los lados de la cara.\nIncliná ligeramente la cadera para iniciar el movimiento.\nFlexioná la cintura contrayendo el abdomen hacia los muslos y exhalá.\nSostené la contracción un segundo abajo.\nVolvé lentamente a la posición inicial mientras inhalás.\nRepetí las repeticiones indicadas.' WHERE name_en = 'Cable Crunch';
UPDATE public.exercises SET instructions_es = 'Colocá las poleas en la posición más baja y seleccioná el peso adecuado.\nUbicate justo en el centro de las torres.\nFlexioná la cadera y las rodillas para bajarte a agarrar las manijas.\nTomá las manijas e iniciá el ascenso.\nEmpujá con los talones y extendé la cadera y las rodillas, manteniendo los brazos a los lados.\nMantené la cabeza levantada y el pecho erguido durante todo el movimiento.\nAl quedar de pie, volvé a la posición inicial y repetí.' WHERE name_en = 'Cable Deadlifts';
UPDATE public.exercises SET instructions_es = 'Enganchá la soga en la polea baja y parate de frente a la máquina a unos 30 centímetros.\nAgarrá la soga con agarre neutro y mantené la espalda recta con el torso firme.\nPegá los codos a los costados del cuerpo y mantenelos inmóviles durante todo el ejercicio.\nFlexioná los antebrazos llevando la soga hacia arriba mientras exhalás hasta contraer los bíceps.\nMantené la contracción máxima durante un segundo.\nBajá el peso de forma controlada hasta la posición inicial.\nRepetí según las repeticiones indicadas.' WHERE name_en = 'Cable Hammer Curls - Rope Attachment';
UPDATE public.exercises SET instructions_es = 'Parate al lado de la polea baja mirando hacia adelante.\nAjustá la tobillera en el tobillo de la pierna más cercana a la máquina.\nDá un paso hacia afuera para alejarte y mantener una postura estable.\nApoyá tu peso en la pierna libre y dejá que la pierna con la tobillera sea llevada hacia la polea.\nLlevá la pierna con la tobillera por delante de la otra pierna contrayendo la cara interna del muslo mientras exhalás.\nVolvé lentamente a la posición inicial mientras inhalás.\nCompletá las repeticiones indicadas y repetí con la otra pierna.' WHERE name_en = 'Cable Hip Adduction';
UPDATE public.exercises SET instructions_es = 'Recostate en un banco inclinado dando la espalda a la polea alta con barra recta.\nAgarrá la barra sobre la cabeza con agarre prono al ancho de hombros y extendé los brazos hacia adelante.\nUbicá la barra a pocos centímetros de los muslos para iniciar el movimiento.\nMantené los brazos firmes y llevalos hacia atrás formando un semicírculo hasta que la barra quede sobre tu cabeza mientras inhalás.\nVolvé lentamente a la posición inicial usando los dorsales y exhalá el aire.\nRepetí según la cantidad de repeticiones indicadas.' WHERE name_en = 'Cable Incline Pushdown';
UPDATE public.exercises SET instructions_es = 'Recostate en un banco inclinado dando la espalda a la polea alta con barra recta.\nSujetá la barra con agarre prono cerrado y mantené los codos pegados al cuerpo.\nExtendé los brazos contrayendo los tríceps mientras exhalás el aire.\nMantené la contracción máxima por un segundo.\nVolvé a la posición inicial de forma lenta y controlada.\nRepetí según las repeticiones indicadas.' WHERE name_en = 'Cable Incline Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Sentate de costado junto a una polea baja y agarrá el manillar individual con el brazo más cercano.\nApoyá el codo contra tu costado, doblado a 90 grados y apuntando hacia la polea.\nRotá el hombro hacia adentro trayendo el manillar hacia tu abdomen en un movimiento semicircular.\nMantené el antebrazo perpendicular al torso en todo momento.\nVolvé lentamente a la posición inicial.\nCompletá las repeticiones y repetí con el otro brazo.' WHERE name_en = 'Cable Internal Rotation';
UPDATE public.exercises SET instructions_es = 'Colocá las poleas en la posición alta, elegí la carga y agarrá una manija con cada mano.\nUbicate en el centro de la máquina abriendo los brazos a los lados en forma de "T".\nMantené la cabeza levantada y el pecho erguido.\nLlevá las manijas hacia los costados de tu cuerpo manteniendo los brazos extendidos.\nHacé una pausa en el punto de máxima contracción y volvé de a poco a la posición inicial.\nRepetí el movimiento hasta completar la serie.' WHERE name_en = 'Cable Iron Cross';
UPDATE public.exercises SET instructions_es = 'Enganchá la soga en la polea más baja de la torre.\nParate de costado a la máquina con los pies separados y agarrá la soga con ambas manos.\nGirá el torso alejándote de la polea y llevá la soga por encima del hombro.\nTrasladá el peso del cuerpo entre los pies mientras rotás y flexionás el tronco hacia abajo.\nVolvé a la posición inicial y repetí hasta llegar al fallo.\nCambiá de lado y repetí la misma secuencia con el perfil opuesto.' WHERE name_en = 'Cable Judo Flip';
UPDATE public.exercises SET instructions_es = 'Recostate en un banco plano y agarrá la barra recta de la polea baja con agarre prono estrecho.\nExtendé los brazos y posicioná la barra sobre tu torso formando un ángulo de 90 grados para la posición inicial.\nBajá la barra flexionando los codos y manteniendo los brazos fijos hasta tocar levemente la frente mientras inhalás.\nExtendé los tríceps para elevar la barra a la posición inicial mientras exhalás.\nMantené la contracción un segundo y repetí la cantidad indicada de repeticiones.' WHERE name_en = 'Cable Lying Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Agarrá la manija de la polea alta con la mano derecha usando agarre supino de frente a la máquina.\nLlevá el agarre hacia abajo pegando el brazo al costado del cuerpo hasta formar un ángulo agudo entre brazo y antebrazo para la posición inicial.\nExtendé el tríceps empujando la manija hacia abajo hasta estirar el brazo por completo mientras exhalás.\nContraé el tríceps y sostené la posición un segundo.\nVolvé lentamente a la posición inicial.\nRepetí las repeticiones indicadas y realizá el mismo movimiento con el otro brazo.' WHERE name_en = 'Cable One Arm Tricep Extension';
UPDATE public.exercises SET instructions_es = 'Ubicá un banco Scott a medio metro frente a la máquina de polea baja.\nConectá una barra recta a la polea baja.\nSentate apoyando firmemente los brazos sobre el cojín y sujetá la barra.\nExtendé completamente los brazos sobre el cojín para la posición inicial.\nFlexioná los brazos llevando la barra hacia los hombros y contraé los bíceps arriba mientras exhalás.\nBajá el peso lentamente hasta la posición inicial.\nRepetí la cantidad recomendada de repeticiones.' WHERE name_en = 'Cable Preacher Curl';
UPDATE public.exercises SET instructions_es = 'Ajustá las poleas por encima de tu cabeza y seleccioná el peso.\nAgarrá la polea izquierda con la mano derecha y la derecha con la mano izquierda cruzando los brazos al frente para la posición inicial.\nLlevá los brazos hacia atrás y hacia afuera manteniéndolos extendidos durante el recorrido.\nHacé una pausa al final del movimiento y volvé a la posición inicial de forma controlada.' WHERE name_en = 'Cable Rear Delt Fly';
UPDATE public.exercises SET instructions_es = 'Colocá una tobillera en la polea baja y ubicá una colchoneta en el suelo de frente a la máquina.\nSentate mirando hacia la polea y enganchá el cable a tus tobillos.\nRecostate, elevá las piernas y flexioná las rodillas a 90 grados alineando las piernas con el cable.\nCon las manos detrás de la cabeza, llevá las rodillas hacia el torso y despegá la cadera del suelo.\nHacé una pausa y bajá lentamente la cadera volviendo a la posición inicial manteniendo tensión en el abdomen.\nRepetí el movimiento hasta el fallo muscular.' WHERE name_en = 'Cable Reverse Crunch';
UPDATE public.exercises SET instructions_es = 'Enganchá una soga en la polea baja.\nAgarrá la soga con agarre neutro y extendé los brazos por encima de la cabeza con los codos cerca de las orejas para la posición inicial.\nBajá la soga lentamente por detrás de la cabeza manteniendo los brazos fijos e inhalá al estirar el tríceps.\nExtendé los brazos para volver a la posición inicial mientras exhalás.\nRepetí la cantidad recomendada de repeticiones.' WHERE name_en = 'Cable Rope Overhead Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Sentate en la máquina de remo en polea baja con el torso recto y las rodillas ligeramente flexionadas.\nConectá la soga a la polea y agarrala con agarre prono manteniendo los brazos extendidos paralelos al suelo para la posición inicial.\nLlevá la soga hacia la parte superior del pecho manteniendo los codos elevados y hacia los lados mientras exhalás.\nVolvé a la posición inicial extendiendo los brazos e inhalando durante el retorno.\nRepetí la cantidad recomendada de repeticiones.' WHERE name_en = 'Cable Rope Rear-Delt Rows';
UPDATE public.exercises SET instructions_es = 'Colocá una manija individual en la polea a altura media.\nRecostate sobre una pelota de estabilidad de forma perpendicular a la máquina y agarrá la manija con ambas manos extendidas frente al pecho.\nElevá la cadera y mantené el abdomen contraído.\nRotá el torso alejándote de la polea en un cuarto de giro manteniendo el cuerpo alineado de la cabeza a las rodillas.\nHacé una pausa y volvé de manera controlada a la posición inicial manteniendo tensión lateral.\nRepetí el movimiento hasta el fallo muscular y realizá la serie del lado opuesto.' WHERE name_en = 'Cable Russian Twists';
UPDATE public.exercises SET instructions_es = 'Sentate en un banco plano dándole la espalda a una polea alta.\nAgarrá la cuerda con ambas manos con las palmas enfrentadas y apoyá las manos sobre tus hombros.\nDejá que el peso hiperextienda levemente tu zona lumbar para iniciar el movimiento.\nMantené la cadera fija y flexioná la cintura llevando los codos hacia las caderas mientras exhalás.\nVolvé lentamente a la posición inicial mientras inhalás.\nRepetí la cantidad indicada de repeticiones.' WHERE name_en = 'Cable Seated Crunch';
UPDATE public.exercises SET instructions_es = 'Ubicá un banco plano de forma perpendicular detrás tuyo en el centro de dos poleas bajas.\nSentate en el borde del banco con los pies adelantados respecto a las rodillas.\nIncliná el torso hacia adelante manteniendo la espalda recta y apoyalo sobre los muslos.\nAgarrá la manija de la polea izquierda con la mano derecha y la derecha con la izquierda por debajo de tus rodillas.\nElevá los brazos hacia los lados hasta que queden paralelos al suelo mientras exhalás y mantené un segundo la contracción.\nBajá los brazos lentamente a la posición inicial mientras inhalás.\nMantené los codos fijos en un ángulo leve durante todo el ejercicio y repetí la cantidad indicada de repeticiones.' WHERE name_en = 'Cable Seated Lateral Raise';
UPDATE public.exercises SET instructions_es = 'Colocá las poleas en la parte inferior de las torres y seleccioná el peso adecuado.\nUbicate en el centro, agarrá los manillares y sostenelos a la altura de los hombros con las palmas hacia adelante.\nMantené la cabeza y el pecho erguidos, y empujá las manijas directamente por encima de la cabeza.\nHacé una breve pausa arriba, volvé a la posición inicial y repetí la cantidad indicada de repeticiones.' WHERE name_en = 'Cable Shoulder Press';
UPDATE public.exercises SET instructions_es = 'Agarrá la barra recta de la polea baja con un agarre prono al ancho de hombros o apenas más ancho.\nParate derecho cerca de la polea con los brazos extendidos hacia abajo sosteniendo la barra.\nElevá los hombros lo más alto posible mientras exhalás y sostené la contracción un segundo arriba.\nBajá la barra a la posición inicial sin flexionar los brazos.\nRepetí la cantidad indicada de repeticiones.' WHERE name_en = 'Cable Shrugs';
UPDATE public.exercises SET instructions_es = 'Colocá un banco plano frente a una polea baja con barra recta.\nAgarrá la barra con agarre supino al ancho de hombros y apoyá los antebrazos sobre tus muslos con las muñecas por fuera de las rodillas.\nFlexioná las muñecas hacia arriba mientras exhalás y sostené la contracción un segundo.\nBajá lentamente las muñecas a la posición inicial mientras inhalás.\nMantené los antebrazos inmóviles durante todo el movimiento.\nRepetí la cantidad indicada de repeticiones.' WHERE name_en = 'Cable Wrist Curl';
UPDATE public.exercises SET instructions_es = 'Ubicate en la máquina de gemelos apoyando las almohadillas sobre tus hombros y mantené el torso erguido.\nElevá los hombros hacia las orejas mientras exhalás y sostené la contracción durante un segundo.\nVolvé lentamente a la posición inicial mientras inhalás.\nRepetí la cantidad indicada de repeticiones.' WHERE name_en = 'Calf-Machine Shoulder Shrug';
UPDATE public.exercises SET instructions_es = 'Ajustá el asiento para que tus piernas queden levemente flexionadas y apoyá el metatarso de los pies firmemente en la plataforma.\nSeleccioná el peso adecuado y sujetá los agarres.\nExtendé las rodillas sin bloquearlas y flexioná los tobillos hacia arriba.\nEmpujá la plataforma extendiendo los tobillos hacia adelante lo más lejos posible.\nHacé una breve pausa, volvé a la posición inicial y repetí la cantidad indicada de repeticiones.' WHERE name_en = 'Calf Press';
UPDATE public.exercises SET instructions_es = 'Sentate en la prensa y colocá los pies al ancho de hombros sobre la plataforma.\nQuitá el seguro y empujá la plataforma hasta extender las piernas sin bloquear las rodillas.\nApoyá únicamente el metatarso y las puntas de los pies en el borde inferior de la plataforma, dejando los talones libres.\nEmpujá la plataforma levantando los talones y extendiendo los tobillos al máximo mientras exhalás.\nSostené la contracción un segundo arriba.\nBajá lentamente los talones flexionando los tobillos hasta sentir el estiramiento mientras inhalás.\nRepetí la cantidad indicada de repeticiones.' WHERE name_en = 'Calf Press On The Leg Press Machine';
UPDATE public.exercises SET instructions_es = 'Sostenete de un objeto firme para mantener el equilibrio y apoyá un pie sobre el agarre de una mancuerna.\nRodá el pie hacia adelante para estirar el gemelo en la posición inicial.\nElevá el talón rodando la mancuerna hacia atrás para lograr la extensión completa y exhalá.\nContraé el gemelo arriba con fuerza y mantené durante un segundo.\nInhalá mientras bajás y rodás la mancuerna hacia adelante para estirar el músculo.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'Calf Raise On A Dumbbell';
UPDATE public.exercises SET instructions_es = 'Pisá el centro de una banda elástica con las puntas de los pies asegurando la misma tensión en ambos lados.\nLlevá los agarres a la altura de los hombros con las palmas hacia adelante y los codos flexionados.\nMantené las manos firmes en los hombros y ponete en puntas de pie mientras exhalás.\nContraé los gemelos al máximo arriba durante un segundo.\nBajá lentamente a la posición inicial.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'Calf Raises - With Bands';
UPDATE public.exercises SET instructions_es = 'Parate de frente a una pared a unos pasos de distancia.\nInclináte hacia adelante y apoyá los antebrazos sobre la pared.\nMantené los talones pegados al suelo y sostené la posición entre 10 y 20 segundos.\nAjustá la distancia con la pared para variar la dificultad.' WHERE name_en = 'Calf Stretch Elbows Against Wall';
UPDATE public.exercises SET instructions_es = 'Parate frente a la pared con un pie más adelante que el otro.\nInclináte apoyando las manos en la pared y mantené alineados el talón trasero, la cadera y la cabeza.\nMantené el talón trasero apoyado en el suelo durante 10 a 20 segundos y cambiá de pierna.' WHERE name_en = 'Calf Stretch Hands Against Wall';
UPDATE public.exercises SET instructions_es = 'Sentate en el suelo y colocá un rodillo de espuma debajo de la pantorrilla.\nCruzá la otra pierna por encima o apoyala en el suelo para sostener parte del peso.\nApoyá las manos a los lados o atrás y elevá la cadera del suelo.\nRodá la pantorrilla desde la rodilla hasta el tobillo, pausando de 10 a 30 segundos en los puntos de tensión.\nRepetí con la otra pierna.' WHERE name_en = 'Calves-SMR';
UPDATE public.exercises SET instructions_es = 'Ubicá los pies a la anchura de la cadera dentro de la estructura.\nIncliná la cadera, sujetá los agarres, inhalá profundo, bajá la cadera y flexioná las rodillas.\nMantené la mirada al frente, el pecho erguido y la espalda recta.\nEmpujá desde los talones hacia arriba, juntá las escápulas y empujá la cadera hacia adelante al extender.\nBajá el peso flexionando la cadera y guiándolo hasta el suelo.' WHERE name_en = 'Car Deadlift';
UPDATE public.exercises SET instructions_es = 'Parate erguido y sujetá un disco con ambas manos por los lados con los brazos extendidos al frente.\nGirá el disco hacia un lado al máximo, como si manejaras un volante.\nInvertí el movimiento girándolo completamente hacia el lado opuesto.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'Car Drivers';
UPDATE public.exercises SET instructions_es = 'Parate con los pies apenas separados y el brazo izquierdo arriba en posición atlética.\nDá un paso rápido de costado con el pie derecho y elevá la rodilla derecha.\nAcompañá el movimiento subiendo los brazos de forma explosiva manteniendo la rodilla recta.\nDesplazate de costado mirando hacia adelante y sin rotar los pies.' WHERE name_en = 'Carioca Quick Step';
UPDATE public.exercises SET instructions_es = 'Ponete en el suelo en cuadrupedia, apoyando manos y rodillas.\nLlevá el ombligo hacia adentro y redondeá la columna, la zona lumbar, los hombros y el cuello, dejando caer la cabeza.\nMantené la posición durante 15 segundos.' WHERE name_en = 'Cat Stretch';
UPDATE public.exercises SET instructions_es = 'Parate de frente a una pared o a un compañero.\nTomá el balón con ambas manos detrás de la cabeza, estirate bien y lanzalo con fuerza hacia adelante.\nAcompañá el movimiento con el cuerpo y preparate para recibir el rebote.\nSi usás la pared, ubicate a una distancia adecuada y apuntá un poco más arriba.' WHERE name_en = 'Catch and Overhead Throw';
UPDATE public.exercises SET instructions_es = 'Enganchá las cadenas a los agarres de la polea y acostate en un banco plano con los codos apuntando hacia arriba.\nExtendé los codos manteniendo los brazos fijos y las muñecas en pronación.\nHacé una pausa en la extensión máxima y volvé a la posición inicial.' WHERE name_en = 'Chain Handle Extension';
UPDATE public.exercises SET instructions_es = 'Conectá las cadenas a los agarres de la polea y acostate en el banco plano en posición de press, con agarre prono y brazos perpendiculares al suelo.\nFlexioná los codos para bajar las cadenas apoyando parte de ellas en el suelo.\nLlegá a un ángulo de 90 grados en los codos y extendelos por completo para volver a la posición inicial.' WHERE name_en = 'Chain Press';
UPDATE public.exercises SET instructions_es = 'Sentate erguido en una silla y agarrate de los lados del asiento.\nLevantá una pierna extendiendo la rodilla y flexionando el tobillo.\nMové esa pierna hacia afuera lentamente hasta donde llegues, volvé al centro y bajala.\nRepetí el movimiento con la otra pierna.' WHERE name_en = 'Chair Leg Extended Stretch';
UPDATE public.exercises SET instructions_es = 'Sentate erguido en una silla.\nInclinate hacia un lado llevando el brazo por encima de la cabeza y sujetate de la silla con la mano libre.\nMantené durante 10 segundos y repetí del otro lado.' WHERE name_en = 'Chair Lower Back Stretch';
UPDATE public.exercises SET instructions_es = 'Ajustá la barra a tu altura, cargá el peso, ubicate debajo y apoyala sobre la parte posterior de los hombros.\nTomá la barra con agarre prono, destrabala y desenganchala extendiendo las piernas.\nAvanzá los pies unos 45 cm por delante de la barra, abrí las piernas al ancho de hombros con las puntas hacia afuera y mantené la espalda neutra.\nBajá despacio flexionando las rodillas con el torso erguido hasta superar los 90 grados de flexión.\nExhalá y empujá desde los talones para extender las rodillas y volver a la posición inicial.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'Chair Squat';
UPDATE public.exercises SET instructions_es = 'Sentate en el borde de una silla y agarrate del respaldo.\nExtendé los brazos, mantené la espalda recta y llevá el torso hacia adelante hasta sentir el estiramiento.\nMantené la posición durante 20 a 30 segundos.' WHERE name_en = 'Chair Upper Body Stretch';
UPDATE public.exercises SET instructions_es = 'Parate derecho con las piernas juntas sujetando una barra o palo de escoba.\nTomá la barra con las palmas hacia abajo y una separación mayor al ancho de hombros.\nLevantá la barra con cuidado por encima y por detrás de tu cabeza.' WHERE name_en = 'Chest And Front Of Shoulder Stretch';
UPDATE public.exercises SET instructions_es = 'Iniciá en posición de tres puntos: en sentadilla, con la espalda recta, una mano en el suelo y el balón medicinal al frente.\nDa el primer paso mientras llevás el balón al pecho y posicionás ambas manos para el lanzamiento.\nAl dar el segundo paso, lanzá el balón hacia adelante de forma explosiva.' WHERE name_en = 'Chest Push from 3 point stance';
UPDATE public.exercises SET instructions_es = 'Ponete de rodillas frente a una pared o un compañero y sujetá el balón con ambas manos pegado al pecho.\nEmpujá el balón con máxima fuerza extendiendo la cadera explosivamente hacia adelante.\nDejate caer hacia adelante al soltarlo y frenate apoyando las manos en el suelo.\nVolvé de inmediato a la posición inicial y repetí la cantidad de repeticiones indicadas.' WHERE name_en = 'Chest Push (multiple response)';
UPDATE public.exercises SET instructions_es = 'Ponete de rodillas sujetando el balón medicinal con ambas manos pegado al pecho.\nLanzá el balón lo más lejos posible extendiendo la cadera explosivamente hacia adelante.\nDejate caer hacia adelante y frenate apoyando las manos en el suelo.' WHERE name_en = 'Chest Push (single response)';
UPDATE public.exercises SET instructions_es = 'Ubicate en posición atlética: rodillas flexionadas, cadera atrás, espalda recta y el balón cerca de las piernas.\nLlevá el balón medicinal al pecho al dar el primer paso.\nEmpujá el balón con explosividad al dar el segundo paso e iniciá un sprint de 10 metros inmediatamente.' WHERE name_en = 'Chest Push with Run Release';
UPDATE public.exercises SET instructions_es = 'Ponete en cuadrupedia al lado de una pelota de pilates.\nApoyá el codo sobre la pelota manteniendo el brazo hacia un costado.\nBajá el torso hacia el suelo manteniendo el codo apoyado.\nMantené el estiramiento de 20 a 30 segundos y repetí con el otro brazo.' WHERE name_en = 'Chest Stretch on Stability Ball';
UPDATE public.exercises SET instructions_es = 'Ponete en cuadrupedia y llevá las manos hacia adelante.\nBajá la cadera hasta sentarte sobre tus talones y deslizá los brazos para estirar la columna.\nLlevá las manos al lado de los pies, apoyá la frente en el suelo y relajá la espalda respirando profundo.\nEvitá esta posición si tenés problemas en las rodillas.' WHERE name_en = 'Child''s Pose';
UPDATE public.exercises SET instructions_es = 'Agarrá la barra de dominadas con las palmas mirando hacia vos y un agarre más cerrado que el ancho de hombros.\nMantené los brazos extendidos, el torso recto, sacá pecho y curvá ligeramente la zona lumbar.\nExhalá y subí el torso concentrando la fuerza en los bíceps hasta que la cabeza llegue a la altura de la barra.\nPausá un segundo arriba contrayendo los bíceps y bajá lentamente hasta extender los brazos por completo mientras inhalás.\nRepetí el movimiento la cantidad de repeticiones indicadas.' WHERE name_en = 'Chin-Up';
UPDATE public.exercises SET instructions_es = 'Sentate en el suelo.\nUbicá ambas manos en la nuca con los dedos entrelazados, los pulgares hacia abajo y los codos apuntando hacia adelante.\nLlevá lentamente la cabeza hacia el pecho.\nMantené la posición durante 20 a 30 segundos.' WHERE name_en = 'Chin To Chest Stretch';
UPDATE public.exercises SET instructions_es = 'Ubicá la mancuerna entre tus pies y sujetá el agarre con ambas manos.\nCargá la mancuerna extendiendo caderas y rodillas hasta llevarla a un hombro y soltá con la otra mano.\nAsegurá una de las cabezas de la mancuerna detrás del hombro para mantener el equilibrio.\nFlexioná levemente las rodillas e impulsate hacia arriba extendiendo el brazo sobre la cabeza, inclinándote un poco hacia el lado opuesto.\nGuiá la mancuerna hacia el suelo con control, preferentemente sobre una colchoneta de goma.' WHERE name_en = 'Circus Bell';
UPDATE public.exercises SET instructions_es = 'Ubicá la barra cerca de las espinillas, agarrala en pronación por fuera de las piernas y bajá la cadera con la espalda recta, el pecho arriba y los hombros levemente por delante de la barra.\nIniciá el primer tirón empujando con los talones y extendiendo las rodillas, manteniendo el torso firme hasta superar las rodillas.\nEjecutá el segundo tirón extendiendo caderas, rodillas y tobillos con potencia para acelerar la barra hacia arriba.\nPasá al tercer tirón encogiéndote de hombros, flexioná los brazos y metete rápido debajo de la barra rotando los codos.\nRecibí la barra sobre los hombros en sentadilla frontal y descendé de forma controlada hasta el fondo.\nPonete de pie empujando con los talones, manteniendo el torso erguido y los codos arriba.' WHERE name_en = 'Clean';
UPDATE public.exercises SET instructions_es = 'Parate con la barra cerca de las espinillas y los pies al ancho de caderas.\nAgarrá la barra al ancho de hombros en pronación y bajá en sentadilla manteniendo la espalda recta y los hombros sobre la barra.\nEmpujá el suelo con la parte delantera de los talones para subir la barra, manteniendo el ángulo de la espalda y abriendo levemente las rodillas.\nAl superar las rodillas, empujá la cadera hacia adelante hasta extender caderas y rodillas por completo.' WHERE name_en = 'Clean Deadlift';
UPDATE public.exercises SET instructions_es = 'Ubicá la barra cerca de las espinillas, agarrala en pronación por fuera de las piernas y bajá la cadera con la espalda recta y el pecho arriba.\nIniciá el primer tirón empujando desde los talones y extendiendo las rodillas hasta superar la altura de las rodillas.\nEjecutá el segundo tirón extendiendo explosivamente caderas, rodillas y tobillos al llegar a la mitad del muslo.\nBuscá una extensión completa, rápida y violenta del cuerpo sin tirar activamente con los brazos.' WHERE name_en = 'Clean Pull';
UPDATE public.exercises SET instructions_es = 'Sostené la barra a la mitad del muslo con agarre al ancho de hombros y el torso inclinado hacia adelante con la espalda recta.\nEncogé los hombros llevándolos hacia las orejas sin perder velocidad en la ejecución.' WHERE name_en = 'Clean Shrug';
UPDATE public.exercises SET instructions_es = 'Ubicá la barra cerca de las espinillas, agarrala por fuera de las piernas y bajá la cadera con la espalda recta.\nRealizá el primer tirón empujando con los talones y extendiendo las rodillas con los brazos estirados.\nEjecutá el segundo tirón extendiendo caderas, rodillas y tobillos para acelerar la barra hacia arriba.\nMetete abajo de la barra rotando los codos, recibila en sentadilla frontal y ponete de pie empujando con los talones.\nFlexioná levemente las rodillas e impulsate con potencia hacia arriba para el envión.\nSepará los pies en tijera (uno adelante y otro atrás), bloqueá los brazos con la barra arriba de la cabeza y ponete de pie alineando las piernas.' WHERE name_en = 'Clean and Jerk';
UPDATE public.exercises SET instructions_es = 'Colocá los pies al ancho de hombros, flexioná caderas y rodillas con la espalda recta y agarrá la barra en pronación por fuera de las piernas.\nExtendé las rodillas subiendo hombros y caderas al mismo tiempo, manteniendo la barra pegada al cuerpo.\nSuperadas las rodillas, extendé con potencia tobillos, rodillas y caderas e impulsá la barra encogiéndote de hombros.\nEntrá rápido debajo de la barra cayendo en sentadilla y rotando los codos hacia adelante para apoyarla en los hombros.\nPonete completamente de pie manteniendo la barra apoyada sobre los hombros.\nEmpujá la barra por encima de la cabeza sin mover los pies al exhalar y bajala con control.' WHERE name_en = 'Clean and Press';
UPDATE public.exercises SET instructions_es = 'Recostate boca abajo y apoyá las manos sobre una mancuerna en posición vertical, manteniendo el torso firme, la punta de los pies apoyada y los brazos extendidos.\nBajá el cuerpo flexionando los codos mientras inhalás, manteniendo la cadera alineada.\nEmpujá hacia arriba extendiendo los codos hasta volver a la posición inicial mientras exhalás.\nPausá un instante arriba y repetí el movimiento hasta completar las repeticiones indicadas.' WHERE name_en = 'Close-Grip Push-Up off of a Dumbbell';
UPDATE public.exercises SET instructions_es = 'Tomá una barra con ambas manos, con las palmas mirando hacia arriba y separadas a pocos centímetros.\nParate derecho con los pies al ancho de hombros, la mirada al frente y los codos pegados al torso.\nSubí la barra hacia los hombros en un movimiento semicircular mientras exhalás y contraé los bíceps arriba durante un segundo.\nBajá la barra lentamente a la posición inicial mientras inhalás.\nRepetí el movimiento hasta completar las repeticiones indicadas.' WHERE name_en = 'Close-Grip Standing Barbell Curl';
UPDATE public.exercises SET instructions_es = 'Recostate boca arriba en el suelo con las piernas rectas y los brazos extendidos detrás de la cabeza.\nLlevá las rodillas al pecho, elevá la pelvis para despegar los glúteos del suelo y traé los brazos hacia adelante realizando un abdominal simultáneo.\nTras una breve pausa, volvé a la posición inicial.' WHERE name_en = 'Cocoons';
UPDATE public.exercises SET instructions_es = 'Cargá el peso y apoyá la barra en la flexión interna de los codos (agarre Zurcher), sujetando tu muñeca con la otra mano.\nLevantá el peso del suelo, mantené una postura erguida y caminá con pasos cortos y rápidos. Mirá hacia adelante mientras girás en círculo sin aguantar la respiración hasta completar las vueltas indicadas.' WHERE name_en = 'Conan''s Wheel';
UPDATE public.exercises SET instructions_es = 'Sentate en un banco plano con las piernas abiertas, los pies apoyados y una mancuerna en el suelo entre tus piernas.\nAgarrá la mancuerna con el brazo derecho, apoyá la parte posterior del brazo en la cara interna del muslo e iniciá con el brazo extendido.\nSubí la mancuerna hacia el hombro mientras exhalás y contraés el bíceps, manteniendo el brazo fijo apoyado en el muslo.\nBajá la mancuerna lentamente a la posición inicial mientras inhalás.\nCompletá las repeticiones indicadas y repetí el movimiento con el brazo izquierdo.' WHERE name_en = 'Concentration Curls';
UPDATE public.exercises SET instructions_es = 'Recostate boca arriba y flexioná las rodillas a 60 grados.\nMantené los pies apoyados en el suelo y ubicá las manos detrás de la cabeza sin ejercer presión.\nElevá el torso llevando el codo y hombro derecho en diagonal hacia la rodilla izquierda mientras exhalás y traés la rodilla hacia el hombro.\nVolvé a la posición inicial mientras inhalás y repetí con el codo izquierdo y la rodilla derecha.\nContinuá alternando lados hasta completar las repeticiones indicadas.' WHERE name_en = 'Cross-Body Crunch';
UPDATE public.exercises SET instructions_es = 'Parate derecho con una mancuerna en cada mano a los costados del cuerpo y las palmas mirando hacia adentro.\nLlevá la mancuerna derecha hacia el hombro izquierdo en diagonal mientras exhalás, sin girar la muñeca.\nBajá la mancuerna lentamente por el mismo recorrido mientras inhalás y repetí el mismo movimiento con el brazo izquierdo.\nContinuá alternando brazos hasta completar las repeticiones indicadas para cada lado.' WHERE name_en = 'Cross Body Hammer Curl';
UPDATE public.exercises SET instructions_es = 'Asegurá una banda elástica alrededor de un poste fijo.\nUbicate de espaldas al poste, agarrá las manijas de la banda y da un paso adelante para generar tensión.\nLevantá los brazos hacia los costados a la altura de los hombros formando una "T", con las palmas hacia adelante y los codos levemente flexionados.\nJuntá los brazos hacia el frente cruzando el pecho en un movimiento semicircular mientras exhalás y contraés los pectorales.\nVolvé lentamente a la posición inicial mientras inhalás.\nRepetí el movimiento hasta completar las repeticiones indicadas.' WHERE name_en = 'Cross Over - With Bands';
UPDATE public.exercises SET instructions_es = 'Colocá la barra sobre los cajones a la altura deseada y tomala por fuera de las piernas con agarre prono o en gancho.\nBajá la cadera llevando el peso a los talones, mantené la espalda recta, el pecho arriba y los hombros levemente por delante de la barra.\nIniciá el primer tirón empujando desde los talones y extendiendo las rodillas.\nMantené el ángulo de la espalda y los brazos extendidos con los codos hacia afuera.\nAl alcanzar la extensión completa, encogé los hombros, flexioná los brazos y meté los codos rápidamente por debajo de la barra.\nRecibí la barra sobre la parte delantera de los hombros, cerca de la garganta con las manos relajadas, cayendo en sentadilla frontal.\nBuscá la profundidad máxima de la sentadilla para estabilizar la carga.\nSubí empujando desde los talones, manteniendo el torso erguido y los codos arriba hasta quedar de pie.\nApoyá la barra nuevamente en los cajones.' WHERE name_en = 'Clean from Blocks';
UPDATE public.exercises SET instructions_es = 'Colocate en posición de flexión de brazos sobre el suelo, apoyando las manos al ancho de los hombros y la punta de los pies.\nMantené el cuerpo recto y alineado durante todo el movimiento.\nBajá el pecho hacia el suelo flexionando los codos.\nEmpujá el suelo con potencia extendiendo los codos hasta despegarte del piso.\nDesplazá el cuerpo lateralmente en el aire de 30 a 45 centímetros.\nGirá el cuerpo unos 30 grados en el aire para la siguiente repetición.\nVolvé a la posición inicial y repetí el movimiento avanzando en círculo hasta completar la vuelta.' WHERE name_en = 'Clock Push-Up';
UPDATE public.exercises SET instructions_es = 'Acostate sobre un banco plano.\nTomá la barra con agarre cerrado al ancho de los hombros, desenganchala y sostenela con los brazos extendidos sobre tu pecho.\nInhalá y bajá la barra lentamente hasta tocar el centro del pecho.\nMantené los codos pegados al torso durante toda la bajada para maximizar el trabajo de los tríceps.\nPausá un segundo abajo y exhalá mientras empujás la barra hacia arriba usando los tríceps.\nExtendé los brazos por completo, sostené un segundo la contracción y volvé a bajar despacio.\nRepetí el movimiento la cantidad de repeticiones indicadas.\nAl terminar, reubicá la barra en el soporte.' WHERE name_en = 'Close-Grip Barbell Bench Press';
UPDATE public.exercises SET instructions_es = 'Ubicá una mancuerna verticalmente sobre un banco plano.\nApoyá únicamente los hombros de forma perpendicular al banco, manteniendo la cadera baja y los pies firmes en el suelo.\nTomá la mancuerna con ambas manos apoyando las palmas contra la base superior y sostenela extendida sobre el pecho.\nIniciá el movimiento bajando la mancuerna hacia tu pecho.\nVolvé a la posición inicial extendiendo los codos.' WHERE name_en = 'Close-Grip Dumbbell Press';
UPDATE public.exercises SET instructions_es = 'Enganchá una banda elástica en cada extremo de la barra EZ y pisá el centro de la banda con un pie.\nParate erguido, tomá la barra con agarre supinado cerrado y pegá los codos al torso.\nFlexioná los codos para subir la barra manteniendo la parte superior de los brazos inmóvil y exhalá.\nLlevá la barra a la altura de los hombros, contraé los bíceps y sostené la posición un segundo.\nBajá la barra lentamente a la posición inicial mientras inhalás.\nRepetí las veces que estén indicadas.' WHERE name_en = 'Close-Grip EZ-Bar Curl with Band';
UPDATE public.exercises SET instructions_es = 'Acostate en un banco plano y sujetá la barra EZ cargada con un agarre cerrado.\nExtendé los brazos de forma perpendicular al suelo manteniendo los codos hacia adentro.\nInhalá y bajá la barra hacia la parte baja del pecho sin abrir los codos.\nExhalá y empujá la barra hacia la posición inicial extendiendo los codos con la fuerza de los tríceps.\nRepetí la secuencia.' WHERE name_en = 'Close-Grip EZ-Bar Press';
UPDATE public.exercises SET instructions_es = 'Parate derecho sosteniendo la barra Z por el agarre interno cerrado.\nOrientá las palmas hacia adelante, ligeramente inclinadas hacia adentro.\nMantené los codos pegados al torso.\nExhalá y flexioná los brazos hacia arriba contratando los bíceps.\nMové únicamente los antebrazos y mantené los brazos fijos.\nLlevá la barra hasta la altura de los hombros y apretá los bíceps un segundo.\nInhalá y bajá la barra lentamente a la posición inicial.\nRepetí la cantidad de repeticiones recomendada.' WHERE name_en = 'Close-Grip EZ Bar Curl';
UPDATE public.exercises SET instructions_es = 'Sentate en la máquina de jalón con la barra ancha enganchada en la polea alta.\nAjustá los rodillos a la altura de tus muslos para fijar el cuerpo.\nAgarrá la barra con las palmas mirando hacia adelante según el ancho de agarre indicado.\nExtendé los brazos, incliná el torso unos 30 grados hacia atrás y sacá pecho.\nExhalá y bajá la barra hacia la parte superior del pecho llevando los hombros y codos hacia abajo y atrás.\nContraé los músculos de la espalda un segundo al final del movimiento sin mover el torso ni tirar con los antebrazos.\nInhalá y subí la barra lentamente hasta extender los brazos y estirar los dorsales.\nRepetí la cantidad de repeticiones indicada.' WHERE name_en = 'Close-Grip Front Lat Pulldown';
UPDATE public.exercises SET instructions_es = 'Parate con los pies separados al ancho de tus hombros.\nDa un paso hacia atrás para hacer una estocada y flexioná la cadera y la rodilla delantera.\nRotá el torso hacia el lado de la pierna delantera a medida que bajás.\nPausá un instante, volvé a la posición inicial y repetí alternando de lado.' WHERE name_en = 'Crossover Reverse Lunge';
UPDATE public.exercises SET instructions_es = 'Parate derecho y sostené el peso a los costados del cuerpo.\nLevantá los brazos hacia los lados hasta que queden paralelos al suelo.\nMantené la posición estática todo el tiempo que podás.\nUsá un peso lo suficientemente pesado para llegar al fallo entre los 30 y 60 segundos.' WHERE name_en = 'Crucifix';
UPDATE public.exercises SET instructions_es = 'Recostate boca arriba con la espalda plana y las rodillas flexionadas a 60 grados.\nApoyá los pies planos en el suelo y extendé los brazos por encima de la cabeza cruzando las palmas.\nExhalá y elevá el torso despegando las escápulas del suelo.\nMantené los brazos alineados con la cabeza y el cuello en todo momento.\nContraé el abdomen un segundo en la cima del movimiento.\nInhalá y bajá lentamente a la posición inicial.\nRepetí la cantidad de repeticiones recomendada.' WHERE name_en = 'Crunch - Hands Overhead';
UPDATE public.exercises SET instructions_es = 'Recostate boca arriba con los pies sobre una pelota de ejercicio y las rodillas flexionadas a 90 grados.\nSepará los pies unos centímetros y juntá las puntas orientándolas hacia adentro.\nApoyá las manos suavemente a los lados de la cabeza con los codos hacia adentro.\nEmpujá la zona lumbar contra el suelo para aislar los abdominales.\nExhalá y elevá los hombros unos diez centímetros del suelo manteniendo la espalda baja apoyada.\nApretá fuerte el abdomen un segundo arriba sin usar impulso.\nInhalá y bajá despacio a la posición inicial.\nRepetí la cantidad de repeticiones recomendada.' WHERE name_en = 'Crunch - Legs On Exercise Ball';
UPDATE public.exercises SET instructions_es = 'Recostate boca arriba con las plantas de los pies apoyadas en el suelo o sobre un banco con las rodillas a 90 grados. Si usás un banco, separá los pies unos 10 cm y orientá las puntas hacia adentro hasta que se toquen.\nApoyá las manos suavemente a los lados de la cabeza con los codos hacia adentro, sin entrelazar los dedos detrás de la nuca.\nEmpujá la zona lumbar contra el suelo para aislar los abdominales y despegá los hombros de la colchoneta.\nExhalá, contraé el abdomen y elevá los hombros unos 10 cm manteniendo la espalda baja pegada al suelo. Mantené la contracción máxima arriba durante un segundo con un movimiento lento y controlado, sin usar inercia.\nInhalá y bajá lentamente hasta la posición inicial.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'Crunches';
UPDATE public.exercises SET instructions_es = 'Parate con una mancuerna en cada mano usando agarre prono. Elevá los brazos hasta que queden paralelos al suelo y dejá colgar los antebrazos en posición de espantapájaros para fijar la posición inicial.\nRealizá una rotación externa de hombros llevando los antebrazos hacia arriba hasta que las muñecas queden alineadas sobre los codos y los antebrazos perpendiculares al suelo.\nEmpujá las mancuernas hacia arriba extendiendo los codos hasta alinear los brazos sobre la cabeza.\nInhalá y regresá a la posición inicial invirtiendo los pasos de forma controlada.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'Cuban Press';
UPDATE public.exercises SET instructions_es = 'Sentate en el suelo con la espalda recta.\nCruzá la pierna derecha sobre la izquierda flexionando la rodilla y mantené la pierna izquierda extendida en el suelo.\nApoyá el brazo izquierdo sobre la pierna derecha y la mano derecha en el suelo detrás de vos.\nGirá el torso hacia la derecha y sostené la posición durante 10 a 20 segundos. Cambiá de lado.' WHERE name_en = 'Dancer''s Stretch';
UPDATE public.exercises SET instructions_es = 'Recostate boca arriba con los brazos extendidos hacia el techo.\nElevá las piernas flexionando caderas y rodillas a 90 grados.\nExhalá fuerte para bajar las costillas, pegá la zona lumbar al suelo, retrovertí la pelvis y contraé los glúteos para fijar la posición inicial.\nExtendé una pierna al frente bajándola casi hasta tocar el suelo.\nMantené la zona lumbar pegada al suelo y la pelvis estable evitando arquear la espalda.\nMantené la tensión muscular y regresá la pierna a la posición inicial.\nRepetí con la otra pierna alternando lados hasta completar la serie.' WHERE name_en = 'Dead Bug';
UPDATE public.exercises SET instructions_es = 'Para peso muerto con bandas cortas, enganchalas en la barra y pisalas; si usás bandas largas, anclalas a una base segura como un rack o mancuernas pesadas.\nUbicá tus pies y tu agarre, inhalá profundo, bajá la cadera y flexioná las rodillas hasta que las espinillas toquen la barra. Mirá al frente, mantené el pecho erguido y la columna neutra, y empujá desde los talones para subir la barra. Al superar las rodillas, llevá la barra hacia atrás retrayendo las escápulas y empujando la cadera hacia adelante.\nBajá la barra flexionando la cadera de forma controlada hasta apoyarla en el suelo.' WHERE name_en = 'Deadlift with Bands';
UPDATE public.exercises SET instructions_es = 'Colocá las cadenas en los extremos de la barra o colgalas en el centro para aumentar la resistencia a medida que subís.\nUbicate frente a la barra con los pies a la anchura de las caderas y el medio pie debajo de ella. Flexioná la cadera para tomar la barra al ancho de hombros con agarre prono o mixto. Inhalá profundo, bajá la cadera y flexioná las rodillas hasta que las espinillas toquen la barra.\nMirá al frente, mantené el pecho erguido y la columna neutra, y empujá con los talones para elevar la carga. Al pasar las rodillas, llevá la barra hacia atrás retrayendo las escápulas y empujando la cadera hacia adelante.\nBajá la barra flexionando la cadera de forma controlada hasta apoyarla en el suelo.' WHERE name_en = 'Deadlift with Chains';
UPDATE public.exercises SET instructions_es = 'Asegurá tus piernas en el extremo del banco declinado y recostate lentamente.\nTomá la barra con un agarre medio, sacala del soporte y mantenela extendida sobre tu pecho.\nInhalá y bajá la barra lentamente hasta tocar la parte inferior del pecho.\nPausá un segundo, exhalá y empujá la barra hacia arriba contrayendo el pecho.\nRepetí el movimiento hasta completar las repeticiones indicadas.\nAl terminar, reubicá la barra en el soporte.' WHERE name_en = 'Decline Barbell Bench Press';
UPDATE public.exercises SET instructions_es = 'Asegurá tus piernas en el extremo del banco declinado y recostate lentamente.\nTomá la barra con un agarre cerrado, sacala del soporte y mantenela extendida con los codos pegados al cuerpo.\nInhalá y bajá la barra hacia la parte inferior del pecho.\nExhalá y empujá la barra hacia arriba usando los tríceps hasta la posición inicial.\nInhalá, mantené los brazos fijos y bajá la barra hacia tu frente flexionando los antebrazos.\nExhalá y extendé los brazos hacia la posición inicial contrayendo los tríceps.\nRepetí hasta completar las repeticiones indicadas.' WHERE name_en = 'Decline Close-Grip Bench To Skull Crusher';
UPDATE public.exercises SET instructions_es = 'Asegurá tus piernas en el extremo del banco declinado y recostate.\nApoyá tus manos suavemente a los lados de la cabeza sin entrelazar los dedos.\nEmpujá la zona lumbar contra el banco y elevá los hombros.\nExhalá y contraé fuertemente el abdomen en la parte alta del movimiento.\nInhalá y bajá lentamente a la posición inicial.\nRepetí hasta completar las repeticiones indicadas.' WHERE name_en = 'Decline Crunch';
UPDATE public.exercises SET instructions_es = 'Asegurá tus piernas en el banco declinado y recostate con una mancuerna en cada mano sobre tus muslos.\nUbicá las mancuernas al ancho de tus hombros sobre el pecho.\nGirá las muñecas hacia adelante dejando las palmas mirando al frente.\nInhalá y bajá las mancuernas lentamente manteniendo los antebrazos perpendiculares al suelo.\nExhalá y empujá las mancuernas hacia arriba contrayendo el pecho.\nRepetí hasta completar las repeticiones indicadas.' WHERE name_en = 'Decline Dumbbell Bench Press';
UPDATE public.exercises SET instructions_es = 'Asegurá tus piernas en el banco declinado y recostate con una mancuerna en cada mano sobre tus muslos.\nExtendé los brazos perpendiculares al suelo con las palmas mirándose entre sí.\nFlexioná ligeramente los codos e inhalá mientras abrí los brazos en un arco amplio.\nExhalá y juntá las mancuernas en la posición inicial contrayendo el pecho.\nMantené la contracción un segundo y repetí hasta completar las repeticiones indicadas.' WHERE name_en = 'Decline Dumbbell Flyes';
UPDATE public.exercises SET instructions_es = 'Asegurá tus piernas en el banco declinado y recostate con una mancuerna en cada mano sobre tus muslos.\nExtendé los brazos perpendiculares al suelo con las palmas mirándose entre sí.\nInhalá, mantené los brazos fijos y bajá las mancuernas hacia tus orejas flexionando los antebrazos.\nExhalá y extendé los brazos hacia la posición inicial contrayendo los tríceps.\nRepetí hasta completar las repeticiones indicadas.' WHERE name_en = 'Decline Dumbbell Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Trabá las piernas al final del banco declinado y recostate lentamente.\nAgarrá la barra Z con un agarre estrecho y mantenela extendida sobre tu pecho con los codos hacia adentro.\nInhalá y bajá la barra lentamente hacia tu frente flexionando los antebrazos.\nEmpujá la barra a la posición inicial contrayendo los tríceps y exhalá.\nRepetí hasta completar las repeticiones recomendadas.' WHERE name_en = 'Decline EZ Bar Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Trabá las piernas al final del banco declinado y recostate lentamente.\nLevantá el torso del banco hasta alcanzar un ángulo de 35 a 45 grados respecto al suelo.\nColocá una mano al lado de la cabeza y la otra sobre tu muslo para marcar la posición inicial.\nElevá el torso lentamente girándolo hacia la izquierda hasta tocar la rodilla izquierda con el codo derecho mientras exhalás.\nMantené la contracción un segundo con el abdomen firme.\nBajá el cuerpo lentamente a la posición inicial mientras inhalás.\nCompletá las repeticiones del lado derecho y cambiá al lado izquierdo.' WHERE name_en = 'Decline Oblique Crunch';
UPDATE public.exercises SET instructions_es = 'Ubicate boca abajo, apoyá las manos abiertas y elevá los pies sobre una caja o banco para la posición inicial.\nBajá el cuerpo lentamente hasta que el pecho casi toque el suelo mientras inhalás.\nExhalá y empujá el torso hacia arriba volviendo a la posición inicial mientras contraés el pecho.\nPausá un instante arriba y repetí el movimiento las repeticiones indicadas.' WHERE name_en = 'Decline Push-Up';
UPDATE public.exercises SET instructions_es = 'Recostate boca arriba en un banco declinado y sujetate firmemente de la parte superior.\nMantené las piernas extendidas y paralelas al suelo activando el abdomen.\nExhalá y llevá las rodillas hacia el pecho elevando la cadera del banco.\nMantené la contracción un segundo y bajá las piernas a la posición inicial mientras inhalás.\nRepetí hasta completar las repeticiones indicadas.' WHERE name_en = 'Decline Reverse Crunch';
UPDATE public.exercises SET instructions_es = 'Ubica el banco declinado en la máquina Smith y ajustá la barra a la altura de tus brazos casi extendidos.\nAgarrá la barra en pronación con un agarre más ancho que tus hombros, destrabala y mantenela extendida sobre tu pecho.\nInhalá y bajá la barra de forma controlada flexionando los codos hasta rozar el torso.\nHacé una breve pausa y empujá la barra a la posición inicial extendiendo los codos mientras exhalás.\nRepetí el movimiento las repeticiones indicadas y volvé a trabar la barra al finalizar.' WHERE name_en = 'Decline Smith Press';
UPDATE public.exercises SET instructions_es = 'Parate sobre una plataforma o discos con los pies al ancho de cadera y la barra centrada.\nFlexioná la cadera y tomá la barra al ancho de hombros con las escápulas relajadas.\nInhalá profundo, bajá la cadera y flexioná las rodillas hasta que las espinillas toquen la barra.\nMantené la mirada al frente, el pecho erguido y empujá con los talones para subir la barra.\nAl superar las rodillas, llevá los hombros hacia atrás y empujá la cadera hacia adelante.\nBajá la barra flexionando la cadera y guiándola hacia el suelo.' WHERE name_en = 'Deficit Deadlift';
UPDATE public.exercises SET instructions_es = 'Ubicá dos cajones o bancos: uno de 30 a 40 cm y otro de 55 a 65 cm.\nParate sobre el cajón más bajo con los pies juntos cerca del borde y los brazos a los lados. Ubicá el otro cajón enfrente, a un metro de distancia.\nDejate caer del cajón, aterrizá con ambos pies e impulsate de inmediato.\nSaltá con máxima intensidad hacia arriba y adelante, usá los brazos para darte impulso y caé sobre el cajón más alto. Flexioná las rodillas para amortiguar el impacto.' WHERE name_en = 'Depth Jump Leap';
UPDATE public.exercises SET instructions_es = 'Sentate firmemente en la máquina de fondos, seleccioná el peso y agarrá los agarres con fuerza.\nPegá los codos a los costados del torso y mantenelos flexionados a 90 grados.\nExhalá y extendé los brazos hacia abajo contrayendo los tríceps. Mantené una leve flexión al final para conservar la tensión.\nInhalá y volvé lentamente a la posición inicial.\nRepetí durante el número determinado de repeticiones.' WHERE name_en = 'Dip Machine';
UPDATE public.exercises SET instructions_es = 'Ubicate en las barras paralelas sosteniendo tu cuerpo con los brazos extendidos.\nInhalá y bajá lentamente inclinando el torso unos 30 grados hacia adelante y abriendo ligeramente los codos hasta sentir el estiramiento en el pecho.\nExhalá y empujá con el pecho para volver a la posición inicial. Apretá el pectoral un segundo arriba.\nRepetí el movimiento durante las repeticiones indicadas.' WHERE name_en = 'Dips - Chest Version';
UPDATE public.exercises SET instructions_es = 'Ubicate en las barras paralelas con el cuerpo suspendido y los brazos casi extendidos.\nInhalá y bajá lentamente manteniendo el torso recto y los codos pegados al cuerpo. Bajá hasta formar un ángulo de 90 grados en los codos.\nExhalá y empujá con los tríceps para subir el cuerpo a la posición inicial.\nRepetí el movimiento durante las repeticiones indicadas.' WHERE name_en = 'Dips - Triceps Version';
UPDATE public.exercises SET instructions_es = 'Ubicá tu zona lumbar y cadera debajo del rodillo acolchado de la máquina de gemelos donkey.\nSujetá los agarres laterales, apoyá las puntas de los pies en el escalón y dejá los talones libres. Mantené las rodillas semiflexionadas sin bloquearlas.\nExhalá y elevá los talones lo más alto posible contrayendo los gemelos. Mantené la posición arriba durante un segundo sin mover las rodillas.\nInhalá y bajá lentamente los talones hasta sentir el estiramiento en los gemelos.\nRepetí el movimiento durante las repeticiones indicadas.' WHERE name_en = 'Donkey Calf Raises';
UPDATE public.exercises SET instructions_es = 'Colocá dos pesas rusas (kettlebells) entre tus pies. Llevá la cadera hacia atrás y mirá hacia el frente.\nCargá una pesa rusa hasta el hombro mientras sujetás la otra abajo.\nCon un movimiento fluido, bajá la pesa de arriba mientras subís la pesa de abajo.' WHERE name_en = 'Double Kettlebell Alternating Hang Clean';
UPDATE public.exercises SET instructions_es = 'Sostené una pesa rusa por la manija en cada mano.\nLlevá las pesas a los hombros mediante un movimiento de empuje, extendiendo piernas y cadera y girando las muñecas hacia adelante.\nHacé un descenso corto flexionando las rodillas y manteniendo el torso erguido.\nCambiá de dirección de inmediato empujando desde los talones para generar impulso.\nAprovechá el impulso y empujá las pesas por encima de la cabeza hasta extender los brazos por completo.\nCaé con los pies en posición de estocada, un pie adelante y otro atrás.\nMantené las pesas arriba, juntá los pies para ponerte de pie y bajá el peso para la siguiente repetición.' WHERE name_en = 'Double Kettlebell Jerk';
UPDATE public.exercises SET instructions_es = 'Llevá dos pesas rusas a tus hombros con un movimiento de empuje.\nHacé una sentadilla corta e invertí el movimiento rápidamente.\nUsá el impulso de las piernas para empujar las pesas rusas por encima de la cabeza.\nUna vez bloqueados los brazos arriba, bajá las pesas a los hombros y repetí.' WHERE name_en = 'Double Kettlebell Push Press';
UPDATE public.exercises SET instructions_es = 'Ubicá dos pesas rusas detrás de tus pies.\nFlexioná las rodillas y llevá la cadera hacia atrás para tomar las pesas.\nBalanceá las pesas rusas entre tus piernas con fuerza e invertí la dirección.\nEmpujá con la cadera y llevá las pesas por encima de la cabeza bloqueando los brazos en un solo movimiento fluido.' WHERE name_en = 'Double Kettlebell Snatch';
UPDATE public.exercises SET instructions_es = 'Ubicá una pesa rusa frente a tu pie delantero y llevá otra pesa por encima de la cabeza con el brazo opuesto.\nMantené el brazo extendido arriba y empujá la cadera hacia el lado de la pesa elevada.\nGirá los pies a cuarenta y cinco grados en dirección opuesta al brazo elevado.\nIncliná el torso hacia un lado flexionando la cadera y bajá lentamente hasta tomar la pesa del suelo.\nMantené la mirada fija en la pesa elevada en todo momento.\nPausá un segundo tras tomar la pesa del suelo y volvé a la posición inicial.' WHERE name_en = 'Double Kettlebell Windmill';
UPDATE public.exercises SET instructions_es = 'Parate con las rodillas ligeramente flexionadas.\nHacé una flexión corta y rápida de cadera y rodillas, e inmediatamente extendete para saltar lo más alto posible.\nAl subir, flexioná las rodillas llevando los talones hacia los glúteos.\nAterrizá con las rodillas semiflexionadas para absorber el impacto.' WHERE name_en = 'Double Leg Butt Kick';
UPDATE public.exercises SET instructions_es = 'Recostate boca abajo sobre una pelota de ejercicio.\nCon el abdomen apoyado en la pelota, avanzá caminando con las manos por el suelo y elevá las piernas.\nMantené codos y rodillas completamente extendidos.' WHERE name_en = 'Downward Facing Balance';
UPDATE public.exercises SET instructions_es = 'Agarrá una barra con agarre supino (palmas mirando hacia adelante) y pegá los codos al torso llevándolos hacia atrás para la posición inicial.\nExhalá y subí la barra arrastrándola pegada al torso, llevando los codos hacia atrás y sin elevar los hombros.\nBajá lentamente a la posición inicial manteniendo la barra en contacto constante con el torso.\nRepetí hasta completar las repeticiones indicadas.' WHERE name_en = 'Drag Curl';
UPDATE public.exercises SET instructions_es = 'Ubicá dos cajas o plataformas bajas a una distancia de 60 a 90 centímetros entre sí.\nColocate en posición de flexiones entre ellas, apoyando las manos sobre las plataformas.\nMantené una buena postura, empujá para salir de las plataformas y dejate caer apoyando las manos en el suelo al ancho de hombros, amortiguando el impacto con los brazos.' WHERE name_en = 'Drop Push';
UPDATE public.exercises SET instructions_es = 'Parate derecho con una mancuerna en cada mano a los lados, los codos pegados al torso y las palmas mirando a los muslos.\nSin mover los brazos, exhalá y subí la mancuerna derecha mientras girás la palma hacia adelante hasta la altura del hombro, apretando el bíceps un segundo.\nInhalá y bajá lentamente la mancuerna mientras rotás la palma de vuelta a la posición inicial.\nRepetí el movimiento con la mano izquierda para completar una repetición.\nContinuá alternando brazos hasta completar las repeticiones indicadas.' WHERE name_en = 'Dumbbell Alternate Bicep Curl';
UPDATE public.exercises SET instructions_es = 'Acostate en un banco plano con una mancuerna en cada mano apoyada sobre tus muslos y las palmas enfrentadas.\nUsá el impulso de los muslos para subir las mancuernas de a una al ancho de tus hombros.\nGirá las muñecas hacia adelante con las palmas mirando al frente y formá un ángulo de 90 grados entre brazos y antebrazos en la posición inicial.\nExhalá, empujá las mancuernas hacia arriba usando el pecho, bloqueá los brazos un segundo apretando el pectoral y bajá lentamente.\nRepetí el movimiento hasta completar las repeticiones indicadas.' WHERE name_en = 'Dumbbell Bench Press';
UPDATE public.exercises SET instructions_es = 'Tomá una mancuerna en cada mano y recostate en un banco plano con los pies apoyados en el suelo y las escápulas retraídas.\nMantené un agarre neutro con palmas enfrentadas y extendé los brazos verticalmente sobre el pecho para la posición inicial.\nFlexioná los codos y bajá los brazos a los lados hasta que las mancuernas lleguen al torso.\nHacé una pausa, extendé los codos y volvé a la posición inicial.' WHERE name_en = 'Dumbbell Bench Press with Neutral Grip';
UPDATE public.exercises SET instructions_es = 'Parate derecho con una mancuerna en cada mano, los codos pegados al torso y las palmas mirando hacia adelante para la posición inicial.\nMantené los brazos fijos, exhalá y subí las mancuernas flexionando los codos hasta la altura de los hombros, apretando el bíceps con una breve pausa arriba.\nInhalá y bajá lentamente las mancuernas a la posición inicial.\nRepetí hasta completar las repeticiones indicadas.' WHERE name_en = 'Dumbbell Bicep Curl';
UPDATE public.exercises SET instructions_es = 'Parate erguido con una mancuerna en cada mano y los pies a la anchura de los hombros.\nFlexioná caderas y rodillas llevando la cadera hacia atrás hasta apoyar las mancuernas en el suelo.\nSaltá con potencia extendiendo caderas, rodillas y tobillos para acelerar las mancuernas hacia arriba manteniendo los brazos extendidos y agarre neutro.\nFlexioná rápido caderas y rodillas para recibir el peso en sentadilla guiando las mancuernas a los hombros.\nExtendé caderas y rodillas para finalizar de pie con las mancuernas apoyadas sobre los hombros.' WHERE name_en = 'Dumbbell Clean';
UPDATE public.exercises SET instructions_es = 'Acostate en el suelo con las rodillas flexionadas y sostené una mancuerna en cada mano con los brazos extendidos sobre el pecho.\nBajá las mancuernas hasta que la parte posterior de los brazos toque el suelo.\nHacé una pausa abajo y empujá las mancuernas hacia arriba extendiendo los codos hasta juntarlas arriba.' WHERE name_en = 'Dumbbell Floor Press';
UPDATE public.exercises SET instructions_es = 'Recostate en un banco plano sostené una mancuerna en cada mano apoyada sobre los muslos con las palmas enfrentadas.\nUsá el impulso de los muslos para subir las mancuernas a la anchura de los hombros y sostenelas con los brazos casi extendidos.\nMantené una ligera flexión en los codos y bajá los brazos hacia los lados en un arco amplio mientras inhalás hasta sentir el estiramiento en el pecho.\nVolvé a la posición inicial apretando el pecho mientras exhalás siguiendo el mismo arco de movimiento.\nPausá un segundo arriba en máxima contracción y repetí las repeticiones indicadas.' WHERE name_en = 'Dumbbell Flyes';
UPDATE public.exercises SET instructions_es = 'Apoyá el pecho sobre un banco inclinado y agarrá una mancuerna en cada mano con agarre neutro.\nDejá los brazos completamente extendidos hacia abajo para iniciar el movimiento.\nRetraé las escápulas y flexioná los codos para llevar las mancuernas hacia tus costados.\nHacé una pausa arriba y volvé de forma controlada a la posición inicial.' WHERE name_en = 'Dumbbell Incline Row';
UPDATE public.exercises SET instructions_es = 'Sentate en un banco inclinado apoyando una mancuerna en cada mano sobre tus muslos.\nImpulsá las mancuernas con las piernas hacia tus hombros, recostate y extendé los brazos verticalmente con las palmas mirando al frente.\nMantené los brazos extendidos y elevá las mancuernas despegando los hombros del banco mientras exhalás.\nBajá las mancuernas a la posición inicial retrayendo las escápulas mientras inhalás.\nRepetí la cantidad de repeticiones recomendada.' WHERE name_en = 'Dumbbell Incline Shoulder Raise';
UPDATE public.exercises SET instructions_es = 'Parate con el torso erguido sostené una mancuerna a cada lado del cuerpo.\nDá un paso largo hacia adelante con la pierna derecha y bajá el torso de forma vertical mientras inhalás.\nAsegurate de que la rodilla delantera no supere la punta del pie y la tibia quede perpendicular al suelo.\nEmpujá con el talón delantero para volver a la posición inicial mientras exhalás.\nCompletá las repeticiones indicadas y repetí el ejercicio con la pierna izquierda.' WHERE name_en = 'Dumbbell Lunges';
UPDATE public.exercises SET instructions_es = 'Recostate boca abajo en un banco con inclinación leve (unos 15 grados) sosteniendo una mancuerna con una mano y sujetate de la pata del banco con la otra.\nUbicá la palma en agarre neutro mirando hacia tu torso y mantené el brazo extendido con el codo ligeramente flexionado.\nExhalá y elevá la mancuerna hacia el costado hasta que el codo quede a la altura del hombro y el brazo paralelo al suelo, aguantando un segundo la contracción arriba.\nInhalá y bajá lentamente la mancuerna a la posición inicial.\nRepetí la cantidad de repeticiones programadas.' WHERE name_en = 'Dumbbell Lying One-Arm Rear Lateral Raise';
UPDATE public.exercises SET instructions_es = 'Recostate boca abajo en un banco plano sosteniendo una mancuerna con una mano y apoyá la cabeza sobre la otra mano cruzada.\nFlexioná el codo a 90 grados entre el brazo y el antebrazo.\nElevá el brazo hasta que quede paralelo al suelo y perpendicular a tu torso, con el antebrazo colgando hacia el piso.\nExhalá y realizá una rotación externa del antebrazo llevando la mancuerna hacia adelante hasta que el antebrazo quede paralelo al suelo, sosteniendo la contracción un segundo.\nInhalá y volvé lentamente a la posición inicial.\nRepetí la cantidad de repeticiones programadas.' WHERE name_en = 'Dumbbell Lying Pronation';
UPDATE public.exercises SET instructions_es = 'Recostate boca abajo en un banco con inclinación leve (unos 15 grados) sosteniendo una mancuerna en cada mano.\nUbicá las palmas en agarre neutro mirando hacia tu torso y mantené los brazos extendidos con los codos ligeramente flexionados.\nExhalá y elevá los brazos hacia los lados hasta que los codos queden a la altura de los hombros y los brazos paralelos al suelo, aguantando un segundo arriba.\nInhalá y bajá lentamente las mancuernas a la posición inicial.\nRepetí la cantidad de repeticiones programadas.' WHERE name_en = 'Dumbbell Lying Rear Lateral Raise';
UPDATE public.exercises SET instructions_es = 'Recostate de costado en un banco plano sosteniendo una mancuerna con la mano de arriba y apoyá la cabeza sobre la otra mano.\nFlexioná el codo a 90 grados entre el brazo y el antebrazo.\nUbicá el antebrazo paralelo al suelo justo frente a vos, manteniendo el brazo pegado al torso.\nExhalá y rotá el antebrazo hacia arriba en un movimiento semicircular hasta que quede perpendicular al suelo, sosteniendo la contracción un segundo.\nInhalá y volvé lentamente a la posición inicial.\nRepetí la cantidad de repeticiones programadas y cambiá de lado.' WHERE name_en = 'Dumbbell Lying Supination';
UPDATE public.exercises SET instructions_es = 'Tomá una mancuerna y sentate en un banco con respaldo o quedate de pie bien derecho.\nLlevá la mancuerna a la altura del hombro y mantené el otro brazo extendido al costado, en la cintura o sujetando una superficie fija.\nGirá la muñeca para que la palma mire hacia adelante.\nExhalá y empujá la mancuerna hacia arriba hasta extender el brazo por completo.\nPausá un segundo arriba, inhalá y bajá lentamente a la posición inicial.\nRepetí la cantidad de repeticiones programadas y cambiá de brazo.' WHERE name_en = 'Dumbbell One-Arm Shoulder Press';
UPDATE public.exercises SET instructions_es = 'Tomá una mancuerna y sentate en un banco con respaldo o quedate de pie bien derecho.\nLlevá la mancuerna sobre la cabeza con el brazo extendido y vertical, al lado de la oreja.\nGirá la muñeca de modo que la palma mire hacia adelante y el meñique apunte hacia el techo.\nInhalá y bajá lentamente la mancuerna por detrás de la cabeza manteniendo el brazo inmóvil hasta sentir el estiramiento del tríceps.\nExhalá y volvé a la posición inicial extendiendo el tríceps sin mover el brazo, solo desplazando el antebrazo.\nRepetí la cantidad de repeticiones programadas y cambiá de brazo.' WHERE name_en = 'Dumbbell One-Arm Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Agarrá una mancuerna con una mano y parate derecho con la espalda recta y la mancuerna apoyada sobre el muslo.\nMantené el otro brazo libre extendido hacia un costado, en la cintura o sujetado a una superficie fija.\nExhalá y elevá la mancuerna cerca del cuerpo usando el hombro hasta llegar cerca del mentón, manteniendo el codo más alto que el antebrazo.\nInhalá y bajá la mancuerna lentamente a la posición inicial.\nRepetí las repeticiones indicadas y cambiá de brazo.' WHERE name_en = 'Dumbbell One-Arm Upright Row';
UPDATE public.exercises SET instructions_es = 'Agarrá una mancuerna en cada mano y recostate boca abajo en un banco inclinado con los hombros en la parte superior.\nDejá caer los brazos extendidos hacia adelante, de forma perpendicular al suelo.\nPegá los codos a los costados del torso y orientá las palmas hacia adelante.\nExhalá y flexioná los bíceps para subir las mancuernas, manteniendo los brazos fijos y moviendo solo los antebrazos.\nBajá las mancuernas lentamente hasta extender los brazos por completo.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'Dumbbell Prone Incline Curl';
UPDATE public.exercises SET instructions_es = 'Agarrá una mancuerna en cada mano y parate derecho con los codos levemente flexionados y las palmas mirando hacia tus muslos.\nExhalá y elevá las mancuernas a los costados del cuerpo hasta la altura del mentón, guiando el movimiento con los codos arriba.\nInhalá y bajá las mancuernas lentamente a la posición inicial.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'Dumbbell Raise';
UPDATE public.exercises SET instructions_es = 'Parate derecho sosteniendo una mancuerna a cada lado del cuerpo.\nInhalá y da un paso largo hacia atrás, bajando el torso erguido y evitando que la rodilla delantera supere la punta del pie.\nExhalá y empujá contra el suelo para volver a la posición inicial.\nRepetí el movimiento alternando con la otra pierna.' WHERE name_en = 'Dumbbell Rear Lunge';
UPDATE public.exercises SET instructions_es = 'Sostené una mancuerna liviana a cada lado del cuerpo con los pulgares apuntando hacia arriba.\nElevá los brazos completamente extendidos en un ángulo diagonal de 30 grados respecto al centro.\nSubí hasta que los brazos queden paralelos al suelo y volvé lentamente a la posición inicial.' WHERE name_en = 'Dumbbell Scaption';
UPDATE public.exercises SET instructions_es = 'Sostené una mancuerna pegada al pecho con ambas manos y sentate en un banco mirando hacia un cajón.\nApoyá los pies firmes, inclinate hacia adelante y extendé caderas y rodillas para saltar hacia el cajón.\nAterrizá con ambos pies sobre el cajón amortiguando el impacto con caderas y rodillas.\nBajá del cajón y regresá a la posición inicial.' WHERE name_en = 'Dumbbell Seated Box Jump';
UPDATE public.exercises SET instructions_es = 'Ubicá un bloque en el suelo a unos 30 cm de un banco plano.\nSentate en el banco y apoyá una mancuerna sobre tu muslo izquierdo, justo por encima de la rodilla.\nApoyá el metatarso del pie izquierdo sobre el bloque para fijar la posición inicial.\nElevá la punta del pie lo más alto posible al exhalar y contraé el gemelo durante un segundo.\nBajá lentamente a la posición inicial sintiendo el estiramiento.\nCompletá las repeticiones indicadas y repetí con la pierna derecha.' WHERE name_en = 'Dumbbell Seated One-Leg Calf Raise';
UPDATE public.exercises SET instructions_es = 'Sentate en un banco con respaldo apoyando una mancuerna sobre cada muslo.\nSubí las mancuernas a la altura de los hombros de a una, impulsándote con los muslos.\nGirá las muñecas para que las palmas queden mirando hacia adelante en la posición inicial.\nEmpujá las mancuernas hacia arriba al exhalar hasta que se toquen arriba.\nPausá un instante en la posición de máxima contracción y bajá el peso lentamente mientras inhalás.\nRepetí hasta completar las repeticiones indicadas.' WHERE name_en = 'Dumbbell Shoulder Press';
UPDATE public.exercises SET instructions_es = 'Parate derecho con una mancuerna en cada mano a los costados y las palmas mirando al torso.\nElevá los hombros lo más alto posible al exhalar manteniendo los brazos extendidos y sostené la contracción un segundo.\nBajá las mancuernas de manera controlada a la posición inicial.\nRepetí hasta completar las repeticiones indicadas.' WHERE name_en = 'Dumbbell Shrug';
UPDATE public.exercises SET instructions_es = 'Parate recto con los pies al ancho de hombros, sostené una mancuerna con la mano izquierda y apoyá la mano derecha en la cintura.\nIncliná el torso hacia la derecha al inhalar, manteniendo la espalda recta y la mirada al frente.\nSostené un segundo y volvé a la posición inicial exhalando.\nIncliná el torso hacia la izquierda, sostené un segundo y volvé al centro.\nRepetí las repeticiones indicadas y cambiá de mano.' WHERE name_en = 'Dumbbell Side Bend';
UPDATE public.exercises SET instructions_es = 'Parate recto sosteniendo una mancuerna en cada mano a los costados del cuerpo.\nSepará los pies al ancho de hombros con las puntas levemente hacia afuera, mantené la espalda recta y la mirada al frente.\nFlexioná las rodillas y bajá lentamente el torso hasta que los muslos queden paralelos al suelo.\nEmpujá el suelo principalmente desde los talones al exhalar para extender las piernas y volver a la posición inicial.\nRepetí por las repeticiones indicadas.' WHERE name_en = 'Dumbbell Squat';
UPDATE public.exercises SET instructions_es = 'Parate recto con un banco plano detrás tuyo y una mancuerna en cada mano a los costados.\nSepará los pies al ancho de hombros con las puntas levemente hacia afuera, mantené la espalda recta y la mirada al frente.\nFlexioná las rodillas e inhalá mientras bajás el torso lentamente hasta apenas rozar el banco.\nEmpujá el suelo desde los talones al exhalar para extender las piernas y volver a la posición inicial.\nRepetí por las repeticiones indicadas.' WHERE name_en = 'Dumbbell Squat To A Bench';
UPDATE public.exercises SET instructions_es = 'Parate derecho sosteniendo una mancuerna en cada mano con las palmas mirando hacia tus piernas.\nApoyá el pie derecho sobre la plataforma elevada. Empujá con el talón extendiendo la cadera y la rodilla derecha para subir el cuerpo y apoyá el pie izquierdo arriba. Exhalá al hacer la fuerza.\nInhalá y bajá primero con el pie izquierdo flexionando la cadera y rodilla derechas. Volvé a la posición inicial apoyando el pie derecho al lado del izquierdo.\nCompletá las repeticiones indicadas con la pierna derecha y luego repetí con la izquierda.' WHERE name_en = 'Dumbbell Step Ups';
UPDATE public.exercises SET instructions_es = 'Recostate en un banco plano sosteniendo dos mancuernas directamente sobre tus hombros con los brazos extendidos a 90 grados respecto al torso.\nMantené las palmas mirando hacia adelante y los codos cerrados en esta posición inicial.\nInhalá y bajá lentamente las mancuernas hasta la altura de tus orejas manteniendo los brazos firmes.\nExhalá y empujá con los tríceps para volver a la posición inicial.' WHERE name_en = 'Dumbbell Tricep Extension -Pronated Grip';
UPDATE public.exercises SET instructions_es = 'Parate con los pies separados al ancho de hombros en la posición inicial.\nMantené los brazos extendidos y balancealos hacia adelante y arriba entre 5 y 10 veces, aumentando el rango de movimiento hasta llevarlos por encima de la cabeza.' WHERE name_en = 'Dynamic Back Stretch';
UPDATE public.exercises SET instructions_es = 'Parate con los brazos extendidos al frente y las manos juntas en la posición inicial.\nMantené los brazos rectos, abrilos rápidamente hacia atrás lo más que puedas y volvé a juntarlos al frente. Repetí entre 5 y 10 veces aumentando la velocidad.' WHERE name_en = 'Dynamic Chest Stretch';
UPDATE public.exercises SET instructions_es = 'Parate derecho tomando una barra EZ por el agarre ancho exterior con las palmas hacia adelante y los codos pegados al torso.\nMantené los brazos firmes, exhalá y flexioná los antebrazos hacia arriba contrayendo los bíceps.\nSubí la barra hasta el nivel de los hombros, mantené la posición un segundo y apretá los bíceps.\nInhalá y bajá la barra lentamente hasta la posición inicial.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'EZ-Bar Curl';
UPDATE public.exercises SET instructions_es = 'Recostate en el banco y sostené la barra EZ con un agarre cerrado, codos hacia adentro y brazos perpendiculares al suelo.\nMantené los brazos firmes e inhalá mientras flexionás los codos para bajar la barra hasta tu frente. Pausá un segundo ahí.\nExtendé los codos y exhalá para llevar la barra de vuelta a la posición inicial.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'EZ-Bar Skullcrusher';
UPDATE public.exercises SET instructions_es = 'Sentate o parate con los pies ligeramente separados.\nApoyá las manos en los hombros con los codos a la altura de los hombros y apuntando hacia afuera.\nDibujá círculos lentos con los codos, exhalando al iniciar el movimiento e inhalando al completarlo.' WHERE name_en = 'Elbow Circles';
UPDATE public.exercises SET instructions_es = 'Acostate en el suelo y cruzá la pierna derecha sobre la rodilla izquierda flexionada. Entrelazá las manos detrás de la cabeza con las escápulas apoyadas. Esta es tu posición inicial.\nFlexioná la columna y rotá el torso para llevar el codo izquierdo hacia la rodilla derecha.\nVolvé a la posición inicial, completá las repeticiones deseada y cambiá de lado.' WHERE name_en = 'Elbow to Knee';
UPDATE public.exercises SET instructions_es = 'Parate derecho.\nApoyá ambas manos en la zona lumbar con los dedos apuntando hacia abajo y los codos hacia afuera.\nLlevá los codos suavemente hacia atrás intentando juntarlos.' WHERE name_en = 'Elbows Back';
UPDATE public.exercises SET instructions_es = 'Colocá una barra cargada en el rack a la altura de los hombros y ubicá una plataforma baja detrás tuyo.\nApoyá la barra sobre la parte alta de la espalda, mantené el torso firme y subí a la plataforma con ambos pies. Esta es tu posición inicial.\nDa un paso hacia atrás con una pierna y bajá flexionando la cadera y las rodillas hasta que la rodilla toque el piso.\nHacé una pausa, extendé la cadera y las rodillas para subir, y volvé a la posición inicial antes de alternar de pierna.' WHERE name_en = 'Elevated Back Lunge';
UPDATE public.exercises SET instructions_es = 'Ubicá una plataforma de unos 10 a 15 cm sobre el asiento de la máquina de remo con polea.\nSentate en la máquina y apoyá los pies en los soportes delanteros manteniendo las rodillas ligeramente flexionadas.\nInclinate con la espalda alineada y agarrá el agarre en V.\nExtendé los brazos y llevá el torso hacia atrás hasta formar un ángulo de 90 grados con las piernas, sacando pecho. Esta es tu posición inicial.\nMantené el torso fijo, exhalá y tirá del agarre hacia el abdomen pegando los codos al cuerpo. Contraé los dorsales durante un segundo y volvé lentamente a la posición inicial mientras inhalás.\nRepetí hasta completar las repeticiones indicadas.' WHERE name_en = 'Elevated Cable Rows';
UPDATE public.exercises SET instructions_es = 'Subite a la elíptica y seleccioná un programa o el modo manual en la consola. Ingresá tu edad y peso para estimar el gasto calórico y ajustá la inclinación para modificar la intensidad.\nSujetá los agarres para monitorear tu frecuencia cardíaca y mantener la intensidad adecuada.' WHERE name_en = 'Elliptical Trainer';
UPDATE public.exercises SET instructions_es = 'Recostá la zona lumbar sobre la fitball.\nApoyá los pies firmemente en el suelo con las rodillas flectadas.\nCruzá las manos sobre el pecho o mantenelas a los lados del cuerpo.\nBajá el torso para estirar los abdominales manteniendo el cuello firme.\nFlexioná la cintura contrayendo los abdominales y elevá los hombros hacia arriba.\nExhalá al subir y sostené la contracción un segundo.\nInhalá mientras bajás lentamente a la posición inicial.\nRepetí la cantidad recomendada de repeticiones.' WHERE name_en = 'Exercise Ball Crunch';
UPDATE public.exercises SET instructions_es = 'Colocate en posición de flexión de brazos con las manos apoyadas al ancho de los hombros.\nApoyá las espinillas sobre la fitball con las piernas extendidas.\nMantené la espalda recta y el torso firme.\nExhalá y llevá las rodillas hacia el pecho haciendo rodar la fitball.\nContraé los abdominales y sostené la posición un segundo.\nInhalá y extendé las piernas lentamente hasta volver a la posición inicial.\nRepetí la cantidad recomendada de repeticiones.' WHERE name_en = 'Exercise Ball Pull-In';
UPDATE public.exercises SET instructions_es = 'Recostate boca arriba en el suelo y sujetá la pesa rusa por la manija con una mano.\nFlexioná la pierna del mismo lado cruzando la rodilla hacia la línea media del cuerpo.\nEmpujá la pesa rusa hacia arriba extendiendo el codo por completo.\nBajá la pesa rusa de forma controlada hasta la posición inicial.' WHERE name_en = 'Extended Range One-Arm Kettlebell Floor Press';
UPDATE public.exercises SET instructions_es = 'Acostate de costado sobre un banco plano y apoyá la cabeza sobre tu brazo libre.\nSujetá la mancuerna con la otra mano y flexioná el codo a 90 grados.\nPegá el brazo al torso manteniendo el antebrazo frente a vos.\nExhalá y rotá el antebrazo hacia arriba manteniendo el codo pegado al cuerpo.\nSostené la contracción arriba durante un segundo.\nInhalá y bajá lentamente a la posición inicial.\nRepetí las repeticiones recomendadas y cambiá de lado.' WHERE name_en = 'External Rotation';
UPDATE public.exercises SET instructions_es = 'Asegurá la banda elástica a un poste a la altura de tu codo.\nParate de costado a la banda y sujetá el extremo con la mano más alejada.\nPegá el codo al costado del cuerpo y mantenelo flectado a 90 grados.\nCruzá la mano por delante de tu torso para iniciar el movimiento.\nRotá el antebrazo hacia afuera manteniendo el codo fijo en su lugar.\nLlevá la banda lo más lejos posible, pausá un segundo y volvé a la posición inicial.' WHERE name_en = 'External Rotation with Band';
UPDATE public.exercises SET instructions_es = 'Ajustá la polea a la altura de tu codo.\nParate de costado a la máquina y agarrá la manija con la mano más alejada.\nPegá el codo al costado de tu cuerpo y mantenelo flectado a 90 grados.\nCruzá la mano por delante del torso para iniciar el movimiento.\nRotá el antebrazo hacia afuera sin despegar el codo de tu cuerpo.\nPausá un segundo y regresá de manera controlada a la posición inicial.' WHERE name_en = 'External Rotation with Cable';
UPDATE public.exercises SET instructions_es = 'Pará frente a la polea alta con cuerda o manijas.\nTirá el peso hacia tu cara separando las manos.\nMantené los brazos superiores paralelos al suelo.' WHERE name_en = 'Face Pull';
UPDATE public.exercises SET instructions_es = 'Pará entre los implementos de peso.\nAgarrá las manijas y levantá empujando con los talones.\nMantené la espalda recta y la cabeza arriba.\nAndá con pasos cortos y rápidos respirando.\nRecorré la distancia lo más rápido posible.' WHERE name_en = 'Farmer''s Walk';
UPDATE public.exercises SET instructions_es = 'Recostá una pierna ligeramente adelante.\nSaltá con el patrón derecha-derecha-paso a izquierda-izquierda-paso.\nMantené el contacto con el suelo y minimizá el tiempo en el aire.' WHERE name_en = 'Fast Skipping';
UPDATE public.exercises SET instructions_es = 'Agarrá la barra con las palmas hacia arriba a la anchura de los hombros.\nApoyá los pies planos, ligeramente más abiertos que los hombros.\nDejá caer la barra hasta que se detenga en la última articulación de los dedos.\nCerrá las manos para subir la barra mientras exhalás y mantené la contracción arriba.' WHERE name_en = 'Finger Curls';
UPDATE public.exercises SET instructions_es = 'Colocá un banco plano entre dos poleas bajas alineando el pecho con los cables.\nRecostá en el banco con los pies apoyados en el suelo.\nTomá las manijas con las palmas hacia arriba.\nExtendé los brazos a los lados con una leve flexión en los codos.\nMantené esa flexión constante durante todo el movimiento.\nEmpujá los cables hacia adelante en un semicírculo hasta que las manos se toquen.\nApretá el pecho y exhalá al subir.\nMantené la contracción un segundo arriba.\nVolvé lentamente a la posición inicial.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Flat Bench Cable Flyes';
UPDATE public.exercises SET instructions_es = 'Recostá en una colchoneta o banco plano con las piernas colgando.\nApoyá las manos bajo los glúteos o a los lados del banco.\nExtendé las piernas rectas.\nDoblá las rodillas y tirá los muslos hacia el abdomen exhalando.\nLlevá las rodillas cerca del pecho.\nMantené la posición contraída un segundo.\nInhalá y volvé lentamente a la posición inicial.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Flat Bench Leg Pull-In';
UPDATE public.exercises SET instructions_es = 'Recostá de rodillas con el torso erguido.\nExtendé las rodillas para bajar sin doblar la cadera.\nLlevá las manos al suelo para empujar y volver arriba.' WHERE name_en = 'Floor Glute-Ham Raise';
UPDATE public.exercises SET instructions_es = 'Recostá en el suelo con la cabeza cerca del rack.\nBajá la barra hasta el pecho o estómago.\nApoyá los codos contra el suelo y mantené la pausa.\nEmpujá la barra hacia arriba con fuerza.' WHERE name_en = 'Floor Press';
UPDATE public.exercises SET instructions_es = 'Ajustá los ganchos a la altura correcta.\nColgá las cadenas de los extremos de la barra, lejos de las discos.\nRecostá en el piso con la cabeza cerca del rack.\nJuntá las escápulas y sacá la barra de los ganchos.\nBajá la barra hacia el pecho o estómago, apretándola.\nMantené los codos pegados al cuerpo.\nBajá hasta que los brazos toquen el piso y pausá.\nEmpujá la barra hacia arriba rápido, alineando codos y muñecas.' WHERE name_en = 'Floor Press with Chains';
UPDATE public.exercises SET instructions_es = 'Recostá boca abajo en el banco con la cadera en el borde.\nExtendé las piernas con las puntas hacia arriba.\nApretá glúteos e isquiotibiales y alineá las piernas con la cadera.\nLevantá la pierna izquierda más alto que la derecha.\nBajá la izquierda mientras levantás la derecha.\nAlterná las piernas de forma controlada hasta completar las repeticiones.' WHERE name_en = 'Flutter Kicks';
UPDATE public.exercises SET instructions_es = 'Sentate sin zapatos.\nApoyá el pie sobre el rodillo en la zona de la bóveda plantar.\nPresioná firmemente y rodá sobre la bóveda.\nMantené la posición entre 10 y 30 segundos.\nCambiá de pie.' WHERE name_en = 'Foot-SMR';
UPDATE public.exercises SET instructions_es = 'Conectá la cadena o cuerda al trineo.\nParate de espaldas al trineo agarrando un mango en cada mano.\nAvanzá un paso hacia adelante.\nIncliná el cuerpo y extendé piernas y caderas.\nPresioná las manos hacia adelante extendiendo los codos.\nRepetí hasta volver a la posición inicial.' WHERE name_en = 'Forward Drag with Press';
UPDATE public.exercises SET instructions_es = 'Colocá la barra en los hombros y extendé los brazos.\nEmpujá los hombros hacia adelante para crear una repisa.\nMantené la barra en contacto con la garganta.\nNo redondees la espalda torácica.\nFlexioná rodillas y caderas para sentarte entre las piernas.\nMantené el torso erguido y los brazos arriba.\nBajá hasta que los isquiotibiales toquen las pantorrillas.\nEmpujá con el antepié para extender rodillas y caderas.' WHERE name_en = 'Frankenstein Squat';
UPDATE public.exercises SET instructions_es = 'Cruzá los brazos sobre el pecho.\nMantené la cabeza arriba y la espalda recta.\nSepará los pies a la anchura de los hombros.\nBajá agachándote hasta que los muslos queden paralelos al suelo.\nSaltá hacia arriba empujando con las puntas de los pies.\nExhalá durante el salto.\nAl tocar el suelo, agachate y saltá de nuevo.\nRepetí la cantidad de veces indicada.' WHERE name_en = 'Freehand Jump Squat';
UPDATE public.exercises SET instructions_es = 'Pará con las manos detrás de la cabeza.\nIncliná el torso hacia adelante.\nSaltá hacia adelante varios pies.\nAterrizá suavemente absorbiendo el impacto con las piernas.\nSaltá de nuevo inmediatamente.\nRepetí de 5 a 10 veces.' WHERE name_en = 'Frog Hops';
UPDATE public.exercises SET instructions_es = 'Recostá boca arriba con las piernas extendidas.\nDoblá las rodillas y juntá las plantas de los pies.\nMantené los muslos externos apoyados en el suelo.\nEmpujá las plantas de los pies hacia arriba.\nCruzá los brazos tocando los hombros opuestos.\nExhalá y elevá el torso a un cuarto de sentadilla.\nMantené la posición un segundo.\nInhala y bajá lentamente.\nRepetí las veces indicadas.' WHERE name_en = 'Frog Sit-Ups';
UPDATE public.exercises SET instructions_es = 'Colocá la barra en el rack a tu altura.\nApoyá la barra sobre los deltoides y cruzá los brazos.\nEmpujá con las piernas para despegar la barra.\nSepará los pies a la anchura de los hombros.\nMantené la cabeza arriba y la espalda recta.\nFlexioná las rodillas bajando la barra.\nDescendé hasta que los muslos queden bajo la paralela.\nEmpujá el suelo con el pie medio para subir.\nRetorná a la posición inicial.\nRepetí las veces indicadas.' WHERE name_en = 'Front Barbell Squat';
UPDATE public.exercises SET instructions_es = 'Colocá un banco plano detrás de vos.\nApoyá la barra sobre los deltoides y cruzá los brazos.\nEmpujá con las piernas para despegar la barra.\nSepará los pies a la anchura de los hombros.\nMantené la cabeza arriba y la espalda recta.\nFlexioná las rodillas bajando la barra.\nDescendé hasta tocar el banco con los glúteos.\nEmpujá el suelo con el talón para subir.\nRetorná a la posición inicial.\nRepetí las veces indicadas.' WHERE name_en = 'Front Barbell Squat To A Bench';
UPDATE public.exercises SET instructions_es = 'Colocá una caja de 1 a 2 pies de altura frente a vos.\nPará con los pies separados al ancho de los hombros.\nHacé un sentadilla corta y llevá los brazos atrás.\nSaltá extendiendo caderas, rodillas y tobillos.\nLlevá los brazos hacia adelante y arriba.\nAterrizá en la caja con las rodillas flexionadas.\nBajá del cajón un pie a la vez.' WHERE name_en = 'Front Box Jump';
UPDATE public.exercises SET instructions_es = 'Elegí el peso en la polea baja.\nAgarrá el mango con la mano izquierda.\nMirá de espaldas a la polea.\nDejá el brazo recto hacia abajo, frente a los muslos.\nMantené el torso quieto.\nLevantá el brazo hacia adelante con el codo levemente flexionado.\nMantené las palmas hacia abajo.\nSubí hasta que el brazo quede ligeramente por encima de la horizontal.\nExhalá al subir y hacé una pausa.\nInhalá al bajar el brazo lentamente.\nRepetí con el brazo derecho.' WHERE name_en = 'Front Cable Raise';
UPDATE public.exercises SET instructions_es = 'Colocá conos separados unos pocos pies entre sí.\nPará frente al primer cono con los pies a la anchura de los hombros.\nSaltá con ambos pies por encima del primer cono, balanceando los brazos.\nAterrizá flexionando las rodillas para absorber el impacto.\nRebotá inmediatamente para saltar el siguiente cono.\nRepetí hasta superar todos los conos.' WHERE name_en = 'Front Cone Hops (or hurdle hops)';
UPDATE public.exercises SET instructions_es = 'Elegí mancuernas y pará con el torso recto.\nMantené las mancuernas frente a los muslos, a la altura de los brazos, con las palmas hacia abajo.\nLevantá la mancuerna izquierda hacia adelante con una leve flexión en el codo.\nSubí hasta que el brazo quede ligeramente por encima de la paralela al suelo.\nExhalá al subir y mantené la posición un segundo.\nInhala al bajar lentamente la mancuerna izquierda.\nSimultáneamente, levantá la mancuerna derecha.\nAlterná los brazos hasta completar las repeticiones indicadas.' WHERE name_en = 'Front Dumbbell Raise';
UPDATE public.exercises SET instructions_es = 'Pará derecho y agarrá la placa con ambas manos a la altura de la cintura.\nMantené los brazos extendidos con una leve flexión en los codos.\nSubí la placa lentamente hasta un poco por encima de los hombros.\nMantené la contracción un segundo sin balancear el peso.\nBajá la placa lentamente hasta la posición inicial.' WHERE name_en = 'Front Plate Raise';
UPDATE public.exercises SET instructions_es = 'Recostá en un banco plano y agarrá la barra con las palmas hacia abajo.\nColocá la barra sobre los muslos y extendé los brazos con una leve flexión.\nSubí la barra en un movimiento semicircular manteniendo los brazos rectos.\nLlevá la barra hasta que quede sobre la cabeza con las palmas hacia el techo.\nBajá la barra lentamente hasta la posición inicial.' WHERE name_en = 'Front Raise And Pullover';
UPDATE public.exercises SET instructions_es = 'Colocá la barra en el soporte un poco por debajo de los hombros.\nApoyá la barra sobre los deltoides, presionando hacia las clavículas y rozando la garganta.\nAjustá las manos con un agarre limpio, tocando la barra solo con los dedos.\nLevantá la barra empujando con las piernas y enderezando el torso.\nRetirate del soporte y separá las piernas a la anchura de los hombros, con los pies ligeramente hacia afuera.\nMantené la cabeza y los codos arriba.\nDobrá las rodillas y sentate entre las piernas.\nBajá hasta que los isquiotibiales toquen las pantorrillas.\nEmpujá las rodillas hacia afuera para alinearlas con los pies.\nSubí la barra exhalando, empujando el suelo con los talones o la planta del pie.\nEnderezá las piernas para volver a la posición inicial.' WHERE name_en = 'Front Squat (Clean Grip)';
UPDATE public.exercises SET instructions_es = 'Limpiá dos kettlebells hasta los hombros.\nExtendé las piernas y caderas mientras tirás de los kettlebells hacia los hombros.\nGirá las muñecas durante el movimiento.\nMirá siempre al frente.\nAgachate lo más bajo posible y hacé una pausa abajo.\nEmpujá las rodillas hacia afuera mientras bajás.\nMantené el torso erguido, con la cabeza y el pecho arriba.\nSubí empujando con los talones y repetí.' WHERE name_en = 'Front Squats With Two Kettlebells';
UPDATE public.exercises SET instructions_es = 'Agarrá dos mancuernas y parate con el torso recto.\nMantené los pesos frente a los muslos, a la altura de los brazos, con las palmas hacia adentro.\nSubí los pesos hacia adelante manteniendo el torso quieto.\nDejá una leve flexión en los codos y las palmas hacia abajo.\nLlegá hasta que los brazos queden ligeramente por encima de la horizontal.\nExhalá al subir y sostené un segundo arriba.\nInhalá al bajar los pesos lentamente hasta la posición inicial.\nRepetí la cantidad de veces indicada.' WHERE name_en = 'Front Two-Dumbbell Raise';
UPDATE public.exercises SET instructions_es = 'Parate o sentate en un banco alto.\nAgarrá las poleas altas con las manos cruzadas y las palmas hacia adelante.\nMantené el pecho arriba y una leve curvatura en la espalda baja.\nJalá los manubrios hacia abajo en un arco, como en un jalón normal.\nGirá las manos para que las palmas se miren en la posición final.\nVolvé lentamente a la posición inicial.\nRepetí el movimiento.' WHERE name_en = 'Full Range-Of-Motion Lat Pulldown';
UPDATE public.exercises SET instructions_es = 'Agarrá la barra con agarre supino a la anchura de los hombros.\nColgá con los brazos extendidos, pecho afuera y espalda inclinada hacia atrás.\nJalate hacia la barra manteniendo la columna arqueada y la cabeza lejos de la barra.\nExhalá al subir.\nLlevá la clavícula por encima de la barra hasta que el esternón toque la barra.\nMantené la contracción un segundo.\nBajá lentamente inhalando hasta la posición inicial.\nRepetí las veces indicadas.' WHERE name_en = 'Gironda Sternum Chins';
UPDATE public.exercises SET instructions_es = 'Ajustá el equipo a tu cuerpo.\nAcostate boca abajo con los pies en la placa y las rodillas justo detrás del cojín.\nPartí de la posición baja con la espalda arqueada.\nFlexioná las rodillas empujando con las puntas de los pies.\nMantené el torso recto hasta quedar de pie.\nBajá controladamente hasta la posición inicial.' WHERE name_en = 'Glute Ham Raise';
UPDATE public.exercises SET instructions_es = 'Arrodillate con los brazos extendidos al frente.\nMantené la mirada al frente y las rodillas a 90 grados.\nExhalá y levantá la pierna derecha hasta alinear el muslo con la espalda.\nContrá los glúteos y mantené la posición un segundo.\nInhalá y bajá la pierna.\nRepetí con la pierna izquierda.\nAlterna las piernas hasta completar las repeticiones.' WHERE name_en = 'Glute Kickback';
UPDATE public.exercises SET instructions_es = 'Parate sosteniendo una kettlebell ligera cerca del pecho.\nAgachate entre las piernas hasta apoyar los isquios en las pantorrillas.\nMantené el pecho y la cabeza arriba y la espalda recta.\nEn el fondo, empujá las rodillas hacia afuera con los codos.\nSubí a la posición inicial.\nRepetí de 10 a 20 veces.' WHERE name_en = 'Goblet Squat';
UPDATE public.exercises SET instructions_es = 'Apoyá la barra en la parte trasera de los hombros.\nMantené la espalda tensa y las escápulas juntas.\nDoblá las rodillas levemente.\nRetirá los pies del soporte.\nIncliná el torso hacia adelante hasta quedar casi paralelo al suelo.\nMantené la curvatura lumbar y el cuello alineado.\nExtendé las caderas con glúteos e isquiotibiales.\nRegresá a la posición inicial.' WHERE name_en = 'Good Morning';
UPDATE public.exercises SET instructions_es = 'Apoyá la barra en la parte trasera de los hombros.\nMantené la espalda tensa y las escápulas juntas.\nDoblá las rodillas levemente.\nExtendé las caderas con glúteos e isquiotibiales para pararte.\nBajá la barra lentamente hasta los soportes.\nRegresá a la posición inicial.' WHERE name_en = 'Good Morning off Pins';
UPDATE public.exercises SET instructions_es = 'Recostá en posición de flexión de brazos.\nSaltá hacia adelante con ambas piernas.\nAterrizá con los pies junto a las manos.\nMantené la cabeza arriba.\nVolvé a la posición inicial.\nRepetí de 10 a 20 veces.' WHERE name_en = 'Groiners';
UPDATE public.exercises SET instructions_es = 'Apoyá la espalda contra el respaldo de la máquina.\nColocá los hombros bajo las almohadillas.\nPoné los pies en la plataforma a ancho de hombros.\nMantené la cabeza arriba y la espalda pegada.\nAgarrá los manillares laterales.\nDesenganchá las barras de seguridad.\nExtendé las piernas sin bloquear las rodillas.\nBajá la unidad doblando las rodillas.\nMantené la postura recta.\nBajá hasta que el muslo quede por debajo de la paralela.\nInhala al bajar.\nEmpujá el suelo con los talones para subir.\nExhala al subir.\nRepetí las veces indicadas.' WHERE name_en = 'Hack Squat';
UPDATE public.exercises SET instructions_es = 'Parate con el torso recto y una mancuerna en cada mano a la altura de los hombros.\nMantené los codos pegados al cuerpo y las palmas hacia adentro.\nExhalá y flexioná los codos llevando las mancuernas hacia arriba.\nLlevá las mancuernas hasta la altura de los hombros y apretá los bíceps.\nMantené la posición un instante.\nInhalá y bajá las mancuernas lentamente hasta la posición inicial.\nRepetí el movimiento la cantidad de veces indicada.' WHERE name_en = 'Hammer Curls';
UPDATE public.exercises SET instructions_es = 'Recostate en un banco inclinado con una mancuerna en cada muslo.\nUsá los muslos para limpiar las mancuernas y llevarlas a la altura de los hombros.\nMantené las palmas mirándose y los codos a 90 grados, perpendiculares al torso.\nInhalá y bajá las mancuernas lentamente hacia los costados.\nExhalá y empujá las mancuernas hacia arriba usando el pecho.\nBloqueá los brazos arriba, mantené un segundo y bajá lentamente.\nRepetí el movimiento la cantidad de veces indicada.\nAl terminar, colocá las mancuernas en los muslos y luego en el suelo.' WHERE name_en = 'Hammer Grip Incline DB Bench Press';
UPDATE public.exercises SET instructions_es = 'Sentate y apoyá las piernas sobre el rodillo.\nApoyá las manos a los lados o atrás.\nLevantá la cadera y pasá el peso a una pierna.\nRelajá los isquiotibiales.\nRodá desde la cadera hasta la rodilla.\nPausá 10-30 segundos en puntos tensos.\nRepetí con la otra pierna.' WHERE name_en = 'Hamstring-SMR';
UPDATE public.exercises SET instructions_es = 'Recostate boca arriba con una pierna extendida arriba.\nMantené la cadera a 90 grados.\nDejá la otra pierna plana en el piso.\nPasá una correa por la planta del pie.\nJalá la correa para tensar gemelos e isquios.\nMantené la postura 10-30 segundos.\nRepetí con la otra pierna.' WHERE name_en = 'Hamstring Stretch';
UPDATE public.exercises SET instructions_es = 'Recostá tu espalda contra la pared.\nIncliná el torso y apoyá las manos en el piso a la anchura de los hombros.\nEmpujá con las piernas para subir contra la pared con brazos y piernas extendidos.\nMantené el cuerpo recto y la cabeza mirando la pared.\nBajá lentamente inhalando hasta que la cabeza casi toque el piso.\nEmpujá hacia arriba exhalando hasta que los codos queden casi bloqueados.\nRepetí las veces indicadas.' WHERE name_en = 'Handstand Push-Ups';
UPDATE public.exercises SET instructions_es = 'Agrupá la barra con agarre prono a la anchura de los hombros.\nMantené la espalda recta y ligeramente inclinada hacia adelante.\nEmpujá con fuerza desde caderas, rodillas y tobillos para subir el peso.\nEncogé los hombros hacia las orejas durante la subida.\nRecuperá empujando con los talones manteniendo el torso erguido.\nMantené los codos arriba hasta quedar de pie.' WHERE name_en = 'Hang Clean';
UPDATE public.exercises SET instructions_es = 'Recostá la espalda recta e inclinada hacia adelante.\nEmpujá fuerte con caderas, rodillas y tobillos.\nEncogé los hombros hacia las orejas.\nFlexioná los brazos con codos arriba y afuera.\nBajate rápido girando los codos bajo la barra.\nRecibí la barra en sentadilla frontal.\nDejá la barra sobre los hombros protractos.\nDescendé hasta el fondo de la sentadilla.\nEmpujá con los talones para levantarte.\nMantené el torso erguido y codos arriba.' WHERE name_en = 'Hang Clean - Below the Knees';
UPDATE public.exercises SET instructions_es = 'Agarrá la barra con agarre ancho y pies afuera.\nMantené la espalda extendida y cabeza al frente.\nEmpujá fuerte con piernas y caderas.\nEncogé los hombros y flexioná los codos.\nBajate rápido para recibir la barra.\nExtendé los brazos por encima de la cabeza.\nLevantate con la barra arriba.\nBajá la barra al suelo con control.' WHERE name_en = 'Hang Snatch';
UPDATE public.exercises SET instructions_es = 'Agarrá la barra con agarre ancho y supino o de gancho.\nColocá los pies debajo de las caderas, ligeramente abiertos.\nDoblá un poco las rodillas e incliná el torso hacia adelante.\nExtendé la columna y mirá al frente.\nDejá la barra justo debajo de las rodillas.\nExtendé con fuerza piernas y caderas.\nEncogé los hombros y flexioná los codos hacia los lados.\nMové los pies a la posición de recepción.\nTirá de vos mismo hacia abajo mientras subís la barra.\nRecibí la barra con el cuerpo lo más bajo posible y brazos extendidos.\nParate con el peso arriba de la cabeza.\nBajá el peso al suelo con control.' WHERE name_en = 'Hang Snatch - Below Knees';
UPDATE public.exercises SET instructions_es = 'Colocá la barra en un soporte a la altura del estómago.\nSuspendé la barra con cadenas o correas.\nIncliná el cuerpo y apoyá la barra en la parte trasera de los hombros.\nMantené la espalda recta y las escápulas juntas.\nDoblá un poco las rodillas y alineá la columna cervical.\nExtendé las caderas usando glúteos e isquiotibiales.\nParate con el peso.\nBajá el peso lentamente hasta que las cadenas lo sostengan.' WHERE name_en = 'Hanging Bar Good Morning';
UPDATE public.exercises SET instructions_es = 'Colgate del bar con brazos extendidos y agarre ancho o medio.\nMantené las piernas rectas y la pelvis ligeramente inclinada hacia atrás.\nLevantá las piernas hasta formar un ángulo de 90 grados con el torso.\nExhalá al subir y mantené la contracción un segundo.\nBajá lentamente mientras inhalás.\nRepetí la cantidad indicada.' WHERE name_en = 'Hanging Leg Raise';
UPDATE public.exercises SET instructions_es = 'Colgate del bar con agarre prono, ligeramente más ancho que los hombros.\nDoblá las rodillas a 90 grados, manteniendo los gemelos perpendiculares al suelo.\nSubí las piernas exhalando hasta casi tocar la barra con las espinillas.\nIntentá estirar las piernas lo máximo posible en la parte superior.\nBajá las piernas lo más lento posible sin balancearte.\nRepetí la cantidad indicada.' WHERE name_en = 'Hanging Pike';
UPDATE public.exercises SET instructions_es = 'Apretá un peso ligero contra la espalda alta.\nSepará los pies un poco más que el ancho de caderas.\nGirá los pies hacia afuera.\nFlexioná levemente las rodillas.\nSaltá hacia arriba para despegar la barra.\nBajá a una sentadilla completa.\nLlevá la barra por encima de la cabeza.\nParate de pie.' WHERE name_en = 'Heaving Snatch Balance';
UPDATE public.exercises SET instructions_es = 'Pará de pie junto a la bolsa de boxeo.\nSepará los pies en posición escalonada.\nApoyá la mano en la bolsa a la altura del pecho.\nGirá el torso.\nEmpujá la bolsa hacia adelante con fuerza.\nMovete rápido.\nRecibí la bolsa cuando vuelva.\nInvertí el movimiento para frenarla.' WHERE name_en = 'Heavy Bag Thrust';
UPDATE public.exercises SET instructions_es = 'Pará entre dos poleas altas y agarrá una manija en cada mano.\nMantené los antebrazos paralelos al suelo con las palmas hacia vos.\nFlexioná los codos para llevar las manijas hasta las orejas.\nExhalá al subir y contraé los bíceps.\nMantené los codos quietos y mové solo los antebrazos.\nSostené la contracción un segundo.\nBajá lentamente hasta la posición inicial.\nRepetí las veces indicadas.' WHERE name_en = 'High Cable Curls';
UPDATE public.exercises SET instructions_es = 'Apoyá manos y rodillas en el suelo con buena postura.\nLevantá una rodilla flexionada del piso.\nGirá el muslo en un arco para hacer un gran círculo con la rodilla.\nMovéte lentamente y repetí las veces indicadas.\nCambiala de lado.' WHERE name_en = 'Hip Circles (prone)';
UPDATE public.exercises SET instructions_es = 'Asegurá un extremo de la banda en la base de un poste y el otro en un tobillo.\nAfrontá el punto de anclaje y agarrate de la columna para estabilizarte.\nCon la cabeza y el pecho arriba, llevá la pierna hacia atrás manteniendo la rodilla recta.\nVolvé la pierna a la posición inicial.' WHERE name_en = 'Hip Extension with Bands';
UPDATE public.exercises SET instructions_es = 'Asegurá un extremo de la banda en la base de un poste y el otro en un tobillo.\nMirá hacia atrás, lejos del punto de anclaje.\nCon la cabeza y el pecho arriba, levantá la rodilla hasta 90 grados y mantené.\nVolvé la pierna a la posición inicial.' WHERE name_en = 'Hip Flexion with Band';
UPDATE public.exercises SET instructions_es = 'Recostá en el centro de la rack con la banda asegurada a los lados.\nAjustá tu posición para que la banda quede sobre las caderas.\nDoblá las rodillas y apoyá los pies planos en el suelo.\nMantené los hombros en el suelo y empujá con los talones para elevar las caderas.\nEmpujá contra la banda hasta el punto más alto posible.\nHacé una pausa arriba y volvé a la posición inicial.' WHERE name_en = 'Hip Lift with Band';
UPDATE public.exercises SET instructions_es = 'Sentate en el suelo.\nApretá la pelota de ejercicio entre ambas piernas.\nBajá las caderas hacia el piso.\nAbrazá la pelota con los brazos para apoyar el cuerpo.\nAjustá las piernas para que los pies queden planos y las rodillas alineadas sobre los tobillos.\nMantené un buen agarre para que la pelota no ruede.' WHERE name_en = 'Hug A Ball';
UPDATE public.exercises SET instructions_es = 'Recostate boca arriba y llevá las rodillas al pecho.\nApoyá los brazos debajo de las rodillas, no encima.\nLlevá las rodillas hacia los hombros para estirar los glúteos.' WHERE name_en = 'Hug Knees To Chest';
UPDATE public.exercises SET instructions_es = 'Colocá vallas o barreras bajas a unos metros de distancia.\nParate frente a la primera con los pies separados al ancho de los hombros.\nSaltá la primera valla con ambos pies y mové los brazos.\nAterriza flexionando las rodillas y saltá la siguiente valla.\nRepetí hasta superar todas las vallas.' WHERE name_en = 'Hurdle Hops';
UPDATE public.exercises SET instructions_es = 'Recostá boca abajo en el banco de hiperextensión.\nFijá los tobillos bajo las almohadillas.\nAjustá el cojín superior para que los muslos queden planos.\nCruzá los brazos frente al pecho o detrás de la cabeza.\nIncliná el torso hacia adelante lentamente manteniendo la espalda recta.\nSentí el estiramiento en los isquiotibiales sin redondear la espalda.\nSubí el torso hasta la posición inicial sin arquear la espalda.\nEvitá balancearte para proteger la zona lumbar.\nRepetí las veces indicadas.' WHERE name_en = 'Hyperextensions (Back Extensions)';
UPDATE public.exercises SET instructions_es = 'Recostá boca abajo en el borde de un banco plano.\nDejá que las caderas cuelguen del extremo.\nMantené el cuerpo recto y cruzá los brazos frente al pecho.\nIncliná el torso hacia adelante lentamente manteniendo la espalda recta.\nBajá hasta casi tocar el piso o sentir el estiramiento en los isquios.\nSubí el torso hasta la posición inicial exhalando.\nEvitá arquear la espalda más allá de la línea recta.\nNo balancees el cuerpo para evitar lesiones.\nRepetí las veces indicadas.' WHERE name_en = 'Hyperextensions With No Hyperextension Bench';
UPDATE public.exercises SET instructions_es = 'Asegurá una banda en un pie y cruzá la pierna extendida por el suelo.\nJalá la banda para levantar los dedos sin apoyar el pie.\nMantené la tensión 10 a 20 segundos.\nRepetí con el otro lado.' WHERE name_en = 'IT Band and Glute Stretch';
UPDATE public.exercises SET instructions_es = 'Recostá de lado con la pierna de abajo sobre el rodillo.\nApoyá el peso corporal en esa pierna y relajá los músculos.\nRodá la pierna desde la cadera hasta la rodilla.\nMantené la pausa 10 a 30 segundos en los puntos de tensión.\nRepetí con la otra pierna.' WHERE name_en = 'Iliotibial Tract-SMR';
UPDATE public.exercises SET instructions_es = 'Pará con los pies juntos.\nEstirá el cuerpo hacia abajo con las piernas rectas.\nApoyá las manos en el piso frente a vos.\nAndá las manos hacia adelante alternando lados.\nDoblá solo la cadera manteniendo las piernas rectas.\nLlegá hasta que el cuerpo quede paralelo al suelo.\nMantené las manos fijas.\nDá pasos cortos con los pies hacia adelante.\nAndá hasta que los pies queden junto a las manos.' WHERE name_en = 'Inchworm';
UPDATE public.exercises SET instructions_es = 'Agarrá la barra con palmas hacia abajo.\nSepará las manos un poco menos que el ancho de hombros.\nRecostá en un banco inclinado entre 45 y 75 grados.\nLlevá la barra sobre la cabeza con brazos extendidos.\nMantené los codos pegados al cuerpo.\nBajá la barra en semicírculo detrás de la cabeza.\nLlevá los antebrazos hasta tocar los bíceps.\nInspirá mientras bajás.\nMantené los brazos superiores fijos junto a la cabeza.\nEmpujá la barra hacia arriba contrayendo los tríceps.\nExpirá al subir.\nMantené la contracción un segundo.' WHERE name_en = 'Incline Barbell Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Agarrá una mancuerna en cada mano y recostá boca abajo en un banco inclinado a 30 grados.\nDejá que los brazos cuelguen extendidos hacia el suelo.\nGirá las muñecas para tener las palmas hacia abajo.\nAbrí los codos hacia afuera para tomar la posición inicial.\nExhalá y levantá las mancuernas doblando los codos hasta que los brazos queden al nivel de la espalda.\nFormá una letra "T" con el torso y mantené la contracción un segundo.\nInhalá y bajá lentamente a la posición inicial.\nRepetí el movimiento la cantidad de veces indicada.' WHERE name_en = 'Incline Bench Pull';
UPDATE public.exercises SET instructions_es = 'Ajustá el peso y sentate agarrando los mangos.\nMantené los brazos superiores a 45 grados del cuerpo y los codos doblados a 90 grados.\nExhalá y empujá los mangos hacia adelante extendiendo los codos.\nMantené las escápulas retraídas durante el movimiento.\nHacé una pausa en la extensión completa.\nVolvé a la posición inicial manteniendo la tensión en los cables.' WHERE name_en = 'Incline Cable Chest Press';
UPDATE public.exercises SET instructions_es = 'Ajustá las poleas al nivel más bajo, debajo del torso.\nColocá un banco inclinado a 45 grados entre las poleas.\nElegí el peso y agarrá una polea en cada mano.\nRecostá en el banco y juntá las manos a la altura de los brazos frente a la cara.\nBajá los brazos en un arco amplio hasta sentir el estiramiento en el pecho.\nInspirá mientras bajás y mantené los brazos estables, moviendo solo el hombro.\nEmpujá de vuelta al inicio apretando el pecho y exhalando.\nMantené la contracción un segundo y repetí las veces indicadas.' WHERE name_en = 'Incline Cable Flye';
UPDATE public.exercises SET instructions_es = 'Recostá en un banco inclinado con una mancuerna en cada muslo.\nPalmas mirándose entre sí.\nUsá los muslos para limpiar las mancuernas hasta la altura de los hombros.\nMantené agarre neutro, codos a 90 grados y brazos perpendiculares al torso.\nBajá las mancuernas lentamente hacia los lados mientras inspirás.\nControlá el peso en todo momento.\nEmpujá hacia arriba usando el pecho mientras exhalás.\nBloqueá los brazos arriba, mantené un segundo y bajá lento.\nLa bajada debe durar el doble que la subida.\nRepetí las veces indicadas.\nDevolvé las mancuernas a los muslos y luego al suelo.' WHERE name_en = 'Incline Dumbbell Bench With Palms Facing In';
UPDATE public.exercises SET instructions_es = 'Recostá en un banco inclinado con una mancuerna en cada mano a la altura de los hombros.\nMantené los codos pegados al torso y girá las palmas hacia adelante.\nFlexioná los antebrazos hacia adelante contrayendo los bíceps mientras exhalás.\nLlevá las mancuernas hasta la altura de los hombros y mantené la contracción un segundo.\nBajá lentamente a la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'Incline Dumbbell Curl';
UPDATE public.exercises SET instructions_es = 'Recostá en un banco inclinado de no más de 30 grados con una mancuerna en cada mano.\nExtendé los brazos hacia arriba con una leve flexión en los codos.\nGirá las muñecas para que las palmas miren hacia vos, con los meñiques juntos.\nBajá los brazos a los lados mientras inhalás, girando las palmas hacia el techo.\nSubí las mancuernas a la posición inicial mientras exhalás, girando las palmas hacia vos.\nMové solo hombros y muñecas, sin flexionar los codos.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'Incline Dumbbell Flyes';
UPDATE public.exercises SET instructions_es = 'Recostá en un banco inclinado de máximo 30 grados con mancuernas en cada mano.\nExtendé los brazos hacia arriba con una leve flexión en los codos.\nGirá las muñecas para que las palmas miren hacia vos, con los meñiques juntos.\nInhala y bajá los brazos lateralmente manteniéndolos extendidos.\nGirá las muñecas hasta que las palmas miren al techo.\nExhalá y subí las mancuernas girando las manos hasta juntar los meñiques.\nMové solo hombros y muñecas, sin flexionar los codos.\nRepetí las veces indicadas.' WHERE name_en = 'Incline Dumbbell Flyes - With A Twist';
UPDATE public.exercises SET instructions_es = 'Recostá en un banco inclinado con mancuernas sobre los muslos.\nPalmas mirándose, usá los muslos para empujar las mancuernas hacia arriba.\nLlevá las mancuernas a la anchura de los hombros.\nGirá las muñecas para que las palmas miren hacia afuera.\nExhalá y empujá las mancuernas hacia arriba con el pecho.\nBloqueá los brazos arriba y mantené un segundo.\nBajá el peso lentamente, el doble de tiempo que la subida.\nRepetí las veces indicadas.\nDevolvé las mancuernas a los muslos y luego al suelo.' WHERE name_en = 'Incline Dumbbell Press';
UPDATE public.exercises SET instructions_es = 'Recostate en un banco inclinado con una mancuerna en cada mano.\nApoyá la espalda firmemente y juntá los pies.\nDejá caer las mancuernas a los lados con agarre neutro.\nFlexioná los codos manteniendo los brazos superiores quietos.\nLlevá las mancuernas hacia arriba y hacé una pausa.\nBajá lentamente hasta la posición inicial.' WHERE name_en = 'Incline Hammer Curls';
UPDATE public.exercises SET instructions_es = 'Recostate en un banco inclinado con una mancuerna en cada mano.\nExtendé los brazos a los lados con las palmas hacia afuera.\nExhalá y elevá las mancuernas hacia afuera y arriba.\nMantené los antebrazos alineados con los deltoides laterales.\nLlegá hasta la altura de los hombros, como en una pose de bíceps.\nContrá los músculos un segundo en la parte superior.\nInhalá y bajá lentamente por el mismo camino.' WHERE name_en = 'Incline Inner Biceps Curl';
UPDATE public.exercises SET instructions_es = 'Pará frente al banco.\nApoyá las manos en el borde, más ancho que los hombros.\nColocá los pies atrás, cuerpo recto y brazos perpendiculares.\nBajá el pecho doblando los brazos.\nEmpujá hasta extender los brazos.\nRepetí.' WHERE name_en = 'Incline Push-Up';
UPDATE public.exercises SET instructions_es = 'Pará frente a la barra.\nApoyá las manos juntas en la barra.\nColocá los pies atrás, cuerpo recto.\nBajá el pecho doblando los codos.\nEmpujá para volver a la posición inicial.' WHERE name_en = 'Incline Push-Up Close-Grip';
UPDATE public.exercises SET instructions_es = 'Colocá una caja de 30 cm y dos escalones.\nApoyá los pies en la caja y las manos en los escalones.\nIncliná el cuerpo en posición de flexión.\nDoblá los codos para bajar el pecho.\nEmpujá fuerte para despegar del suelo.\nAterrizá con las manos en los escalones.\nAbsorbé el impacto doblando los codos.\nVolvé a la posición inicial.' WHERE name_en = 'Incline Push-Up Depth Jump';
UPDATE public.exercises SET instructions_es = 'Pará frente a la barra de la máquina Smith.\nApoyá las manos a la anchura de los hombros.\nRetirá los pies para alinear el cuerpo.\nMantené el cuerpo recto.\nDoblá los codos para bajar el pecho.\nEmpujá para volver a la posición inicial.' WHERE name_en = 'Incline Push-Up Medium';
UPDATE public.exercises SET instructions_es = 'Pará frente a la barra de la máquina Smith o plataforma elevada a la altura adecuada.\nColocá las manos en la barra con las palmas hacia arriba, a la anchura de los hombros.\nRetirá los pies de la barra manteniendo brazos y cuerpo rectos.\nBajá el pecho hacia la barra flexionando los codos con el cuerpo recto.\nExtendé los codos para volver a la posición inicial.' WHERE name_en = 'Incline Push-Up Reverse Grip';
UPDATE public.exercises SET instructions_es = 'Pará frente a la barra de la máquina Smith o plataforma elevada a la altura adecuada.\nColocá las manos en la barra más abiertas que la anchura de los hombros.\nRetirá los pies de la barra manteniendo brazos y cuerpo rectos, con los brazos perpendiculares al cuerpo.\nBajá el pecho hacia la barra flexionando los codos con el cuerpo recto.\nExtendé los codos para volver a la posición inicial.' WHERE name_en = 'Incline Push-Up Wide';
UPDATE public.exercises SET instructions_es = 'Recostá boca arriba con las piernas extendidas.\nAsegurá una banda en un pie y abrí la pierna lateralmente.\nTirá suavemente para tensar la ingle y el isquiotibial.\nMantené 10-20 segundos y cambiá de lado.' WHERE name_en = 'Intermediate Groin Stretch';
UPDATE public.exercises SET instructions_es = 'Recostá boca abajo con una banda en un pie.\nDoblá la rodilla y extendé la cadera tirando de la banda.\nLevantá la rodilla y la cadera del suelo para tensar el flexor y el cuádriceps.\nMantené 10-20 segundos y cambiá de pierna.' WHERE name_en = 'Intermediate Hip Flexor and Quad Stretch';
UPDATE public.exercises SET instructions_es = 'Ajustá la banda a la altura del codo.\nPará de lado a la banda.\nAgarrá la banda con el codo pegado al costado.\nMantené el codo flexionado a 90 grados.\nGirá el brazo hacia adelante sin mover el codo.\nLlegá al máximo, pausá y volvé.' WHERE name_en = 'Internal Rotation with Band';
UPDATE public.exercises SET instructions_es = 'Colocá la barra a la altura de la cintura.\nAgarrá la barra con manos más abiertas que los hombros.\nColgá con el cuerpo recto y los talones en el piso.\nFlexioná los codos llevando el pecho hacia la barra.\nRetraé los omóplatos durante el movimiento.\nPausá arriba y volvé a la posición inicial.' WHERE name_en = 'Inverted Row';
UPDATE public.exercises SET instructions_es = 'Recostá tu espalda plana en un banco y extendé tus piernas hacia adelante, colgando del borde.\nColocá tus manos debajo de los glúteos con las palmas hacia abajo o a los lados sujetando el banco. Esta será tu posición inicial.\nMantené las piernas extendidas lo más rectas posible, con las rodillas ligeramente flexionadas pero bloqueadas, y levantá las piernas hasta formar un ángulo de 90 grados con el suelo. Exhalá al realizar esta parte del movimiento y mantené la contracción arriba durante un segundo.\nAhora, mientras inhalás, bajá lentamente las piernas de vuelta a la posición inicial.' WHERE name_en = 'Flat Bench Lying Leg Raise';
UPDATE public.exercises SET instructions_es = 'Sujetá la mancuerna hacia el lado más alejado de vos para que haya más peso en el lado más cercano. (Esto puede hacerse para un buen efecto en todos los ejercicios de bíceps con mancuernas). Ahora hacé una curl de mancuerna en banco inclinado normal, pero mantené las muñecas lo más atrás posible para neutralizar cualquier estrés que se les coloque.\nSentate en un banco inclinado a 45 grados sosteniendo una mancuerna en cada mano.\nDejá que tus brazos cuelguen a los lados, con los codos hacia adentro, y girá las palmas de las manos hacia adelante con los pulgares apuntando lejos del cuerpo. Consejo: Mantendrás esta posición de las manos durante todo el movimiento, ya que no debe haber ningún giro de las manos al subir. Esta será tu posición inicial.\nSubí las dos mancuernas al mismo tiempo hasta que tus bíceps estén completamente contraídos y exhalá. Consejo: No balancees los brazos ni uses impulso. Mantené un movimiento controlado en todo momento. Mantené la posición contraída durante un segundo arriba.\nMientras inhalás, volvé lentamente a la posición inicial.\nRepetí la cantidad recomendada de repeticiones.' WHERE name_en = 'Flexor Incline Dumbbell Curls';
UPDATE public.exercises SET instructions_es = 'Sentate en un banco inclinado con un ángulo entre 30 y 60 grados, sosteniendo una mancuerna en cada mano.\nExtendé tus brazos rectos hacia adelante con las palmas hacia abajo, manteniendo las mancuernas a unos 2,5 cm por encima de los muslos.\nLevantá lentamente las mancuernas rectas hacia arriba hasta que estén ligeramente por encima de los hombros, manteniendo los codos bloqueados.\nApretá en la parte superior durante un segundo y exhalá durante esta fase del movimiento.\nBajá los brazos de vuelta a la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Front Incline Dumbbell Raise';
UPDATE public.exercises SET instructions_es = 'Parate al lado de una silla u otro soporte, agarrándote con una mano.\nBalanza tu pierna hacia adelante manteniéndola recta.\nContinuá con un balanceo hacia abajo, llevando la pierna hacia atrás lo más que te permita tu flexibilidad.\nRepetí de 5 a 10 veces y luego cambiá de pierna.' WHERE name_en = 'Front Leg Raises';
UPDATE public.exercises SET instructions_es = 'Colgate de la barra de dominadas con agarre supino (palmas hacia vos) un poco más ancho que el ancho de tus hombros.\nDoblá las rodillas a 90 grados para que las pantorrillas queden paralelas al suelo y los muslos perpendiculares a él. Esta será tu posición inicial.\nExhalá y tirá de vos mismo hacia arriba mientras doblás las rodillas al mismo tiempo hasta que lleguen al nivel del pecho. Dejá de subir cuando tu nariz quede a la misma altura que la barra. Consejo: Al llegar a este punto, también deberías estar terminando el crunch al mismo tiempo.\nIniciá a inhalar lentamente mientras volvé a la posición inicial.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Gorilla Chin/Crunch';
UPDATE public.exercises SET instructions_es = 'Sentate en el suelo con las rodillas dobladas y los pies juntos.\nEntrelazá los dedos detrás de la cabeza. Esta será tu posición inicial.\nFlexioná hacia abajo, llevando los codos hacia el interior de los muslos. Después de una breve pausa, volvé a la posición inicial con la cabeza arriba y la espalda recta. Repetí de 10 a 20 veces.' WHERE name_en = 'Groin and Back Stretch';
UPDATE public.exercises SET instructions_es = 'Colgá una cuerda o correas de suspensión de un rack u otro objeto estable.\nAgarrá los extremos y recostate en posición supina colgando de las cuerdas.\nMantené tu cuerpo recto con los talones en el suelo y los brazos completamente extendidos. Esta será tu posición inicial.\nComenzá flexionando el codo, empujando tu pecho hacia tus manos.\nRetraé las escápulas mientras realizás el movimiento.\nHacé una pausa en la parte superior del movimiento y volvé a la posición inicial.\nRepetí la cantidad de repeticiones deseadas.' WHERE name_en = 'Inverted Row with Straps';
UPDATE public.exercises SET instructions_es = '2\n' WHERE name_en = 'Iron Cross';
UPDATE public.exercises SET instructions_es = 'Recostate boca abajo en el suelo, con los brazos extendidos a los lados y las palmas apoyadas en el piso.\nFlexioná una rodilla y llevá esa pierna cruzando por la espalda, intentando tocar el suelo cerca de la mano opuesta.\nRetorná la pierna rápidamente a la posición inicial y repetí con la otra pierna.\nContinuá alternando por 10-20 repeticiones.' WHERE name_en = 'Iron Crosses (stretch)';
UPDATE public.exercises SET instructions_es = 'Sentate o parate, doblá los brazos a 90 grados y juntá las palmas de las manos frente al pecho.\nEmpujá ambas manos una contra la otra mientras contraés el pecho.\nComenzá con tensión lenta e incrementala gradualmente, manteniendo la respiración normal.\nMantené la posición durante los segundos recomendados.\nSoltá la tensión lentamente.\nDescansá el tiempo indicado y repetí.' WHERE name_en = 'Isometric Chest Squeezes';
UPDATE public.exercises SET instructions_es = 'Mantené la cabeza y el cuello en posición neutra, mirando hacia adelante.\nColocá ambas manos en la parte frontal de tu cabeza.\nEmpujá suavemente hacia adelante mientras contraés los músculos del cuello, resistiendo cualquier movimiento de la cabeza.\nIniciá con una tensión lenta e incrementala gradualmente, respirando con normalidad.\nMantené la posición durante los segundos recomendados.\nSoltá la tensión lentamente.\nDescansá el tiempo indicado y repetí el ejercicio colocando las manos en la parte trasera de la cabeza.' WHERE name_en = 'Isometric Neck Exercise - Front And Back';
UPDATE public.exercises SET instructions_es = 'Mantené la cabeza y el cuello en posición neutra, mirando hacia adelante.\nColocá tu mano izquierda en el lado izquierdo de tu cabeza.\nEmpujá suavemente hacia la izquierda mientras contraés los músculos del cuello izquierdo, resistiendo cualquier movimiento de la cabeza.\nIniciá con una tensión lenta e incrementala gradualmente, respirando con normalidad.\nMantené la posición durante los segundos recomendados.\nSoltá la tensión lentamente.\nDescansá el tiempo indicado y repetí el ejercicio colocando la mano derecha en el lado derecho de la cabeza.' WHERE name_en = 'Isometric Neck Exercise - Sides';
UPDATE public.exercises SET instructions_es = 'Recostá tu peso sobre las manos y las puntas de los pies, manteniendo el cuerpo recto con las manos ligeramente más afuera que el ancho de los hombros.\nDesplazá el peso del cuerpo hacia un lado lo más posible, flexionando el codo de ese lado mientras bajás.\nExtendé el brazo flexionado para empujar hacia arriba y luego caé hacia el otro lado.\nRepetí el movimiento la cantidad de veces deseadas.' WHERE name_en = 'Isometric Wipers';
UPDATE public.exercises SET instructions_es = 'Recostate en un banco plano sosteniendo la barra con los brazos extendidos y los codos juntos, alineando la barra directamente sobre el pecho superior.\nBajá la barra como en una extensión de tríceps acostado, inhalando, y cuando estés a la mitad, dejá que la barra ruede hacia atrás moviendo los brazos superiores hacia las piernas hasta que sean perpendiculares al torso.\nExhalá y empujá la barra hacia arriba usando los tríceps para realizar un press de banca con agarre cerrado.\nVolvé a la posición inicial y repetí.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'JM Press';
UPDATE public.exercises SET instructions_es = 'Recostá boca arriba en el suelo (o colchoneta) con los brazos extendidos detrás de la cabeza y las piernas estiradas.\nExhalá, doblá la cintura y levantá simultáneamente las piernas y los brazos hasta encontrarse en posición de tijera.\nMantené las piernas extendidas a un ángulo de 35 a 45 grados respecto al suelo y los brazos paralelos a las piernas, con el torso superior despegado del piso.\nInhalá y bajá los brazos y las piernas de vuelta a la posición inicial.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Jackknife Sit-Up';
UPDATE public.exercises SET instructions_es = 'Colocá tu cuerpo en el suelo en la posición básica de abdominal, con las rodillas a 90 grados, los pies planos en el suelo y los brazos cruzados sobre el pecho o a los costados.\nContráé fuertemente los glúteos y los isquiotibiales, llená los pulmones de aire y, en una ascensión lenta (de 3 a 6 segundos), exhalá lentamente.\nInhalá y volvé de manera controlada a la posición inicial.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Janda Sit-Up';
UPDATE public.exercises SET instructions_es = 'Colocá la barra en posición de jerk, con los hombros hacia adelante para crear una repisa y la barra tocando suavemente la garganta\nPosicioná los pies directamente debajo de las caderas, con los pies girados hacia afuera según tu comodidad\nMantené el torso vertical y bajá flexionando las rodillas, permitiendo que se desplacen hacia adelante sin mover las caderas hacia atrás\nNo excedas la profundidad de la bajada\nRegresá a la posición inicial empujando con fuerza a través de los pies' WHERE name_en = 'Jerk Dip Squat';
UPDATE public.exercises SET instructions_es = 'Subí a la cinta y seleccioná la opción deseada del menú\nElegí un ajuste manual o un programa de carrera\nIngresá tu edad y peso para estimar las calorías quemadas durante el ejercicio\nAjustá la elevación para cambiar la intensidad del entrenamiento\nMantené una postura adecuada mientras corré\nAgarrate de los apoyos solo cuando sea necesario, como al bajar o al revisar tu frecuencia cardíaca' WHERE name_en = 'Jogging, Treadmill';
UPDATE public.exercises SET instructions_es = 'Colocá las barricas a la distancia deseada de la plataforma de carga, generalmente a 30-50 pies.\nAgarrá el mango cercano de la primera barrica, inclinala sobre su costado para tomar el borde opuesto de la base y levantala hasta tu pecho.\nCuanto más alto coloques la barrica, más rápido podrás moverte hacia la plataforma; por lo general no se permite apoyarla en el hombro, así que mantené un agarre firme.\nMovete lo más rápido posible hacia la plataforma y cargala, extendiendo caderas, rodillas y tobillos para subirla lo más alto que puedas.\nVolvé a la posición inicial para recuperar la siguiente barrica y repetí hasta completar la prueba.' WHERE name_en = 'Keg Load';
UPDATE public.exercises SET instructions_es = 'Limpia la kettlebell hasta tu hombro extendiendo piernas y caderas mientras la subís, con la palma mirando hacia adentro.\nMirá al frente, presioná la kettlebell hacia arriba y rotá la muñeca para que la palma mire hacia adelante en la parte superior del movimiento.\nDevolvé la kettlebell a la posición inicial, con la palma mirando hacia adentro.' WHERE name_en = 'Kettlebell Arnold Press';
UPDATE public.exercises SET instructions_es = 'Colocá la kettlebell entre tus pies. Para llegar a la posición inicial, empujá el glúteo hacia atrás y mirá al frente.\nLlevá la kettlebell hasta el hombro. Subila hasta los hombros extendiendo las piernas y las caderas mientras la elevás. La muñeca debe rotar al hacerlo.\nBajá la kettlebell, manteniendo los isquiotibiales cargados con la espalda recta y el glúteo hacia atrás.' WHERE name_en = 'Kettlebell Dead Clean';
UPDATE public.exercises SET instructions_es = 'Colocá una kettlebell entre tus piernas y tomá una postura más ancha que el ancho de los hombros. Incliná el cuerpo empujando el glúteo hacia atrás y manteniendo la espalda plana.\nLevantá la kettlebell y pasala a la otra mano entre las piernas. La mano receptora debe alcanzar desde detrás de las piernas. Repetí el movimiento de ida y vuelta varias veces.' WHERE name_en = 'Kettlebell Figure 8';
UPDATE public.exercises SET instructions_es = 'Colocá la kettlebell entre tus pies.\nEmpujá la cadera hacia atrás y mirá al frente para tomar la posición inicial.\nLlevá la kettlebell al hombro extendiendo piernas y cadera mientras la subís, rotando la muñeca.\nBajá la kettlebell a la posición colgante entre las piernas manteniendo los isquiotibiales tensos y la cabeza arriba.' WHERE name_en = 'Kettlebell Hang Clean';
UPDATE public.exercises SET instructions_es = 'Agarrá la kettlebell por el mango con una mano.\nPará sobre una pierna, del mismo lado que sostenés la kettlebell.\nCon esa rodilla ligeramente flexionada, hacé un peso muerto de pierna recta flexionando la cadera y extendiendo la pierna libre hacia atrás para el equilibrio.\nBajá la kettlebell hasta quedar paralelo al suelo y volvé a la posición de pie.' WHERE name_en = 'Kettlebell One-Legged Deadlift';
UPDATE public.exercises SET instructions_es = 'Pará con los pies separados al ancho de cadera, sosteniendo la kettlebell por los cuernos con ambas manos.\nEmpujá la pesa por encima de la cabeza hasta que los brazos estén extendidos, dejando que la campana cuelgue detrás de tus manos.\nApretá el abdomen y mantené los brazos superiores verticales y pegados a la cabeza; esta es tu posición inicial.\nDobrá los codos para bajar la kettlebell detrás de la cabeza, llegando tan lejos como te permita la movilidad de los hombros sin que los codos se abran hacia afuera.\nExtendé los codos para empujar la kettlebell de vuelta a la posición inicial, manteniendo los brazos superiores quietos durante todo el movimiento.\nMantené las costillas hacia abajo y evitá arquear la parte baja de la espalda al extender los brazos.' WHERE name_en = 'Kettlebell Overhead Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Colocá una kettlebell entre las piernas y adoptá una postura cómoda.\nIncliná el cuerpo hacia adelante empujando el glúteo hacia atrás y manteniendo la espalda recta.\nLevantá la kettlebell y pasala a la otra mano entre las piernas, formando una "W".\nRepetí el movimiento de un lado a otro varias veces.' WHERE name_en = 'Kettlebell Pass Between The Legs';
UPDATE public.exercises SET instructions_es = 'Tomá una postura amplia y sostené la kettlebell con ambas manos\nDejá que cuelgue a la altura de la cintura con los brazos extendidos\nIniciá el movimiento girando hacia un lado y balanceando la kettlebell hasta la altura de la cabeza\nHacé una breve pausa en la parte superior del movimiento\nDejá caer la pesa mientras girás hacia el lado opuesto, levantando la kettlebell hasta la altura de la cabeza otra vez\nRepetí la cantidad de repeticiones deseadas' WHERE name_en = 'Kettlebell Pirate Ships';
UPDATE public.exercises SET instructions_es = 'Levantá una kettlebell con ambas manos y sostenela por los cuernos\nMantené una pierna en el aire y agachate con la otra\nAgachate flexionando la rodilla y sentándote hacia atrás, sosteniendo la kettlebell frente a vos\nMantené la posición inferior por un segundo y luego invertí el movimiento, impulsando con el talón y manteniendo la cabeza y el pecho arriba\nBajate otra vez y repetí' WHERE name_en = 'Kettlebell Pistol Squat';
UPDATE public.exercises SET instructions_es = 'Sentate en el piso y abrí las piernas cómodamente.\nLlevá una kettlebell a tu hombro.\nEmpujá la kettlebell hacia arriba y afuera hasta bloquear el codo. Volvé a la posición inicial.' WHERE name_en = 'Kettlebell Seated Press';
UPDATE public.exercises SET instructions_es = 'Llevá dos kettlebells a tus hombros.\nEmpujá una kettlebell.\nBajá la kettlebell y empujá inmediatamente la otra. Asegurate de hacer la misma cantidad de repeticiones en ambos lados.' WHERE name_en = 'Kettlebell Seesaw Press';
UPDATE public.exercises SET instructions_es = 'Colocá una kettlebell en el suelo entre tus pies.\nPosicioná tus pies en una postura amplia y agarrá la kettlebell con ambas manos.\nLlevá la cadera hacia atrás lo más posible, con las rodillas flexionadas.\nMantené el pecho y la cabeza arriba.\nExtendé la cadera y las rodillas, mientras tirás de la kettlebell hacia tus hombros, levantando los codos al mismo tiempo.\nInvertí el movimiento para volver a la posición inicial.' WHERE name_en = 'Kettlebell Sumo High Pull';
UPDATE public.exercises SET instructions_es = 'Llevá dos kettlebells a tus hombros extendiendo las piernas y la cadera mientras tirás de ellas hacia arriba.\nGirá las muñecas mientras lo hacés.\nIniciá la sentadilla flexionando la cadera y las rodillas, bajando la cadera entre las piernas.\nMantené la espalda recta y erguida mientras descendés lo más bajo que puedas.\nEn el punto más bajo, invertí la dirección extendiendo las rodillas y la cadera, impulsando a través de los talones.\nAl mismo tiempo, empujá ambas kettlebells por encima de la cabeza extendiendo los brazos rectos hacia arriba, usando el impulso de la sentadilla.\nPara la siguiente repetición, devolvé los pesos a los hombros.' WHERE name_en = 'Kettlebell Thruster';
UPDATE public.exercises SET instructions_es = 'Recostá boca arriba en el piso y empujá la kettlebell hasta la posición superior extendiendo el codo. Flexioná la rodilla del mismo lado que la kettlebell.\nMantené la kettlebell bloqueada en todo momento, girá hacia el lado opuesto y usá tu brazo no dominante para ayudarte a avanzar hacia la posición de zancada. Con tu mano libre, empujá tu cuerpo hacia una posición sentada y luego progresá a una rodilla.\nMirando hacia arriba a la kettlebell, levantate lentamente. Revertí el movimiento de vuelta a la posición inicial y repetí.' WHERE name_en = 'Kettlebell Turkish Get-Up (Lunge style)';
UPDATE public.exercises SET instructions_es = 'Recostá boca arriba en el piso y empujá la kettlebell hasta la posición superior extendiendo el codo. Flexioná la rodilla del mismo lado que la kettlebell.\nMantené la kettlebell bloqueada en todo momento, girá hacia el lado opuesto y usá tu brazo no dominante para ayudarte a avanzar hacia la posición de zancada.\nCon tu mano libre, empujá tu cuerpo hacia una posición sentada y luego progresá a los pies. Mirando hacia arriba a la kettlebell, levantate lentamente. Revertí el movimiento de vuelta a la posición inicial y repetí.' WHERE name_en = 'Kettlebell Turkish Get-Up (Squat style)';
UPDATE public.exercises SET instructions_es = 'Colocá una kettlebell frente a tu pie de apoyo y hacé un clean y press por encima de la cabeza con tu brazo opuesto.\nLlevá la kettlebell a tu hombro extendiendo las piernas y las caderas mientras tirás de la kettlebell hacia tus hombros.\nGirá la muñeca para que la palma mire hacia adelante.\nEmpujá por encima de la cabeza extendiendo el codo.\nMantené la kettlebell bloqueada en todo momento y empujá el trasero en la dirección de la kettlebell bloqueada.\nGirá los pies a 45 grados desde el brazo con la kettlebell bloqueada.\nIncliná el cuerpo hacia un lado flexionando la cadera, sacando el trasero, hasta tocar el suelo con la mano libre.\nMantené la mirada en la kettlebell que sostenés sobre la cabeza.\nHacé una pausa de un segundo al tocar el suelo y revertí el movimiento hasta la posición inicial.' WHERE name_en = 'Kettlebell Windmill';
UPDATE public.exercises SET instructions_es = 'Agarrá los aros con un agarre falso, colocando la base de las palmas sobre los aros.\nComenzá con un movimiento balanceando las piernas hacia atrás ligeramente.\nContrarrestá ese movimiento balanceando las piernas hacia adelante y arriba, jalando la barbilla y el pecho hacia atrás, subiéndote con ambos brazos.\nAl llegar a la posición superior del jalón, llevá los aros a las axilas mientras girás los hombros hacia adelante, permitiendo que los codos se muevan rectos hacia atrás.\nMantené el control y la estabilidad, y extendé el codo para completar el movimiento.\nBajate al suelo con cuidado.' WHERE name_en = 'Kipping Muscle Up';
UPDATE public.exercises SET instructions_es = 'Recostate en el piso con la pierna derecha estirada.\nDoblá la pierna izquierda y bajala cruzando el cuerpo, sosteniendo la rodilla hacia el piso con la mano derecha.\nColocá el brazo izquierdo cómodamente a tu lado y girá la cabeza hacia la izquierda.\nImaginá que tenés un peso atado a tu coxis.\nDejá que el coxis caiga hacia atrás hacia el piso mientras el pecho se extiende en la dirección opuesta para estirar la zona lumbar.\nCambialo de lado.' WHERE name_en = 'Knee Across The Body';
UPDATE public.exercises SET instructions_es = 'Parate con las piernas juntas y las manos en la cintura.\nMové las rodillas en un movimiento circular mientras respirás de forma normal.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Knee Circles';
UPDATE public.exercises SET instructions_es = 'Recostá tu cuerpo en el banco de elevación vertical de piernas, apoyando los antebrazos en los cojines junto al torso y agarrando los mangos.\nMantené los codos doblados a 90 grados.\nMantené el torso recto, con la zona lumbar presionada contra el cojín de la máquina y las piernas extendidas apuntando hacia el piso.\nExhalá y levantá las piernas manteniéndolas extendidas.\nLlevá las piernas hasta que queden paralelas al piso y mantené la contracción por un segundo.\nNo uses impulso ni balancees el cuerpo durante el ejercicio.\nVolvé lentamente a la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Knee/Hip Raise On Parallel Bars';
UPDATE public.exercises SET instructions_es = 'Parate en una posición cómoda con las rodillas ligeramente flexionadas.\nMantené las manos frente a ti, con las palmas hacia abajo y las puntas de los dedos juntas a la altura del pecho.\nBajá rápidamente en un cuarto de sentadilla y explotá hacia arriba inmediatamente.\nLlevá las rodillas hacia el pecho, intentando tocarlas con las palmas de las manos.\nSaltá lo más alto que puedas, elevando las rodillas.\nAterriza extendiendo bien las piernas y absorbiendo el impacto permitiendo que las rodillas se vuelvan a flexionar.' WHERE name_en = 'Knee Tuck Jump';
UPDATE public.exercises SET instructions_es = 'Iniciá de rodillas, con el pie izquierdo adelante y la rodilla derecha en el suelo.\nAplicá presión a través del talón delantero para mantener activados los glúteos y los isquiotibiales.\nComenzá bloqueando los brazos en oscilaciones largas, como péndulos.\nCerrá el ángulo de los brazos, bloqueándolos como lo harías al trotar, y progresá hasta correr y finalmente hacer un sprint.\nEn cuanto tus manos pasen la cadera, acelerálas hacia adelante durante el movimiento de sprint para moverlas lo más rápido posible.\nCambiá de rodilla y repetí.' WHERE name_en = 'Kneeling Arm Drill';
UPDATE public.exercises SET instructions_es = 'Conectá un accesorio de cuerda a una polea alta y colocá una colchoneta en el suelo frente a ella.\nAgarrá la cuerda con ambas manos y arrodillate a aproximadamente dos pies de distancia de la torre.\nPosicioná la cuerda detrás de tu cabeza, con las manos junto a las orejas.\nMantené las manos en el mismo lugar, contraé los abdominales y tirá de la cuerda hacia abajo con un movimiento de crunch hasta que tus codos lleguen a las rodillas.\nHacé una pausa breve en la parte inferior y subí de manera lenta y controlada hasta la posición inicial.\nRepetí el mismo movimiento hacia abajo hasta la mitad, momento en que comenzarás a rotar uno de tus codos hacia la rodilla opuesta.\nVolvé a hacer una pausa breve en la parte inferior y subí de manera lenta y controlada hasta la posición inicial.\nRepetí el mismo movimiento anterior, pero alterná el otro codo hacia la rodilla opuesta.\nContinuá esta serie de movimientos hasta el fallo.' WHERE name_en = 'Kneeling Cable Crunch With Alternating Oblique Twists';
UPDATE public.exercises SET instructions_es = 'Colocá un banco de lado frente a una máquina de polea alta.\nSujetá un agarre recto sobre tu cabeza con las manos separadas unos 15 cm y las palmas hacia abajo.\nMirá hacia atrás, alejándote de la máquina, y arrodillate.\nApoyá tu cabeza y la parte posterior de tus brazos superiores en el banco. Tus codos deben estar flexionados con los antebrazos apuntando hacia la polea alta. Esta será tu posición inicial.\nMientras mantenés tus brazos superiores pegados a tu cabeza y los codos hacia adentro, empujá la barra en un movimiento semicircular hasta que los codos estén extendidos y tus brazos queden paralelos al suelo. Contraé fuerte los tríceps y mantené esta posición por un segundo. Exhalá mientras realizás este movimiento.\nVolvé lentamente a la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Kneeling Cable Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Comenzá arrodillado sobre una alfombra con las palmas planas y los dedos apuntando hacia atrás, hacia tus rodillas.\nInclináte lentamente hacia atrás manteniendo las palmas planas en el suelo hasta que sientas un estiramiento en las muñecas y los antebrazos. Mantené esta posición durante 20-30 segundos.' WHERE name_en = 'Kneeling Forearm Stretch';
UPDATE public.exercises SET instructions_es = 'Elegí el peso adecuado usando una polea que esté sobre tu cabeza.\nAsegurá una cuerda al cable y arrodillate a un par de pies de distancia, sosteniendo la cuerda frente a vos con ambos brazos extendidos. Esta será tu posición inicial.\nIniciá el movimiento flexionando los codos y retrayendo completamente los hombros, tirando de la cuerda hacia el pecho superior con los codos hacia afuera.\nDespués de una breve pausa, volvé lentamente a la posición inicial.' WHERE name_en = 'Kneeling High Pulley Row';
UPDATE public.exercises SET instructions_es = 'Arrodillate sobre una alfombra y llevá la rodilla derecha hacia arriba para que la planta del pie toque el suelo y extendé la pierna izquierda hacia atrás con la parte superior del pie apoyada en el piso.\nDesplazá el peso hacia adelante hasta sentir un estiramiento en la cadera.\nMantené la posición durante 15 segundos y repetí en el otro lado.' WHERE name_en = 'Kneeling Hip Flexor';
UPDATE public.exercises SET instructions_es = 'Recostá de rodillas en el suelo con una barra en la espalda, o usá tu peso corporal.\nSentá hacia atrás con las caderas hasta que los glúteos toquen los pies, manteniendo la cabeza y el pecho arriba.\nExplotá hacia arriba con las caderas, generando suficiente potencia para aterrizar con los pies planos en el suelo.\nContinuá con la sentadilla impulsando con los talones y extendiendo las rodillas para llegar a la posición de pie.' WHERE name_en = 'Kneeling Jump Squat';
UPDATE public.exercises SET instructions_es = 'Conectá un mango único a una polea alta y elegí tu peso.\nRecostá de rodillas frente a la torre de cables, tomá el cable con una mano y el brazo extendido.\nCon la palma hacia adelante, tirá el peso hacia tu torso flexionando el codo y retrayendo la escápula.\nMientras lo hacés, rotá la muñeca para que al final del movimiento la palma mire hacia vos.\nDespués de una breve pausa, volvé a la posición inicial.' WHERE name_en = 'Kneeling Single-Arm High Pulley Row';
UPDATE public.exercises SET instructions_es = 'Ajustá la barra a la altura correcta en un rack de potencia.\nArrodillate detrás de la barra; puede ser útil poner una colchoneta para proteger las rodillas.\nDeslizate bajo la barra, apoyándola en la parte trasera de los hombros.\nRetraé los omóplatos y mantené la barra firme contra la espalda.\nDesbloqueá el peso.\nCon la cabeza mirando hacia adelante, sentate hacia atrás con el glúteo hasta tocar las pantorrillas.\nInvertí el movimiento, devolviendo el torso a una posición vertical.' WHERE name_en = 'Kneeling Squat';
UPDATE public.exercises SET instructions_es = 'Colocá la barra en un landmine o anclala firmemente en una esquina.\nCargá la barra con un peso adecuado.\nLevantá la barra del suelo hasta la altura de los hombros con ambas manos y los brazos extendidos frente a vos.\nAdoptá una postura amplia. Esta será tu posición inicial.\nRealizá el movimiento rotando el tronco y las caderas mientras balanceás el peso hacia un lado.\nMantené los brazos extendidos durante todo el ejercicio.\nInvertí el movimiento para balancear el peso hacia el lado opuesto.\nContinuá alternando el movimiento hasta completar la serie.' WHERE name_en = 'Landmine 180''s';
UPDATE public.exercises SET instructions_es = 'Colocá la barra en un landmine o, si no tenés uno, anclala firmemente en una esquina. Cargá la barra con un peso adecuado y colocá el accesorio de agarre en la barra.\nLevantá la barra del suelo, llevando los agarres hacia tus hombros. Esta será tu posición inicial.\nEn una postura atlética, agachate flexionando las caderas y llevándolas hacia atrás, manteniendo los brazos flexionados.\nInvertí el movimiento extendiendo con fuerza a través de las caderas, rodillas y tobillos, mientras también extendés los codos para enderezar los brazos. Este movimiento debe hacerse de forma explosiva, saliendo del agachado hacia la extensión completa con la mayor potencia posible.\nVolvé a la posición inicial.' WHERE name_en = 'Landmine Linear Jammer';
UPDATE public.exercises SET instructions_es = 'Asumí una posición de medio agachado, mirando 90 grados respecto a tu dirección de desplazamiento. Esta será tu posición inicial.\nDejá que tu pierna delantera haga un movimiento de contramovimiento hacia adentro mientras transferís el peso a la pierna externa.\nInmediatamente impulsate y extendé, intentando saltar hacia el lado lo más lejos posible.\nAl aterrizar, impulsate inmediatamente en la dirección opuesta, volviendo a tu posición de inicio original.\nContinuá de un lado a otro durante varias repeticiones.' WHERE name_en = 'Lateral Bound';
UPDATE public.exercises SET instructions_es = 'Pará cómodo con una caja corta a tu lado como posición inicial\nHacé un cuarto de sentadilla rápido para activar el reflejo de estiramiento y rebotá hacia arriba y al lado\nLlevá las rodillas lo suficientemente alto para que los pies pasen por encima de la caja\nAterriza en el centro de la caja usando las piernas para absorber el impacto\nSaltá con cuidado al otro lado de la caja y repetí el movimiento varias veces' WHERE name_en = 'Lateral Box Jump';
UPDATE public.exercises SET instructions_es = 'Colocá una fila de conos separados entre sí\nPará al final de los conos mirando 90 grados respecto a la dirección de avance como posición inicial\nIniciá el salto flexionando las rodillas para activar el reflejo de estiramiento y empujá el suelo para saltar hacia arriba y al lado por encima del cono\nUsá las piernas para absorber el impacto al aterrizar y rebotá hacia el siguiente salto continuando por la fila de conos' WHERE name_en = 'Lateral Cone Hops';
UPDATE public.exercises SET instructions_es = 'Pará sobre la banda elástica para que la tensión comience a la altura de tus brazos.\nAgarrá los mangos con las palmas hacia los muslos, en una posición ligeramente más angosta que el ancho de tus hombros.\nDejá que los mangos descansen en los lados de tus muslos, con los brazos extendidos, una leve flexión en los codos y la espalda recta.\nUsá tus hombros laterales para levantar los mangos hacia los lados mientras exhalás.\nSeguí levantando hasta que queden ligeramente por encima de la posición paralela.\nIncliná ligeramente la mano como si estuvieras vertiendo agua y mantené los brazos extendidos.\nMantené el torso quieto y hacé una pausa de un segundo en la parte superior del movimiento.\nBajá los mangos lentamente hasta la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Lateral Raise - With Bands';
UPDATE public.exercises SET instructions_es = 'Recostá en el piso y colocá el rodillo de espuma bajo tu espalda, hacia un lado, justo detrás de tu axila.\nMantené el brazo del lado que estás estirando detrás y hacia el costado.\nDesplazá tu peso sobre los dorsales para mantener el torso elevado del suelo.\nMantené la posición durante 10 a 30 segundos.\nCambiá de lado.' WHERE name_en = 'Latissimus Dorsi-SMR';
UPDATE public.exercises SET instructions_es = 'Recostá en el piso con una kettlebell en el pecho, agarrándola por el mango.\nExtendé la pierna del lado de trabajo por encima de la pierna del lado no activo.\nExtendé el brazo libre hacia el costado para apoyar.\nEmpujá la kettlebell hasta la posición bloqueada.\nBajá el peso hasta que el codo toque el suelo, manteniendo la kettlebell por encima del codo.\nRepetí la cantidad de repeticiones deseadas.' WHERE name_en = 'Leg-Over Floor Press';
UPDATE public.exercises SET instructions_es = 'Recostá boca arriba, doblá una rodilla y apoyá ese pie plano en el piso para estabilizar la columna.\nExtendé la otra pierna en el aire.\nSi tenés rigidez, no vas a poder estirarla del todo, está bien.\nExtendé la rodilla de modo que la planta del pie elevado mire al techo (o lo más cerca que puedas).\nEstirá las piernas lo más rectas que puedas y luego tirá la pierna hacia la nariz.\nCambiá de lado.' WHERE name_en = 'Leg-Up Hamstring Stretch';
UPDATE public.exercises SET instructions_es = 'Elegí tu peso y sentate en la máquina con las piernas bajo la almohadilla (pies apuntando hacia adelante) y las manos agarrando las barras laterales.\nAjustá la almohadilla para que caiga sobre la parte inferior de la pierna (justo por encima de los pies) y asegurá de que tus piernas formen un ángulo de 90 grados entre la pierna inferior y la superior.\nExtendé las piernas al máximo usando los cuádriceps mientras exhalás, manteniendo el resto del cuerpo quieto en el asiento.\nHacé una pausa de un segundo en la posición contraída.\nBajá el peso lentamente a la posición original mientras inhalás, asegurándote de no pasar el límite de 90 grados.\nRepetí la cantidad de veces recomendadas.' WHERE name_en = 'Leg Extensions';
UPDATE public.exercises SET instructions_es = 'Parate derecho con los pies juntos a la anchura de los hombros y agarrate de una superficie firme, como los laterales de una rack de sentadillas o el respaldo de una silla, para mantener el equilibrio.\nLevantá una pierna hacia atrás como si hicieras una curl de pierna pero de pie, manteniendo la otra pierna recta, y exhalá mientras realizás el movimiento.\nLlevá la pierna elevada de vuelta al suelo lentamente mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.\nRepetí el movimiento con la pierna opuesta.' WHERE name_en = 'Leg Lift';
UPDATE public.exercises SET instructions_es = 'Sentate en la máquina de prensa de piernas y colocá tus pies en la plataforma con una separación a la anchura de los hombros.\nBajá las barras de seguridad y empujá la plataforma hacia arriba hasta que tus piernas estén completamente extendidas, sin bloquear las rodillas.\nInhala y bajá la plataforma lentamente hasta que tus muslos y pantorrillas formen un ángulo de 90 grados.\nExhalá y empujá principalmente con los talones, usando los cuádriceps, para volver a la posición inicial.\nRepetí la cantidad de repeticiones recomendadas y asegurá los seguros antes de salirte.' WHERE name_en = 'Leg Press';
UPDATE public.exercises SET instructions_es = 'Recostate boca arriba en una colchoneta con las piernas extendidas y las manos apoyadas a los costados o bajo los glúteos.\nExhalá y doblá las rodillas, llevando los muslos hacia el abdomen hasta que las rodillas queden a la altura del pecho, manteniendo las pantorrillas paralelas al suelo.\nContrá los abdominales y mantené la posición un segundo en la parte superior.\nInhala y volvé lentamente a la posición inicial.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Leg Pull-In';
UPDATE public.exercises SET instructions_es = 'Cargá un peso adecuado en los pasadores y ajustá el asiento a tu altura. Las manijas deben estar cerca de la parte inferior o media de los pectorales al inicio del movimiento.\nMantené el pecho y la cabeza arriba y las escápulas retraídas. Esta será tu posición inicial.\nEmpujá las manijas hacia adelante extendiendo los codos.\nDespués de una breve pausa arriba, devolvé el peso justo por encima de la posición inicial, manteniendo la tensión en los músculos sin apoyar el peso en los toques hasta completar la serie.' WHERE name_en = 'Leverage Chest Press';
UPDATE public.exercises SET instructions_es = 'Cargá los pasadores con un peso adecuado. Colocate directamente entre las manijas. Agarrá las manijas inferiores con un agarre cómodo y bajá las caderas mientras tomás aire. Mirá al frente con la cabeza y mantené el pecho arriba. Esta será tu posición inicial.\nDevolvé el peso a la posición inicial.' WHERE name_en = 'Leverage Deadlift';
UPDATE public.exercises SET instructions_es = 'Cargá un peso adecuado en los pasadores y ajustá el respaldo a tu altura. Las empuñaduras deben estar cerca de la parte inferior de los pectorales al inicio del movimiento. Mantené el pecho y la cabeza arriba y las escápulas retraídas. Esta será tu posición inicial.\nEmpujá las empuñaduras hacia adelante extendiendo los codos.\nDespués de una breve pausa en la parte superior, devolvé el peso justo por encima de la posición inicial, manteniendo la tensión en los músculos sin apoyar el peso en los topeadores hasta completar la serie.' WHERE name_en = 'Leverage Decline Chest Press';
UPDATE public.exercises SET instructions_es = 'Cargá un peso adecuado en los pasadores y ajustá la altura del asiento para que apenas alcances las empuñaduras que están sobre tu cabeza. Ajustá la almohadilla de rodillas para ayudarte a mantenerte abajo. Agarrá las empuñaduras con una agarre prono. Esta será tu posición inicial.\nJalá las empuñaduras hacia tu torso, retraendo las escápulas mientras flexionás los codos.\nHacé una pausa en la parte inferior del movimiento y luego devolvé las empuñaduras lentamente a la posición inicial.\nPara múltiples repeticiones, evitá apoyar completamente el peso en los topeadores para mantener la tensión en los músculos trabajados.' WHERE name_en = 'Leverage High Row';
UPDATE public.exercises SET instructions_es = 'Cargá un peso adecuado en los pasadores y ajustá el respaldo a tu altura. Las manijas deben estar cerca de la parte superior de los pectorales al inicio del movimiento. Mantené el pecho y la cabeza arriba y las escápulas retraídas. Esta será tu posición inicial.\nEmpujá las manijas hacia adelante extendiendo los codos.\nDespués de una breve pausa en la parte superior, volvé el peso justo por encima de la posición inicial, manteniendo la tensión en los músculos sin devolver el peso a los toques hasta completar la serie.' WHERE name_en = 'Leverage Incline Chest Press';
UPDATE public.exercises SET instructions_es = 'Cargá un peso adecuado en los pasadores y ajustá la altura del asiento para que las manijas queden a la altura del pecho. Agarrá las manijas con un agarre neutro o prono. Esta será tu posición inicial.\nJalá las manijas hacia tu torso, retraendo las escápulas mientras flexionás los codos.\nHacé una pausa en la parte inferior del movimiento y luego volvé las manijas lentamente a la posición inicial. Para varias repeticiones, evitá devolver completamente el peso a los toques para mantener la tensión en los músculos trabajados.' WHERE name_en = 'Leverage Iso Row';
UPDATE public.exercises SET instructions_es = 'Cargá un peso adecuado en los pasadores y ajustá el asiento a tu altura.\nMantené el pecho y la cabeza arriba, con las manijas cerca de la parte superior de los hombros y un agarre prono.\nEmpujá las manijas hacia arriba extendiendo los codos.\nHacé una breve pausa arriba y volvé el peso a justo encima de la posición inicial, manteniendo la tensión en los músculos sin apoyar el peso en los toques hasta terminar la serie.' WHERE name_en = 'Leverage Shoulder Press';
UPDATE public.exercises SET instructions_es = 'Cargá los pasadores con un peso adecuado y colocate directamente entre las manijas.\nAgarrá las manijas superiores con un agarre cómodo y bajá las caderas mientras tomás aire.\nMiran al frente con la cabeza y mantené el pecho arriba.\nEmpujá el suelo con los talones, extendiendo caderas y rodillas para ponerte de pie, manteniendo los brazos rectos y los hombros atrás.\nLevantá el peso encogiendo los hombros hacia las orejas, moviéndolo recto hacia arriba y abajo.\nHacé una pausa arriba y volvé el peso a la posición inicial.' WHERE name_en = 'Leverage Shrug';
UPDATE public.exercises SET instructions_es = 'Colocá los dos pies sobre la línea de partida.\nApoyá la punta del pie izquierdo junto al tobillo derecho.\nColocá el pie derecho 4 a 6 pulgadas detrás del izquierdo.\nApoyá la mano derecha sobre la línea y acercá la nariz a la rodilla izquierda.\nAgachate y inclináte hacia adelante, manteniendo la cabeza más baja que las caderas y el peso sobre la pierna izquierda.\nLevantá la mano izquierda hasta que quede paralela al suelo, apuntando hacia atrás, y explotá hacia adelante cuando estés listo.' WHERE name_en = 'Linear 3-Part Start Technique';
UPDATE public.exercises SET instructions_es = 'Inclináte contra la pared a unos 45 grados, con los pies juntos y los glúteos contraídos.\nLevantá rápidamente la rodilla derecha, hacé una pausa y luego impulsala directamente hacia el suelo.\nCambiá de pierna, levantá la rodilla opuesta y atacá el suelo directamente hacia abajo.\nRepetí una vez más con la pierna derecha y, en cuanto el pie derecho toque el suelo, acelerá rápidamente alternando izquierda y derecha lo más rápido que puedas.' WHERE name_en = 'Linear Acceleration Wall Drill';
UPDATE public.exercises SET instructions_es = 'Pará sobre una de las cajas mirando hacia la otra.\nBajate suavemente al suelo entre las plataformas, flexionando las rodillas y las caderas.\nExplotá hacia arriba extendiendo caderas, rodillas y tobillos para saltar a la otra plataforma.\nAterrizá suavemente absorbiendo el impacto con las piernas.' WHERE name_en = 'Linear Depth Jump';
UPDATE public.exercises SET instructions_es = 'Pará con el tronco frente a vos, agarrá los mangos y empezá a limpiarlo.\nMientras estás agachado, intentá llevar el tronco lo más alto posible, tirándolo hacia tu pecho.\nExtendé caderas y rodillas para completar el clean.\nEmpujá la cabeza hacia atrás y mirá hacia arriba para crear una repisa en el pecho para descansar el tronco.\nEmpezá el press bajando ligeramente flexionando las rodillas y luego revirtiendo el movimiento para generar impulso.\nExtendé los codos para presionar el tronco sobre tu cabeza.\nAsegurate de empujar la cabeza hacia adelante en cada repetición, mirando al frente.\nRepetí tantas veces como puedas, controlando la bajada del tronco al suelo.' WHERE name_en = 'Log Lift';
UPDATE public.exercises SET instructions_es = 'Asegurá una cuerda de escalada en una viga alta o travesaño. Debajo, verificá que la barra de la máquina Smith esté bloqueada con las seguridades y no pueda moverse. Alternativamente, podés usar una caja segura.\nPará sobre la barra, usá la cuerda para equilibrarte. Esta será tu posición inicial.\nMantené el cuerpo recto, inclinát hacia atrás y bajá el cuerpo lentamente pasando la mano por la cuerda. Continuí hasta que seas perpendicular al suelo.\nMantené el cuerpo recto, invertí el movimiento y pasá la mano por la cuerda de vuelta a la posición inicial.' WHERE name_en = 'London Bridges';
UPDATE public.exercises SET instructions_es = 'Arrodillát en el piso, agarrá tus talones con ambas manos.\nLevantá los glúteos hacia arriba y adelante mientras llevás la cabeza hacia atrás para mirar el techo, creando un arco en la espalda.' WHERE name_en = 'Looking At Ceiling';
UPDATE public.exercises SET instructions_es = 'Colocá las poleas en la posición baja, elegí la resistencia y agarrá un mango en cada mano.\nDá un paso al frente para generar tensión en las poleas, con las palmas hacia adelante, las manos por debajo de la cintura y los brazos estirados.\nCon una leve flexión en los codos, subí las manos hacia la línea media de tu cuerpo hasta que se junten frente a tu pecho, con las palmas hacia arriba.\nVolvé a la posición inicial después de una breve pausa.' WHERE name_en = 'Low Cable Crossover';
UPDATE public.exercises SET instructions_es = 'Elegí el peso deseado y recostate boca arriba en el banco de la máquina de remada sentada con cuerda, con la cabeza apuntando hacia el anclaje.\nAgarrá los extremos externos de la cuerda con las palmas mirándose entre sí (agarre neutro).\nColocá los codos flexionados a 90 grados y los brazos superiores perpendiculares a tu torso, apuntando al techo mientras los antebrazos miran hacia la polea.\nExhalá y extendé los antebrazos hasta que queden rectos y verticales, manteniendo los codos y brazos superiores quietos.\nContrá los tríceps con fuerza durante un segundo.\nInhalá y volvé lentamente a la posición inicial.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Low Cable Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Sentate en la máquina de remos con polea baja con un accesorio de cuerda.\nAgarrá los extremos de la cuerda con las palmas hacia abajo y sentate con la espalda recta y las rodillas ligeramente flexionadas. Consejo: Mantené la espalda casi completamente vertical y los brazos completamente extendidos frente a vos. Esta será tu posición inicial.\nMientras mantenés el torso inmóvil, levantá los codos y empezá a flexionarlos mientras tirás de la cuerda hacia tu cuello mientras exhalás. Durante todo el movimiento, los brazos superiores deben permanecer paralelos al suelo. Consejo: Continuá este movimiento hasta que tus manos estén casi junto a tus orejas (los antebrazos no estarán paralelos al suelo al final del movimiento, ya que estarán inclinados un poco hacia arriba) y tus codos estén alejados de los costados.\nDespués de mantener la posición contraída por un segundo o así, volvé lentamente a la posición inicial mientras inhalás. Consejo: De nuevo, en ninguna parte del movimiento debe moverse el torso.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Low Pulley Row To Neck';
UPDATE public.exercises SET instructions_es = 'En posición sentada, colocá un rodillo de espuma bajo tu espalda baja. Cruzá los brazos frente a vos y protráe los hombros. Esta será tu posición inicial.\nLevantá las caderas del suelo y recostate hacia atrás, manteniendo el peso en tu espalda baja. Ahora, desplazá el peso ligeramente hacia un lado, manteniendo el peso fuera de la columna y en los músculos a los lados de ella. Rodá sobre tu espalda baja, sosteniendo los puntos de tensión durante 10-30 segundos. Repetí en el otro lado.' WHERE name_en = 'Lower Back-SMR';
UPDATE public.exercises SET instructions_es = 'Recostate boca abajo con los brazos extendidos a los costados. Esta será tu posición inicial.\nUsando los músculos de la zona lumbar, extendé tu columna vertebral levantando el pecho del suelo. No uses los brazos para empujarte hacia arriba. Mantené la cabeza arriba durante el movimiento. Repetí de 10 a 20 repeticiones.' WHERE name_en = 'Lower Back Curl';
UPDATE public.exercises SET instructions_es = 'Parate con el torso erguido sosteniendo una kettlebell en la mano derecha. Esta será tu posición inicial.\nDá un paso adelante con el pie izquierdo y bajá el cuerpo superior flexionando la cadera y la rodilla, manteniendo el torso erguido. Bajá la rodilla trasera hasta que casi toque el suelo.\nMientras hacés la zancada, pasá la kettlebell por debajo de la pierna delantera hacia la mano opuesta.\nEmpujando a través del talón del pie, volvé a la posición inicial.\nRepetí el movimiento por la cantidad de repeticiones recomendadas, alternando las piernas.' WHERE name_en = 'Lunge Pass Through';
UPDATE public.exercises SET instructions_es = 'Ajustá una barra en una máquina Smith a la altura adecuada.\nPosicioná tu cuerpo bajo la barra, apoyándola en la parte trasera de tus hombros.\nDesbloqueá la barra y separá tus pies, llevando uno hacia adelante y el otro hacia atrás. Esta será tu posición inicial.\nBajá tu rodilla trasera casi hasta el suelo, flexionando las rodillas y bajando las caderas al hacerlo.\nEn el punto más bajo de la bajada, invertí la dirección de inmediato.\nEmpujá explosivamente a través del talón de tu pie delantero con una presión ligera desde tu pie trasero. Saltá y cambiá la posición de tus piernas.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Lunge Sprint';
UPDATE public.exercises SET instructions_es = 'Recostate boca arriba con las rodillas dobladas y las plantas de los pies juntas. Pedile a tu compañero que sostenga tus rodillas. Esta será tu posición inicial.\nIntentá apretar tus rodillas juntas, mientras tu compañero impide que se produzca cualquier movimiento.\nDespués de 10 a 20 segundos, relajá tus músculos mientras tu compañero empuja suavemente tus rodillas hacia el suelo. Asegurate de informar a tu ayudante cuando el estiramiento sea suficiente para evitar lesiones o estiramientos excesivos.' WHERE name_en = 'Lying Bent Leg Groin';
UPDATE public.exercises SET instructions_es = 'Agarrá una barra recta o de E-Z conectada al polea baja con ambas manos, usando un agarre supino (palmas hacia arriba) a la anchura de los hombros.\nRecostá boca arriba sobre una colchoneta frente a la torre de pesos, con los pies apoyados firmemente en el marco de la máquina y las piernas estiradas.\nCon los brazos extendidos y los codos cerca del cuerpo, flexioná ligeramente los brazos. Esta será tu posición inicial.\nMientras mantenés los brazos superiores estacionarios y los codos pegados al cuerpo, subí la barra lentamente hacia el pecho mientras exhalás y apretás los bíceps.\nDespués de un segundo de contracción en la parte superior del movimiento, volvé lentamente a la posición inicial.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Lying Cable Curl';
UPDATE public.exercises SET instructions_es = 'Colocá una barra curvada debajo de un banco de ejercicios.\nRecostá boca abajo sobre el banco de ejercicios y agarrá la barra con un agarre prono (palmas hacia abajo) más ancho que la anchura de los hombros. Esta será tu posición inicial.\nMientras exhalás, jalá la barra hacia arriba manteniendo los codos pegados al cuerpo, ya sea hacia el pecho para trabajar la parte media superior de la espalda o hacia el estómago si tu objetivo es trabajar los dorsales.\nDespués de sostener un segundo en la parte superior, bajá lentamente a la posición inicial mientras inhalás.' WHERE name_en = 'Lying Cambered Barbell Row';
UPDATE public.exercises SET instructions_es = 'Recostá sobre tu espalda en un banco plano con la cabeza colgando del borde, sosteniendo la barra con agarre prono (palmas hacia adelante).\nExtendé los brazos frente a vos, manteniendo la barra sobre el pecho y los brazos perpendiculares al torso (ángulo de 90 grados).\nInhala y bajá la barra en un movimiento semicircular flexionando los codos, manteniendo los brazos superiores fijos y los codos pegados al cuerpo hasta que la barra toque suavemente tu barbilla.\nExhalá y empujá la barra hacia arriba en un movimiento semicircular hasta la posición inicial, contrayendo los tríceps con fuerza durante un segundo en la parte superior.\nRepetí el movimiento la cantidad de repeticiones recomendadas.' WHERE name_en = 'Lying Close-Grip Barbell Triceps Press To Chin';
UPDATE public.exercises SET instructions_es = 'Recostá sobre tu espalda con las piernas extendidas.\nCruzá una pierna sobre el cuerpo con la rodilla flexionada, intentando tocar la rodilla al suelo, mientras tu pareja se arrodilla a tu lado sujetando tu hombro con una mano y controlando la pierna cruzada con la otra.\nIntentá levantar la rodilla flexionada del suelo mientras tu pareja impide cualquier movimiento real.\nDespués de 10 a 20 segundos, relajá la pierna mientras tu pareja presiona suavemente la rodilla hacia el suelo y repetí con el otro lado.' WHERE name_en = 'Lying Crossover';
UPDATE public.exercises SET instructions_es = 'Recostate en un banco plano sosteniendo dos mancuernas directamente frente a vos.\nExtendé los brazos completamente a 90 grados respecto a tu torso y al suelo, con las palmas mirándose y los codos pegados al cuerpo.\nInhalá y mantené los brazos superiores estacionarios con los codos pegados mientras bajás lentamente el peso hasta que las mancuernas queden cerca de tus orejas.\nExhalá y usá los tríceps para llevar el peso de vuelta a la posición inicial, manteniendo los codos pegados y los brazos superiores quietos.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Lying Dumbbell Tricep Extension';
UPDATE public.exercises SET instructions_es = 'Recostate boca abajo con el cuerpo recto en un banco plano, sosteniendo una placa de peso detrás de la cabeza.\nPosicionate de modo que los hombros queden ligeramente por encima del extremo del banco para que el pecho superior, el cuello y la cara queden fuera del banco.\nMantené la placa firme en la nuca y bajá lentamente la cabeza (como diciendo "sí") mientras inhalás.\nLevantá la cabeza de vuelta a la posición inicial en un movimiento semicircular mientras exhalás.\nMantené la contracción por un segundo.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Lying Face Down Plate Neck Resistance';
UPDATE public.exercises SET instructions_es = 'Recostá boca arriba con el cuerpo completamente recto en un banco plano, sosteniendo una placa de peso sobre la frente.\nPosicionate de modo que los hombros queden ligeramente por encima del extremo del banco, dejando las trapecios, el cuello y la cabeza fuera del banco. Esta será tu posición inicial.\nMientras mantenes la placa firme sobre la frente, bajá lentamente la cabeza hacia atrás en un movimiento semicircular mientras inhalás.\nLevantá la cabeza de vuelta a la posición inicial en un movimiento semicircular mientras exhalás. Mantené la contracción durante un segundo.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Lying Face Up Plate Neck Resistance';
UPDATE public.exercises SET instructions_es = 'Recostá boca abajo con tu pareja arrodillada a tu lado.\nFlexioná la cadera de una pierna, levantándola del suelo. Rotá la pierna para que el pie quede sobre la cadera opuesta, con la pierna inferior perpendicular a tu cuerpo. Tu pareja debe sostener la rodilla y el tobillo en su lugar. Esta será tu posición inicial.\nIntentá empujar la pierna hacia tu pareja, quien debe evitar cualquier movimiento real de la pierna.\nDespués de 10 a 20 segundos, relajate por completo mientras tu pareja empuja suavemente el tobillo y la rodilla hacia tu pecho. Asegurate de informar a tu asistente cuando el estiramiento sea adecuado para prevenir lesiones o estiramientos excesivos.' WHERE name_en = 'Lying Glute';
UPDATE public.exercises SET instructions_es = 'Recostá boca arriba con las piernas extendidas y pedile a tu pareja que se arrodille a tu lado.\nLevantá una pierna hacia el techo y dejá que tu pareja sostenga tu tobillo, usando su hombro para estabilizarla si es necesario.\nCon tu pareja sosteniendo la pierna, intentá flexionar la rodilla contrayendo los isquiotibiales durante 10 a 20 segundos.\nRelajá la pierna y dejá que tu pareja la empuje suavemente hacia tu cabeza, avisándole cuando el estiramiento sea suficiente para evitar lesiones.\nCambiala de lado una vez que termines.' WHERE name_en = 'Lying Hamstring';
UPDATE public.exercises SET instructions_es = 'Recostá boca abajo en un banco plano alto sosteniendo una barra con agarre supino (palmas hacia arriba).\nPosicioná tu cuerpo de modo que el pecho superior quede sobre el borde del banco y la barra cuelgue frente a vos con los brazos extendidos y perpendiculares al suelo.\nManteniendo los codos pegados y los brazos superiores quietos, subí el peso en un movimiento semicircular contrayendo los bíceps mientras exhalás.\nMantené la posición en la parte superior del movimiento durante un segundo.\nInhalá y volvé lentamente a la posición inicial, manteniendo el control total del peso y evitando balanceos, moviendo solo los antebrazos.\nRepetí el ejercicio la cantidad de veces recomendada.' WHERE name_en = 'Lying High Bench Barbell Curl';
UPDATE public.exercises SET instructions_es = 'Recostá boca abajo en un banco plano sosteniendo una mancuerna en una mano, usá la otra mano para agarrar la pata del banco para estabilidad.\nPosicioná la palma de la mano con la mancuerna de forma neutra (mirando hacia tu torso) con el brazo extendido y el codo ligeramente doblado, esta es tu posición inicial.\nLevantá el brazo con la mancuerna hacia el lado hasta que el codo quede a la altura del hombro y el brazo quede paralelo al suelo, exhalá mientras subís.\nMantené el brazo perpendicular al torso y extendido durante todo el movimiento, sostené la contracción arriba por un segundo.\nBajá lentamente la mancuerna a la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Lying One-Arm Lateral Raise';
UPDATE public.exercises SET instructions_es = 'Recostá boca abajo en el suelo con tu pareja arrodillada a tu lado, flexioná una rodilla y levantá esa pierna intentando tocar tus glúteos con el pie mientras tu pareja sostiene la rodilla y el tobillo, esta es tu posición inicial.\nIntentá extender la rodilla mientras tu pareja impide cualquier movimiento real.\nDespués de 10 a 20 segundos, relajá tus músculos mientras tu pareja empuja suavemente el pie hacia tus glúteos para estirar más los cuádriceps y los flexores de la cadera.\nDespués de 10 a 20 segundos, cambiá de lado.' WHERE name_en = 'Lying Prone Quadriceps';
UPDATE public.exercises SET instructions_es = 'Recostá boca abajo en un banco plano sosteniendo una mancuerna en cada mano.\nPosicioná las palmas de las manos de forma neutra (mirando hacia tu torso) y mantené los brazos extendidos con los codos ligeramente flexionados; esta será tu posición inicial.\nAhora, subí los brazos hacia los lados hasta que los codos estén a la altura de los hombros y los brazos queden paralelos al suelo, mientras exhalás.\nConsejo: Mantené los brazos perpendiculares al torso y extendidos durante todo el movimiento. Además, mantené la contracción arriba durante un segundo.\nBajá lentamente las mancuernas hasta la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas y luego cambiá al otro brazo.' WHERE name_en = 'Lying Rear Delt Raise';
UPDATE public.exercises SET instructions_es = 'Recostá boca arriba en un banco plano sosteniendo una mancuerna en cada brazo sobre los muslos.\nLlevá las mancuernas hacia los lados con los brazos extendidos y las palmas de las manos mirando hacia los muslos (agarre neutro).\nMientras mantenés los brazos cerca del torso y los codos pegados, bajá lentamente los brazos (manteniéndolos extendidos con una leve flexión en los codos) lo más cerca posible del suelo.\nUna vez que no puedas bajar más, bloqueá los brazos superiores en esa posición; esa será tu posición inicial.\nMientras exhalás, empezá a hacer curl con los pesos lentamente, rotando simultáneamente las muñecas para que las palmas miren hacia arriba.\nContinuá el curl hasta que los bíceps estén completamente contraídos y apretá fuerte en la posición superior durante un segundo.\nConsejo: Solo deben moverse los antebrazos. Los brazos superiores deben permanecer estacionarios y los codos deben mantenerse pegados durante todo el movimiento.\nVolvé a la posición inicial muy lentamente.' WHERE name_en = 'Lying Supine Dumbbell Curl';
UPDATE public.exercises SET instructions_es = 'Cargá la máquina de remos T-bar con el peso deseado y ajustá la altura de las piernas para que tu pecho superior quede en la parte superior del cojín.\nRecostá boca abajo sobre el cojín y agarrá los mangos. Podés usar una posición de palmas hacia abajo, hacia arriba o hacia adentro, dependiendo de qué parte de la espalda quieras enfatizar.\nLevantá la barra del soporte y extendé los brazos frente a vos. Esta será tu posición inicial.\nMientras exhalás, tirá el peso hacia arriba lentamente y apretá la espalda en la parte superior del movimiento. Tip: Mantené los brazos superiores lo más cerca posible del torso durante todo el movimiento para involucrar mejor los músculos de la espalda. Además, no levantéis el cuerpo del cojín en ningún momento y evitá usar los bíceps para levantar el peso.\nDespués de un segundo de contracción en la parte superior, mientras inhalás, volvé a bajar lentamente a la posición inicial.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Lying T-Bar Row';
UPDATE public.exercises SET instructions_es = 'Recostá en un banco plano con una barra EZ (mi preferencia) o una barra recta colocada en el suelo detrás de tu cabeza y los pies en el piso.\nAgarrá la barra detrás de vos, usando un agarre medio supino (pronado), y levantá la barra frente a vos con los brazos extendidos. Tip: Los brazos deben ser perpendiculares al torso y al piso. Los codos deben estar recogidos. Esta es la posición inicial.\nMientras inhalás, bajá el peso lentamente hasta que la barra toque suavemente tu frente, manteniendo los brazos superiores y los codos estacionarios.\nEn ese punto, usá los tríceps para llevar el peso de vuelta a la posición inicial mientras exhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Lying Triceps Press';
UPDATE public.exercises SET instructions_es = 'Sentate en la máquina de press de pecho y elegí el peso.\nPoné el pie en la palanca provista por la máquina, ya que te va a ayudar a acercar los agarres para que puedas tomarlos y extender completamente los brazos.\nAgarrá los mangos con las palmas hacia abajo y levantá los codos para que los brazos superiores queden paralelos al suelo a los lados de tu torso. Tip: Tus antebrazos van a apuntar hacia adelante porque estás agarrando los mangos. Una vez que acerques los mangos y extiendas los brazos, vas a estar en la posición inicial.\nAhora acercá los mangos hacia vos mientras inhalás.\nEmpujá los mangos lejos de vos mientras contraés los pectorales y exhalás. Mantené la contracción un segundo antes de volver a la posición inicial.\nRepetí la cantidad de repeticiones recomendadas.\nCuando termines, poné el pie en la palanca otra vez y devolvé los mangos a su lugar original lentamente.' WHERE name_en = 'Machine Bench Press';
UPDATE public.exercises SET instructions_es = 'Ajustá el asiento a la altura adecuada y elegí tu peso. Apoyá los brazos superiores contra las almohadillas y agarrá los mangos. Esta va a ser tu posición inicial.\nRealizá el movimiento flexionando el codo, llevando el brazo inferior hacia el brazo superior.\nHacé una pausa en la parte superior del movimiento y luego devolvé el peso lentamente a la posición inicial.\nEvitá devolver el peso hasta los tope finales hasta que completes la serie para mantener la tensión en los músculos que estás trabajando.' WHERE name_en = 'Machine Bicep Curl';
UPDATE public.exercises SET instructions_es = 'Sentate en la máquina de curl predicador y elegí el peso.\nApoyá la parte trasera de tus brazos superiores (tríceps) en el cojín del predicador y agarrá los mangos con un agarre supino (palmas hacia arriba). Consejo: Asegurate de mantener los codos pegados al cuerpo al apoyar los brazos en el cojín. Esta será tu posición inicial.\nAhora levantá los mangos mientras exhalás y contraés los bíceps. En la parte superior de la posición, asegurate de mantener la contracción durante un segundo. Consejo: Solo los antebrazos deben moverse. Los brazos superiores deben permanecer estacionarios y sobre el cojín en todo momento.\nBajá los mangos lentamente de vuelta a la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Machine Preacher Curls';
UPDATE public.exercises SET instructions_es = 'Sentate en la máquina de press de hombros y elegí el peso.\nAgarrá los mangos a los lados de tu cuerpo manteniendo los codos doblados y alineados con tu torso. Esta será tu posición inicial.\nAhora levantá los mangos mientras exhalás y extendés los brazos por completo. En la parte superior de la posición, asegurate de mantener la contracción durante un segundo.\nBajá los mangos lentamente de vuelta a la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Machine Shoulder (Military) Press';
UPDATE public.exercises SET instructions_es = 'Ajustá el asiento a la altura adecuada y elegí tu peso.\nApoyá tus brazos superiores contra las almohadillas y agarrá los mangos.\nExtendé el codo para alejar el antebrazo del brazo superior.\nHacé una pausa al completar el movimiento y volvé lentamente a la posición inicial.\nEvitá que el peso llegue a los tope finales hasta terminar la serie para mantener la tensión en los músculos.' WHERE name_en = 'Machine Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Vas a necesitar un compañero para este ejercicio; si no tenés uno, podés hacerlo contra una pared.\nComenzá frente a tu compañero sosteniendo la pelota medicinal en el torso con ambas manos.\nJalá la pelota hacia el pecho y extendé los codos para lanzarla.\nTu compañero debe atrapar la pelota y devolvértela.\nRecibí el lanzamiento con ambas manos a la altura del pecho.' WHERE name_en = 'Medicine Ball Chest Pass';
UPDATE public.exercises SET instructions_es = 'Parate espalda contra espalda con tu compañero, dejando un espacio de 2 a 3 pies entre ustedes.\nSujetá la pelota medicinal frente al tronco.\nAbrí las caderas y girá los hombros al mismo tiempo que tu compañero.\nGiren en la misma dirección, por ejemplo, en sentido antihorario, para lograr una rotación completa.\nPasale la pelota a tu compañero y giren en la dirección opuesta para repetir el movimiento.' WHERE name_en = 'Medicine Ball Full Twist';
UPDATE public.exercises SET instructions_es = 'Asumí una posición de media sentadilla sujetando la pelota medicinal con las manos.\nDejá que los brazos cuelguen para que la pelota quede cerca de tus pies.\nEmpujá las caderas hacia adelante mientras extendés las piernas y saltás hacia arriba.\nAl mismo tiempo, levantá los brazos por encima de la cabeza manteniéndolos extendidos.\nSoltá la pelota en el punto más alto de tu movimiento para lanzarla lo más lejos posible hacia atrás.' WHERE name_en = 'Medicine Ball Scoop Throw';
UPDATE public.exercises SET instructions_es = 'Recostá boca abajo en un banco inclinado sosteniendo una mancuerna en cada mano.\nExtendé los brazos por completo, dejándolos colgar hacia el suelo con las palmas de las manos mirándose entre sí.\nExhalá, apretá las escápulas juntas y mantené la contracción durante un segundo completo.\nInhalá y volvé a la posición inicial.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Middle Back Shrug';
UPDATE public.exercises SET instructions_es = 'Parate con los pies separados al ancho de los hombros y las manos en las caderas.\nGirá la cintura hasta sentir el estiramiento.\nMantené la posición de 10 a 15 segundos.\nGirá hacia el otro lado.' WHERE name_en = 'Middle Back Stretch';
UPDATE public.exercises SET instructions_es = 'Agarrá la barra de dominadas con una separación apenas un poco más ancha que el ancho de los hombros, con la palma de una mano hacia adelante y la de la otra hacia vos.\nIniciá la posición de partida.\nComenzá a subir tu cuerpo mientras exhalás.\nConcentráte en usar los músculos de la espalda con el brazo que tiene la palma hacia arriba, manteniendo el codo cerca del torso.\nCon el otro brazo, que tiene la palma hacia adelante, mantené los codos alejados pero alineados con el torso, enfocándote en usar los dorsales para subir.\nMantené una contracción de un segundo en la parte superior.\nBajá lentamente mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.\nEn la siguiente serie, cambiá los agarres: si tenías la mano derecha hacia vos y la izquierda hacia adelante, ahora poné la derecha hacia adelante y la izquierda hacia vos.' WHERE name_en = 'Mixed Grip Chin';
UPDATE public.exercises SET instructions_es = 'Colocá una banda alrededor de ambos tobillos y otra alrededor de ambas rodillas.\nAsegurate de que haya suficiente tensión para que estén tensas cuando tus pies estén separados al ancho de los hombros.\nComenzá dando pasos cortos hacia adelante alternando el pie izquierdo y el derecho.\nDespués de varios pasos, hacé lo contrario y caminá hacia atrás hasta donde empezaste.' WHERE name_en = 'Monster Walk';
UPDATE public.exercises SET instructions_es = 'Colocate en posición de flexión, con el peso apoyado en las manos y las puntas de los pies.\nFlexioná la rodilla y la cadera, llevando una pierna hasta que la rodilla quede aproximadamente bajo la cadera. Esta será tu posición inicial.\nInvertí explosivamente la posición de tus piernas, extendiendo la pierna flexionada hasta que quede recta y apoyada en la punta del pie, mientras subís el otro pie con la cadera y la rodilla flexionadas.\nRepetí de manera alternada durante 20 a 30 segundos.' WHERE name_en = 'Mountain Climbers';
UPDATE public.exercises SET instructions_es = 'Este movimiento ayuda a preparar tu forma de carrera para que destaqués en el sprint. Mientras corrés, asegurá de flexionar la rodilla, apuntando a golpear los glúteos a medida que la cadera se extiende.\nRecargá el cuádriceps a medida que la pierna se mueve hacia adelante, atacando el suelo en el siguiente paso.\nAsegurate de que, mientras corrés, bloqueés con los brazos, empujando en un movimiento rápido de 1-2.' WHERE name_en = 'Moving Claw Series';
UPDATE public.exercises SET instructions_es = 'Colocá la barra cargada a la altura del muslo con agarre ancho.\nMantené los pies directamente debajo de las caderas, girándolos hacia afuera si es necesario.\nBajá las caderas manteniendo el pecho arriba y la mirada al frente.\nDejá que los hombros queden justo frente a la barra para la posición inicial.\nIniciá el tirón empujando con la parte delantera de los talones para levantar la barra.\nTransicioná a la segunda fase extendiendo caderas, rodillas y tobillos para subir la barra lo más rápido posible.\nMantené la barra pegada al cuerpo.\nSeguí subiendo la barra hasta la posición sobre la cabeza sin doblar las rodillas de nuevo.' WHERE name_en = 'Muscle Snatch';
UPDATE public.exercises SET instructions_es = 'Agarrá los aros con agarre falso, apoyando la base de las palmas sobre ellos.\nIniciá el jalón bajando los codos hacia los lados y flexionando los codos.\nAl llegar a la posición superior, llevá los aros hacia las axilas mientras girás los hombros hacia adelante.\nDejá que los codos se muevan rectos hacia atrás para posicionarte para el empuje.\nMantené el control y la estabilidad mientras extendés los codos para completar el movimiento.\nBajate al suelo con cuidado.' WHERE name_en = 'Muscle Up';
UPDATE public.exercises SET instructions_es = 'Colocá la barra en un soporte que se ajuste a tu altura.\nApoyá la parte trasera de tus hombros (justo debajo del cuello) sobre la barra.\nAgarrá la barra con ambas manos a los lados y levantala empujando con las piernas mientras enderezás el torso.\nRetretá del soporte y posicioná las piernas en una postura más angosta que el ancho de los hombros, con los pies apuntando ligeramente hacia afuera.\nMantené la cabeza arriba y la espalda recta en todo momento.\nBajá la barra lentamente doblando las rodillas, manteniendo la postura recta y la cabeza arriba.\nContinuá bajando hasta que el ángulo entre el muslo y la pantorrilla sea ligeramente menor a 90 grados (muslos por debajo de la paralela al suelo).\nInhalá mientras realizás esta parte del movimiento.\nSubí la barra exhalando, empujando el suelo principalmente con los talones mientras enderezás las piernas de vuelta a la posición inicial.\nRepetí por la cantidad de repeticiones recomendadas.' WHERE name_en = 'Narrow Stance Squats';
UPDATE public.exercises SET instructions_es = 'Posicionate en la máquina de jalón al pecho o banco predicador con los tobillos bajo las almohadillas, las rodillas en el asiento y mirando hacia atrás.\nMantené una postura erguida y correcta.\nBajate de forma controlada hasta que las rodillas estén casi completamente estiradas.\nSubite de vuelta a la posición inicial manteniendo el control.\nSi no podés completar la repetición, usá una banda, un compañero o empujá desde una caja para ayudarte.' WHERE name_en = 'Natural Glute Ham Raise';
UPDATE public.exercises SET instructions_es = 'Colocá el rodillo detrás de tu cabeza y contra tu cuello.\nAsegurate de no apoyar el rodillo directamente sobre la columna, sino girarlo ligeramente para que presione los músculos a ambos lados de la misma.\nEste será tu punto de partida.\nComenzando desde la parte superior del cuello, bajá lentamente rodando sobre los músculos del cuello.\nHacé pausas de 10 a 30 segundos en los puntos de tensión.' WHERE name_en = 'Neck-SMR';
UPDATE public.exercises SET instructions_es = 'Recostate boca arriba en un banco plano.\nUsá un agarre de ancho medio (que forme un ángulo de 90 grados entre los antebrazos y los brazos superiores en el punto medio del movimiento).\nLevantá la barra del soporte y mantenela recta sobre tu cuello con los brazos extendidos.\nEste será tu punto de partida.\nMientras inhalás, bajá lentamente hasta sentir la barra en tu cuello.\nDespués de una pausa de un segundo, devolvé la barra a la posición inicial mientras exhalás.\nEmpujá la barra usando los músculos del pecho.\nExtendé los brazos y contraé el pecho en la posición final.\nMantené la contracción un segundo y luego comenzá a bajar lentamente de nuevo.\nRecordá que el descenso debe tomar al menos el doble de tiempo que la subida.\nRepetí el movimiento la cantidad de repeticiones indicadas.\nCuando termines, devolvé la barra al soporte.' WHERE name_en = 'Neck Press';
UPDATE public.exercises SET instructions_es = 'Recostate plano en el suelo con la parte baja de la espalda apoyada en el piso. Colocá una mano al lado de la cabeza y la otra a un lado contra el suelo.\nAsegurate de que tus pies estén elevados y apoyados en una superficie plana.\nAhora levantá el hombro del lado donde tenés la mano tocando la cabeza.\nElevá tu hombro y cuerpo hacia arriba hasta tocar tu rodilla. Por ejemplo, si tenés la mano derecha al lado de la cabeza, querés elevar el cuerpo hacia arriba hasta que tu codo derecho toque tu rodilla izquierda. Podés aplicar la misma variación haciendo lo inverso y usando tu codo izquierdo para tocar tu rodilla derecha.\nDespués de que tu rodilla toque el codo, bajá tu cuerpo hasta haber alcanzado la posición inicial.\nRecordá inhalar durante la parte excéntrica (bajada) del ejercicio y exhalar durante la parte concéntrica (subida).\nSeguí alternando de esta manera hasta completar todas las repeticiones recomendadas para cada lado.' WHERE name_en = 'Oblique Crunches';
UPDATE public.exercises SET instructions_es = 'Comenzá recostado de lado derecho con las piernas una sobre la otra. Asegurate de que las rodillas estén dobladas un poco.\nColocá tu mano izquierda detrás de la cabeza.\nUna vez que estés en esta posición de inicio, comenzá moviendo tu codo izquierdo hacia arriba, como si realizaras un crunch normal, pero esta vez el énfasis principal está en tus oblicuos.\nHacé el crunch lo más alto que puedas, mantené la contracción por un segundo y luego bajá lentamente de vuelta a la posición inicial.\nRecordá inhalar durante la parte excéntrica (bajada) del ejercicio y exhalar durante la parte concéntrica (elevación).' WHERE name_en = 'Oblique Crunches - On The Floor';
UPDATE public.exercises SET instructions_es = 'Colocá la barra sobre los trapecios, mantené el pecho arriba y la cabeza mirando al frente.\nAdoptá una postura con los pies separados al ancho de cadera y girados hacia afuera según necesites.\nDescendé flexionando las rodillas, evitando mover la cadera hacia atrás lo máximo posible.\nDejá que las rodillas avancen hacia adelante, asegurándote de que queden alineadas con los pies.\nMantené el torso lo más vertical posible y el peso en la parte delantera del talón.\nBajá hasta que el muslo toque la pantorrilla y empujá el peso hacia arriba para revertir el movimiento.' WHERE name_en = 'Olympic Squat';
UPDATE public.exercises SET instructions_es = 'Recostate en un banco plano o escalón y dejá caer una pierna y un brazo por el costado.\nDoblá la rodilla y agarrá la parte superior del pie, cuidando de no arquear la zona lumbar.\nJalá el ombligo hacia la columna vertebral para mantener la postura neutra.\nEmpujá el pie hacia abajo y contra tu mano.\nPara estirar la cadera, levantá la cadera de la pierna que estás sosteniendo hacia el techo.\nCambiate de lado.' WHERE name_en = 'On-Your-Back Quad Stretch';
UPDATE public.exercises SET instructions_es = 'Recostate de lado derecho, con la rodilla derecha doblada a 90 grados apoyada en el suelo frente a vos para estabilizar el torso.\nDoblá la rodilla izquierda hacia atrás y agarrate el pie izquierdo con la mano izquierda.\nPara estirar el flexor de la cadera, empujá la cadera izquierda hacia adelante mientras empujás el pie izquierdo contra tu mano.\nCambiá de lado.' WHERE name_en = 'On Your Side Quad Stretch';
UPDATE public.exercises SET instructions_es = 'Elegí un banco plano y colocá una mancuerna a cada lado.\nApoyá la pierna derecha sobre el extremo del banco, incliná el torso hacia adelante desde la cintura hasta que quede paralelo al suelo y apoyá la mano derecha en el otro extremo del banco para sostenerte.\nUsá la mano izquierda para tomar la mancuerna del suelo y mantené el peso con la espalda baja recta, con la palma de la mano mirando hacia el torso.\nJalá la resistencia recto hacia el costado del pecho, manteniendo el brazo superior pegado al costado y el torso inmóvil, exhalando mientras lo hacés.\nConcentrate en apretar los músculos de la espalda al llegar a la posición de máxima contracción, asegurándote de que la fuerza venga de la espalda y no de los brazos, manteniendo el torso superior quieto.\nBajá la resistencia recto hacia la posición inicial, inhalando mientras lo hacés.\nRepetí el movimiento la cantidad de repeticiones indicadas.\nCambiá de lado y repetí con el otro brazo.' WHERE name_en = 'One-Arm Dumbbell Row';
UPDATE public.exercises SET instructions_es = 'Recostate en un banco plano con una mancuerna en una mano apoyada sobre el muslo, manteniendo la palma en agarre neutro.\nUsá tus muslos para ayudar a subir la mancuerna hasta tenerla frente a vos con el brazo de levantamiento completamente extendido, mientras tu otra mano sostiene el banco para mejor apoyo.\nMantené una leve flexión en el codo del brazo con el peso para evitar estrés en el tendón del bíceps.\nBajá tu brazo con el peso en un arco amplio hasta sentir un estiramiento en el pecho, respirando mientras lo hacés, y asegurá de que el movimiento ocurra solo en la articulación del hombro.\nVolvé a la posición inicial apretando los músculos del pecho y exhalando, usando el mismo arco de movimiento que usaste para bajar.\nMantené la posición contraída por un segundo y repetí el movimiento la cantidad de repeticiones prescritas.\nCambiá de brazo y repetí el ejercicio.' WHERE name_en = 'One-Arm Flat Bench Dumbbell Flye';
UPDATE public.exercises SET instructions_es = 'Conectá una manija estándar a la torre y mové el cable a la posición más alta de la polea.\nParate de lado al cable y, con una mano, agarrá la manija con agarre supino (palma hacia arriba).\nJalá el cable hacia abajo hasta que tu codo toque tu costado y la manija quede junto a tu hombro.\nMantené los pies separados al ancho de caderas y colocá tu mano libre en la cadera para ayudar a medir el punto de pivote.\nMantené el brazo en posición estática y contraé el oblicuo para bajar el peso en un crunch lateral.\nUna vez que alcances la máxima contracción, soltá el peso lentamente hasta la posición inicial, asegurándote de que la torre de pesos nunca se descargue por completo para mantener tensión constante.\nRepetí hasta el fallo.\nReposicioná y repetí la misma serie de movimientos en el lado opuesto.' WHERE name_en = 'One-Arm High-Pulley Cable Side Bends';
UPDATE public.exercises SET instructions_es = 'Recostá de lado en un banco inclinado con una mancuerna en la mano.\nAsegurate de que el hombro presione contra el banco y el brazo esté cruzado sobre tu cuerpo con la palma cerca del ombligo.\nMantené la mancuerna en el brazo superior extendida frente a vos, paralela al suelo. Esta es tu posición inicial.\nMantené la mancuerna paralela al suelo en todo momento mientras realizás un elevación lateral.\nSubí el brazo recto hasta que apunte al techo. Exhalá mientras realizás este movimiento.\nMantené la mancuerna en esa posición y sentí la contracción en los hombros durante un segundo.\nInhalá y bajá el peso cruzando el cuerpo de vuelta a la posición inicial.\nRepetí el movimiento la cantidad de repeticiones prescritas.\nCambialo de brazo y repetí el movimiento.' WHERE name_en = 'One-Arm Incline Lateral Raise';
UPDATE public.exercises SET instructions_es = 'Colocá una kettlebell entre tus pies.\nIncliná el cuerpo hacia abajo para agarrar la kettlebell, empujando el glúteo hacia atrás y manteniendo la mirada al frente.\nLlevá la kettlebell a tus hombros extendiendo las piernas y las caderas mientras la subís hacia el hombro.\nRotá la muñeca mientras realizás este movimiento.\nDevolvé el peso a la posición inicial.' WHERE name_en = 'One-Arm Kettlebell Clean';
UPDATE public.exercises SET instructions_es = 'Sujetá la kettlebell por el mango.\nLlevá la kettlebell hasta el hombro extendiendo las piernas y la cadera mientras tirás de la pesa hacia el hombro. Girá la muñeca para que la palma mire hacia adelante.\nFlexioná las rodillas para bajar el cuerpo, manteniendo el torso erguido.\nInvertí la dirección inmediatamente, empujando a través de los talones, saltando para crear impulso. Mientras lo hacés, empujá la kettlebell por encima de la cabeza hasta bloquear las articulaciones extendiendo los brazos, usando el impulso del cuerpo para mover el peso.\nRecibí el peso por encima de la cabeza volviendo a una posición de sentadilla debajo del peso.\nManteniendo el peso por encima de la cabeza, volvé a una posición de pie. Bajá el peso al suelo para realizar la siguiente repetición.' WHERE name_en = 'One-Arm Kettlebell Clean and Jerk';
UPDATE public.exercises SET instructions_es = 'Recostate en el suelo sujetando una kettlebell con una mano, con el brazo superior apoyado en el piso. La palma debe mirar hacia adentro.\nEmpujá la kettlebell recta hacia el techo, girando la muñeca.\nBajá la kettlebell de vuelta a la posición inicial y repetí.' WHERE name_en = 'One-Arm Kettlebell Floor Press';
UPDATE public.exercises SET instructions_es = 'Sujetá la kettlebell por el mango.\nLlevá la kettlebell al hombro extendiendo las piernas y la cadera mientras tirás de ella hacia el hombro.\nGirá la muñeca para que la palma mire hacia adelante. Esta es tu posición inicial.\nIncliná el cuerpo doblando las rodillas, manteniendo el torso erguido.\nInvertí la dirección inmediatamente, empujando a través de los talones, saltando para crear impulso.\nMientras lo hacés, empujá la kettlebell por encima de la cabeza hasta bloquear las articulaciones extendiendo los brazos, usando el impulso del cuerpo para mover el peso.\nRecibí el peso por encima de la cabeza volviendo a una posición de sentadilla debajo del peso.\nManteniendo el peso por encima de la cabeza, volvé a una posición de pie.\nBajá el peso para realizar la siguiente repetición.' WHERE name_en = 'One-Arm Kettlebell Jerk';
UPDATE public.exercises SET instructions_es = 'Llevá la kettlebell al hombro.\nLlevá la kettlebell al hombro extendiendo las piernas y la cadera mientras tirás de ella hacia el hombro.\nGirá la muñeca para que la palma mire hacia adentro. Esta es tu posición inicial.\nMirá la kettlebell y empujá hacia arriba y hacia afuera hasta que quede bloqueada por encima de la cabeza.\nBajá la kettlebell de vuelta al hombro con control y repetí.\nAsegurate de contraer los dorsales, el glúteo y el abdomen con fuerza para mayor estabilidad y fuerza.' WHERE name_en = 'One-Arm Kettlebell Military Press To The Side';
UPDATE public.exercises SET instructions_es = 'Recostá la mancuerna de hierro sobre tu hombro extendiendo piernas y caderas mientras la tirás hacia arriba.\nGirá la muñeca para que la palma mire hacia adelante y mantené esta posición inicial.\nEmpujá la mancuerna hacia arriba y hacia afuera hasta bloquear los brazos por encima de la cabeza.\nBajá la mancuerna de vuelta al hombro con control y repetí.\nContrá fuerte los dorsales, glúteos y abdomen para ganar estabilidad y fuerza.' WHERE name_en = 'One-Arm Kettlebell Para Press';
UPDATE public.exercises SET instructions_es = 'Agarrá la mancuerna de hierro por el mango.\nRecostá la mancuerna sobre tu hombro extendiendo piernas y caderas mientras la tirás hacia arriba.\nGirá la muñeca para que la palma mire hacia adelante y mantené esta posición inicial.\nHacé un descenso doblando las rodillas manteniendo el torso erguido.\nInvertí la dirección inmediatamente empujando con los talones, como si saltaras, para crear impulso.\nEmpujá la mancuerna por encima de la cabeza hasta bloquear los brazos usando el impulso del cuerpo.\nBajá el peso para realizar la siguiente repetición.' WHERE name_en = 'One-Arm Kettlebell Push Press';
UPDATE public.exercises SET instructions_es = 'Colocá una kettlebell frente a tus pies.\nDoblá levemente las rodillas y empujá el trasero hacia atrás lo más posible mientras te agachás para tomar la posición inicial.\nAgarrá la kettlebell y tirala hacia tu estómago, retraé la escápula y flexioná el codo.\nMantené la espalda recta.\nBajá y repetí.' WHERE name_en = 'One-Arm Kettlebell Row';
UPDATE public.exercises SET instructions_es = 'Colocá una kettlebell entre tus pies.\nDoblá las rodillas y empujá el trasero hacia atrás para tomar la posición inicial correcta.\nMirá al frente y balanceá la kettlebell hacia atrás entre las piernas.\nInmediatamente invertí la dirección y empujá con las caderas y las rodillas, acelerando la kettlebell hacia arriba.\nMientras la kettlebell sube hasta el hombro, girá la mano y empujá recto hacia arriba, usando el impulso para recibir el peso bloqueado sobre la cabeza.' WHERE name_en = 'One-Arm Kettlebell Snatch';
UPDATE public.exercises SET instructions_es = 'Sujetá la kettlebell por el mango.\nLimpá la kettlebell hasta tu hombro extendiendo a través de las piernas y caderas mientras tirás la kettlebell hacia tu hombro.\nGirá la muñeca mientras lo hacés, para que la palma mire hacia adelante. Esta será tu posición inicial.\nBajá tu cuerpo doblando las rodillas, manteniendo el torso erguido.\nInvertí la dirección inmediatamente, impulsando a través de los talones, en esencia saltando para crear impulso.\nMientras lo hacés, empujá la kettlebell por encima de la cabeza hasta el bloqueo extendiendo los brazos, usando el impulso de tu cuerpo para mover el peso.\nRecibí el peso por encima de la cabeza volviendo a una posición de sentadilla debajo del peso, posicionando una pierna frente a vos y la otra detrás.\nManteniendo el peso por encima de la cabeza, volvé a una posición de pie y juntá los pies.\nBajá el peso para realizar la siguiente repetición.' WHERE name_en = 'One-Arm Kettlebell Split Jerk';
UPDATE public.exercises SET instructions_es = 'Sujetá una kettlebell en una mano por el mango.\nHacé una sentadilla hacia el suelo y luego invertí el movimiento, extendiendo las caderas, las rodillas y finalmente los tobillos, para levantar la kettlebell por encima de la cabeza.\nDespués de extender completamente el cuerpo, descendé a una posición de zancada para recibir los pesos por encima de la cabeza, una pierna adelante y la otra atrás.\nAsegurate de impulsar con tus caderas y bloquear las kettlebells por encima de la cabeza en un movimiento ininterrumpido.\nVolvé a una posición de pie, sosteniendo el peso por encima de la cabeza, y juntá los pies.\nBajá el peso para volver a la posición inicial.' WHERE name_en = 'One-Arm Kettlebell Split Snatch';
UPDATE public.exercises SET instructions_es = '1\n' WHERE name_en = 'One-Arm Kettlebell Swings';
UPDATE public.exercises SET instructions_es = 'Colocá la barra en un landmine o en una esquina para que no se mueva. Cargá un peso adecuado en tu extremo.\nPará al lado de la barra y agarrala con una mano cerca del collar. Usando tus caderas y piernas, levantate hasta quedar de pie.\nAsumí una postura con las rodillas flexionadas, las caderas hacia atrás y el pecho arriba. Tu brazo debe estar extendido. Esta será tu posición inicial.\nJalá el peso hacia tu lado retraiendo el hombro y flexionando el codo. No hagas movimientos bruscos ni truches durante el ejercicio.\nDespués de una breve pausa, volvé a la posición inicial.' WHERE name_en = 'One-Arm Long Bar Row';
UPDATE public.exercises SET instructions_es = 'Pará con una postura atlética escalonada, sosteniendo la pelota medicinal en una mano, del mismo lado que tu pierna trasera.\nGirá el brazo y levantá la pelota sobre tu cabeza mientras extendés caderas, rodillas y tobillos para cargar el movimiento.\nEn la máxima extensión, flexioná hombros, columna y caderas para lanzar la pelota con fuerza al suelo, justo frente a vos.\nAtrapá la pelota en el rebote y repetí el movimiento la cantidad de veces deseadas.' WHERE name_en = 'One-Arm Medicine Ball Slam';
UPDATE public.exercises SET instructions_es = 'Colocá una kettlebell entre tus pies.\nAgarrá el mango con una mano y levantá la kettlebell rápidamente, dejándola girar hasta que la parte esférica caiga en la palma de tu mano.\nLanzá la kettlebell hacia adelante y atrapá el mango con una mano.\nLlevá la kettlebell al suelo y repetí el ejercicio, asegurándote de trabajar ambos brazos.' WHERE name_en = 'One-Arm Open Palm Kettlebell Clean';
UPDATE public.exercises SET instructions_es = 'Recostá el kettlebell sobre tu hombro extendiendo las piernas y caderas mientras lo tirás hacia arriba, girando la muñeca.\nEmpujá el peso por encima de la cabeza extendiendo el codo.\nMantené la mirada al frente y el kettlebell bloqueado arriba, flexioná las rodillas y caderas para bajar el torso entre las piernas, manteniendo la cabeza y el pecho arriba.\nHacé una pausa de un segundo en la posición inferior antes de subir de nuevo, impulsando desde los talones.' WHERE name_en = 'One-Arm Overhead Kettlebell Squats';
UPDATE public.exercises SET instructions_es = 'Parate al lado de la barra cerca de su centro, flexioná las rodillas y bajá el cuerpo hasta alcanzar la barra.\nAgarrá la barra como si fuera una maleta, con las palmas hacia vos, y mantené esta posición inicial.\nUsá las piernas para levantar la barra mientras exhalás, extendiendo los brazos por completo hasta quedar de pie.\nBajá la barra lentamente mientras inhalás, asegurándote de flexionar las rodillas al bajar para evitar lesiones.\nRepetí el movimiento la cantidad de veces recomendada.\nCambiá de brazo y repetí el movimiento.' WHERE name_en = 'One-Arm Side Deadlift';
UPDATE public.exercises SET instructions_es = 'Elegí una mancuerna y colocala en una de tus manos. Usá tu mano no dominante para agarrar algo firme, como un banco inclinado.\nIncliná tu cuerpo hacia el brazo que levanta y alejá la mano que agarra el banco para mantener el equilibrio.\nParate con el torso recto y la mancuerna a un lado, a la altura del brazo, con la palma de la mano mirándote. Esta es tu posición inicial.\nMientras mantenés el torso inmóvil (sin balancearte), levantá la mancuerna a un lado con una leve flexión en el codo y la mano ligeramente inclinada hacia adelante, como si estuvieras vertiendo agua en un vaso. Subí hasta que tu brazo quede paralelo al suelo. Exhalá al ejecutar este movimiento y hacé una pausa de un segundo arriba.\nBajá la mancuerna lentamente a la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.\nCambiá de brazo y repetí el ejercicio.' WHERE name_en = 'One-Arm Side Laterals';
UPDATE public.exercises SET instructions_es = 'Enganchá una tobillera de cuero a una polea baja y luego colocá la tobillera en tu tobillo.\nMirá la torre de pesas desde una distancia de aproximadamente dos pies, agarrando el marco de acero para apoyarte.\nMientras mantenés las rodillas y caderas ligeramente flexionadas y el abdomen apretado, contraé tus glúteos para "patinear" la pierna de trabajo hacia atrás en un arco semicircular hasta donde te resulte cómodo, mientras exhalás. Consejo: En la extensión completa, apretá los glúteos durante un segundo para lograr una contracción máxima.\nAhora, llevá tu pierna de trabajo hacia adelante lentamente, resistiendo la tracción del cable hasta que llegues a la posición inicial.\nRepetí la cantidad de repeticiones recomendadas.\nCambiá de pierna y repetí el movimiento para el otro lado.' WHERE name_en = 'One-Legged Cable Kickback';
UPDATE public.exercises SET instructions_es = 'Pará y apoyá un brazo flexionado contra una pared o marco de puerta.\nIncliná el cuerpo lentamente hacia tu brazo hasta sentir el estiramiento en los dorsales.' WHERE name_en = 'One Arm Against Wall';
UPDATE public.exercises SET instructions_es = 'Colocá una toalla alrededor de la barra de dominadas.\nAgarrá la barra con la palma hacia vos; una mano sujeta la barra y la otra la toalla.\nLlevá el torso hacia atrás unos 30 grados, curvando la zona lumbar y sacando el pecho; esa es tu posición inicial.\nSubí el torso hasta que la barra toque el pecho superior, llevando los hombros y brazos superiores hacia abajo y atrás; exhalá durante este movimiento.\nConcentrate en apretar los músculos de la espalda al llegar a la posición de máxima contracción, manteniendo el torso superior estable y moviendo solo los brazos.\nMantené la posición contraída un segundo, inhalá y bajá el torso lentamente hasta la posición inicial con los brazos extendidos y los dorsales estirados.\nRepetí el movimiento la cantidad de repeticiones indicadas.\nCambiá de brazo y repetí el movimiento.' WHERE name_en = 'One Arm Chin-Up';
UPDATE public.exercises SET instructions_es = 'Recostate sobre una superficie plana con la espalda apoyada en el piso o una colchoneta. Asegurate de que las rodillas estén flexionadas.\nPedile a tu compañero que te pase la barra con una mano. Al empezar, tu brazo debe estar casi completamente extendido, similar a la posición inicial de un press de banca con barra. Sin embargo, esta vez tu agarre será neutro (palmas mirando hacia tu torso).\nAsegurate de que la mano que no está levantando el peso esté colocada a tu lado.\nComenzá el ejercicio bajando la barra hasta que tu codo toque el suelo. Recordá inhalar durante esta fase excéntrica (bajada).\nLuego, empezá a levantar la barra de vuelta a la posición inicial. Recordá exhalar durante la fase concéntrica (subida).\nRepetí hasta completar las repeticiones recomendadas.\nCambiá de brazo y repetí el movimiento.' WHERE name_en = 'One Arm Floor Press';
UPDATE public.exercises SET instructions_es = 'Elegí un peso adecuado y ajustá la rodillera para ayudarte a mantenerte abajo. Agarrá el mango con un agarre prono. Esta será tu posición inicial.\nJalá el mango hacia abajo, apretando tu codo contra tu costado mientras flexionás el codo.\nHacé una pausa en la parte inferior del movimiento y luego volvé lentamente el mango a la posición inicial.\nPara múltiples repeticiones, evitá devolver completamente el peso para mantener la tensión en los músculos trabajados.' WHERE name_en = 'One Arm Lat Pulldown';
UPDATE public.exercises SET instructions_es = 'Recostate plano en el banco sosteniendo una mancuerna con el brazo extendido, perpendicular a tu cuerpo, con la palma de la mano mirando hacia los pies (agarre prono).\nApoyá tu mano no dominante sobre el bíceps para dar soporte.\nBajá lentamente la mancuerna mientras inhalás.\nSubí la mancuerna contrayendo los tríceps y exhalá durante la fase de empuje.\nRepetí hasta completar las repeticiones de tu serie.\nCambiá de brazo y repetí el movimiento.' WHERE name_en = 'One Arm Pronated Dumbbell Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Recostate plano en el banco sosteniendo una mancuerna con el brazo extendido, perpendicular a tu cuerpo, con la palma de la mano mirando hacia tu cara (agarre supino).\nApoyá tu mano no dominante sobre el bíceps para dar soporte.\nBajá lentamente la mancuerna mientras inhalás.\nSubí la mancuerna contrayendo los tríceps y exhalá durante la fase de empuje.\nRepetí hasta completar las repeticiones de tu serie.\nCambiá de brazo y repetí el movimiento.\nCambiá de brazo nuevamente y repetí el movimiento.' WHERE name_en = 'One Arm Supinated Dumbbell Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Recostá boca abajo en el piso.\nColocá tu mano izquierda bajo tu cadera izquierda para acolchatar la cadera y el hueso púbico.\nDoblá tu rodilla derecha para poder sostener el pie con tu mano derecha.\nLevantá el pie en el aire y al mismo tiempo levantá los hombros del piso. Esto también estira el flexor de la cadera derecha y el pecho y los hombros. Cambiá de lado. Si no te molesta la espalda, podés intentarlo con ambos brazos y piernas al mismo tiempo.' WHERE name_en = 'One Half Locust';
UPDATE public.exercises SET instructions_es = 'Agarrate de una barra de dominadas con una mano, usando un agarre prono.\nMantené los pies en el piso o en un escalón.\nDejá que la mayor parte de tu peso cuelgue de esa mano, mientras mantenés los pies en el suelo.\nMantené la posición por 10-20 segundos y cambiá de lado.' WHERE name_en = 'One Handed Hang';
UPDATE public.exercises SET instructions_es = 'Recostate en el piso.\nExtendé una pierna recta y llevá la otra rodilla hacia tu pecho. Sostené debajo de la articulación de la rodilla para proteger la rótula.\nJalá suavemente esa rodilla hacia tu nariz.\nCambiá de lado. Esto estira los glúteos y la parte baja de la espalda de la pierna doblada y el flexor de la cadera de la pierna recta.' WHERE name_en = 'One Knee To Chest';
UPDATE public.exercises SET instructions_es = 'Parate a unos 60-90 cm frente a un banco plano con la espalda hacia el banco. Tené una barra en el piso frente a vos. Tip: Tus pies deben estar separados a la anchura de los hombros.\nDoblá las rodillas y usá un agarre prono con las manos más separadas que la anchura de los hombros para levantar la barra hasta apoyarla en tu pecho.\nLuego, levantá la barra sobre tu cabeza y apoyala en la base de tu cuello. Mové un pie hacia atrás para que la punta del pie descanse en el banco plano. Tu otro pie debe permanecer quieto frente a vos. Mantené la cabeza levantada en todo momento, ya que mirar hacia abajo te desequilibrará, y mantené la espalda recta. Tip: Asegurate de que tu espalda esté recta y el pecho afuera mientras realizás este ejercicio.\nMientras inhalás, bajá lentamente la pierna hasta que tu muslo quede paralelo al piso. En este punto, tu rodilla debe estar sobre las puntas de los pies. Tu pecho debe estar directamente sobre el medio de tu muslo.\nLlevando el pecho y las caderas al frente y contrayendo los cuádriceps, elevá tu pierna de vuelta a la posición inicial mientras exhalás.\nRepetí la cantidad de repeticiones recomendadas.\nCambiá de pierna y repetí el movimiento.' WHERE name_en = 'One Leg Barbell Squat';
UPDATE public.exercises SET instructions_es = 'Colocá una kettlebell entre tus pies.\nLimpia la kettlebell extendiendo a través de las piernas y las caderas mientras la subís hacia los hombros.\nDejá la kettlebell mientras sube y dejala girar para que la bola aterrice en las palmas de tus manos.\nDejá la kettlebell hacia adelante y agarrá el mango con ambas manos.\nBajá la kettlebell a la posición inicial y repetí.' WHERE name_en = 'Open Palm Kettlebell Clean';
UPDATE public.exercises SET instructions_es = 'Fijá tus pies y recostate en el piso.\nMantené las rodillas dobladas.\nSujetá un peso con ambas manos contra el pecho. Esta será tu posición inicial.\nIniciá el movimiento flexionando las caderas y la columna para levantar el torso del suelo.\nMientras subís, empujá el peso hacia arriba para que quede sobre la cabeza en la parte superior del movimiento.\nDevolvé el peso al pecho mientras invertís el movimiento del abdominal, asegurándote de no bajar completamente hasta el piso.' WHERE name_en = 'Otis-Up';
UPDATE public.exercises SET instructions_es = 'Elegí un peso cómodo para cada lado de la máquina de poleas y asegurate de que sea igual en ambos lados.\nAjustá la altura de las poleas para que queden por encima de tus hombros.\nPará en el medio, agarrá los mangos con agarre supino (palmas hacia el techo) y extendé los brazos por completo, paralelos al suelo, con los pies separados a la anchura de los hombros.\nExhalá y contraé los bíceps lentamente hasta que tus antebrazos y bíceps se toquen.\nInhalá y volvé a la posición inicial, manteniendo el resto del cuerpo quieto.\nRepetí la cantidad de repeticiones indicadas en tu programa.' WHERE name_en = 'Overhead Cable Curl';
UPDATE public.exercises SET instructions_es = 'Sentate erguido en el suelo con tu pareja detrás de vos.\nLevantá un brazo recto hacia arriba y flexioná el codo intentando tocar la espalda con la mano, mientras tu pareja sostiene tu tríceps y muñeca.\nIntentá llevar el brazo superior hacia el costado mientras tu pareja impide que lo hagas.\nDespués de 10 a 20 segundos, relajá el brazo y dejá que tu pareja estire el dorsal aplicando presión suave sobre el tríceps.\nMantené la posición por 10 a 20 segundos y cambiá de lado.' WHERE name_en = 'Overhead Lat';
UPDATE public.exercises SET instructions_es = 'Sostené una pelota medicinal con ambas manos y pará con los pies a la anchura de los hombros. Esta será tu posición inicial.\nIniciá el movimiento contrapuesto levantando la pelota por encima de la cabeza y extendiendo completamente el cuerpo.\nInvertí el movimiento, golpeando la pelota contra el suelo directamente frente a vos con toda la fuerza posible.\nRecibí la pelota con ambas manos en el rebote y repetí el movimiento.' WHERE name_en = 'Overhead Slam';
UPDATE public.exercises SET instructions_es = 'Comenzá con una barra en el suelo frente a vos. Tus pies deben estar más separados que la anchura de los hombros.\nDoblá las rodillas y usá un agarre prono (palmas hacia vos) para tomar la barra. Tus manos deben estar más separadas que la anchura de los hombros antes de levantar. Una vez posicionado, levantá la barra hasta apoyarla en tu pecho.\nMové la barra por encima y ligeramente detrás de tu cabeza, asegurándote de que los brazos estén completamente extendidos. Mantené la cabeza arriba en todo momento y también una espalda recta. Retraé las escápulas. Esta es tu posición inicial.\nBajá el peso lentamente doblando las rodillas hasta que los muslos queden paralelos al suelo, mientras inhalás. Consejo: Mantené la espalda recta durante este ejercicio para evitar lesiones y los brazos deben permanecer extendidos y por encima de la cabeza en todo momento.\nAhora usá tus pies y piernas para ayudar a subir el peso de vuelta a la posición inicial, mientras exhalás.\nRepetí por la cantidad de repeticiones recomendadas.' WHERE name_en = 'Overhead Squat';
UPDATE public.exercises SET instructions_es = 'Pará de pie, entrelazá los dedos y abrí las palmas hacia el techo.\nMantené los hombros abajo mientras extendés los brazos hacia arriba.\nPara lograr un estiramiento completo del torso, tirá del coxis hacia abajo y estabilizá el tronco.\nEstirá los músculos de la parte frontal y posterior del torso.' WHERE name_en = 'Overhead Stretch';
UPDATE public.exercises SET instructions_es = 'Sentate erguido en el piso con tu pareja detrás de vos.\nLevantá un brazo recto hacia arriba y flexioná el codo, intentando tocar la espalda con la mano.\nTu pareja debe sostener tu codo y la muñeca; esta será tu posición inicial.\nIntentá extender el brazo recto hacia el aire mientras tu pareja impide que lo hagas realmente.\nDespués de 10 a 20 segundos, relajá el brazo y dejá que tu pareja estire más el tríceps aplicando una presión suave en la muñeca.\nMantené la posición por 10 a 20 segundos y luego cambiá de lado.' WHERE name_en = 'Overhead Triceps';
UPDATE public.exercises SET instructions_es = 'Colocá dos mancuernas a un lado de un banco plano.\nArrodillate con ambas rodillas mirando hacia el banco.\nAgarrá ambas mancuernas con agarre prono (palmas hacia abajo) y llevá los antebrazos a descansar sobre el banco, dejando que las muñecas cuelguen del borde.\nCurlé las muñecas hacia arriba mientras exhalás.\nBajá lentamente las muñecas a la posición inicial mientras inhalás.\nMantené los antebrazos estacionarios, ya que la muñeca es el único movimiento necesario.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Palms-Down Dumbbell Wrist Curl Over A Bench';
UPDATE public.exercises SET instructions_es = 'Colocá una barra a un lado de un banco plano.\nArrodillate con ambas rodillas mirando hacia el banco.\nAgarrá la barra con agarre prono (palmas hacia abajo) y llevá los antebrazos a descansar sobre el banco, dejando que las muñecas cuelguen del borde.\nCurlé las muñecas hacia arriba mientras exhalás.\nBajá lentamente las muñecas a la posición inicial mientras inhalás.\nMantené los antebrazos estacionarios, ya que la muñeca es el único movimiento necesario.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Palms-Down Wrist Curl Over A Bench';
UPDATE public.exercises SET instructions_es = 'Colocá una barra en un lado de un banco plano.\nArrodillate con ambas rodillas mirando hacia el banco.\nAgarrá la barra con agarre supino (palmas hacia arriba) y llevá los antebrazos hasta apoyarlos sobre el banco, dejando que las muñecas cuelguen del borde.\nCurlé las muñecas hacia arriba mientras exhalás.\nBajá las muñecas lentamente a la posición inicial mientras inhalás.\nMantené los antebrazos estacionarios, ya que la muñeca es el único movimiento necesario.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Palms-Up Barbell Wrist Curl Over A Bench';
UPDATE public.exercises SET instructions_es = 'Colocá dos mancuernas en un lado de un banco plano.\nArrodillate con ambas rodillas mirando hacia el banco.\nAgarrá ambas mancuernas con agarre supino (palmas hacia arriba) y llevá los antebrazos hasta apoyarlos sobre el banco, dejando que las muñecas cuelguen del borde.\nCurlé las muñecas hacia arriba mientras exhalás.\nBajá las muñecas lentamente a la posición inicial mientras inhalás, asegurándote de inhalar en esta parte.\nMantené los antebrazos estacionarios, ya que la muñeca es el único movimiento necesario.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Palms-Up Dumbbell Wrist Curl Over A Bench';
UPDATE public.exercises SET instructions_es = 'Pará entre un set de barras paralelas.\nApoyá una mano en cada barra y hacé un pequeño salto para ayudarte a llegar a la posición inicial con los brazos extendidos.\nComenzá flexionando el codo y bajando tu cuerpo hasta que tus brazos rompan el ángulo de 90 grados.\nEvitá balancearte y mantené una buena postura durante todo el descenso.\nInvertí el movimiento extendiendo el codo y empujándote hacia arriba hasta la posición inicial.\nRepetí la cantidad de repeticiones deseadas.' WHERE name_en = 'Parallel Bar Dip';
UPDATE public.exercises SET instructions_es = 'Recostate con los pies en el suelo, los talones directamente debajo de las rodillas.\nLevantá solo el hueso de la cadera hacia el techo para estirar la parte baja de la espalda.\nNo levantes toda la columna todavía y meté el abdomen.\nPara hacer el puente, levantá toda la columna excepto el cuello.' WHERE name_en = 'Pelvic Tilt Into Bridge';
UPDATE public.exercises SET instructions_es = 'Recostá de lado, apoyando tu peso en el antebrazo y en un rodillo de espuma colocado en la parte externa de la pierna inferior.\nTu pierna superior puede estar sobre la inferior o cruzada por delante de vos.\nEsta será tu posición inicial.\nLevantá las caderas del suelo y empezá a rodar desde debajo de la rodilla hasta arriba del tobillo en el lateral de la pierna.\nHacé pausas en los puntos de tensión durante 10 a 30 segundos.\nRepetí con la otra pierna.' WHERE name_en = 'Peroneals-SMR';
UPDATE public.exercises SET instructions_es = 'Sentate y pasá una correa, cuerda o banda alrededor de un pie.\nEsta será tu posición inicial.\nCon la pierna extendida y el talón fuera del suelo, tirá de la correa para que el pie se invierta, llevando la parte interna del pie hacia vos.\nMantené la posición durante 10 a 20 segundos.\nCambialo de lado.' WHERE name_en = 'Peroneals Stretch';
UPDATE public.exercises SET instructions_es = 'Recostá tu parte superior de la espalda sobre la pelota, dejando que tus caderas queden sin apoyo.\nMantené ambos pies planos en el suelo, separados a la anchura de las caderas o más.\nExtendé las caderas usando tus glúteos e isquiotibiales, elevando las caderas hacia arriba mientras hacés el puente.\nMantené la pausa en la parte superior del movimiento y volvé a la posición inicial.' WHERE name_en = 'Physioball Hip Bridge';
UPDATE public.exercises SET instructions_es = 'Configurá el banco dentro de un rack de potencia.\nAjustá los pasadores al punto deseado de tu rango de movimiento, ya sea en el bloqueo o a un pulgada de tu pecho.\nMover la barra a los pasadores y preparala para levantar.\nRecostá en el banco, con la barra directamente sobre el punto de contacto de tu press normal.\nMetené los pies debajo de vos y arqueá la espalda.\nUsá la barra para ayudar a soportar tu peso, levantá los hombros del banco y retraelos, apretando las escápulas juntas.\nUsá tus pies para empujar los trapecios contra el banco.\nMantené esta posición corporal tensa durante todo el movimiento.\nPodés tomar un agarre estándar de press o a la anchura de los hombros para enfocarte en los tríceps.\nMantené la barra, la muñeca y el codo alineados en todo momento.\nEnfocate en apretar la barra e intentar separarla.\nEmpujá la barra hacia arriba con la mayor fuerza posible.\nMantené los codos pegados hasta el bloqueo.\nVolvé la barra a los pasadores, haciendo una pausa antes de comenzar la siguiente repetición.' WHERE name_en = 'Pin Presses';
UPDATE public.exercises SET instructions_es = 'Sentate con las nalgas sobre un rodillo de espuma.\nDoblá las rodillas y cruzá una pierna para que el tobillo quede sobre la rodilla.\nIncliná el peso hacia el lado de la pierna cruzada, rodando sobre las nalgas hasta sentir tensión en el glúteo superior.\nPodés asistir el estiramiento tirando de la rodilla doblada hacia el pecho con una mano.\nMantené esta posición de 10 a 30 segundos y luego cambiá de lado.' WHERE name_en = 'Piriformis-SMR';
UPDATE public.exercises SET instructions_es = 'Acostate boca abajo en el suelo, apoyando el peso en las puntas de los pies y los antebrazos.\nMantené los brazos doblados y directamente debajo de los hombros.\nMantené el cuerpo recto en todo momento y sostené esta posición el mayor tiempo posible.\nPara aumentar la dificultad, podés levantar un brazo o una pierna.' WHERE name_en = 'Plank';
UPDATE public.exercises SET instructions_es = 'Agarrá dos discos de borde ancho y juntalos con las caras lisas hacia afuera.\nSujetá el exterior del disco con los dedos y el otro lado con el pulgar para mantener ambos discos juntos; esta es la posición inicial.\nApretá el disco con los dedos y el pulgar, y mantené esta posición el mayor tiempo posible.\nRepetí la cantidad de series recomendadas en tu programa.\nCambiá de brazo y repetí los movimientos.' WHERE name_en = 'Plate Pinch';
UPDATE public.exercises SET instructions_es = 'Recostate en el suelo o en una colchoneta con las piernas completamente extendidas y el torso erguido; agarrá el disco por los lados con ambas manos frente a los abdominales, con los brazos ligeramente flexionados.\nCruzá lentamente las piernas cerca de los tobillos y levantálas del suelo, manteniendo las rodillas ligeramente flexionadas; incliná el torso hacia atrás para mantener el equilibrio; esta es la posición inicial.\nLlevá el disco hacia el lado izquierdo y tocá el suelo con él, exhalando mientras realizás el movimiento.\nVolvé a la posición inicial inhalando y repetí el movimiento hacia el lado derecho, usando un movimiento lento y controlado para evitar lesiones en la espalda.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Plate Twist';
UPDATE public.exercises SET instructions_es = 'Recostá sobre tu espalda con las piernas extendidas en un piso de madera o similar.\nColocá una toalla de gimnasio o un peso ligero debajo de tu talón.\nFlexioná la rodilla manteniendo la otra pierna recta.\nLlevá el talón hacia vos deslizándolo sobre el piso.\nAl llegar a la flexión máxima de la rodilla, invertí el movimiento para volver a la posición inicial.' WHERE name_en = 'Platform Hamstring Slides';
UPDATE public.exercises SET instructions_es = 'Sujetá una mancuerna con ambas manos en la base y pará de pie.\nSepará las piernas más que el ancho de los hombros con las rodillas ligeramente flexionadas.\nOrientá las puntas de los pies hacia afuera y mantené los brazos quietos.\nFlexioná las rodillas lentamente hasta que los muslos queden paralelos al piso, inhalando.\nEmpujá principalmente con el talón para volver a la posición inicial, exhalando.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Plie Dumbbell Squat';
UPDATE public.exercises SET instructions_es = 'Colocá una kettlebell en el suelo.\nPosicionate en plancha, con las puntas de los pies en el suelo, una mano apoyada y la otra sosteniendo la kettlebell, con los codos extendidos.\nBajate lo más bajo que puedas manteniendo la espalda recta.\nInvertí la dirección rápidamente y con fuerza, empujándote hacia el otro lado de la kettlebell mientras cambiás de mano.\nContinuá el movimiento bajando y repitiendo el vaivén.' WHERE name_en = 'Plyo Kettlebell Pushups';
UPDATE public.exercises SET instructions_es = 'Recostate boca abajo en el suelo, apoyando tu peso en las manos y las puntas de los pies.\nExtendé los brazos por completo con las manos a la anchura de los hombros y mantené el cuerpo recto durante todo el movimiento.\nBajate flexionando los codos, acercando el pecho al suelo.\nEn el punto más bajo, invertí el movimiento empujándote hacia arriba extendiendo los codos lo más rápido posible.\nIntentá empujar el torso hasta que las manos se despeguen del suelo.\nVolvé a la posición inicial y repetí el ejercicio.\nPara mayor dificultad, agregá palmas mientras estás en el aire.' WHERE name_en = 'Plyo Push-up';
UPDATE public.exercises SET instructions_es = 'Pará con el torso recto y una mancuerna en cada mano, sostenidas a la altura de los brazos.\nMantené los codos cerca del torso y las palmas de las manos mirando hacia tu cuerpo.\nSepará los pies a la anchura de los hombros para tu posición inicial.\nMantené los brazos rectos y el torso quieto, y levantá los pesos hacia los lados hasta la altura de los hombros mientras exhalás.\nSentí la contracción por un segundo y bajá los pesos de vuelta a la posición inicial mientras inhalás.\nConsejo: Mantené las palmas hacia abajo con el meñique ligeramente más alto al levantar y bajar los pesos para concentrar el esfuerzo en los hombros.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Power Partials';
UPDATE public.exercises SET instructions_es = 'Comenzá con una barra cargada en el suelo, cerca o tocando las espinillas, agarrándola con un agarre ancho.\nColocá los pies directamente debajo de las caderas, girándolos hacia afuera si es necesario.\nBajá las caderas manteniendo el pecho arriba y la cabeza mirando hacia adelante, con los hombros justo frente a la barra.\nIniciá el primer tirón impulsando a través de la parte delantera de los talones para levantar la barra del suelo, manteniendo el ángulo de la espalda igual hasta que la barra pase las rodillas.\nTransicioná al segundo tirón extendiendo caderas, rodillas y tobillos para impulsar la barra hacia arriba lo más rápido posible, manteniéndola cerca del cuerpo.\nEn la extensión máxima, encogé los hombros y permití que los codos se flexionen hacia los lados.\nMientras movés los pies a la posición de recepción, ligeramente más ancha, tirá de tu cuerpo hacia abajo bajo la barra mientras la elevás por encima de la cabeza.\nRecibí la barra en un sentadilla parcial y continuá subiendo hasta que quede bloqueada por encima de la cabeza.\nVolvé a la posición de pie con el peso por encima de la cabeza.' WHERE name_en = 'Power Snatch';
UPDATE public.exercises SET instructions_es = 'Asegurate de tener un banco predicador y una barra E-Z.\nAgarrá la barra E-Z por los mangos internos más cercanos (idealmente que alguien te la pase o tomala del soporte frontal del banco).\nMantené las palmas de las manos hacia adelante y ligeramente inclinadas hacia adentro debido a la forma de la barra.\nApoyá los brazos superiores contra la almohadilla del banco predicador y el pecho contra ella, sosteniendo la barra a la altura de los hombros como posición inicial.\nMientras inhalás, bajá la barra lentamente hasta que el brazo superior esté extendido y el bíceps completamente estirado.\nAl exhalar, usá el bíceps para curlar el peso hacia arriba hasta que el bíceps esté completamente contraído y la barra esté a la altura de los hombros.\nApretá fuerte el bíceps y mantené esta posición por un segundo.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Preacher Curl';
UPDATE public.exercises SET instructions_es = 'Colocá la parte superior de ambos brazos sobre el banco predicador sosteniendo una mancuerna en cada mano con las palmas mirándose (agarre neutro).\nMientras inhalás, bajá las mancuernas lentamente hasta que el brazo superior esté extendido y el bíceps completamente estirado.\nAl exhalar, usá el bíceps para curlar el peso hacia arriba hasta que el bíceps esté completamente contraído y las mancuernas estén a la altura de los hombros.\nApretá fuerte el bíceps por un segundo en la posición contraída y repetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Preacher Hammer Dumbbell Curl';
UPDATE public.exercises SET instructions_es = 'Recostá en un banco con una barra sobre el pecho y asegurá tus piernas en la extensión del banco abdominal.\nInhalá, contraé tus abdominales y glúteos, y empujá la barra hacia arriba mientras exhalás, usando los brazos para asistir el movimiento.\nBajá tu cuerpo y la barra de vuelta a la posición inicial inhalando.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Press Sit-Up';
UPDATE public.exercises SET instructions_es = 'Necesitás un compañero; recostá boca abajo con las piernas estiradas y pedile que te coloque la mano en el talón.\nFlexioná la rodilla para doblar la pierna hacia arriba mientras tu compañero aplica resistencia, empezando suave y aumentando la presión al completar el movimiento.\nHacé una pausa arriba y volvé a la posición inicial mientras tu compañero resiste el descenso.' WHERE name_en = 'Prone Manual Hamstring';
UPDATE public.exercises SET instructions_es = 'Colocá tu trineo sobre una superficie adecuada, cargado con un peso apropiado.\nEl trineo debe ofrecer suficiente resistencia para exigir esfuerzo, pero no tan pesado que te frene significativamente.\nPodés usar los agarres verticales o los bajos para este ejercicio.\nColocá tus manos en los agarres con los brazos extendidos, inclinándote hacia el implemento.\nCon buena postura, impulsá contra el suelo con pasos cortos y alternados.\nMovete tan rápido como puedas por una corta distancia.' WHERE name_en = 'Prowler Sprint';
UPDATE public.exercises SET instructions_es = 'Comenzá de pie a unos metros frente a una polea baja con una cuerda o agarre.\nMirá hacia atrás de la máquina, cruzando el cable, con los pies separados.\nIniciá el movimiento alcanzando entre tus piernas lo más lejos posible, flexionando en la cadera.\nMantené las rodillas ligeramente flexionadas.\nCon los brazos rectos, extendé por la cadera para ponerte de pie recto.\nEvitá tirar hacia arriba con los hombros; todo el movimiento debe originarse en la cadera.' WHERE name_en = 'Pull Through';
UPDATE public.exercises SET instructions_es = 'Agarrá la barra de dominadas con las palmas hacia adelante usando el agarre prescrito. Tené en cuenta: para un agarre ancho, separá las manos más que el ancho de tus hombros; para un agarre medio, separalas igual al ancho de tus hombros; y para un agarre cerrado, separalas menos que el ancho de tus hombros.\nCon ambos brazos extendidos hacia adelante sosteniendo la barra en el ancho elegido, llevá el torso hacia atrás unos 30 grados, creando una curvatura en la zona lumbar y sacando el pecho. Esta es tu posición inicial.\nSubí el torso hasta que la barra toque el pecho superior, bajando y llevando los hombros y los brazos superiores hacia atrás. Exhalá mientras realizás esta parte del movimiento. Consejo: concentrate en apretar los músculos de la espalda cuando llegues a la posición de máxima contracción. El torso superior debe permanecer estacionario mientras se mueve en el espacio, y solo los brazos deben moverse. Los antebrazos no deben hacer otro trabajo que no sea sostener la barra.\nDespués de un segundo en la posición contraída, empezá a inhalar y bajá lentamente el torso a la posición inicial cuando los brazos estén completamente extendidos y los dorsales estén completamente estirados.\nRepetí este movimiento por la cantidad de repeticiones prescritas.' WHERE name_en = 'Pullups';
UPDATE public.exercises SET instructions_es = 'Con las manos bien separadas, apoyá tu cuerpo en las puntas de los pies y las manos en posición de plancha. Tus codos deben estar extendidos y el cuerpo recto. No permitas que la cadera se hunda. Esta será tu posición inicial.\nPara comenzar, permití que los codos se flexionen, bajando el pecho hacia el suelo mientras inhalás.\nUsando los músculos pectorales, empujá el torso superior de vuelta a la posición inicial extendiendo los codos. Exhalá mientras realizás este paso.\nDespués de pausar en la posición contraída, repetí el movimiento por la cantidad de repeticiones prescritas.' WHERE name_en = 'Push-Up Wide';
UPDATE public.exercises SET instructions_es = 'Recostá boca abajo en el suelo y colocá tus manos más cerca que el ancho de los hombros para una posición de manos cerradas. Asegurate de mantener el torso elevado a la extensión de los brazos.\nBajate hasta que tu pecho casi toque el suelo mientras inhalás.\nUsando tus tríceps y parte de los músculos pectorales, empujá tu cuerpo superior de vuelta a la posición inicial y contraé el pecho. Exhalá mientras realizás este paso.\nDespués de una pausa de un segundo en la posición contraída, repetí el movimiento por la cantidad de repeticiones prescritas.' WHERE name_en = 'Push-Ups - Close Triceps Position';
UPDATE public.exercises SET instructions_es = 'Recostá boca abajo en el suelo y colocá tus manos a unos 36 pulgadas de distancia entre sí, manteniendo el torso elevado a la extensión de los brazos.\nColocá las puntas de los pies sobre un banco plano. Esto permitirá que tu cuerpo quede elevado. Nota: Cuanto mayor sea la elevación del banco plano, mayor será la resistencia del ejercicio.\nBajate hasta que tu pecho casi toque el suelo mientras inhalás.\nUsando los músculos pectorales, empujá tu cuerpo superior de vuelta a la posición inicial y contraé el pecho. Exhalá mientras realizás este paso.\nDespués de una pausa de un segundo en la posición contraída, repetí el movimiento por la cantidad de repeticiones prescritas.' WHERE name_en = 'Push-Ups With Feet Elevated';
UPDATE public.exercises SET instructions_es = 'Recostá boca abajo en el piso y colocá tus manos separadas aproximadamente 90 cm entre sí, manteniendo el torso elevado con los brazos extendidos.\nApoyá las puntas de los pies sobre una pelota de ejercicio para elevar tu cuerpo.\nBajate hasta que tu pecho casi toque el suelo mientras inhalás.\nUsando los músculos pectorales, empujá tu parte superior del cuerpo de vuelta a la posición inicial y contraé el pecho. Exhalá mientras realizás este paso.\nDespués de una pausa de un segundo en la posición contraída, repetí el movimiento por la cantidad de repeticiones indicadas.' WHERE name_en = 'Push-Ups With Feet On An Exercise Ball';
UPDATE public.exercises SET instructions_es = '2\n' WHERE name_en = 'Push Press';
UPDATE public.exercises SET instructions_es = 'Pará con la barra apoyada en la parte trasera de los hombros.\nCon los pies directamente debajo de las caderas, flexioná las rodillas sin mover las caderas hacia atrás.\nBajá solo un poco y cambiá de dirección con la mayor potencia posible.\nEmpujá a través de los talones para generar la mayor velocidad y fuerza posible, moviendo la barra en un camino vertical.\nUsá el impulso generado para terminar empujando el peso por encima de la cabeza extendiendo los brazos.\nVolvé a la posición inicial usando las piernas para absorber el impacto.' WHERE name_en = 'Push Press - Behind the Neck';
UPDATE public.exercises SET instructions_es = 'Colocate en posición de flexión sobre las puntas de los pies, con las manos justo fuera del ancho de los hombros.\nRealizá una flexión permitiendo que los codos se flexionen.\nMientras descendés, mantené el cuerpo recto.\nHacé una flexión y, al subir, transferí el peso al lado izquierdo del cuerpo.\nGirá hacia el lado mientras levantás el brazo derecho hacia el techo en una plancha lateral.\nBajá el brazo de vuelta al suelo para otra flexión y luego girá hacia el otro lado.\nRepetí la serie alternando cada lado durante 10 o más repeticiones.' WHERE name_en = 'Push Up to Side Plank';
UPDATE public.exercises SET instructions_es = 'Recostá boca abajo en el suelo y colocá tus manos separadas unos 90 centímetros, manteniendo el torso elevado a la altura de los brazos.\nBajá tu cuerpo hasta que tu pecho casi toque el suelo mientras inhalás.\nExhalá y empujá tu parte superior del cuerpo de vuelta a la posición inicial, apretando el pecho.\nDespués de una breve pausa en la posición superior contraída, podés volver a bajar para las repeticiones necesarias.' WHERE name_en = 'Pushups';
UPDATE public.exercises SET instructions_es = 'Recostá boca abajo con el cuerpo recto, las puntas de los pies en el suelo y las manos más anchas que el ancho de los hombros para una posición amplia, o más cerca para una posición cerrada. Asegurate de mantener el torso elevado a la altura de los brazos.\nBajá tu cuerpo hasta que tu pecho casi toque el suelo mientras inhalás.\nUsando tus músculos pectorales, empujá tu parte superior del cuerpo de vuelta a la posición inicial y apretá el pecho. Exhalá mientras realizás este paso.\nDespués de una pausa de un segundo en la posición contraída, repetí el movimiento por la cantidad de repeticiones prescritas.' WHERE name_en = 'Pushups (Close and Wide Hand Positions)';
UPDATE public.exercises SET instructions_es = 'Iniciá rodando tu torso hacia adelante sobre la pelota hasta que tus caderas descansen en la parte superior y sean el punto más alto de tu cuerpo.\nApoyá tus manos y pies en el suelo.\nMantené tus brazos y piernas ligeramente flexionados o rectos, según el tamaño de la pelota, tu flexibilidad y la longitud de tus extremidades.\nEsto también ayuda a desarrollar fuerza estabilizadora en tu torso y hombros.' WHERE name_en = 'Pyramid';
UPDATE public.exercises SET instructions_es = 'Acostate de lado.\nPasá un cinturón, cuerda o banda alrededor de tu pie superior.\nFlexioná la rodilla y extendé la cadera, intentando tocar tus glúteos con el pie, mientras sostenés el cinturón con tus manos.\nEsta será tu posición inicial.\nCon el cinturón sostenido sobre el hombro o por encima de la cabeza, tirá suavemente para aumentar el estiramiento en los cuádriceps.\nMantené la posición de 10 a 20 segundos y luego cambiá de lado.' WHERE name_en = 'Quad Stretch';
UPDATE public.exercises SET instructions_es = 'Recostá boca abajo en el piso con el peso apoyado en las manos o antebrazos.\nColocá un rodillo de espuma debajo de una pierna sobre los cuádriceps y mantené el pie en el aire.\nRelajá la pierna lo más posible.\nTransfirí el peso hacia la pierna que vas a estirar hasta donde sea tolerable.\nRodá sobre el espuma desde arriba de la rodilla hasta debajo de la cadera.\nMantené los puntos de tensión durante 10 a 30 segundos.\nCambiá de lado.' WHERE name_en = 'Quadriceps-SMR';
UPDATE public.exercises SET instructions_es = 'Necesitás una caja para este ejercicio.\nPará frente a la caja a 1 o 2 pies de su borde.\nUsá las caderas para saltar sobre la caja y aterrizá con ambas piernas.\nAsegurate de aterrizar con las piernas flexionadas y los pies planos.\nInmediatamente después de aterrizar, extendé todo el cuerpo y sacá los brazos por encima de la cabeza para explotar fuera de la caja.\nUsá las piernas para absorber el impacto del aterrizaje.' WHERE name_en = 'Quick Leap';
UPDATE public.exercises SET instructions_es = 'Comenzá sosteniendo la barra en la posición de espantapájaros, con los brazos superiores paralelos al suelo y los antebrazos colgando.\nUsá un agarre de gancho, con los dedos envueltos sobre los pulgares.\nGirá los codos alrededor de la barra para llevarla a los hombros.\nRelajá el agarre a medida que los codos se muevan hacia adelante.\nProyectá los hombros hacia adelante para crear una repisa para la barra, que debe tocar suavemente la garganta.\nMantené la barra cerca del cuerpo en todo momento.\nAumentá la velocidad y la carga a medida que el movimiento se vuelva más fluido.' WHERE name_en = 'Rack Delivery';
UPDATE public.exercises SET instructions_es = 'Colocá la barra en los pines de la rack de potencia, ajustándolos a la altura deseada (justo debajo de las rodillas, justo encima o a la altura del muslo medio).\nAsegurá las bandas en la base de la rack o con mancuernas, y conectá el otro extremo a la barra.\nApretá las bandas si es necesario para generar tensión.\nPosicioná tu cuerpo contra la barra en la postura correcta para peso muerto.\nColocá los pies debajo de las caderas, con un agarre a la anchura de los hombros, la espalda arqueada y las caderas hacia atrás para activar los isquiotibiales.\nUsá un agarre mixto, de gancho o correas para ayudarte a sostener el peso, ya que suele ser pesado.\nMantené la cabeza mirando hacia adelante.\nExtendé las caderas y las rodillas, tirando del peso hacia arriba y hacia atrás hasta el bloqueo.\nRetirá los hombros hacia atrás al completar el movimiento.\nDevolvé el peso a los pines y repetí.' WHERE name_en = 'Rack Pull with Bands';
UPDATE public.exercises SET instructions_es = 'Colocá la barra en los soportes de la rack de potencia, ajustando la altura a la posición deseada (justo debajo de las rodillas, justo encima o a la altura del medio del muslo).\nPosicioná tu cuerpo contra la barra en la postura correcta para el peso muerto: pies debajo de las caderas, agarre a la anchura de los hombros, espalda arqueada y caderas hacia atrás para activar los isquiotibiales.\nDado que el peso suele ser pesado, podés usar un agarre mixto, agarre de gancho o poleas para ayudarte a sostener la carga.\nMantené la cabeza mirando hacia adelante y extendé las caderas y las rodillas, jalando el peso hacia arriba y hacia atrás hasta el bloqueo completo.\nAsegurate de jalar los hombros hacia atrás al completar el movimiento.\nDevolvé el peso a los soportes y repetí.' WHERE name_en = 'Rack Pulls';
UPDATE public.exercises SET instructions_es = 'Colocate en posición de manos y rodillas sobre una colchoneta de ejercicio.\nMantené la cabeza mirando hacia adelante y doblá las rodillas para formar un ángulo de 90 grados entre los isquiotibiales y los gemelos; esta será tu posición inicial.\nExtendé una pierna hacia arriba y hacia atrás, asegurándote de extender tanto la rodilla como la cadera.\nRepetí de 5 a 10 veces y luego cambiá de lado.' WHERE name_en = 'Rear Leg Raises';
UPDATE public.exercises SET instructions_es = 'Sentate en la bicicleta y ajustá el asiento a tu altura.\nElegí la opción deseada del menú; quizás tengas que pedalear para encenderla.\nPodés usar la configuración manual o seleccionar un programa.\nIngresá tu edad y peso para estimar las calorías quemadas.\nCambió el nivel de resistencia durante el entrenamiento si lo necesitás.\nUsá los manubrios para monitorear tu frecuencia cardíaca y mantener la intensidad adecuada.' WHERE name_en = 'Recumbent Bike';
UPDATE public.exercises SET instructions_es = 'Necesitás un compañero para este ejercicio.\nComenzá en una postura atlética de 2 o 3 puntos.\nAl recibir la señal, movete para recibir el pase de tu compañero.\nAtrapá la pelota medicinal con ambas manos y devolvéla de inmediato.\nPodés modificar el ejercicio corriendo por diferentes rutas.' WHERE name_en = 'Return Push from Stance';
UPDATE public.exercises SET instructions_es = 'Colocá la barra cargada en el piso dentro de un rack de potencia.\nFijá las bandas en la parte superior del rack, usando los pasadores o el propio marco.\nConectá el otro extremo de las bandas a la barra.\nAcercate a la barra para que esta cruce el centro de tus pies.\nSepará los pies muy ancho, casi hasta las cuñas.\nIncliná la cadera para agarrar la barra.\nMantené los brazos directamente debajo de los hombros, por dentro de las piernas, y usá un agarre prono, mixto o de gancho.\nRelajá los hombros para alargar el alcance de tus brazos.\nTomá aire y bajá la cadera, mirando al frente con el pecho arriba.\nEmpujá contra el piso, separando los pies, con el peso en la parte trasera de los pies.\nExtendé la cadera y las rodillas.\nCuando la barra pase las rodillas, echate hacia atrás y empujá la cadera contra la barra, juntando las escápulas.\nDevolvé el peso al suelo flexionando la cadera y controlando la bajada.' WHERE name_en = 'Reverse Band Sumo Deadlift';
UPDATE public.exercises SET instructions_es = 'Parate con el torso erguido sosteniendo una barra a la altura de los hombros, con los codos pegados al cuerpo.\nMantené las palmas de las manos hacia abajo (agarre prono). Esta es tu posición inicial.\nMantené los brazos superiores quietos y flexioná los antebrazos para subir la barra, contrayendo los bíceps mientras exhalás.\nMové solo los antebrazos.\nLlevá la barra hasta la altura de los hombros hasta que los bíceps estén completamente contraídos.\nMantené la posición contraída por un segundo apretando el músculo.\nBajá la barra lentamente a la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Reverse Barbell Curl';
UPDATE public.exercises SET instructions_es = 'Agarrá la barra EZ con un ancho de hombros y las palmas hacia abajo.\nApoyá la parte superior de ambos brazos sobre el banco predicador y mantené los brazos extendidos.\nExhalá y usá los bíceps para levantar el peso hasta que estén completamente contraídos y la barra llegue a la altura de los hombros.\nApretá fuerte los bíceps durante un segundo en la posición contraída.\nInhalá y bajá la barra lentamente hasta que los brazos superiores estén extendidos y los bíceps estén completamente estirados.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Reverse Barbell Preacher Curls';
UPDATE public.exercises SET instructions_es = 'Parate con el torso erguido sosteniendo un accesorio de barra conectado a una polea baja con un agarre prono (palmas hacia abajo) y ancho de hombros.\nMantené los codos pegados al torso.\nMientras mantenés los brazos superiores fijos, flexioná los antebrazos para levantar el peso contrayendo los bíceps mientras exhalás.\nSolo deben moverse los antebrazos.\nContinuá el movimiento hasta que los bíceps estén completamente contraídos y la barra llegue a la altura de los hombros.\nMantené la posición contraída durante un segundo apretando el músculo.\nInhalá y bajá la barra lentamente hasta la posición inicial.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Reverse Cable Curl';
UPDATE public.exercises SET instructions_es = 'Recostá en el piso con las piernas completamente extendidas y los brazos a los lados del torso, con las palmas apoyadas en el suelo. Mantené los brazos quietos durante todo el ejercicio.\nLlevá las piernas hacia arriba hasta que los muslos queden perpendiculares al piso y los pies juntos y paralelos al suelo. Esta es la posición inicial.\nMientras inhalás, acercá las piernas al torso, girá la pelvis hacia atrás y levantá las caderas del piso. Al final del movimiento, las rodillas deben tocar el pecho.\nMantené la contracción un segundo y volvé las piernas a la posición inicial mientras exhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Reverse Crunch';
UPDATE public.exercises SET instructions_es = 'Para empezar, recostá en un banco inclinado con el pecho y el abdomen apoyados contra la superficie. Tené una mancuerna en cada mano con las palmas mirándose (agarre neutro).\nExtendé los brazos frente a vos hasta que queden perpendiculares al ángulo del banco. Mantené las piernas quietas aplicando presión con la punta de los pies. Esta es la posición inicial.\nMantené una leve flexión en los codos y mové los pesos hacia afuera y separados (lateralmente) en un movimiento de arco mientras exhalás. Consejo: Intentá juntar las escápulas para obtener los mejores resultados de este ejercicio.\nElevá los brazos hasta que queden paralelos al piso.\nSentí la contracción y bajá los pesos lentamente de vuelta a la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Reverse Flyes';
UPDATE public.exercises SET instructions_es = 'Recostá en un banco inclinado a 30 grados, presionando el pecho y el abdomen contra la superficie.\nTomá una mancuerna en cada mano con las palmas hacia abajo, manteniendo los brazos perpendiculares al banco y con una leve flexión en los codos.\nFijá las piernas y apoyá la presión en la punta de los pies, sin que los talones toquen el suelo.\nMantené la leve flexión de los codos y mové los pesos hacia afuera en un arco mientras exhalás.\nRotá externamente las muñecas 90 grados para pasar de una agarre con palmas hacia abajo a un agarre neutro (palmas enfrentadas).\nElevá los brazos hasta que queden al nivel de la cabeza, apretando las escápulas.\nSentí la contracción y bajá los pesos lentamente a la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Reverse Flyes With External Rotation';
UPDATE public.exercises SET instructions_es = 'Parate erguido sosteniendo una barra con agarre supino (palmas hacia arriba).\nDoblá ligeramente las rodillas e incliná el torso hacia adelante desde la cintura, manteniendo la espalda recta hasta que quede casi paralela al suelo.\nMantené la cabeza arriba y dejá que la barra cuelgue directamente frente a vos, con los brazos perpendiculares al suelo y al torso.\nMantené el torso inmóvil y levantá la barra mientras exhalás, manteniendo los codos pegados al cuerpo.\nEn la posición superior, apretá los músculos de la espalda y mantené la tensión por un segundo.\nBajá el peso lentamente a la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Reverse Grip Bent-Over Rows';
UPDATE public.exercises SET instructions_es = 'Colocá una barra recta o e-z en la polea alta.\nMirá la barra y agarrala con las palmas hacia arriba (agarre supino) a la anchura de los hombros.\nBajá la barra usando tus dorsales hasta que los brazos estén completamente extendidos a los lados.\nTip: Los codos deben estar pegados a los costados y los pies a la anchura de los hombros. Esta es la posición inicial.\nSubí la barra lentamente mientras inhalás hasta que quede alineada con tu pecho.\nSolo deben moverse los antebrazos; los codos y los brazos superiores deben permanecer quietos a los lados.\nLuego, bajá la barra de vuelta a la posición inicial mientras exhalás y contraés los tríceps con fuerza.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Reverse Grip Triceps Pushdown';
UPDATE public.exercises SET instructions_es = 'Colocá los pies entre las almohadillas después de cargar el peso adecuado.\nRecostate en la almohadilla superior, dejando que las caderas cuelguen por detrás, mientras agarrás los mangos para mantener tu posición.\nPara comenzar el movimiento, flexioná las caderas, tirando de las piernas hacia adelante.\nInvertí el movimiento extendiendo las caderas y pateando la pierna hacia atrás.\nEs muy importante no hiperextender la cadera en este movimiento; detente antes de alcanzar el rango de movimiento completo.\nVolvé a flexionar la cadera, tirando del carro hacia adelante lo más que puedas.\nRepetí la cantidad de repeticiones deseadas.' WHERE name_en = 'Reverse Hyperextension';
UPDATE public.exercises SET instructions_es = 'Ajustá las manijas para que queden completamente hacia atrás.\nElegí un peso adecuado y ajustá la altura del asiento para que las manijas queden a la altura de los hombros.\nAgarrá las manijas con las palmas de las manos mirando hacia adentro. Esta será tu posición inicial.\nEn un movimiento semicircular, llevá las manos hacia los lados y hacia atrás, contrayendo los deltoides posteriores.\nMantené los brazos ligeramente flexionados durante todo el movimiento, asegurándote de que toda la acción ocurra en la articulación del hombro.\nHacé una pausa en la parte posterior del movimiento y volvé lentamente el peso a la posición inicial.' WHERE name_en = 'Reverse Machine Flyes';
UPDATE public.exercises SET instructions_es = 'Comenzá de pie, recto, sosteniendo una placa con peso con ambas manos y los brazos completamente extendidos.\nUsá un agarre prono (palmas hacia abajo) y asegurá de que tus dedos agarran el lado rugoso de la placa mientras que el pulgar agarra el lado liso. Nota: Para obtener los mejores resultados, agarrá la placa en la posición de las 11:00 y las 1:00.\nTus pies deben estar separados a la anchura de los hombros y la placa debe estar cerca del área de la ingle. Esta es la posición inicial.\nLevantá lentamente la placa hacia arriba manteniendo los codos pegados al cuerpo y los brazos superiores estacionarios hasta que tus bíceps y antebrazos se toquen, mientras exhalás. La placa debe estar alineada uniformemente con tu torso en este punto.\nSentí la contracción durante un segundo y comenzá a bajar el peso de vuelta a la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Reverse Plate Curls';
UPDATE public.exercises SET instructions_es = 'Recostá en un banco plano.\nCon un agarre cerrado y supinado (a la anchura de los hombros), levantá la barra del soporte y mantenela recta sobre vos con los brazos extendidos y bloqueados, perpendiculares al suelo.\nInhala y bajá lentamente hasta sentir la barra en el centro del pecho, manteniendo los codos pegados al torso en todo momento.\nHacé una pausa de un segundo y empujá la barra de vuelta a la posición inicial usando los tríceps mientras exhalás.\nBloqueá los brazos en la posición contraída, mantené un segundo y bajá de nuevo lentamente, asegurándote de que la bajada tome el doble de tiempo que la subida.\nRepetí el movimiento la cantidad de repeticiones indicadas.\nAl terminar, devolvé la barra al soporte.' WHERE name_en = 'Reverse Triceps Bench Press';
UPDATE public.exercises SET instructions_es = 'Recostá de espaldas en el suelo.\nColocá un rodillo de espuma debajo de la parte superior de la espalda y cruzá los brazos frente a vos, protrayendo los hombros.\nLevantá la cadera del suelo, apoyando el peso sobre el rodillo.\nDesplazá el peso de un lado a otro, rodando sobre la parte media y superior de la espalda.\nMantené la posición en los puntos de tensión durante 10 a 30 segundos.' WHERE name_en = 'Rhomboids-SMR';
UPDATE public.exercises SET instructions_es = 'Colocá el marco en el punto de partida y cargalo con el peso adecuado.\nPará en el centro del marco, agarrá los mangos y empujá a través de los talones para levantar el marco.\nMantené el pecho y la cabeza arriba y la espalda recta.\nEmpezá a caminar rápidamente con pasos cortos y controlados.\nMantené el pecho arriba, la cabeza al frente y seguí respirando.\nLlevá el marco al suelo cuando llegues al punto final.' WHERE name_en = 'Rickshaw Carry';
UPDATE public.exercises SET instructions_es = 'Cargá el marco con el peso deseado.\nCentráte entre los mangos.\nMantené los pies separados a la anchura de las caderas.\nIncliná la cadera para agarrar los mangos, permitiendo que las escápulas se proyecten hacia adelante.\nCon los pies y el agarre listos, tomá una respiración profunda y luego bajá la cadera y flexioná las rodillas.\nMirá al frente, mantené el pecho arriba y la espalda arqueada, y empujá a través de los talones para mover el peso hacia arriba.\nA medida que el peso sube, juntá las escápulas mientras empujás la cadera hacia adelante.\nBajá el peso inclinando la cadera y guiándolo hasta el suelo.' WHERE name_en = 'Rickshaw Deadlift';
UPDATE public.exercises SET instructions_es = 'Agarrá un aro con cada mano y saltá un poco para llegar a la posición inicial con los brazos estirados.\nFlexioná los codos y bajá el cuerpo hasta que los brazos formen un ángulo de 90 grados, evitando balancearte y manteniendo buena postura.\nExtendé los codos para empujarte hacia arriba y volver a la posición inicial.\nRepetí el movimiento la cantidad de veces que necesites.' WHERE name_en = 'Ring Dips';
UPDATE public.exercises SET instructions_es = 'Comenzá en una postura relajada con los pies separados al ancho de los hombros y los brazos pegados al cuerpo.\nBajá a media sentadilla y explotá hacia arriba lo más alto posible.\nExtendé todo el cuerpo, estirando los brazos por encima de la cabeza, y al aterrizar amortiguá el impacto con las piernas.' WHERE name_en = 'Rocket Jump';
UPDATE public.exercises SET instructions_es = 'Colocá la barra en un rack a la altura de tus hombros.\nApoyá la barra en la parte posterior de tus hombros, justo debajo del cuello.\nSujetá la barra con ambas manos y levantala empujando con las piernas mientras enderezás el torso.\nRetirate del rack y separá las piernas a la anchura de los hombros con las puntas de los pies ligeramente hacia afuera.\nMantené la cabeza arriba, la espalda recta y las rodillas con una leve flexión, nunca bloqueadas.\nExhalá y elevá los talones extendiendo los tobillos al máximo para contraer los gemelos.\nMantené la posición contraída por un segundo.\nInhalá y bajá los talones lentamente hasta estirar los gemelos.\nExhalá y levantá las puntas de los pies contrayendo los músculos tibiales.\nMantené por un segundo y bajá inhalando.\nRepetí el movimiento la cantidad de veces indicada.' WHERE name_en = 'Rocking Standing Calf Raise';
UPDATE public.exercises SET instructions_es = 'Agarrá la barra de dominadas con las palmas hacia adelante y un agarre ancho.\nExtendé los brazos y incliná el torso hacia atrás unos 30 grados, arqueando la zona lumbar y sacando el pecho.\nExhalá y tirá de tu cuerpo hacia arriba hasta que la barra toque el pecho superior, bajando los hombros y los brazos.\nConcentrate en apretar los músculos de la espalda en la posición máxima de contracción.\nMantené la posición por un segundo.\nInhalá y bajá lentamente hasta que los brazos estén completamente extendidos y los dorsales estirados.\nRepetí el movimiento manteniendo el torso recto esta vez, tocando la barra con la parte posterior del cuello.\nIncliná la cabeza ligeramente hacia adelante para ayudar a ejecutar bien esta parte.\nBajá hasta la posición inicial y repetí el ejercicio la cantidad de veces prescrita.' WHERE name_en = 'Rocky Pull-Ups/Pulldowns';
UPDATE public.exercises SET instructions_es = 'Colocá una barra en el suelo frente a vos y agarrala con un agarre prono (palmas hacia abajo) un poco más ancho que el ancho de los hombros.\nDoblá las rodillas ligeramente, mantené los esguinces verticales, las caderas hacia atrás y la espalda recta; esta será tu posición inicial.\nMantené la espalda y los brazos completamente rectos en todo momento y usá tus caderas para levantar la barra mientras exhalás.\nUna vez que estés de pie completamente recto, bajá la barra empujando las caderas hacia atrás, doblando las rodillas solo ligeramente.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Romanian Deadlift';
UPDATE public.exercises SET instructions_es = 'Comenzá de pie sosteniendo una barra a la altura de los brazos frente a vos.\nDoblá las rodillas ligeramente y luego flexioná en la cadera, moviendo el glúteo hacia atrás lo más posible y bajando el torso hasta el límite de tu flexibilidad.\nMantené la espalda en extensión absoluta en todo momento y asegurá que la barra permanezca en contacto con las piernas.\nInvertí el movimiento para volver a la posición inicial.' WHERE name_en = 'Romanian Deadlift from Deficit';
UPDATE public.exercises SET instructions_es = 'Agarrá la cuerda con ambas manos por encima de tu cabeza. Tirá de la cuerda hacia abajo mientras das un pequeño salto.\nEnvolvé la cuerda alrededor de una pierna, usando los pies para apretarla. Alcanzá lo más alto posible con los brazos, agarrando la cuerda con fuerza.\nSoltá la cuerda de tus pies mientras te subís con los brazos, llevando las rodillas hacia el pecho.\nVolvé a asegurar los pies en la cuerda y parate para tomar otra agarre alto. Continuá hasta llegar a la parte superior de la cuerda.\nPara bajar, aflojá el agarre de los pies en la cuerda mientras deslizás hacia abajo usando un movimiento de mano sobre mano.' WHERE name_en = 'Rope Climb';
UPDATE public.exercises SET instructions_es = 'Arrodillate a 1-2 pies frente a un sistema de poleas con una cuerda.\nDespués de elegir un peso adecuado, agarrá la cuerda con ambas manos alcanzando por encima de la cabeza. Tu torso debe estar erguido en la posición inicial.\nPara comenzar, flexioná la columna, intentando llevar tu caja torácica hacia las piernas mientras tirás del cable hacia abajo.\nHacé una pausa en la parte inferior del movimiento y luego volvé lentamente a la posición inicial.\nPodés hacerlos con giros o hacia un lado para trabajar los oblicuos.' WHERE name_en = 'Rope Crunch';
UPDATE public.exercises SET instructions_es = 'Sujetá un extremo de la cuerda en cada mano\nColocá la cuerda detrás de vos en el suelo\nLevantá los brazos y pasá la cuerda por encima de la cabeza hasta bajarla frente a vos\nSaltá sobre la cuerda cuando toque el suelo\nEncontrá un ritmo de giro que puedas mantener\nProbá diferentes velocidades y técnicas para variar' WHERE name_en = 'Rope Jumping';
UPDATE public.exercises SET instructions_es = 'Conectá una cuerda a una polea alta y elegí tu peso\nPará un par de pies atrás de la polea con los pies escalonados y tomá la cuerda con ambas manos\nIncliná el torso hacia adelante desde la cadera, manteniendo la espalda recta y los brazos extendidos hacia arriba y adelante\nMantené los brazos rectos y extendé los hombros para tirar de la cuerda hacia abajo hasta los muslos\nHacé una pausa en la parte inferior del movimiento, apretando los dorsales\nVolvé a la posición inicial sin dejar que el peso se apoye completamente en la torre' WHERE name_en = 'Rope Straight-Arm Pulldown';
UPDATE public.exercises SET instructions_es = 'Pará derecho con las piernas juntas, sosteniendo una barra o escoba.\nMantené la barra detrás de tus caderas con un agarre más ancho que el de tus hombros, con las palmas hacia abajo y los pulgares hacia afuera.\nLevantá lentamente los brazos detrás de tu cabeza, sin forzar si te resulta difícil subir más.' WHERE name_en = 'Round The World Shoulder Stretch';
UPDATE public.exercises SET instructions_es = 'Sentate en el remo, asegurándote de que los talones descansen cómodamente contra la base de los pedales y que las correas estén seguras.\nElegí el programa que quieras usar, si aplica, y mantené la espalda recta flexionando la cadera hacia adelante.\nIniciá la fase de tracción con las rodillas dobladas contra el pecho y el torso ligeramente inclinado hacia adelante manteniendo buena postura.\nEmpujá los pedales con fuerza extendiendo las piernas mientras llevás las manos hacia el abdomen superior, apretando los hombros hacia atrás usando principalmente los músculos de las piernas y caderas.\nRecuperá la posición inicial estirando los brazos, doblando las rodillas y llevando el cuerpo hacia adelante para volver a la fase de tracción.' WHERE name_en = 'Rowing, Stationary';
UPDATE public.exercises SET instructions_es = 'Parate y poné una pierna atrás.\nBajá el torso lentamente hacia el piso.\nMantené el talón delantero apoyado en el suelo.\nSi se levanta, alejá la otra pierna más atrás.\nApoyá las manos a los costados de la pierna delantera.\nEmpujá el glúteo hacia el techo para intensificar la estirada.\nBajá el glúteo gradualmente de vuelta al piso.' WHERE name_en = 'Runner''s Stretch';
UPDATE public.exercises SET instructions_es = 'Subite a la cinta y elegí la opción deseada del menú.\nSeleccioná un ajuste manual o un programa de carrera.\nIngresá tu edad y peso para estimar las calorías quemadas.\nAjustá la inclinación para cambiar la intensidad del entrenamiento.\nMantené una postura correcta mientras corres.\nAgarrate de los apoyos solo cuando sea necesario, como al bajar o al revisar tu frecuencia cardíaca.' WHERE name_en = 'Running, Treadmill';
UPDATE public.exercises SET instructions_es = 'Recostá en el piso con los pies bajo algo que no se mueva o con un compañero que los sostenga. Doblá las rodillas.\nElevá el torso para formar una V imaginaria con los muslos. Extendé los brazos por completo frente a vos, perpendiculares al tronco, con las manos entrelazadas. Esta es la posición inicial.\nGirá el torso hacia la derecha hasta que los brazos queden paralelos al piso mientras exhalás.\nMantené la contracción un segundo y volvé a la posición inicial exhalando. Ahora pasá al lado opuesto aplicando la misma técnica.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Russian Twist';
UPDATE public.exercises SET instructions_es = 'Para cargar las bolsas de arena u otros objetos, empezá con los implementos a una distancia de la plataforma de carga, típicamente 50 pies.\nComenzá levantando la bolsa de arena. Son muy incómodas y la forma de levantarlas puede variar según el tipo. Alcanzalas lo más lejos posible, extendiendo caderas y rodillas para subirla alto. Generalmente no se permite apoyarlas en los hombros.\nMovete lo más rápido posible hacia la plataforma y cargala, extendiendo caderas, rodillas y tobillos para subirla lo más alto posible. Colocala en la plataforma asegurándote de que no se caiga.\nVolvé a la posición inicial para recuperar la siguiente bolsa y repetí hasta completar la prueba.' WHERE name_en = 'Sandbag Load';
UPDATE public.exercises SET instructions_es = 'Apretá la barra de dominadas con agarre prono.\nDesde la posición colgada, elevá tu cuerpo unos centímetros sin usar los brazos, deprimiendo tu cintura escapular con un movimiento de encogimiento inverso.\nHacé una pausa al completar el movimiento y volvé lentamente a la posición inicial antes de hacer más repeticiones.' WHERE name_en = 'Scapular Pull-Up';
UPDATE public.exercises SET instructions_es = 'Recostate con la espalda apoyada en el suelo o sobre una colchoneta (opcional), con los brazos extendidos a los lados y las palmas hacia abajo; mantené los brazos quietos todo el tiempo.\nCon una leve flexión de rodillas, levantá las piernas hasta que los talones queden a unos 15 cm del suelo; esta es la posición inicial.\nLevantá la pierna izquierda hasta un ángulo de 45 grados mientras bajás la derecha hasta que el talón quede a unos 5-7 cm del suelo.\nCambialas subiendo la pierna derecha y bajando la izquierda, recordá respirar mientras hacés el ejercicio.\nRepetí la cantidad de veces recomendadas.' WHERE name_en = 'Scissor Kick';
UPDATE public.exercises SET instructions_es = 'Asumí una posición de zancada con un pie adelante y la rodilla flexionada, y la rodilla trasera casi tocando el suelo.\nAsegurate de que la rodilla delantera esté sobre la línea media del pie. Extendé a través de ambas piernas y saltá lo más alto posible, balanceando los brazos para ganar impulso.\nMientras saltás lo más alto que puedas, cambiá la posición de tus piernas, moviendo la pierna delantera hacia atrás y la trasera hacia adelante.\nAl aterrizar, absorbé el impacto a través de las piernas adoptando la posición de zancada, y repetí.' WHERE name_en = 'Scissors Jump';
UPDATE public.exercises SET instructions_es = 'Fijá una banda cerca del suelo y colocá un banco a un par de pies de distancia.\nSentate en el banco y asegurá la banda detrás de tus tobillos, comenzando con las piernas rectas. Esta será tu posición inicial.\nFlexioná las rodillas, llevando los pies hacia el banco. Puede que necesites inclinarte ligeramente hacia atrás para evitar que los pies golpeen el piso.\nHacé una pausa al completar el movimiento y luego volvé lentamente a la posición inicial.' WHERE name_en = 'Seated Band Hamstring Curl';
UPDATE public.exercises SET instructions_es = 'Sentate en un banco de press militar con la barra detrás de tu cabeza y pedile a un compañero que te la pase (es mejor para el manguito rotador) o levantala vos mismo con cuidado usando una agarre prono (palmas hacia adelante). Tip: Tu agarre debe ser más ancho que el ancho de tus hombros y debe crear un ángulo de 90 grados entre el antebrazo y el brazo superior cuando la barra baje.\nUna vez que levantes la barra con la longitud de agarre correcta, subila sobre tu cabeza bloqueando los brazos. Mantenela a la altura de los hombros y ligeramente adelante de tu cabeza. Esta es tu posición inicial.\nBajá la barra lentamente hasta la clavícula mientras inhalás.\nLevantá la barra de vuelta a la posición inicial mientras exhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Seated Barbell Military Press';
UPDATE public.exercises SET instructions_es = 'Comenzá sentándote al final de un banco plano con una barra sobre tus muslos. Tus pies deben estar separados al ancho de tus hombros.\nAgarrá la barra con las palmas hacia abajo y asegurate de que tus manos estén más separadas que el ancho de tus hombros. Comenzá a levantar la barra sobre tu cabeza hasta que tus brazos estén completamente extendidos.\nAhora bajá la barra detrás de tu cabeza hasta que descanse en la base de tu cuello. Esta es la posición inicial.\nMientras mantenés los pies y la cabeza quietos, mové la cintura de un lado a otro para que tus músculos oblicuos sientan la contracción. Solo movete de lado a lado hasta donde tu cintura te permita. Estirarte o moverte demasiado puede causar una lesión. Tip: Usá un movimiento lento y controlado.\nRecordá exhalá mientras girás el cuerpo hacia un lado e inhalá al volver a la posición inicial.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Seated Barbell Twist';
UPDATE public.exercises SET instructions_es = 'Sentate al final de un banco plano con una mancuerna en cada brazo usando agarre neutro (palmas hacia vos).\nDobla las rodillas ligeramente y lleva el torso hacia adelante, flexionando la cintura, mientras mantenés la espalda recta hasta que quede casi paralela al suelo. Asegurate de mantener la cabeza arriba.\nLos brazos superiores con las mancuernas deben estar cerca del torso y alineados con él (levantados hasta que queden paralelos al suelo mientras los antebrazos apuntan hacia el suelo y las manos sostienen los pesos). Consejo: Debe haber un ángulo de 90 grados entre los antebrazos y el brazo superior. Esta es tu posición inicial.\nMantené los brazos superiores estacionarios y usá los tríceps para levantar el peso mientras exhalás hasta que los antebrazos queden paralelos al suelo y el brazo completo esté extendido. Como en muchos otros ejercicios de brazos, solo se mueve el antebrazo.\nDespués de un segundo de contracción en la parte superior, bajá lentamente las mancuernas a la posición inicial mientras inhalás.\nRepetí el movimiento por la cantidad de repeticiones prescritas.' WHERE name_en = 'Seated Bent-Over Two-Arm Dumbbell Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Sentate en el suelo con las rodillas dobladas y tu pareja de pie detrás de vos. Extendé los brazos rectos hacia atrás con las palmas mirándose entre sí. Tu pareja sostendrá tus muñecas. Esta será la posición inicial.\nIntentá flexionar los codos, mientras tu pareja impide cualquier movimiento real.\nDespués de 10 a 20 segundos, relajá los brazos mientras tu pareja tira suavemente de tus muñecas hacia arriba para estirar los bíceps. Asegurate de decirle a tu pareja cuándo el estiramiento es apropiado para prevenir lesiones o estiramientos excesivos.' WHERE name_en = 'Seated Biceps';
UPDATE public.exercises SET instructions_es = 'Sentate en la máquina y apoyá los pies en la plataforma frontal, manteniendo las rodillas ligeramente flexionadas.\nIncliná el torso hacia adelante manteniendo la alineación natural de la espalda y agarrá las empuñaduras de la barra en V.\nExtendé los brazos hasta que el torso forme un ángulo de 90 grados con las piernas, con la espalda ligeramente arqueada y el pecho afuera para sentir el estiramiento en los dorsales.\nMantené el torso fijo y jalá las empuñaduras hacia el abdomen, manteniendo los brazos pegados al cuerpo mientras exhalás.\nApretá los músculos de la espalda fuertemente, mantené la contracción un segundo y volvé lentamente a la posición inicial inhalando.\nRepetí el movimiento la cantidad de veces recomendadas.' WHERE name_en = 'Seated Cable Rows';
UPDATE public.exercises SET instructions_es = 'Ajustá el peso a un nivel adecuado, sentate y agarrá las empuñaduras.\nMantené los brazos superiores a 90 grados respecto al cuerpo, con la cabeza y el pecho arriba, y los codos flexionados a 90 grados.\nExtendé los codos para empujar las empuñaduras juntas hacia arriba sobre la cabeza.\nHacé una pausa en la parte superior y volvé a la posición inicial asegurándote de mantener la tensión en los cables.\nPodés realizar este movimiento con la espalda fuera del cojín y alternando las manos.' WHERE name_en = 'Seated Cable Shoulder Press';
UPDATE public.exercises SET instructions_es = 'Sentate en la máquina y apoyá las puntas de los pies en la parte inferior de la plataforma, dejando que los talones queden colgando.\nElegí la posición de las puntas de los pies que prefieras (hacia adelante, adentro o afuera) según lo indicado al inicio de este capítulo.\nColocá tus muslos inferiores bajo el cojín de la palanca, ajustándolo según la altura de tus muslos.\nApoyá tus manos sobre el cojín de la palanca para evitar que se deslice hacia adelante.\nLevantá ligeramente la palanca empujando los talones hacia arriba y soltá la barra de seguridad. Esta será tu posición inicial.\nBajá lentamente los talones flexionando los tobillos hasta que los gemelos estén completamente estirados. Inspirá mientras realizás este movimiento.\nLevantá los talones extendiendo los tobillos lo más alto posible, contrayendo los gemelos y exhalando.\nMantené la contracción superior durante un segundo.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Seated Calf Raise';
UPDATE public.exercises SET instructions_es = 'Sentate derecho sobre una alfombrilla de ejercicio.\nDoblad una rodilla y apoyá ese pie en el suelo para estabilizar el torso.\nEstirá la otra pierna y flexioná el tobillo.\nUsando una banda, una toalla o tu mano si podés alcanzarla, tirá de los dedos hacia vos.\nMantené la posición de 10 a 20 segundos y luego cambiá de lado.' WHERE name_en = 'Seated Calf Stretch';
UPDATE public.exercises SET instructions_es = 'Sentate en el extremo de un banco plano con una mancuerna en cada mano, sosteniéndolas a la altura de los brazos.\nMantené los codos cerca del torso.\nGirá las palmas de las manos hacia adentro para que queden en posición neutra. Esta será tu posición inicial.\nMientras mantenés los brazos superiores estacionarios, flexioná las mancuernas hacia afuera y hacia arriba, girando las palmas hacia afuera al levantar y manteniendo los antebrazos alineados con tus deltoides externos.\nSolo deben moverse los antebrazos. Continuá el movimiento hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.\nMantené la posición contraída por un segundo mientras apretás los bíceps.\nLlevá las mancuernas de vuelta a la posición inicial lentamente mientras inhalás.\nRecordá girar los brazos al bajar las mancuernas para volver a la agarre neutro.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Seated Dumbbell Inner Biceps Curl';
UPDATE public.exercises SET instructions_es = 'Comenzá colocando dos mancuernas en el suelo frente a un banco plano.\nSentate en el borde del banco plano con las piernas separadas aproximadamente a la anchura de los hombros.\nAsegurate de mantener los pies apoyados en el suelo.\nUsá tus brazos para agarrar ambas mancuernas y levantas hasta que tus antebrazos descansen sobre tus muslos, con las palmas de las manos hacia abajo.\nDejá que tus muñecas cuelguen sobre el borde de tus muslos.\nComenzá flexionando las muñecas hacia arriba mientras exhalás.\nBajá las muñecas lentamente de vuelta a la posición inicial mientras inhalás.\nAsegurate de inhalar durante esta parte del ejercicio.\nMantené los antebrazos estacionarios, ya que la muñeca es el único movimiento necesario para realizar este ejercicio.\nRepetí la cantidad de repeticiones recomendadas.\nCuando termines, simplemente bajá las mancuernas al suelo.' WHERE name_en = 'Seated Dumbbell Palms-Down Wrist Curl';
UPDATE public.exercises SET instructions_es = 'Colocá dos mancuernas en el piso frente a un banco plano.\nSentate en el borde del banco con las piernas separadas a la anchura de los hombros y los pies apoyados en el suelo.\nAgarrá ambas mancuernas y levantá los brazos hasta que tus antebrazos descansen sobre los muslos, con las palmas hacia arriba y las muñecas colgando sobre el borde de los muslos.\nCurlé las muñecas hacia arriba mientras exhalás.\nBajá lentamente las muñecas a la posición inicial mientras inhalás, manteniendo los antebrazos estacionarios.\nRepetí la cantidad de repeticiones recomendadas.\nAl terminar, bajá las mancuernas al piso.' WHERE name_en = 'Seated Dumbbell Palms-Up Wrist Curl';
UPDATE public.exercises SET instructions_es = 'Agarrá un par de mancuernas y sentate en un banco con respaldo, colocando las mancuernas verticales sobre tus muslos.\nLimpia las mancuernas una por una usando tus muslos para llevarlas a la altura de los hombros.\nRotá las muñecas para que las palmas de tus manos miren hacia adelante; esta es tu posición inicial.\nMientras exhalás, empujá las mancuernas hacia arriba hasta que se toquen en la parte superior.\nDespués de una pausa de un segundo, bajá lentamente a la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Seated Dumbbell Press';
UPDATE public.exercises SET instructions_es = 'Sentate en un banco con las piernas estiradas hacia adelante, ligeramente por debajo de la paralela, y sostené los lados del banco con los brazos.\nIncliná tu torso hacia atrás formando un ángulo de aproximadamente 45 grados con el banco.\nLlevá las rodillas hacia vos mientras acercás el torso a ellas al mismo tiempo.\nExhalá mientras realizás este movimiento.\nDespués de una pausa de un segundo, volvé a la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Seated Flat Bench Leg Pull-In';
UPDATE public.exercises SET instructions_es = 'Sentate en una alfombra con la pierna derecha extendida hacia adelante y la pierna izquierda doblada, con el pie apoyado en la cara interna del muslo derecho.\nInclinate hacia adelante desde las caderas y estirá los brazos hacia el tobillo hasta sentir un estiramiento en el isquiotibial.\nMantené la posición durante 15 segundos.\nRepetí el ejercicio con el otro lado.' WHERE name_en = 'Seated Floor Hamstring Stretch';
UPDATE public.exercises SET instructions_es = 'Sentate en el piso con las piernas dobladas y tu pareja de pie detrás de vos.\nExtendé los brazos rectos hacia los lados, con las palmas hacia el suelo.\nIntentá llevarlos lo más atrás posible mientras tu asistente sostiene tus muñecas; esta será tu posición inicial.\nMantené los codos rectos e intentá llevar los brazos hacia adelante, mientras tu pareja te frena suavemente para evitar movimiento real durante 10-20 segundos.\nAhora, relajá los músculos y dejá que tu pareja aumente suavemente el estiramiento en hombros y pecho; mantené la posición de 10 a 20 segundos.' WHERE name_en = 'Seated Front Deltoid';
UPDATE public.exercises SET instructions_es = 'Sentate con las rodillas dobladas y cruzá un tobillo sobre la rodilla opuesta.\nTu pareja se parará detrás de vos.\nIncliná el torso hacia adelante mientras tu pareja sujeta tus hombros con las manos; esta será tu posición inicial.\nIntentá empujar el torso hacia atrás durante 10-20 segundos, mientras tu pareja impide cualquier movimiento real.\nAhora relajá los músculos y dejá que tu pareja aumente el estiramiento empujando suavemente el torso hacia adelante durante 10-20 segundos.' WHERE name_en = 'Seated Glute';
UPDATE public.exercises SET instructions_es = 'Colocá una caja en la jaula de potencia y ajustá los pines a la altura adecuada.\nEntrá bajo la barra y apoyala en la parte trasera de los hombros, no sobre los trapecios.\nApretá las escápulas entre sí y rotá los codos hacia adelante, intentando doblar la barra sobre los hombros.\nSacá la barra de la jaula creando un arco firme en la zona lumbar.\nMantené la cabeza mirando hacia adelante y la espalda, hombros y core tensos.\nEmpujá las rodillas y el glúteo hacia afuera para iniciar el descenso.\nSentate hacia atrás con las caderas hasta apoyarlas sobre la caja.\nMantené la barra pegada al cuerpo y flexioná la cadera hacia adelante lo más posible.\nHacé una pausa justo sobre los pines y revertí el movimiento hasta que el torso quede vertical.' WHERE name_en = 'Seated Good Mornings';
UPDATE public.exercises SET instructions_es = 'Sentate con las piernas extendidas y pedile a tu compañero que se pare detrás de vos.\nIncliná el torso hacia adelante mientras tu compañero sujeta tus hombros con las manos.\nIntentá empujar el torso hacia atrás durante 10 a 20 segundos, mientras tu compañero impide cualquier movimiento real.\nRelajá los músculos mientras tu compañero aumenta el estiramiento empujando suavemente tu torso hacia adelante durante 10 a 20 segundos.' WHERE name_en = 'Seated Hamstring';
UPDATE public.exercises SET instructions_es = 'Pasá una correa, cuerda o banda alrededor de un pie.\nSentate con ambas piernas extendidas. Esta será tu posición inicial.\nInclináte ligeramente hacia adelante y tirá de la correa para llevar los dedos de tu pie hacia atrás.\nMantené esta posición durante 10-20 segundos y repetí con la otra pierna.' WHERE name_en = 'Seated Hamstring and Calf Stretch';
UPDATE public.exercises SET instructions_es = 'Colocá una correa para el cuello en el suelo al final de un banco plano.\nElegí los pesos y sentate al final del banco con los pies más separados que el ancho de los hombros.\nApuntá los dedos de los pies hacia afuera.\nMové tu torso lentamente hacia adelante hasta que quede casi paralelo al suelo.\nUsando ambas manos, posicioná firmemente la correa alrededor de tu cabeza.\nTip: Asegurate de que los pesos sigan en el suelo para evitar tensión en el cuello.\nAhora agarrá el peso con ambas manos mientras elevás tu torso hacia atrás hasta que quede casi perpendicular al suelo.\nNota: Tu cabeza y torso deben estar ligeramente inclinados hacia adelante para realizar este ejercicio.\nAhora colocá ambas manos sobre las rodillas. Esta es la posición inicial.\nBajá lentamente el cuello hasta que tu barbilla toque la parte superior del pecho mientras inhalás.\nMientras exhalás, llevá tu cuello de vuelta a la posición inicial.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Seated Head Harness Neck Resistance';
UPDATE public.exercises SET instructions_es = 'Ajustá la palanca de la máquina a tu altura y sentate con la espalda apoyada en el respaldo.\nColocá la parte trasera de la pantorrilla sobre la palanca acolchada (unos centímetros por debajo de los gemelos) y asegurá el cojín de las piernas contra los muslos, justo por encima de las rodillas.\nAgarrá los mangos laterales de la máquina, apuntá los pies hacia adelante (o usá cualquiera de las otras dos posturas) y asegurá que las piernas estén completamente estiradas frente a vos. Esta será tu posición inicial.\nMientras exhalás, jalá la palanca de la máquina hacia atrás, lo más cerca posible de la parte trasera de los muslos, flexionando las rodillas.\nMantené el torso inmóvil en todo momento.\nMantené la posición contraída por un segundo.\nVolvé lentamente a la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Seated Leg Curl';
UPDATE public.exercises SET instructions_es = 'Sentate en un banco con las piernas estiradas frente a vos, ligeramente por debajo de la paralela, y agarrá los lados del banco con los brazos.\nIncliná el torso hacia atrás formando un ángulo de aproximadamente 45 grados con el banco. Esta será tu posición inicial.\nLlevá las rodillas hacia vos mientras acercás el torso a ellas al mismo tiempo.\nExhalá mientras realizás este movimiento.\nDespués de una pausa de un segundo, volvé a la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Seated Leg Tucks';
UPDATE public.exercises SET instructions_es = 'Sentate en un banco plano con una mancuerna en la mano derecha.\nColocá los pies planos en el suelo, a una distancia ligeramente más amplia que el ancho de los hombros.\nIncliná el torso hacia adelante y apoyá el antebrazo derecho sobre el muslo derecho superior con la palma hacia abajo. Tip: Asegurate de que la parte posterior de la muñeca quede sobre las rodillas. Esta será tu posición inicial.\nBajá la mancuerna lo más posible manteniendo un agarre firme. Inhalá mientras realizás este movimiento.\nAhora, flexioná la muñeca para subir la mancuerna lo más alto posible, contraé los antebrazos y exhalá. Mantené la contracción un segundo antes de bajar de nuevo. Tip: El único movimiento debe ocurrir en la muñeca.\nRealizá la cantidad de repeticiones recomendadas, cambiá de brazo y repetí el movimiento.' WHERE name_en = 'Seated One-Arm Dumbbell Palms-Down Wrist Curl';
UPDATE public.exercises SET instructions_es = 'Sentate en un banco plano con una mancuerna en la mano derecha.\nColocá los pies planos en el suelo, a una distancia ligeramente más amplia que el ancho de los hombros.\nIncliná el torso hacia adelante y apoyá el antebrazo derecho sobre el muslo derecho superior con la palma hacia arriba. Tip: Asegurate de que la parte frontal de la muñeca quede sobre las rodillas. Esta será tu posición inicial.\nBajá la mancuerna lo más posible manteniendo un agarre firme. Inhalá mientras realizás este movimiento.\nAhora, flexioná la muñeca para subir la mancuerna lo más alto posible, contraé los antebrazos y exhalá. Mantené la contracción un segundo antes de bajar de nuevo. Tip: El único movimiento debe ocurrir en la muñeca.\nRealizá la cantidad de repeticiones recomendadas, cambiá de brazo y repetí el movimiento.' WHERE name_en = 'Seated One-Arm Dumbbell Palms-Up Wrist Curl';
UPDATE public.exercises SET instructions_es = 'Sentate en la máquina y apoyá tus pies en la plataforma frontal o barra transversal, asegurándote de que las rodillas estén ligeramente flexionadas y no bloqueadas.\nIncliná el torso manteniendo la alineación natural de tu espalda y agarrá el accesorio de una sola manija con el brazo izquierdo usando un agarre con las palmas hacia abajo.\nCon el brazo extendido, tirá hacia atrás hasta que tu torso forme un ángulo de 90 grados con tus piernas; tu espalda debe estar ligeramente arqueada y el pecho proyectado hacia afuera, sintiendo un buen estiramiento en el dorsal mientras sostenés la barra frente a vos, manteniendo el brazo derecho a la altura de la cintura.\nManteniendo el torso inmóvil, tirá de las manijas hacia tu torso manteniendo los brazos pegados a él mientras rotás la muñeca, de modo que cuando tu mano llegue a la altura de los abdominales esté en posición neutra (palmas mirando hacia el torso), exhalando mientras realizás ese movimiento y apretando fuerte los músculos de la espalda.\nMantené esa contracción por un segundo y volvé lentamente a la posición original inhalando; recordá rotar la muñeca al volver para que las palmas queden mirando hacia abajo de nuevo.\nRepetí el movimiento la cantidad de repeticiones recomendadas y luego realizá el mismo ejercicio con la mano derecha.' WHERE name_en = 'Seated One-arm Cable Pulley Rows';
UPDATE public.exercises SET instructions_es = 'Sentate derecho sobre una colchoneta de ejercicio.\nJuntá las plantas de tus pies y colocálos a unos 15 a 20 centímetros frente a tus caderas.\nApoyá una mano en el suelo a tu lado y la otra detrás de tu cabeza.\nLlevá tu codo hacia el techo mientras inclinás el torso hacia el otro lado; mantené esta posición de 10 a 20 segundos y luego cambiá de lado.' WHERE name_en = 'Seated Overhead Stretch';
UPDATE public.exercises SET instructions_es = 'Sujetá la barra con ambas manos, palmas hacia arriba, separadas a la anchura de los hombros.\nColocá los pies planos en el suelo, ligeramente más separados que la anchura de los hombros.\nIncliná el torso hacia adelante y apoyá los antebrazos sobre los muslos, palmas hacia arriba. Asegurate de que la parte frontal de las muñecas descansen sobre las rodillas. Esta es tu posición inicial.\nBajá la barra lo más posible mientras inhalás y mantenés un agarre firme.\nAhora, flexioná los antebrazos para subir la barra lo más alto posible mientras exhalás. Mantené la contracción arriba durante un segundo. Recordá: solo deben moverse las muñecas.' WHERE name_en = 'Seated Palm-Up Barbell Wrist Curl';
UPDATE public.exercises SET instructions_es = 'Sujetá la barra con ambas manos, palmas hacia abajo, separadas a la anchura de los hombros.\nColocá los pies planos en el suelo, ligeramente más separados que la anchura de los hombros.\nIncliná el torso hacia adelante y apoyá los antebrazos sobre los muslos, palmas hacia abajo. Asegurate de que la parte posterior de las muñecas descansen sobre las rodillas. Esta es tu posición inicial.\nBajá la barra lo más posible mientras inhalás y mantenés un agarre firme.\nAhora, flexioná los antebrazos para subir la barra lo más alto posible mientras exhalás. Mantené la contracción arriba durante un segundo. Recordá: solo deben moverse las muñecas.' WHERE name_en = 'Seated Palms-Down Barbell Wrist Curl';
UPDATE public.exercises SET instructions_es = 'Elegí un par de mancuernas y sentate al final de un banco plano con los pies firmes en el suelo.\nSujetá las mancuernas con las palmas hacia adentro y los brazos rectos hacia abajo a los costados, a la altura de los brazos. Esta será tu posición inicial.\nMientras mantenés el torso inmóvil (sin balancearte), levantá las mancuernas hacia los costados con una leve flexión en el codo y las manos ligeramente inclinadas hacia adelante, como si estuvieras vertiendo agua en un vaso.\nSeguí subiendo hasta que tus brazos queden paralelos al suelo. Exhalá mientras realizás este movimiento y hacé una pausa de un segundo en la parte superior.\nBajá las mancuernas lentamente hasta la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Seated Side Lateral Raise';
UPDATE public.exercises SET instructions_es = 'Sentate en un banco con respaldo y sujetá una mancuerna con ambas manos, sosteniéndola sobre la cabeza a la altura de los brazos.\nConsejo: una mejor forma es que alguien te la pase, especialmente si es muy pesada. La resistencia debe descansar en las palmas de tus manos con los pulgares alrededor. La palma de la mano debe estar mirando hacia adentro. Esta será tu posición inicial.\nManteniendo los brazos superiores cerca de la cabeza (codos hacia adentro) y perpendiculares al suelo, bajá la resistencia en un movimiento semicircular detrás de la cabeza hasta que tus antebrazos toquen tus bíceps.\nConsejo: Los brazos superiores deben permanecer inmóviles y solo los antebrazos deben moverse. Inhalá mientras realizás este paso.\nVolvé a la posición inicial usando los tríceps para levantar la mancuerna. Exhalá mientras realizás este paso.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Seated Triceps Press';
UPDATE public.exercises SET instructions_es = 'Fijá una sola manija en un cable bajo.\nElegí el peso correcto y parate a un par de pies de distancia con una postura de zancada amplia. Tu brazo debe estar extendido y el hombro hacia adelante. Esta será tu posición inicial.\nRealizá el movimiento retrayendo el hombro y flexionando el codo. Mientras tirás, supiná la muñeca, girando la palma hacia arriba a medida que avanzás.\nDespués de una breve pausa, volvé a la posición inicial.' WHERE name_en = 'Shotgun Row';
UPDATE public.exercises SET instructions_es = 'Con los hombros relajados y los brazos descansando sueltos a los costados (o en el regazo si estás sentado), girá suavemente los hombros hacia adelante, hacia arriba, hacia atrás y hacia abajo.\nInvertí la dirección. Podés hacer este ejercicio alternando los hombros o moviendo ambos al mismo tiempo.' WHERE name_en = 'Shoulder Circles';
UPDATE public.exercises SET instructions_es = 'Pará sobre una banda de ejercicio para que la tensión comience a la altura de los brazos.\nAgarrá las manijas y levantá las manos hasta la altura de los hombros a cada lado.\nGirá las muñecas para que las palmas de las manos miren hacia adelante.\nMantené los codos flexionados, con los brazos superiores y antebrazos alineados con el torso. Esta es tu posición inicial.\nAl exhalar, levantá las manijas hasta que los brazos estén completamente extendidos sobre la cabeza.' WHERE name_en = 'Shoulder Press - With Bands';
UPDATE public.exercises SET instructions_es = 'Relajá los brazos a los costados.\nLevantá los hombros hacia las orejas y luego bajalos.' WHERE name_en = 'Shoulder Raise';
UPDATE public.exercises SET instructions_es = 'Extendé tu brazo izquierdo a través del cuerpo\nMantenelo estirado' WHERE name_en = 'Shoulder Stretch';
UPDATE public.exercises SET instructions_es = 'Recostá sobre tu lado izquierdo\nDobla tu rodilla izquierda hacia adelante para estabilizar el torso\nUsá tus músculos abdominales para mantenerte erguido\nEstirá tu pierna derecha y apoyá el pie en el suelo detrás de la izquierda\nExtendé tu brazo derecho por encima de la cabeza\nJalá suavemente tu muñeca derecha para estirar todo el lado derecho del cuerpo\nCambialo de lado' WHERE name_en = 'Side-Lying Floor Stretch';
UPDATE public.exercises SET instructions_es = '1\n' WHERE name_en = 'Side Bridge';
UPDATE public.exercises SET instructions_es = 'Parate al lado de un cono o valla\nIniciá este ejercicio saltando lateralmente sobre el obstáculo, rebotando desde el aterrizaje para volver a saltar hacia donde empezaste\nSaltá la cantidad de repeticiones indicada lo más rápido posible y terminá el ejercicio corriendo a máxima velocidad una corta distancia tras el último salto' WHERE name_en = 'Side Hop-Sprint';
UPDATE public.exercises SET instructions_es = 'Pará con una mancuerna en cada mano a los costados de tu cuerpo.\nMantené los codos ligeramente flexionados y elevá los pesos directamente frente a ti hasta la altura de los hombros, evitando balancearte.\nEn la parte superior, llevá los pesos hacia adelante manteniendo los brazos extendidos.\nBajá los pesos con un movimiento controlado.\nEn la siguiente repetición, elevá los pesos frente a ti hasta la altura de los hombros antes de moverlos lateralmente hacia los costados.\nBajá los pesos a la posición inicial.' WHERE name_en = 'Side Laterals to Front Raise';
UPDATE public.exercises SET instructions_es = 'Pará al lado de una silla, a la que podés agarrarte como apoyo, y quedá de pie sobre una sola pierna.\nMantené la pierna recta, elevala lo más lejos posible hacia el costado y bajala permitiendo que cruce la pierna opuesta.\nRepetí este movimiento de balanceo de 5 a 10 veces, aumentando el rango de movimiento a medida que avanzás.' WHERE name_en = 'Side Leg Raises';
UPDATE public.exercises SET instructions_es = 'Recostate sobre tu lado derecho y doblá tu rodilla derecha hacia adelante para estabilizar el torso.\nApoyá tu cabeza en tu mano derecha o en tu hombro. Levantá tu pierna izquierda hacia arriba y sostenela por la parte trasera de la rodilla (más fácil) o por el pie (más difícil).\nJalá tu rodilla izquierda hacia tu hombro izquierdo y al mismo tiempo presioná tu pie o rodilla hacia el suelo. Para intensificar este estiramiento, estirá tu pierna izquierda. Cambiá de lado.' WHERE name_en = 'Side Lying Groin Stretch';
UPDATE public.exercises SET instructions_es = 'Empezá con los hombros relajados y incliná suavemente tu cabeza hacia tu hombro.\nAsistí el estiramiento con un jalón suave en el lado de la cabeza.' WHERE name_en = 'Side Neck Stretch';
UPDATE public.exercises SET instructions_es = 'Pará con los pies separados al ancho de caderas en una postura atlética.\nMantené la cabeza y el pecho arriba, con las rodillas y caderas ligeramente flexionadas.\nIncliná el cuerpo hacia la derecha y extendé caderas, rodillas y tobillos para saltar al aire.\nUsá los brazos para bloquear y guiar el movimiento, saltando lo más lejos posible hacia la derecha.\nAterrizá mirando en la misma dirección, con los pies al ancho de caderas, absorbiendo el impacto con las piernas.' WHERE name_en = 'Side Standing Long Jump';
UPDATE public.exercises SET instructions_es = 'Agarrá la barra de dominadas con las palmas hacia adelante usando un agarre ancho.\nCon los brazos extendidos sosteniendo la barra, incliná el torso hacia atrás unos 30 grados, curvando la zona lumbar y sacando el pecho.\nSubí el torso inclinándolo hacia el lado izquierdo hasta que la barra casi toque el pecho superior, bajando hombros y brazos superiores.\nExhalá mientras realizás este movimiento y concentrá en apretar los músculos de la espalda al llegar a la posición máxima.\nMantené el torso superior estable sin balancearte; solo los brazos deben moverse y los antebrazos solo sostener la barra.\nMantené la contracción un segundo e inhalá mientras volvé a la posición inicial.\nSubí el torso inclinándolo hacia el lado derecho hasta que la barra casi toque el pecho superior, bajando hombros y brazos superiores.\nExhalá mientras realizás este movimiento y concentrá en apretar los músculos de la espalda al llegar a la posición máxima.\nMantené el torso superior estable sin balancearte; solo los brazos deben moverse y los antebrazos solo sostener la barra.\nMantené la contracción un segundo e inhalá mientras volvé a la posición inicial.\nRepetí los pasos anteriores hasta completar las repeticiones prescritas para cada lado.' WHERE name_en = 'Side To Side Chins';
UPDATE public.exercises SET instructions_es = 'Pará de pie y cruzá tu brazo izquierdo por el centro de tu cuerpo.\nAgarrá tu muñeca izquierda con la mano derecha a la altura de las caderas, manteniendo el codo izquierdo doblado.\nExtendé, tirá y levantá el brazo hasta la altura de los hombros.\nSentí el estiramiento en la espalda, no en los hombros, y no tires demasiado de la articulación.\nCambiá de lado.' WHERE name_en = 'Side Wrist Pull';
UPDATE public.exercises SET instructions_es = 'Pará a un lado de la caja con el pie izquierdo apoyado en el centro.\nSaltá hacia el otro lado, aterrizando con el pie derecho sobre la caja y el izquierdo en el suelo.\nBalanseá los brazos para ayudar en el movimiento.\nSeguí moviéndote de un lado a otro sobre la caja.' WHERE name_en = 'Side to Side Box Shuffle';
UPDATE public.exercises SET instructions_es = 'Mové las poleas a la posición alta, elegí la resistencia y tomá una manija en cada mano.\nDá un paso adelante frente a ambas poleas con los brazos extendidos hacia adelante, juntando las manos. Mantené la cabeza y el pecho arriba mientras te inclinás hacia adelante, con los pies en posición escalonada. Esta será tu posición inicial.\nMantené el brazo izquierdo en su lugar y dejá que el brazo derecho se extienda hacia el lado, manteniendo una leve flexión en el codo. El brazo derecho debe ser perpendicular al cuerpo a la altura aproximada de los hombros.\nVolvé el brazo a la posición inicial llevando la mano de vuelta a la línea media del cuerpo.\nMantené la posición inicial por un segundo y repetí el movimiento en el lado opuesto. Continúa alternando para completar las repeticiones indicadas.' WHERE name_en = 'Single-Arm Cable Crossover';
UPDATE public.exercises SET instructions_es = 'Colocá una barra en un landmine o anclala firmemente en una esquina. Cargá la barra con un peso adecuado.\nLevantá la barra del suelo hasta los hombros con una o ambas manos. Adoptá una postura amplia. Esta será tu posición inicial.\nRealizá el movimiento extendiendo el codo y empujando el peso hacia arriba. Movete de forma explosiva, extendiendo caderas y rodillas por completo para generar la máxima fuerza.\nVolvé a la posición inicial.' WHERE name_en = 'Single-Arm Linear Jammer';
UPDATE public.exercises SET instructions_es = 'Recostá boca abajo en el suelo.\nMovete a una posición donde apoyes tu peso en las puntas de los pies y un brazo.\nColocá el brazo de trabajo directamente debajo del hombro, completamente extendido.\nExtendé las piernas y separá los pies más de lo habitual para tener una base más amplia.\nMantené una buena postura y colocá la mano libre detrás de la espalda.\nBajate flexionando el codo hasta tocar el suelo.\nDescendé lentamente y extendé el brazo para volver a la posición inicial.' WHERE name_en = 'Single-Arm Push-Up';
UPDATE public.exercises SET instructions_es = 'Pará al lado del cono con un brazo atrás y el otro adelante.\nMovié los pies lo más rápido posible, bloqueando con los brazos.\nDad la vuelta al cono manteniendo las rodillas arriba y con una acción de pies violenta.\nDescansá después de tres vueltas al cono.' WHERE name_en = 'Single-Cone Sprint Drill';
UPDATE public.exercises SET instructions_es = 'Colocá una caja en un rack y asegurá una banda o cuerda arriba de la caja.\nPará enfrente y subí a la caja hasta quedar de pie, dejando la otra pierna sin apoyo.\nAgarrá la banda para mantener el equilibrio.\nSeguí subiendo y bajando con la misma pierna antes de cambiar al otro lado.' WHERE name_en = 'Single-Leg High Box Squat';
UPDATE public.exercises SET instructions_es = 'Alineá una fila de conos frente a vos y pará relajado/a sobre una sola pierna.\nLevantá la rodilla de la pierna opuesta para tomar la posición inicial.\nSaltá hacia adelante y aterrizá con la misma pierna sobre el cono.\nUsá un salto con contramovimiento para saltar de cono en cono.\nAl final, girá y volvé usando la otra pierna.' WHERE name_en = 'Single-Leg Hop Progression';
UPDATE public.exercises SET instructions_es = 'Pará al lado de un cono o valla.\nPara la posición inicial, pará sobre una pierna con la rodilla ligeramente flexionada.\nComenzá ejecutando un salto contrarresto para saltar lateralmente sobre el cono.\nAterrizá sobre la pierna de salto y rebotá inmediatamente de vuelta a la posición inicial.\nSeguí saltando de un lado a otro.' WHERE name_en = 'Single-Leg Lateral Hop';
UPDATE public.exercises SET instructions_es = 'Sentate en la máquina y ajustala para que estés bien posicionado.\nEl cojín debe estar contra la parte inferior de la espinilla, pero sin tocar el tobillo.\nAjustá el asiento para que el punto de pivote quede alineado con tu rodilla.\nElegí un peso adecuado a tus capacidades.\nMantené una buena postura y extendé completamente una pierna, haciendo una pausa en la parte superior del movimiento.\nVolvé a la posición inicial sin dejar que el peso se detenga, manteniendo la tensión en el músculo.\nRepetí el movimiento la cantidad de veces deseadas.' WHERE name_en = 'Single-Leg Leg Extension';
UPDATE public.exercises SET instructions_es = 'Pará al lado de una caja con el pie interno sobre ella, cerca del borde.\nComenzá balanceando los brazos hacia arriba mientras empujás a través de la pierna superior, saltando hacia arriba lo más alto posible. Intentá llevar la rodilla opuesta hacia arriba.\nAterrizá en la misma posición en la que empezaste, usando la pierna interna para desacelerar el impacto.' WHERE name_en = 'Single-Leg Stride Jump';
UPDATE public.exercises SET instructions_es = 'Con una postura amplia, sostené una mancuerna con ambas manos, agarrando la cabeza de la mancuerna en lugar del mango. Tus brazos deben estar extendidos y colgando a la altura de la cintura. Esta será tu posición inicial.\nLevantá el peso hasta que esté por encima del nivel de los hombros, manteniendo los brazos extendidos. Tu torso y caderas deben permanecer estacionarios durante todo el movimiento.\nVolvé a la posición inicial y repetí por la cantidad de repeticiones recomendadas.' WHERE name_en = 'Single Dumbbell Raise';
UPDATE public.exercises SET instructions_es = 'Pará sobre una pierna, con la rodilla flexionada y elevada. Esta será tu posición inicial.\nUsá un salto con contramovimiento, despegá hacia arriba extendiendo la cadera, la rodilla y el tobillo de la pierna apoyada.\nInmediatamente flexioná la rodilla y intentá tocar tu glúteo con el talón de la pierna que salta.\nVolvé la pierna a una posición parcialmente flexionada debajo de las caderas y aterrizá. Tu pierna opuesta debe mantenerse en una posición relativamente igual durante todo el ejercicio.' WHERE name_en = 'Single Leg Butt Kick';
UPDATE public.exercises SET instructions_es = 'Recostá en el suelo con los pies planos y las rodillas flexionadas.\nLevantá una pierna del suelo, llevando la rodilla hacia el pecho. Esta será tu posición inicial.\nEjecutá el movimiento empujando a través del talón, extendiendo la cadera hacia arriba y levantando los glúteos del suelo.\nExtendé lo más posible, mantené la posición y volvé a la posición inicial.' WHERE name_en = 'Single Leg Glute Bridge';
UPDATE public.exercises SET instructions_es = 'Pará en el suelo con un pie apoyado en la caja, con el talón cerca del borde.\nEmpujá con el pie que está sobre la caja, intentando ganar la mayor altura posible extendiendo la cadera y la rodilla.\nAterrizá con el mismo pie sobre la caja y volvé a colocar el otro pie en la posición inicial.' WHERE name_en = 'Single Leg Push-off';
UPDATE public.exercises SET instructions_es = 'Recostá en el suelo con los pies bajo algo que no se mueva o con un compañero que los sostenga. Mantené las piernas flexionadas en las rodillas.\nColocá las manos detrás de la cabeza y entrelazá los dedos. Esta es la posición inicial.\nElevá el torso para formar una V imaginaria con los muslos. Exhalá al realizar esta parte del ejercicio.\nSentí la contracción por un segundo y bajá el torso de vuelta a la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Sit-Up';
UPDATE public.exercises SET instructions_es = 'Pará con los pies separados a la anchura de los hombros. Esta será tu posición inicial.\nIniciá el movimiento flexionando las rodillas y las caderas, sentándote hacia atrás con las caderas.\nContinuá hasta que hayas agachado una parte del camino hacia abajo, pero por encima de la paralela, y revertí rápidamente el movimiento hasta que regreses a la posición inicial. Repetí de 5 a 10 repeticiones.' WHERE name_en = 'Sit Squats';
UPDATE public.exercises SET instructions_es = 'El patinaje sobre ruedas es una actividad divertida que puede ser efectiva para mejorar la aptitud cardiorrespiratoria y la resistencia muscular. Requiere un equilibrio y coordinación relativamente buenos. Es necesario aprender las bases del patinaje, incluyendo girar y detenerse, y usar equipo de protección para evitar posibles lesiones.\nPodés patinar a un ritmo cómodo durante 30 minutos seguidos. Si querés un desafío cardiovascular, hacé patinaje intervalado: patiná rápido dos minutos de cada cinco minutos, usando los tres minutos restantes para recuperarte. Una persona de 150 libras quemará típicamente alrededor de 175 calorías en 30 minutos patinando a un ritmo cómodo, similar a caminar a paso ligero.' WHERE name_en = 'Skating';
UPDATE public.exercises SET instructions_es = 'Cargá el trineo con el peso deseado y conectá la correa de tracción.\nPodés tirar con las manijas, usar un arnés o conectar la correa a un cinturón de peso.\nIncliná el cuerpo en la dirección del movimiento y avanzá extendiendo las caderas y las rodillas.' WHERE name_en = 'Sled Drag - Harness';
UPDATE public.exercises SET instructions_es = 'Conectá las manijas dobles a un trineo unido por una cuerda o cadena y cargalo con un peso ligero.\nMirá al trineo y retrocedé hasta que la línea tenga algo de tensión.\nMantené las manos directamente sobre la cabeza con los codos extendidos; esta será tu posición inicial.\nCaminá hacia atrás manteniendo los brazos levantados sobre la cabeza y evitá movimientos bruscos.' WHERE name_en = 'Sled Overhead Backward Walk';
UPDATE public.exercises SET instructions_es = 'Fijá las manijas dobles al trineo usando una cadena o cuerda y cargalo con el peso adecuado.\nColocate de espaldas al trineo y alejate hasta que la línea quede tensa.\nLevantá las manos por encima de la cabeza, manteniéndolas juntas con las palmas mirándose y los codos flexionados apuntando hacia arriba.\nExtendé los codos para enderezar los brazos, asegurándote de que los brazos superiores no se muevan para aislar los tríceps.\nAl alcanzar la extensión completa, avanzá un paso para quitar la holgura de la línea, manteniendo los pies escalonados si necesitás más estabilidad.' WHERE name_en = 'Sled Overhead Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Cargá el trineo de empuje con el peso deseado.\nAdoptá una postura atlética, inclinándote sobre el trineo con los brazos completamente extendidos sujetando las manijas.\nEmpujá el trineo lo más rápido posible, enfocándote en extender las caderas y las rodillas para fortalecer la cadena posterior.' WHERE name_en = 'Sled Push';
UPDATE public.exercises SET instructions_es = 'Fijá los manillares dobles en un trineo conectado por una cuerda o cadena y cargalo con un peso ligero.\nMirá el trineo y retrocedé hasta que la línea tenga algo de tensión.\nTomá ambos manillares a la altura de la cintura, con los brazos extendidos.\nDobiná las rodillas ligeramente y mantené el pecho y la cabeza arriba.\nSin doblar los codos, empujá los manillares hacia arriba y hacia afuera, realizando un vuelo inverso con algo de rotación externa.\nMantené las palmas de las manos mirando hacia adelante mientras hacés esto.\nVolvé a la posición inicial, dando un par de pasos hacia atrás para quitarle la holgura a la línea.' WHERE name_en = 'Sled Reverse Flye';
UPDATE public.exercises SET instructions_es = 'Fijá los manillares dobles en un trineo conectado por una cuerda o cadena y cargalo con un peso adecuado.\nMirá el trineo y retrocedé hasta que la línea tenga algo de tensión.\nTomá un manillar en cada mano, doblá las rodillas ligeramente y mantené la cabeza y el pecho arriba, con los brazos extendidos.\nPara iniciar el movimiento, doblá los codos mientras retraés las escápulas, jalando el trineo hacia vos.\nDá un o dos pasos hacia atrás para recuperar la tensión en la línea y repetí.' WHERE name_en = 'Sled Row';
UPDATE public.exercises SET instructions_es = 'Necesitás una llanta y un martillo de guerra para este ejercicio.\nPará frente a la llanta a unos dos pies de distancia con una postura escalonada.\nAgarrá el martillo de guerra.\nSi sos diestro, tu mano izquierda debe estar en la parte inferior del mango y tu mano derecha más cerca de la cabeza.\nAl levantar el martillo, tu mano derecha se desliza hacia la cabeza; al golpear hacia abajo, tu mano derecha se desliza hacia abajo para unirse a tu mano izquierda.\nGolpeá con toda tu fuerza contra la llanta.\nControlá el rebote del martillo sobre la llanta.\nRepetí en el otro lado.' WHERE name_en = 'Sledgehammer Swings';
UPDATE public.exercises SET instructions_es = 'Colocá un banco inclinado debajo de la máquina Smith.\nAjustá la barra a una altura que puedas alcanzar al estar acostado con los brazos casi completamente extendidos.\nUna vez que hayas seleccionado el peso necesario, recostate en el banco inclinado y asegurate de que tus hombros estén alineados justo debajo de la barra.\nUsando un agarre prono (palmas hacia adelante) con la anchura de los hombros, levantá la barra del soporte y mantenela recta sobre vos con una leve flexión en los codos.\nEsta será tu posición inicial.\nAl exhalar, levantá la barra hasta que tus brazos estén completamente extendidos.\nNota: La contracción debe sentirse alrededor de los hombros.\nDespués de una pausa de un segundo, bajá la barra a la posición inicial mientras inhalás.\nRepetí el movimiento por la cantidad de repeticiones prescritas.\nCuando termines, colocá la barra de vuelta en el soporte.' WHERE name_en = 'Smith Incline Shoulder Raise';
UPDATE public.exercises SET instructions_es = 'Colocá la barra a la altura de los muslos y cargá un peso adecuado.\nParate con la barra detrás de vos, tomala con una agarre prono a la anchura de los hombros y desenganchar el peso. Tenés que estar de pie, recto, con la cabeza y el pecho arriba y los brazos extendidos. Esta es tu posición inicial.\nIniciá el movimiento encogiendo los hombros hacia arriba. No flexiones los brazos ni las muñecas durante el movimiento.\nDespués de una breve pausa, devolvé el peso a la posición inicial.\nRepetí el movimiento la cantidad de veces deseadas antes de enganchar los seguros para estibar el peso.' WHERE name_en = 'Smith Machine Behind the Back Shrug';
UPDATE public.exercises SET instructions_es = 'Colocá un banco plano debajo de la máquina Smith. Ahora ajustá la barra a una altura que puedas alcanzar al acostarte con los brazos casi completamente extendidos. Una vez que hayas elegido el peso necesario, acostate en el banco plano. Usá un agarre prono más ancho que los hombros, desbloqueá la barra del soporte y sostenela recta sobre vos con los brazos bloqueados. Esta es tu posición inicial.\nMientras inhalás, bajá lentamente hasta sentir la barra en el centro del pecho.\nDespués de una pausa de un segundo, llevá la barra de vuelta a la posición inicial mientras exhalás y empujás la barra usando los músculos del pecho. Bloqueá los brazos en la posición contraída, mantené por un segundo y luego empezá a bajar lentamente de nuevo. Consejo: debería tomar al menos el doble de tiempo bajar que subir.\nRepetí el movimiento la cantidad de repeticiones prescritas.\nCuando termines, bloqueá la barra de vuelta en el soporte.' WHERE name_en = 'Smith Machine Bench Press';
UPDATE public.exercises SET instructions_es = 'Ajustá la barra de la máquina Smith a una altura aproximadamente 5 cm por debajo de las rodillas.\nDoblá ligeramente las rodillas y llevá el torso hacia adelante flexionando la cintura, manteniendo la espalda recta hasta que quede casi paralela al suelo. Tip: Asegurate de mantener la cabeza arriba.\nAgarrá la barra con un agarre prono (palmas hacia abajo) y desbloqueala del soporte de la máquina Smith. Dejá que cuelgue directamente frente a vos, con los brazos extendidos perpendiculares al suelo y al torso. Esta es tu posición inicial.\nMientras mantenés el torso inmóvil, levantá la barra mientras exhalás, manteniendo los codos pegados al cuerpo y sin hacer fuerza con los antebrazos más que sostener los pesos. En la posición superior contraída, apretá los músculos de la espalda y mantené la posición por un segundo.\nBajá el peso lentamente de vuelta a la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Smith Machine Bent Over Row';
UPDATE public.exercises SET instructions_es = 'Colocá un bloque o disco de peso debajo de la barra en la máquina Smith. Ajustá la barra a la posición que mejor se adapte a tu altura. Una vez elegida la altura correcta y cargada la barra, subite a los discos con las puntas de los pies y apoyá la barra en la parte trasera de los hombros.\nTomá la barra con ambas manos mirando hacia adelante. Girá la barra para desbloquearla. Esta será tu posición inicial.\nLevantá los talones lo más alto posible empujando con las puntas de los pies, flexionando el gemelo en la parte superior de la contracción. Las rodillas deben permanecer extendidas. Mantené la posición contraída por un segundo antes de empezar a bajar.\nVolvé lentamente a la posición inicial mientras inhalás, bajando los talones.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Smith Machine Calf Raise';
UPDATE public.exercises SET instructions_es = 'Colocá un banco plano debajo de la máquina Smith.\nAjustá la barra a una altura donde puedas alcanzarla con los brazos casi extendidos mientras estás acostado.\nRecostá en el banco plano una vez que hayas seleccionado el peso deseado.\nAgarrá la barra con un agarre cerrado y prono (palmas hacia adelante) a la anchura de los hombros.\nDesbloqueá la barra del soporte y mantenela recta sobre tu cabeza con los brazos extendidos.\nInspirá y bajá la barra lentamente hasta que sientas el contacto en el pecho medio.\nMantené los codos pegados al torso en todo momento para maximizar el trabajo de los tríceps.\nHacé una pausa de un segundo y empujá la barra de vuelta a la posición inicial mientras exhalás usando los tríceps.\nBloqueá los brazos en la posición contraída, mantené un segundo y bajá lentamente de nuevo.\nAsegurate de que el descenso tome al menos el doble de tiempo que el ascenso.\nRepetí el movimiento la cantidad de repeticiones prescritas.\nAl terminar, bloqueá la barra de vuelta en el soporte.' WHERE name_en = 'Smith Machine Close-Grip Bench Press';
UPDATE public.exercises SET instructions_es = 'Posicioná un banco declinado en la jaula para que la barra quede sobre tu pecho.\nCargá un peso adecuado y tomá tu lugar en el banco.\nGirá la barra para desengancharla del soporte y extendé completamente los brazos.\nMantené la espalda ligeramente arqueada y las escápulas retraídas como posición inicial.\nIniciá el movimiento flexionando los brazos y bajando la barra hacia el pecho.\nHacé una breve pausa y luego empujá el peso extendiendo los brazos de vuelta a la posición inicial.\nAl completar las repeticiones deseadas, girá la barra para apoyarla en el soporte.' WHERE name_en = 'Smith Machine Decline Press';
UPDATE public.exercises SET instructions_es = 'Colocá la barra a la altura de las rodillas y cargala con un peso adecuado.\nTomá la barra con agarre prono, más ancho que los hombros, y desenganchala de la máquina. Mantené los brazos completamente extendidos, con la cabeza y el pecho arriba. Apuntá los codos hacia afuera, con los hombros hacia atrás y abajo. Retraé las caderas para cargar la tensión en los isquiotibiales. Esta será tu posición inicial.\nIniciá el movimiento extendiendo con fuerza las caderas y las rodillas, acelerando hacia la barra. Asegurate de mantener los brazos rectos durante esta parte del movimiento.\nAl alcanzar la extensión completa, doblá nuevamente las caderas y las rodillas para bajar a tu posición de recepción.\nPermití que los brazos se flexionen en este punto, rotando los codos alrededor de la barra para recibirla sobre tus hombros.\nExtendé las caderas y las rodillas para llegar a una posición de pie con la barra apoyada en tus hombros y completar el movimiento.' WHERE name_en = 'Smith Machine Hang Power Clean';
UPDATE public.exercises SET instructions_es = 'Colocá un banco en la jaula y cargá la barra con un peso adecuado. Recostate en el banco, colocando la parte inferior de tus pies contra la barra. Desbloqueá la barra y extendé las piernas. Podés usar las manos para ayudarte. Para mayor estabilidad, agarrá los laterales de la máquina Smith. Esta será tu posición inicial.\nIniciá el movimiento rotando la pelvis y flexionando la columna para elevar las caderas del banco. Mantené una leve flexión en las rodillas durante todo el movimiento.\nDespués de una breve pausa, bajá las caderas de vuelta al banco.\nRepetí el ejercicio la cantidad de veces deseadas.' WHERE name_en = 'Smith Machine Hip Raise';
UPDATE public.exercises SET instructions_es = 'Colocá un banco inclinado debajo de la máquina Smith.\nAjustá la barra a una altura donde puedas alcanzarla al estar acostado con los brazos casi completamente extendidos.\nRecostá en el banco inclinado y asegurá de que tu pecho superior esté alineado con la barra.\nUsá un agarre prono (palmas hacia adelante) más ancho que el ancho de tus hombros.\nDesbloqueá la barra del soporte y mantenela recta sobre vos con los brazos bloqueados.\nInspirá y bajá la barra lentamente hasta sentirla en tu pecho superior.\nHacé una pausa de un segundo y volvé a la posición inicial exhalando, empujando la barra con los músculos del pecho.\nBloqueá los brazos en la posición contraída, mantené un segundo y bajá lentamente de nuevo.\nRepetí el movimiento la cantidad de repeticiones indicadas.\nCuando termines, colocá la barra de vuelta en el soporte.' WHERE name_en = 'Smith Machine Incline Bench Press';
UPDATE public.exercises SET instructions_es = 'Posicioná la barra de la máquina Smith a un par de pies del suelo.\nAsegurate de que esté apoyada en las protecciones de seguridad.\nCargá la barra con el peso adecuado y recostate debajo de ella.\nColocá la parte media de tus pies sobre la barra, juntando las rodillas contra el pecho.\nEmpujá a través de tus pies para mover la barra hacia arriba, extendiendo las caderas y las rodillas.\nNo bloquees las rodillas por completo.\nEn la parte superior del movimiento, hacé una breve pausa antes de volver a la posición inicial.' WHERE name_en = 'Smith Machine Leg Press';
UPDATE public.exercises SET instructions_es = 'Colocá la barra a la altura de los muslos y cargá un peso adecuado.\nAgarrá la barra con una toma amplia y desenganchá el peso, quitando tu mano libre de la barra. Extendé el brazo mientras te parás derecho, con la cabeza y el pecho arriba. Esta será tu posición inicial.\nIniciá el movimiento flexionando el codo y levantando el brazo superior con el codo apuntando hacia afuera. Continuá hasta que tu brazo superior quede paralelo al suelo.\nDespués de una breve pausa, devolvé el peso a la posición inicial.\nRepetí la cantidad de repeticiones deseadas antes de enganchar los ganchos para estibar el peso.' WHERE name_en = 'Smith Machine One-Arm Upright Row';
UPDATE public.exercises SET instructions_es = 'Para empezar, colocá un banco plano (o preferiblemente uno con respaldo) debajo de una máquina Smith. Ajustá la altura de la barra para que, al sentarte en el banco, debas extender casi por completo los brazos para alcanzarla.\nUna vez que tengas la altura correcta, sentate ligeramente detrás de la barra de modo que haya una línea imaginaria recta desde la punta de tu nariz hasta la barra. Mantené los pies fijos. Agarrá la barra con las palmas hacia adelante, desbloqueala y levantala hasta que tus brazos queden completamente extendidos. Esta es la posición inicial.\nComenzá a bajar la barra lentamente hasta que quede a la altura de tu barbilla mientras inhalás.\nLuego, levantá la barra de vuelta a la posición inicial usando los hombros mientras exhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Smith Machine Overhead Shoulder Press';
UPDATE public.exercises SET instructions_es = 'Ajustá la barra a la altura que mejor se adapte a tu estatura.\nColocá la barra sobre la parte trasera de tus hombros.\nTomá la barra con las palmas hacia adelante, desbloqueala y levantala extendiendo las piernas.\nMové un pie hacia adelante, unos 30 cm frente a la barra, y extendé la otra pierna hacia adelante manteniéndola en el aire.\nMirá siempre al frente y mantené la columna neutra o ligeramente arqueada.\nBajate flexionando la rodilla y la cadera hasta donde te permita la flexibilidad.\nHacé una breve pausa abajo y volvé a la posición inicial empujando con el talón, extendiendo la rodilla y la cadera.' WHERE name_en = 'Smith Machine Pistol Squat';
UPDATE public.exercises SET instructions_es = 'Ajustá la barra en la máquina Smith a tu altura y alineá una plataforma elevada justo debajo de la barra.\nPará sobre la plataforma asegurando los talones en la parte superior y dejando que las puntas de los pies se extiendan más allá del borde.\nMantené los pies hacia adelante con una separación a la anchura de los hombros.\nColocá los hombros bajo la barra y empujala hacia arriba extendiendo las caderas y las rodillas hasta que el torso quede erguido.\nMantené las rodillas con una leve flexión; nunca las bloquees.\nLevantá las puntas de los pies mientras exhalás, extendiendo los dedos lo más alto posible y flexionando el gemelo.\nMantené la rodilla quieta en todo momento, sin doblarla.\nMantené la posición contraída por un segundo antes de bajar.\nBajá lentamente a la posición inicial mientras inhalás, bajando las puntas de los pies y los dedos.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Smith Machine Reverse Calf Raises';
UPDATE public.exercises SET instructions_es = 'Ajustá la barra a la altura que mejor se adapte a tu estatura.\nColocá la parte trasera de tus hombros (ligeramente por debajo del cuello) sobre la barra.\nAgarrá la barra con ambas manos, palmas hacia adelante, desbloqueala y levantala empujando con las piernas mientras enderezás el torso.\nPosicioná las piernas en una postura media de ancho de hombros, con las puntas de los pies ligeramente hacia afuera.\nMantené la cabeza arriba y la espalda recta en todo momento.\nBajá la barra lentamente doblando las rodillas, manteniendo la postura recta y la cabeza arriba.\nContinuá bajando hasta que el ángulo entre el muslo y la pantorrilla sea ligeramente menor a 90 grados (muslos por debajo de la paralela al suelo).\nInhala mientras realizás esta parte del movimiento.\nEmpujá el suelo con el talón para enderezar las piernas y volver a la posición inicial mientras exhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Smith Machine Squat';
UPDATE public.exercises SET instructions_es = 'Ajustá la barra en la máquina Smith a una altura a la mitad de tus muslos.\nAgarrá la barra con un agarre prono (palmas hacia adelante) a la anchura de los hombros.\nLevantá la barra extendiendo completamente los brazos mientras mantenés la espalda recta.\nPará con el torso recto y las piernas a la anchura de los hombros o más juntas, con las rodillas ligeramente dobladas.\nMantené las rodillas estacionarias y bajá la barra por encima de los pies flexionando la cintura, manteniendo la espalda recta.\nIncliná el torso hacia adelante hasta sentir un estiramiento en los isquiotibiales mientras exhalás.\nEnderezá el torso extendiendo la cadera y la cintura para volver a la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Smith Machine Stiff-Legged Deadlift';
UPDATE public.exercises SET instructions_es = 'Colocá la barra en el suelo.\nParate en el medio de la barra en sentido longitudinal.\nIncliná el cuerpo doblando las rodillas y manteniendo la espalda recta, y agarrá el frente de la barra con la mano derecha en agarre neutro con la palma mirando hacia la izquierda.\nAgarrá el fondo de la barra con la mano izquierda en agarre neutro con la palma mirando hacia la derecha, asegurándote de que el agarre sea equidistante y el torso quede centrado.\nParate erguido con el peso, manteniendo los pies separados a la anchura de los hombros y las puntas de los pies ligeramente hacia afuera.\nAgachate doblando las rodillas y manteniendo la espalda recta hasta que los muslos queden paralelos al suelo, con la espalda lo más vertical posible, la cabeza arriba y sin que las rodillas pasen de las puntas de los pies, inhalando durante el descenso.\nEmpujá con los pies para volver a la posición inicial, manteniendo la barra colgando a la longitud de los brazos con los codos bloqueados y un ligero doblado, usando los brazos solo como ganchos y realizando el esfuerzo con los muslos.' WHERE name_en = 'Jefferson Squats';
UPDATE public.exercises SET instructions_es = 'Recostá la barra en posición de jerk, con los hombros hacia adelante, el torso erguido y los pies ligeramente separados.\nIniciá el movimiento como en un jerk normal, flexionando las rodillas manteniendo el torso vertical y empujando hacia arriba con fuerza usando el impulso, no los brazos.\nMantené el pie trasero en su lugar y usalo para empujar el cuerpo hacia adelante hasta lograr una apertura completa mientras realizás el jerk.\nRecuperate parándote con la barra sobre la cabeza.' WHERE name_en = 'Jerk Balance';
UPDATE public.exercises SET instructions_es = 'Pará de pie con los pies separados al ancho de las caderas.\nSujetá la kettlebell boca abajo por los cuernos, con la campana sobre tus manos y cerca del pecho.\nApretá los abdominales y las glúteos para mantener la caja torácica baja.\nMantené los codos cerca de la cabeza y llevá la kettlebell hacia arriba pasando una oreja y detrás de la cabeza.\nContinuá el círculo pasando la oreja opuesta y bajá de vuelta a la posición inicial frente al pecho, dejando que la campana pase cerca del cuerpo durante todo el recorrido.\nCompletá la cantidad de círculos indicados en una dirección y repetí la misma cantidad en la dirección opuesta.\nMovete lentamente y mantené la cabeza, las caderas y la zona lumbar quietas.\nSi la zona lumbar se arquea o la campana se aleja mucho de la cabeza, usá un peso más liviano.' WHERE name_en = 'Kettlebell Halo';
UPDATE public.exercises SET instructions_es = 'Pará de pie con los pies separados al ancho de las caderas.\nAgarrá la kettlebell boca abajo por los cuernos, con la campana sobre tus manos y cerca del pecho.\nApretá los abdominales y las glúteos para mantener la caja torácica baja.\nMantené los codos cerca de la cabeza.\nMové la kettlebell hacia arriba pasando por una oreja y rodeá hasta que quede detrás de la cabeza.\nHacé una pausa aquí.\nExtendé los codos para empujar la kettlebell hacia arriba y sobre la cabeza hasta que los brazos estén rectos, manteniendo los brazos superiores al lado de la cabeza.\nDoblá los codos para bajar la kettlebell de vuelta a la posición de pausa detrás de la cabeza, con control.\nContinuá el círculo pasando por la oreja opuesta y bajá de vuelta a la posición inicial frente al pecho para completar una repetición.\nAlterná la dirección del círculo en cada repetición.\nMantené la cabeza, las caderas y la zona lumbar quietas durante todo el ejercicio; si la zona lumbar se arquea o no podés llegar a la posición sobre la cabeza sin inclinar hacia atrás, usá un peso más ligero o realizá el halo y la extensión como ejercicios separados.' WHERE name_en = 'Kettlebell Halo with Overhead Extension';
UPDATE public.exercises SET instructions_es = 'Colocá un banco plano frente a una polea alta o máquina de jalón.\nAgarrá la barra recta con un agarre supino (palmas hacia arriba) a la anchura de los hombros.\nRecostá boca arriba con la cabeza sobre el extremo del banco.\nExtendé los brazos rectos sobre los hombros, formando un ángulo de 90 grados con el torso y manteniendo los codos flexionados hacia adentro.\nExhalá y jalá la barra hacia abajo en un movimiento semicircular hasta que toque tu barbilla.\nApretá los bíceps durante un segundo en la posición de contracción máxima.\nMové solo los antebrazos, manteniendo los brazos superiores perpendiculares y sin moverlos en ningún momento.\nVolvé lentamente a la posición inicial.\nRepetí el movimiento la cantidad de veces recomendada.' WHERE name_en = 'Lying Close-Grip Bar Curl On High Pulley';
UPDATE public.exercises SET instructions_es = 'Recostá boca arriba en un banco plano con la cabeza cerca del extremo, sosteniendo la barra con agarre prono (palmas hacia adelante) a la anchura de los hombros o en los agarres internos si usás barra EZ.\nExtendé los brazos frente a vos y llevá la barra hacia atrás en un movimiento semicircular hasta ubicarla sobre la cabeza, manteniendo los brazos extendidos y paralelos al suelo.\nInhalá y bajá la barra flexionando solo los codos, manteniendo los brazos superiores fijos, hasta que los antebrazos queden perpendiculares al suelo.\nExhalá y empujá la barra hacia arriba en un movimiento semicircular hasta que los antebrazos vuelvan a estar paralelos al suelo, contrayendo los tríceps con fuerza un segundo en la posición superior.\nRepetí el movimiento la cantidad de veces recomendadas.' WHERE name_en = 'Lying Close-Grip Barbell Triceps Extension Behind The Head';
UPDATE public.exercises SET instructions_es = 'Ajustá la palanca de la máquina a tu altura y recostate boca abajo con el cojín en la parte trasera de las piernas, justo por debajo de los gemelos.\nMantené el torso plano en el banco, asegurá que las piernas estén completamente estiradas y agarrá los mangos laterales de la máquina.\nPosicioná los pies rectos o en la postura que prefieras para la base.\nExhalá y doblá las piernas hacia arriba lo más que puedas sin levantar la parte superior de las piernas del cojín.\nMantené la posición contraída un segundo.\nInhalá y volvé las piernas a la posición inicial.\nRepetí el movimiento la cantidad de veces recomendada.' WHERE name_en = 'Lying Leg Curls';
UPDATE public.exercises SET instructions_es = 'Ajustá la máquina de piernas a una altura que te permita entrar con las rodillas flexionadas y los muslos ligeramente por debajo de la posición paralela.\nElegí el peso y colocate dentro de la máquina boca arriba, con las rodillas flexionadas y los muslos ligeramente por debajo de la plataforma.\nAsegurate de que las rodillas no pasen de las puntas de los pies.\nMantené el ángulo entre los isquiotibiales y los gemelos ligeramente menor a 90 grados.\nApoyá la espalda y la cabeza en la máquina mientras presionás los hombros contra las almohadillas.\nColocá las manos en los agarres y poné los pies apuntando ligeramente hacia afuera, a la anchura de los hombros.\nEmpujá con las puntas de los pies mientras exhalás, extendé todo el cuerpo y contraé los cuádriceps.\nMantené la posición contraída durante un segundo.\nBajá lentamente mientras inhalás, pero detenete cuando los muslos queden paralelos a la plataforma.\nMantené el ángulo entre los isquiotibiales y los gemelos a 90 grados.\nRepetí el movimiento la cantidad de veces recomendada.' WHERE name_en = 'Lying Machine Squat';
UPDATE public.exercises SET instructions_es = 'Recostá la parte posterior del torso contra el cojín de la máquina y enganchá los hombros bajo las almohadillas.\nColocá las piernas en la plataforma con una postura estrecha, menos que el ancho de hombros, con los pies apuntando ligeramente hacia afuera y separados unos 7,5 cm o menos.\nMantené la cabeza en alto y la espalda pegada al cojín en todo momento.\nApoyá los brazos en los mangos laterales y desenganchá las barras de seguridad moviendo los mangos de la posición frontal a la diagonal.\nEnderezá las piernas sin bloquear las rodillas para establecer la posición inicial.\nBajá la unidad lentamente flexionando las rodillas, manteniendo la postura recta y la cabeza en alto.\nContinuá bajando hasta que el ángulo entre el muslo y la pantorrilla sea ligeramente menor a 90 grados, con los muslos por debajo de la paralela al suelo.\nInspirá mientras realizás esta parte del movimiento.\nSubí la unidad exhalando, empujando el suelo principalmente con los talones.\nEnderezá las piernas para volver a la posición inicial.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Narrow Stance Hack Squats';
UPDATE public.exercises SET instructions_es = 'Sentate en la máquina de prensa de piernas y colocá tus pies en la plataforma con una postura más angosta que el ancho de los hombros, con las puntas ligeramente hacia afuera.\nMantené tus pies separados a no más de 7,5 centímetros.\nMantené la cabeza en alto y la espalda apoyada en el cojín en todo momento.\nBajá las barras de seguridad y empujá la plataforma hacia arriba hasta que tus piernas queden completamente extendidas.\nEvitá bloquear las rodillas y asegurá de que tu torso y piernas formen un ángulo de 90 grados.\nInhalá y bajá la plataforma lentamente hasta que tus muslos y pantorrillas formen un ángulo de 90 grados.\nExhalá y empujá principalmente con los talones, usando los cuádriceps, para volver a la posición inicial.\nRepetí el movimiento la cantidad de veces recomendada.\nBloqueá los pasadores de seguridad correctamente al terminar para evitar que la plataforma caiga sobre vos.' WHERE name_en = 'Narrow Stance Leg Press';
UPDATE public.exercises SET instructions_es = 'Recostate en un banco plano con una mancuerna en una mano sobre el muslo.\nUsá tu muslo para ayudarte a subir la mancuerna hasta que puedas sostenerla frente a vos a la anchura de los hombros.\nUsá la mano que no está levantando para ayudar a posicionar correctamente la mancuerna sobre vos.\nUna vez a la anchura de los hombros, girá la muñeca hacia adelante para que la palma de la mano mire hacia afuera.\nBajá los pesos lentamente hacia tu lado mientras inhalás.\nMantené el control total de la mancuerna en todo momento.\nExhalá y empujá las mancuernas hacia arriba usando los músculos pectorales.\nBloqueá los brazos en la posición contraída, apretá el pecho, mantené por un segundo y empezá a bajar lentamente.\nRepetí el movimiento por la cantidad de repeticiones prescritas en tu programa de entrenamiento.\nCambiate de brazo y repetí el movimiento.' WHERE name_en = 'One Arm Dumbbell Bench Press';
UPDATE public.exercises SET instructions_es = 'Agarrá una mancuerna con el brazo derecho y apoyá el brazo superior sobre el banco predicador o el banco inclinado.\nMantené la mancuerna a la altura de los hombros como posición inicial.\nMientras inhalás, bajá lentamente la mancuerna hasta extender el brazo superior y estirar completamente el bíceps.\nAl exhalar, usá el bíceps para subir el peso hasta contraerlo por completo y llevar la mancuerna a la altura de los hombros.\nRecordá llevar el dedo meñique más alto que el pulgar para asegurar la contracción total.\nApretá fuerte el bíceps durante un segundo en la posición contraída y repetí el movimiento la cantidad de repeticiones recomendadas.\nCambió de brazo y repetí el movimiento.' WHERE name_en = 'One Arm Dumbbell Preacher Curl';
UPDATE public.exercises SET instructions_es = 'Conectá una manija estándar a la torre y, si es posible, posicioná el cable a la altura de los hombros. Si no, una polea baja será suficiente.\nColocá tu costado hacia el cable, agarrá la manija con ambas manos y alejáte de la torre. Debés estar a aproximadamente un brazo de distancia de la polea, con la tensión del peso en el cable.\nCon los pies separados a la anchura de las caderas y las rodillas ligeramente flexionadas, mantené el cable en el centro de tu pecho. Esta será tu posición inicial.\nEmpujá el cable lejos de tu pecho, extendiendo completamente ambos brazos. Tu core debe estar firme y activado.\nMantené la repetición durante varios segundos antes de volver a la posición inicial.\nAl finalizar la serie, repetí el ejercicio mirando hacia la otra dirección.' WHERE name_en = 'Pallof Press';
UPDATE public.exercises SET instructions_es = 'Conectá una manija estándar a la torre y posicioná el cable a la altura de los hombros.\nColocá tu costado frente al cable, agarrá la manija con una mano y alejá de la torre.\nMantené una distancia aproximada de un brazo de la polea, con la tensión del peso en el cable.\nAlineá el brazo extendido con el cable.\nCon los pies separados a la anchura de las caderas, jalá el cable hacia el pecho y agarrá la manija con la otra mano.\nAmbas manos deben estar sobre la manija en este momento.\nMirando hacia adelante, empujá el cable lejos de tu pecho.\nTu core debe estar firme y activado.\nMantené las caderas rectas y girá el torso alejándolo de la polea hasta lograr una rotación completa de un cuarto de vuelta.\nMantené tu postura rígida y los brazos rectos.\nRegresá a la posición neutra de manera lenta y controlada.\nTus brazos deben estar extendidos frente a vos.\nCon la tensión lateral que sigue activando tu core, llevá las manos al pecho y empujá hacia afuera inmediatamente hasta la extensión completa.\nEsto constituye una repetición.\nRepetí hasta el fallo.\nLuego, repositionate y repetí la misma serie de movimientos en el lado opuesto.' WHERE name_en = 'Pallof Press With Rotation';
UPDATE public.exercises SET instructions_es = 'Sentate y pasá una correa, cuerda o banda alrededor de un pie.\nExtendé la pierna con el talón despegado del suelo.\nJalá la correa para evertir el pie, llevando la parte externa hacia vos.\nMantené la posición entre 10 y 20 segundos.\nCambialo de lado.' WHERE name_en = 'Posterior Tibialis Stretch';
UPDATE public.exercises SET instructions_es = 'Pará con los pies ligeramente más separados que el ancho de los hombros y las puntas de los pies apuntando hacia afuera.\nAgachate y agarrá la barra con un agarre cerrado y prono, con las manos ligeramente más separadas que el ancho de los hombros, fuera de las rodillas y los codos completamente extendidos.\nColocá la barra a unos 2,5 cm frente a las espinillas y sobre las puntas de los pies.\nMantené la espalda plana o ligeramente arqueada, el pecho elevado y los omóplatos retraídos.\nMantené la cabeza en posición neutra, alineada con la columna vertebral y sin inclinarse ni rotar, con la mirada fija al frente, y respirá por la nariz durante esta fase.\nLevantá la barra del suelo extendiendo con fuerza las caderas y las rodillas mientras exhalás, manteniendo el mismo ángulo del torso superior, sin doblar la cintura ni dejar que las caderas suban antes que los hombros.\nMantené los codos completamente extendidos, la cabeza en posición neutra y los hombros sobre la barra.\nMantené la barra lo más cerca posible de las espinillas mientras sube.\nCuando la barra pase las rodillas, empujá las caderas hacia adelante y flexioná ligeramente las rodillas para evitar bloquearlas, asegurándote de que los muslos estén en contacto con la barra.\nMantené la espalda plana o ligeramente arqueada, los codos completamente extendidos y la cabeza neutra, conteniendo la respiración hasta la siguiente fase.' WHERE name_en = 'Power Clean';
UPDATE public.exercises SET instructions_es = 'Recostá la barra sobre cajas de la altura deseada y agarrala justo afuera de las piernas.\nBajá las caderas manteniendo el peso en los talones, la espalda recta, la cabeza al frente y el pecho arriba, con los hombros justo adelante de la barra.\nIniciá la primera tracción empujando con los talones y extendiendo las rodillas.\nMantené el ángulo de la espalda igual y los brazos rectos.\nCuando la barra llegue a la mitad del muslo, empezá a extender las caderas.\nAcelerá en un movimiento de salto extendiendo caderas, rodillas y tobillos para subir la barra con velocidad.\nNo necesitás tirar activamente con los brazos para acelerar el peso.\nAl final de la segunda tracción, el cuerpo debe estar completamente extendido, inclinado ligeramente hacia atrás, con los brazos aún extendidos.\nAl lograr la extensión completa, pasá a la tercera tracción encogiendo agresivamente los hombros y flexionando los brazos con los codos arriba y afuera.\nEn la extensión máxima, tirate por debajo de la barra lo suficiente para apoyarla en los hombros, rotando los codos por debajo de la barra.\nApoyá la barra sobre los hombros protruidos, tocando levemente la garganta con las manos relajadas.\nRecuperate inmediatamente empujando con los talones, manteniendo el torso erguido y los codos arriba.\nSeguí hasta que te hayas puesto de pie y completá la repetición devolviendo el peso a las cajas.' WHERE name_en = 'Power Clean from Blocks';
UPDATE public.exercises SET instructions_es = 'Pará con la barra apoyada en la parte frontal de los hombros.\nColocá los pies directamente debajo de las caderas.\nFlexioná las rodillas sin mover las caderas hacia atrás.\nBajá solo un poco y cambiá de dirección con la mayor potencia posible.\nEmpujá a través de los talones generando la mayor velocidad y fuerza posible.\nMové la cabeza para que no estorbe cuando la barra salga de los hombros.\nCuando los pies salgan del suelo, colocálos en la posición de recepción lo más rápido posible.\nMové los pies a una posición ligeramente más abierta con las rodillas parcialmente flexionadas.\nRecibí la barra con los brazos extendidos por encima de la cabeza.\nVolvé a la posición de pie.' WHERE name_en = 'Power Jerk';
UPDATE public.exercises SET instructions_es = 'Recostá la barra cargada sobre cajas o soportes de la altura deseada.\nAgarrá la barra con una toma amplia.\nColocá los pies directamente debajo de las caderas, con los pies girados hacia afuera según sea necesario.\nBajá las caderas, manteniendo el pecho arriba y la cabeza mirando hacia adelante.\nDejá que los hombros queden justo frente a la barra, con los codos apuntando hacia afuera.\nIniciá la primera tracción empujando a través de la parte delantera de los talones, levantando la barra desde las cajas.\nTransicioná a la segunda tracción extendiendo las caderas, rodillas y tobillos, impulsando la barra hacia arriba lo más rápido posible.\nMantené la barra cerca del cuerpo.\nAl alcanzar la extensión máxima, encogé los hombros y permití que los codos se flexionen hacia los lados.\nMientras movés los pies a la posición de recepción, jalate con fuerza por debajo de la barra mientras la elevás sobre la cabeza.\nMové los pies a justo afuera de las caderas, girados hacia afuera según sea necesario.\nRecibí la barra sobre una sentadilla completa y con los brazos totalmente extendidos sobre la cabeza.\nMantené la barra alineada sobre la parte delantera de los talones, con la cabeza y el pecho arriba.\nEmpujá a través de los talones para pasar a una posición de pie.\nDevolvé la carga a las cajas con cuidado.' WHERE name_en = 'Power Snatch from Blocks';
UPDATE public.exercises SET instructions_es = 'Agarrá el implemento con ambas manos.\nSepará los pies y mantené la cabeza y el pecho arriba.\nEmpujá el suelo con los talones y extendé las rodillas y caderas para levantar el peso.\nIncliná el torso hacia atrás y sacudí el peso hacia las escaleras de 16 a 18 pulgadas de alto.\nUsá las piernas para ayudar a empujar el peso sobre el escalón.\nRepetí de 3 a 5 veces y continuá con un peso más pesado, moviéndote lo más rápido posible.' WHERE name_en = 'Power Stairs';
UPDATE public.exercises SET instructions_es = 'Colocá un banco dentro de la jaula de potencia con la barra a la altura correcta.\nAnclá las bandas en los soportes o en la parte superior de la jaula.\nAsegurate de estar bien posicionado bajo las bandas.\nConectá el otro extremo a la barra.\nRecostá en el banco, meté los pies debajo de vos y arqueá la espalda.\nUsá la barra para apoyar tu peso, levantá los hombros del banco y retraelos apretando las escápulas.\nUsá los pies para presionar los trapecios contra el banco.\nMantené esta posición corporal tensa durante todo el movimiento.\nAsegurate de que tu agarre cubra el anillo de la barra, sin importar su amplitud.\nSacá la barra de la jaula sin protruir los hombros.\nConcentrate en apretar la barra e intentá separarla.\nBajá la barra hasta el pecho inferior o el estómago superior.\nMantené la barra, la muñeca y el codo alineados en todo momento.\nHacé una pausa cuando la barra toque tu torso.\nEmpujá la barra hacia arriba con la mayor fuerza posible.\nMantené los codos pegados al cuerpo hasta el bloqueo.' WHERE name_en = 'Reverse Band Bench Press';
UPDATE public.exercises SET instructions_es = 'Recostá una caja a la altura adecuada detrás de vos.\nColocá las bandas en los soportes o en la parte superior de la jaula, asegurándote de que queden directamente sobre la barra.\nAnclá el otro extremo de las bandas a la barra.\nEntrá bajo la barra y apoyala en la parte posterior de los hombros.\nApretá las escápulas entre sí y rotá los codos hacia adelante, intentando doblar la barra sobre los hombros.\nSacá la barra de la jaula, creando un arco firme en la zona lumbar, y retrocedé para ubicarte en posición.\nSepará los pies más de lo habitual para enfatizar la espalda, glúteos, aductores e isquiotibiales, o juntalos para priorizar los cuádriceps.\nMantené la cabeza mirando hacia adelante.\nCon la espalda, los hombros y el core tensos, empujá las rodillas y los glúteos hacia afuera para iniciar el descenso.\nSentate hacia atrás con las caderas hasta apoyarte en la caja.\nMantené las espinillas perpendiculares al suelo.\nHacé una pausa al llegar a la caja y relajá los flexores de la cadera.\nNo rebotes sobre la caja.\nMantené el peso en los talones y empujá los pies y las rodillas hacia afuera.\nImpulsate hacia arriba desde la caja, liderando el movimiento con la cabeza.\nSeguí ascendiendo, manteniendo la tensión de la cabeza a los pies.\nDevolvé' WHERE name_en = 'Reverse Band Box Squat';
UPDATE public.exercises SET instructions_es = 'Ajustá la barra en un rack de potencia.\nFijá las bandas en la parte superior del rack usando los pasadores o el propio marco.\nConectá el otro extremo de las bandas a la barra.\nAcercate a la barra para que quede centrada sobre tus pies.\nSepará los pies a la anchura de las caderas.\nInclinate desde la cadera para agarrar la barra a la anchura de los hombros, permitiendo que las escápulas se proyecten hacia adelante.\nUsá un agarre prono o mixto en las series más pesadas.\nCon los pies y el agarre listos, tomá una respiración profunda.\nBajá las caderas y doblá las rodillas hasta que las espinillas toquen la barra.\nMirá al frente, mantené el pecho arriba y la espalda arqueada.\nEmpujá a través de los talones para mover el peso hacia arriba.\nUna vez que la barra pase las rodillas, jaleá la barra hacia atrás con fuerza.\nJuntá las escápulas mientras empujás las caderas hacia adelante contra la barra.\nBajá la barra flexionando las caderas y guiándola hasta el suelo.' WHERE name_en = 'Reverse Band Deadlift';
UPDATE public.exercises SET instructions_es = 'Colocá los pines y la barra en la altura adecuada dentro del rack de potencia.\nCargá la barra y fijá las bandas en la parte superior del rack usando los pasadores o el propio marco.\nConectá el otro extremo de las bandas a la barra.\nEntrá bajo la barra y apoyala en la parte trasera de los hombros.\nApretá los omóplatos entre sí y rotá los codos hacia adelante, intentando doblar la barra contra los hombros.\nRetirá la barra del rack, creando un arco firme en la zona lumbar, y retrocedé para ubicarte en posición.\nSepará los pies más de lo habitual para enfatizar la espalda, glúteos, aductores e isquiotibiales.\nMantené la cabeza mirando hacia adelante.\nCon la espalda, los hombros y el core tensos, empujá las rodillas y los glúteos hacia afuera para iniciar la bajada.\nSentate hacia atrás con las caderas lo más posible.\nIdealmente, las espinillas deben quedar perpendiculares al suelo.\nSi la posición de la barra es más baja, incliná más el torso para mantener la barra sobre los talones.\nBajá hasta romper la paralela, definida como la línea de la cadera a la altura de la parte superior de la rodilla.\nMantené el peso en los talones y empujá los pies y las rodillas hacia afuera.\nImpulsate hacia arriba liderando el movimiento con la cabeza.\nSeguí subiendo, manteniendo la tensión de la cabeza a' WHERE name_en = 'Reverse Band Power Squat';
UPDATE public.exercises SET instructions_es = 'Sentate al final de un banco plano con una mancuerna en una mano usando agarre neutro (palmas hacia vos).\nDoblá levemente las rodillas y llevá el torso hacia adelante flexionando la cintura, manteniendo la espalda recta hasta que quede casi paralela al suelo.\nMantené la cabeza arriba.\nMantené el brazo superior con la mancuerna cerca del torso y alineado con él, levantado hasta que quede paralelo al suelo mientras los antebrazos apuntan hacia el suelo.\nAsegurate de que haya un ángulo de 90 grados entre los antebrazos y el brazo superior.\nMantené el brazo superior fijo y usá los tríceps para levantar el peso mientras exhalás, hasta que el antebrazo quede paralelo al suelo y el brazo completo esté extendido.\nMantené la contracción un segundo en la parte superior.\nBajá lentamente la mancuerna hasta la posición inicial mientras inhalás.\nRepetí el movimiento la cantidad de repeticiones indicadas.\nCambiá de brazo y repetí el ejercicio.' WHERE name_en = 'Seated Bent-Over One-Arm Dumbbell Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Colocá un par de mancuernas mirando hacia adelante frente a un banco plano.\nSentate en el extremo del banco con las piernas juntas y las mancuernas detrás de los gemelos.\nIncliná el tronco hacia adelante manteniendo la espalda recta para levantar las mancuernas, con las palmas de las manos mirándose entre sí.\nMantené el torso hacia adelante y estático, con los codos ligeramente flexionados, y levantá las mancuernas en línea recta hacia los lados hasta que los brazos queden paralelos al suelo, exhalando al subir.\nMantené una contracción de un segundo en la posición superior y bajá lentamente las mancuernas hasta la posición inicial.\nRepetí el movimiento la cantidad de repeticiones recomendadas.' WHERE name_en = 'Seated Bent-Over Rear Delt Raise';
UPDATE public.exercises SET instructions_es = 'Sentate en un banco plano con una barra o barra E-Z frente a vos, entre las piernas.\nSepará las piernas con las rodillas flexionadas y los pies apoyados en el suelo.\nLevantá la barra con los brazos y apoyá la parte posterior de los brazos superiores sobre los muslos internos, a unos nueve centímetros de la rodilla.\nUsá un agarre supinado más angosto que el ancho de los hombros.\nExtendé los brazos por completo para que la barra quede sobre el suelo, esta es tu posición inicial.\nMantené los brazos superiores fijos y flexioná los antebrazos hacia adelante contrayendo los bíceps mientras exhalás.\nMové solo los antebrazos hasta que los bíceps estén completamente contraídos y la barra llegue a la altura de los hombros.\nMantené la posición contraída por un segundo apretando los bíceps.\nVolvé lentamente a la posición inicial mientras inhalás.\nEvitá movimientos de balanceo en todo momento.\nRepetí el ejercicio la cantidad de veces recomendada.' WHERE name_en = 'Seated Close-Grip Concentration Barbell Curl';
UPDATE public.exercises SET instructions_es = 'Sentate en un banco plano con una mancuerna en cada mano, sostenidas a la altura de los hombros y los codos pegados al torso.\nGirá las palmas de las manos hacia tu cuerpo para establecer la posición inicial.\nMantené los brazos superiores quietos y flexioná los codos para subir las mancuernas, torciendo las muñecas cuando pasen las rodillas para que las palmas miren hacia adelante al final del movimiento.\nContráé los bíceps mientras exhalás, asegurándote de que solo se muevan los antebrazos hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.\nMantené la posición contraída durante un segundo apretando los bíceps.\nBajá lentamente las mancuernas a la posición inicial mientras inhalás y girás las muñecas de vuelta a la agarre neutro.\nRepetí el movimiento por la cantidad de repeticiones recomendadas.' WHERE name_en = 'Seated Dumbbell Curl';
UPDATE public.exercises SET instructions_es = 'Colocá un banco frente a una máquina de polea baja con una barra o barra EZ.\nAlejá el banco lo suficiente para que, al llevar la manija a la parte superior de los muslos, se genere tensión en el cable al subir la torre de pesas.\nAgarrá la manija con ambas manos, palmas hacia arriba, usando un agarre a la anchura de los hombros.\nRetretá y sentate en el banco con los pies a la anchura de los hombros, firmes en el suelo.\nIncliná el torso hacia adelante y apoyá los antebrazos sobre los muslos, con la parte posterior de las muñecas sobre las rodillas.\nBajá la barra lo más posible, mientras inhalás y mantenés un agarre firme.\nFlexioná la barra hacia arriba lo más posible, mientras contraés los antebrazos.\nMantené la contracción un segundo en la parte superior y volvé a la posición inicial, mientras inhalás.\nRepetí el movimiento la cantidad de repeticiones recomendadas.' WHERE name_en = 'Seated Two-Arm Palms-Up Low-Pulley Wrist Curl';
UPDATE public.exercises SET instructions_es = 'Agarrá una mancuerna en cada mano y parate erguido.\nLevantá las mancuernas hasta el nivel del pecho o los hombros y girá las muñecas para que las palmas miren hacia vos, como si fueras a hacer un press de Arnold. Esta será tu posición inicial.\nExtendé el brazo izquierdo hacia arriba mientras girás la muñeca para que la palma mire hacia adelante al subir. Los codos también deben salir mientras levantás el peso. Al mismo tiempo, flexioná el tronco desde la cadera hacia el lado opuesto. Si lo hacés bien, parecerá que intentás alcanzar algo sobre tu cabeza del lado derecho de tu cuerpo, pero con el brazo izquierdo. Exhalá al realizar este movimiento.\nAl llegar a la posición superior, inhalá. Luego, con el peso completamente extendido sobre la cabeza y el tronco inclinado hacia tu lado derecho, iniciá el movimiento hacia el lado izquierdo.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'See-Saw Press (Alternating Side Press)';
UPDATE public.exercises SET instructions_es = 'Recostá sobre el suelo con las rodillas flexionadas y los pies apoyados.\nEmpujá el suelo con las piernas para elevar la cadera hasta alinear el cuerpo.\nMantené la posición contrayendo los glúteos y el abdomen.' WHERE name_en = 'Side Jackknife';
UPDATE public.exercises SET instructions_es = 'Elegí un par de mancuernas y parate con el torso recto, los brazos extendidos a los costados y las palmas hacia adentro.\nMantené el torso quieto sin balancearte y levantá las mancuernas hacia los costados con una leve flexión en los codos y las manos ligeramente inclinadas hacia adelante, como si estuvieras vertiendo agua en un vaso.\nSubí hasta que los brazos queden paralelos al suelo, exhalá durante el movimiento y mantené la posición un segundo en la parte superior.\nBajá las mancuernas lentamente hasta la posición inicial mientras inhalás.\nRepetí el movimiento la cantidad de veces recomendadas.' WHERE name_en = 'Side Lateral Raise';
UPDATE public.exercises SET instructions_es = 'Ajustá la barra en la máquina Smith a la altura de la mitad de los muslos.\nAgarrá la barra con las palmas hacia adelante, a la anchura de los hombros.\nLevantá la barra extendiendo completamente los brazos con la espalda recta.\nMantené una leve flexión en los codos como posición inicial.\nUsá los hombros laterales para subir la barra mientras exhalás.\nMantené la barra cerca del cuerpo al subir hasta que casi toque la barbilla.\nMantené los codos siempre más altos que los antebrazos durante el movimiento.\nMantené el torso inmóvil y hacé una pausa de un segundo en la parte superior.\nBajá la barra lentamente hasta la posición inicial mientras inhalás.\nRepetí el movimiento la cantidad de repeticiones recomendadas.' WHERE name_en = 'Smith Machine Upright Row';
UPDATE public.exercises SET instructions_es = 'Colocá un banco plano a 2-3 pies detrás de la máquina Smith.\nAjustá la barra a la altura que mejor se adapte a tu estatura.\nUna vez cargada la barra, pasá por debajo y apoyá la parte trasera de los hombros (ligeramente por debajo del cuello) sobre ella.\nAgarrá la barra con ambos brazos a los costados (palmas hacia adelante), desbloqueala y levantala empujando con las piernas mientras enderezás el torso.\nColocá un pie ligeramente adelante bajo la barra y extendé la otra pierna hacia atrás apoyando el empeine en el banco.\nBajá la barra lentamente flexionando la rodilla, manteniendo la postura recta y la cabeza arriba.\nContinuá bajando hasta que el ángulo entre el muslo y la pantorrilla sea ligeramente menor a 90 grados.\nInhalá mientras realizás esta parte del movimiento.\nAsegurate de que la rodilla no pase la línea imaginaria de los dedos del pie para no forzar la articulación.\nExhalá mientras empujás el suelo con el talón para enderezar la pierna y volver a la posición inicial.\nRepetí el movimiento la cantidad de repeticiones recomendadas.\nCambiala de pierna y repetí el ejercicio.' WHERE name_en = 'Smith Single-Leg Split Squat';
UPDATE public.exercises SET instructions_es = 'Colocá los pies a la anchura de los hombros con la barra justo sobre la unión de los dedos y el resto del pie.\nAgarrá la barra con las palmas hacia abajo y un agarre más ancho que los hombros, doblá las rodillas manteniendo la espalda recta y bajá las caderas como si fueras a sentarte en una silla.\nEmpujá el suelo con los pies como si fuera una plataforma móvil y levantá la barra manteniéndola pegada a las piernas.\nCuando la barra llegue a la mitad de los muslos, empujá el suelo con las piernas y levantá el cuerpo hasta la extensión completa con un movimiento explosivo.\nLlevá los hombros hacia atrás en un movimiento de encogimiento mientras subís la barra, sacando los codos hacia los lados y manteniéndolos por encima de la barra el mayor tiempo posible.\nCon un movimiento rápido y potente, meté el cuerpo debajo de la barra cuando alcance la altura suficiente para controlarla, bajá y bloqueá los brazos sosteniendo la barra por encima de la cabeza en posición de sentadilla.\nFinalizá el movimiento levantándote de la sentadilla para completar el levantamiento, asegurándote de que ambos pies estén alineados y los brazos completamente extendidos sosteniendo la barra por encima de la cabeza.' WHERE name_en = 'Snatch';
UPDATE public.exercises SET instructions_es = 'Colocá los pies en la posición de tracción, la barra apoyada en la parte trasera de los hombros y las manos en agarre ancho de arranque.\nImpulsá la barra con una flexión brusca y una extensión agresiva de las rodillas, y metete rápidamente debajo de la barra mientras llevás los pies a la posición de recepción.\nRecibí la barra con los brazos extendidos por encima de la cabeza cerca del fondo de la sentadilla, manteniendo el torso vertical y bajando las caderas entre las piernas.\nSeguí descendiendo hasta la profundidad completa y volvé a la posición de pie, bajando el peso con cuidado.' WHERE name_en = 'Snatch Balance';
UPDATE public.exercises SET instructions_es = 'Agrupá la barra con un agarre ancho de arrancada sobre la plataforma.\nColocá los pies directamente debajo de las caderas, con las puntas hacia afuera.\nAgachate hasta la barra, manteniendo la espalda completamente extendida y la cabeza mirando al frente.\nIniciá el movimiento empujando a través de los talones para elevar las caderas.\nMantené el ángulo de la espalda igual hasta que la barra pase las rodillas.\nEmpujá las caderas a través de la barra mientras te recostás hacia atrás.\nDevolvé la barra a la plataforma invirtiendo el movimiento.' WHERE name_en = 'Snatch Deadlift';
UPDATE public.exercises SET instructions_es = 'Recostá la barra en el suelo cerca de los esguinces y tomá una agarre de arranque ancho.\nBajá las caderas con el peso en los talones, mantené la espalda recta, la cabeza mirando al frente y el pecho arriba, con los hombros justo delante de la barra.\nIniciá el primer tirón empujando a través de los talones y extendiendo las rodillas.\nMantené el ángulo de la espalda igual y los brazos rectos.\nMové el peso con control hasta pasar las rodillas.\nCuando la barra llegue a la mitad del muslo, empezá a extender las caderas.\nAcelerá extendiendo las caderas, las rodillas y los tobillos en un movimiento de salto para subir la barra con velocidad.\nNo necesitás tirar activamente con los brazos para acelerar el peso.\nAl final del segundo tirón, el cuerpo debe estar completamente extendido, inclinado ligeramente hacia atrás.\nHacé que la extensión sea violenta y abrupta, sin prolongarla más de lo necesario.' WHERE name_en = 'Snatch Pull';
UPDATE public.exercises SET instructions_es = 'Asumí un agarre ancho con la barra colgando a la altura del muslo medio.\nPodés usar agarre de gancho o supino.\nMantené la espalda recta e inclinada ligeramente hacia adelante.\nElevá los hombros hacia las orejas.\nEvitá sobrecargar el peso para no frenar la ejecución.' WHERE name_en = 'Snatch Shrug';
UPDATE public.exercises SET instructions_es = 'Recostá la barra cargada sobre cajas o soportes de la altura deseada.\nTomá la barra con un agarre ancho.\nColocá los pies directamente debajo de las caderas, girándolos hacia afuera según sea necesario.\nBajá las caderas manteniendo el pecho arriba y la mirada al frente.\nDejá que los hombros queden justo adelante de la barra, con los codos apuntando hacia afuera.\nIniciá la primera tracción empujando con la parte delantera de los talones para levantar la barra de las cajas.\nPasá a la segunda tracción extendiendo caderas, rodillas y tobillos, impulsando la barra hacia arriba lo más rápido posible.\nMantené la barra cerca del cuerpo.\nAl alcanzar la extensión máxima, encogé los hombros y permití que los codos se flexionen hacia los lados.\nMientras movés los pies a la posición de recepción, tirá de tu cuerpo hacia abajo bajo la barra mientras la elevás por encima de la cabeza.\nColocá los pies justo afuera de las caderas, girándolos hacia afuera si es necesario.\nRecibí la barra con el cuerpo lo más bajo posible y los brazos completamente extendidos por encima de la cabeza.\nMantené la barra alineada sobre la parte delantera de los talones, con la cabeza y el pecho arriba.\nEmpujá con los talones para pasar a la posición de pie.\nDevolvé la carga a las cajas con cuidado.' WHERE name_en = 'Snatch from Blocks';
UPDATE public.exercises SET instructions_es = 'Anclá la banda al suelo o a la base de un banco inclinado y pará sobre ella o frente al banco.\nJalá la banda detrás de tu cabeza con agarre prono y codos elevados para asumir la posición inicial.\nExtendé los codos hasta enderezar los brazos manteniendo los brazos superiores fijos.\nHacé una pausa y volvé a la posición inicial.' WHERE name_en = 'Speed Band Overhead Triceps';
UPDATE public.exercises SET instructions_es = 'Anclá las bandas de forma segura cerca del suelo y ajustá el agarre para lograr la tensión adecuada.\nElegí una caja de altura apropiada y cargá la barra con un peso entre el 50% y el 70% de tu máximo, manteniendo la velocidad.\nColocá la barra en la parte alta de la espalda, retraé los omóplatos, arqueá la espalda y mantené todo el cuerpo tenso de la cabeza a los pies.\nDescolgá la barra, parate frente a la caja y sentate hacia atrás controlando el descenso para no caer bruscamente.\nHacé una pausa breve y explotá desde la caja extendiendo caderas y rodillas.' WHERE name_en = 'Speed Box Squat';
UPDATE public.exercises SET instructions_es = 'Ajustá la barra en el rack a la altura de tus hombros.\nColocá la barra sobre la parte posterior de tus hombros, justo debajo del cuello.\nApoyá la barra con ambas manos a los costados.\nEmpujá con las piernas y enderezá el torso para despegar la barra del rack.\nDale un paso hacia atrás y separá las piernas a la anchura de los hombros con las puntas de los pies ligeramente hacia afuera.\nMantené la cabeza en alto y la espalda recta.\nIncliná las rodillas para bajar la barra manteniendo la postura recta y la cabeza en alto.\nBajá hasta que el ángulo entre el muslo y la pantorrilla sea ligeramente menor a 90 grados.\nInspirá mientras realizás esta parte del movimiento.\nAsegurate de que las rodillas no pasen la línea imaginaria de las puntas de los pies.\nEmpujá el suelo con los talones para subir la barra lo más rápido posible sin usar impulso.\nExpirá mientras enderezás las piernas y volvé a la posición inicial.\nRepetí el movimiento la cantidad de veces recomendada.' WHERE name_en = 'Speed Squats';
UPDATE public.exercises SET instructions_es = 'Sujetá una mancuerna en cada mano con agarre prono.\nColocá los pies separados y mantené caderas y rodillas extendidas.\nIniciá el movimiento llevando ambas mancuernas hacia un lado junto a tu cadera, rotando el torso.\nMantené los brazos rectos y las mancuernas paralelas al suelo mientras rotás el torso para llevar los pesos al lado opuesto.\nSeguí alternando, rotando de un lado al otro hasta completar la serie.' WHERE name_en = 'Spell Caster';
UPDATE public.exercises SET instructions_es = 'Recostá boca abajo en el suelo.\nApoyá tu peso en las manos y las puntas de los pies, con los pies juntos y el cuerpo recto.\nDoblá los brazos a 90 grados.\nLevantá un pie del suelo.\nRotá externamente la pierna y llevá la rodilla hacia el codo, lo más adelante posible.\nVolvé esta pierna a la posición inicial.\nRepetí en el lado opuesto.' WHERE name_en = 'Spider Crawl';
UPDATE public.exercises SET instructions_es = 'Colocá la barra en la parte del banco predicador donde normalmente te sentás y alineala bien para que quede equilibrada y no se caiga.\nPasá al frente del banco predicador y posicionate para recostarte con una inclinación de 45 grados, presionando el torso y el estómago contra la parte frontal del banco.\nAsegurate de que tus pies, especialmente las puntas, estén bien apoyados en el suelo y colocá tus brazos superiores sobre el cojín ubicado en la parte interior del banco.\nAgarrá la barra con un agarre supinado (palmas hacia arriba) a la anchura de los hombros o ligeramente más cerca.\nLevantá lentamente la barra hacia arriba y exhalá, mantené la posición contraída un segundo mientras apretás los bíceps.\nBajá lentamente la barra hasta la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Spider Curl';
UPDATE public.exercises SET instructions_es = 'Sentate en una silla con la espalda recta y los pies apoyados en el piso.\nEntrelazá los dedos detrás de la cabeza, con los codos hacia afuera y la barbilla abajo.\nGirá el torso hacia un lado lo más que puedas unas 3 veces y luego inclináte hacia adelante para llevar el codo al piso dentro de la rodilla.\nVolvé a la posición vertical y repetí en el otro lado.' WHERE name_en = 'Spinal Stretch';
UPDATE public.exercises SET instructions_es = 'Colocá la barra en el piso cerca de los escaques y agarrala con agarre prono justo afuera de las piernas.\nBajá las caderas con el peso en los talones, mantené la espalda recta, la cabeza mirando al frente y el pecho arriba, con los hombros justo adelante de la barra.\nIniciá el primer tirón empujando con los talones y extendiendo las rodillas, manteniendo el ángulo de la espalda igual y los brazos rectos.\nMové el peso con control hasta pasar por encima de las rodillas.\nIniciá el segundo tirón extendiendo las caderas cuando la barra llegue a la mitad del muslo.\nAcelerá extendiendo las caderas, rodillas y tobillos en un movimiento de salto para subir la barra con velocidad.\nMantené los brazos extendidos y dejá que el cuerpo se extienda por completo, inclinándose ligeramente hacia atrás al final del segundo tirón.\nAlcanzá la extensión completa y pasá al tercer tirón encogiendo agresivamente los hombros y flexionando los brazos con los codos arriba y afuera.\nEn la extensión máxima, bajá el cuerpo agresivamente rotando los codos por debajo de la barra.\nRecibí la barra con los pies separados, moviendo un pie hacia adelante y el otro hacia atrás.\nEncajá la barra sobre los hombros protruidos, tocando levemente la garganta con las manos relajadas.\nContinuá descendiendo hasta la posición inferior para facilitar la recuperación.\nRecuperate inmediatamente empujando con los talones' WHERE name_en = 'Split Clean';
UPDATE public.exercises SET instructions_es = 'Recostá el peso en la parte frontal de los hombros y empezá con la flexión.\nColocá los pies directamente debajo de las caderas y flexioná las rodillas sin mover las caderas hacia atrás.\nBajá solo un poco y cambiá de dirección con la mayor potencia posible.\nEmpujá a través de los talones para generar la mayor velocidad y fuerza posible, y asegurá de mover la cabeza de lado cuando la barra salga de los hombros.\nEn el momento en que los pies salgan del suelo, colocá los pies en la posición de recepción lo más rápido posible.\nMientras los pies no empujan activamente contra la plataforma, el esfuerzo de empujar la barra hacia arriba te hará bajar.\nMové los pies a una posición de zancada, con un pie adelante y otro atrás, manteniendo las rodillas parcialmente flexionadas.\nRecibí la barra con los brazos extendidos por encima de la cabeza.\nVolvé a la posición de pie juntando los pies.' WHERE name_en = 'Split Jerk';
UPDATE public.exercises SET instructions_es = 'Asumí una posición de zancada con un pie adelante y la rodilla flexionada, y la rodilla trasera casi tocando el suelo.\nAsegurate de que la rodilla delantera esté sobre la línea media del pie.\nExtendé ambas piernas y saltá lo más alto posible, balanceando los brazos para ganar impulso.\nMientras saltás, juntá los pies y movelos de vuelta a su posición inicial al aterrizar.\nAbsorbí el impacto volviendo a la posición de inicio.' WHERE name_en = 'Split Jump';
UPDATE public.exercises SET instructions_es = 'Colocá la barra cargada en el suelo, cerca o tocando las espinillas, con un agarre ancho.\nPosicioná los pies directamente debajo de las caderas, girándolos hacia afuera según sea necesario.\nBajá las caderas manteniendo el pecho arriba y la mirada al frente, con los hombros justo delante de la barra.\nIniciá el primer tirón empujando con la parte delantera de los talones para levantar la barra del suelo.\nMantené el ángulo de la espalda igual hasta que la barra pase las rodillas.\nTransicioná al segundo tirón extendiendo caderas, rodillas y tobillos para impulsar la barra hacia arriba lo más rápido posible.\nMantené la barra cerca del cuerpo y, en la extensión máxima, encogé los hombros y permití que los codos se flexionen hacia los lados.\nMové los pies con fuerza a una posición dividida, uno adelante y otro atrás, mientras tirás de tu cuerpo hacia abajo para elevar la barra sobre la cabeza.\nRecibí la barra con el cuerpo lo más bajo posible y los brazos completamente extendidos sobre la cabeza.\nMantené la barra alineada sobre la parte delantera de los talones, con la cabeza y el pecho arriba.\nEmpujá con los talones para pasar a la posición de pie y juntá los pies.\nDevolvé la carga al suelo con cuidado.' WHERE name_en = 'Split Snatch';
UPDATE public.exercises SET instructions_es = 'Recostá en una posición escalonada con el pie trasero elevado y el delantero hacia adelante.\nSujetá una mancuerna en cada mano, dejándolas colgar a los costados. Esta será tu posición inicial.\nComenzá bajando, flexionando la rodilla y la cadera para descender el cuerpo.\nMantené una buena postura durante todo el movimiento.\nMantené la rodilla delantera alineada con el pie mientras realizás el ejercicio.\nEn la parte inferior del movimiento, empujá con el talón para extender la rodilla y la cadera y volver a la posición inicial.' WHERE name_en = 'Split Squat with Dumbbells';
UPDATE public.exercises SET instructions_es = 'Parate de pie.\nSaltá a una posición de zancada con una pierna adelante y la otra atrás, flexionando las rodillas y bajando ligeramente las caderas.\nAl descender, invertí la dirección de inmediato, parate y saltá, cambiando la posición de las piernas.\nRepetí de 5 a 10 veces con cada pierna.' WHERE name_en = 'Split Squats';
UPDATE public.exercises SET instructions_es = 'Recostá el peso en la parte frontal de los hombros y empezá con la flexión.\nColocá los pies directamente debajo de las caderas y flexioná las rodillas sin mover las caderas hacia atrás.\nBajá solo un poco y cambiá de dirección con la mayor potencia posible.\nEmpujá a través de los talones para generar la mayor velocidad y fuerza posible, y asegurá de mover la cabeza de lado cuando la barra salga de los hombros.\nEn el momento en que los pies salgan del suelo, colocá los pies en la posición de recepción lo más rápido posible.\nMové los pies con fuerza justo afuera de las caderas, girándolos hacia afuera si es necesario.\nRecibí la barra con el cuerpo en una sentadilla completa y los brazos completamente extendidos sobre la cabeza.\nMantené la barra alineada sobre la parte frontal de los talones, con la cabeza y el pecho arriba.\nEmpujá a través de los talones para pasar a una posición de pie.\nDevolvé el peso al suelo con cuidado.' WHERE name_en = 'Squat Jerk';
UPDATE public.exercises SET instructions_es = 'Colocá las bandas en las mangas, asegurándolas a los pernos, la jaula o las mancuernas para generar la tensión adecuada.\nIngresá bajo la barra y apoyala en la parte posterior de los hombros.\nApretá los omóplatos y rotá los codos hacia adelante, intentando doblar la barra sobre los hombros.\nSacá la barra de la jaula, creando un arco firme en la zona lumbar, y retrocedé hasta tu posición.\nSepará los pies para enfatizar la espalda, glúteos, aductores e isquiotibiales.\nMantené la cabeza mirando hacia adelante.\nCon la espalda, los hombros y el core tensos, empujá las rodillas y los glúteos hacia afuera para iniciar la bajada.\nSentate hacia atrás con las caderas lo máximo posible.\nMantené las espinillas perpendiculares al suelo.\nIncliná más el torso si la barra baja para mantenerla sobre los talones.\nBajá hasta romper la paralela, donde el pliegue de la cadera quede a la altura de la rodilla.\nMantené el peso en los talones y empujá los pies y las rodillas hacia afuera.\nImpulsate hacia arriba liderando el movimiento con la cabeza.\nSubí manteniendo la tensión de la cabeza a los pies hasta volver a la posición inicial.' WHERE name_en = 'Squat with Bands';
UPDATE public.exercises SET instructions_es = 'Colocá la cadena guía sobre las mangas de la barra.\nConectá la cadena pesada usando un gancho de seguridad.\nAjustá la longitud de la cadena guía para que queden unos eslabones en el suelo en la parte superior del movimiento.\nEntrá bajo la barra y apoyala en la parte trasera de los hombros.\nApretá los omóplatos y rotá los codos hacia adelante para intentar doblar la barra sobre los hombros.\nSacá la barra del soporte creando un arco firme en la zona lumbar y retrocedé para ubicarte en posición.\nSepará los pies para enfatizar la espalda, glúteos, aductores e isquiotibiales.\nMantené la cabeza mirando hacia adelante.\nCon la espalda, los hombros y el core tensos, empujá las rodillas y el glúteo hacia afuera para iniciar la bajada.\nSentate hacia atrás con la cadera lo más posible.\nMantené las espinillas perpendiculares al suelo.\nIncliná más el torso si la barra baja para mantenerla sobre los talones.\nBajá hasta romper la paralela, donde el pliegue de la cadera esté a la altura de la rodilla.\nMantené el peso sobre los talones y empujá los pies y las rodillas hacia afuera.\nImpulsate hacia arriba liderando el movimiento con la cabeza.\nSeguí subiendo manteniendo la tensión de la cabeza a los pies hasta volver a la posición inicial.' WHERE name_en = 'Squat with Chains';
UPDATE public.exercises SET instructions_es = 'Ajustá la barra en el soporte a la altura de los hombros.\nColocá una placa de peso en el suelo a un par de pies del soporte.\nCargá la barra y pasá por debajo, apoyando la parte trasera de los hombros sobre ella.\nAgarrá la barra con ambas manos y levantala del soporte empujando con las piernas y enderezando el torso.\nRetirate del soporte y adoptá una postura amplia con los pies ligeramente hacia afuera, apoyando un pie sobre la placa de peso.\nMantené la cabeza en alto en todo momento.\nIniciá el movimiento bajando la barra lentamente, flexionando las rodillas y las caderas.\nContinuá bajando hasta que el ángulo entre el muslo y la pantorrilla sea ligeramente menor a 90 grados.\nExhalá y levantá la barra empujando el suelo con los talones mientras extendés las caderas y las rodillas.\nEn la parte superior del movimiento, hacé un paso lateral juntando los pies del otro lado de la placa.\nCon el pie interno, empujá la placa de peso deslizándola por el suelo hasta donde estabas parado.\nApoyá el pie interno sobre la placa de peso y adoptá una postura amplia para la siguiente repetición.' WHERE name_en = 'Squat with Plate Movers';
UPDATE public.exercises SET instructions_es = 'Asegurate de que la banda esté dividida equitativamente entre el lado izquierdo y derecho del cuerpo.\nUsá tus manos para agarrar ambos lados de la banda y colocá ambos pies en el medio de la misma.\nMantené los pies separados a la anchura de los hombros.\nAl sostener las bandas, asegurá de que estén a la misma altura en cada lado.\nUsá un agarre pronado (palmas hacia adelante) y mantené los mangos de las bandas junto a tu cara.\nIniciá la posición de partida.\nComenzá a doblar lentamente las rodillas y bajá las piernas hasta que los muslos queden paralelos al suelo, mientras exhalás.\nEmpujá tu cuerpo hacia arriba hasta la posición inicial usando el talón de los pies, mientras exhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Squats - With Bands';
UPDATE public.exercises SET instructions_es = 'Subí a la escalera mecánica y elegí la opción deseada del menú.\nPodés elegir una configuración manual o seleccionar un programa para ejecutar.\nGeneralmente, podés ingresar tu edad y peso para estimar la cantidad de calorías quemadas durante el ejercicio.\nMové las piernas hacia arriba y abajo en un ritmo establecido, empujando los pedales hacia abajo pero sin llegar hasta el piso.\nSe recomienda que mantengas el agarre en los mangos para que no te caigas.\nPodés usar los mangos para monitorear tu frecuencia cardíaca para ayudarte a mantener una intensidad apropiada.' WHERE name_en = 'Stairmaster';
UPDATE public.exercises SET instructions_es = 'Pará con una mancuerna en cada mano.\nLevantá las mancuernas hasta los hombros con las palmas hacia adelante y los codos apuntando hacia afuera.\nExtendé un brazo para empujar la mancuerna recto hacia arriba, manteniendo la otra mano en su lugar.\nNo te inclines ni hagas movimientos bruscos con el peso durante el ejercicio.\nMantené una breve pausa y volvé al punto de partida.\nRepetí con el otro lado, alternando los brazos.' WHERE name_en = 'Standing Alternating Dumbbell Press';
UPDATE public.exercises SET instructions_es = 'Recostá la barra sobre la parte posterior de tus hombros, justo debajo del cuello.\nEmpujá con las piernas y enderezá el torso para levantar la barra del soporte.\nMantené los pies a la anchura de los hombros con las puntas ligeramente hacia afuera.\nMantené la cabeza arriba y la espalda recta en todo momento.\nMantené las rodillas con una flexión leve, sin bloquearlas.\nEmpujá los talones hacia arriba extendiendo los tobillos al máximo.\nMantené la posición contraída durante un segundo.\nBajá los talones lentamente doblando los tobillos hasta estirar los gemelos.' WHERE name_en = 'Standing Barbell Calf Raise';
UPDATE public.exercises SET instructions_es = 'Colocá la barra en un rack a la altura de tus hombros.\nPonete debajo de la barra y apoyá la parte posterior de tus hombros, justo debajo del cuello, sobre ella.\nAgarrá la barra con ambas manos y levantala empujando con las piernas mientras enderezás el torso.\nDale un paso hacia atrás y separá las piernas a la anchura de los hombros con las puntas de los pies ligeramente hacia afuera.\nMantené la espalda recta durante todo el ejercicio.\nElevá la barra por encima de la cabeza extendiendo completamente los brazos mientras exhalás.\nMantené la contracción durante un segundo.\nBajá la barra hasta la posición inicial mientras inhalás.\nRepetí el movimiento la cantidad de veces recomendadas.' WHERE name_en = 'Standing Barbell Press Behind Neck';
UPDATE public.exercises SET instructions_es = 'Recostá el torso hacia adelante doblando la cintura hasta que quede casi paralelo al suelo, manteniendo la espalda recta y la cabeza arriba.\nMantené el brazo superior pegado al torso y paralelo al suelo, con el antebrazo apuntando hacia el piso y formando un ángulo de 90 grados.\nEmpujá el peso hacia arriba usando los tríceps mientras exhalás, hasta que el antebrazo quede paralelo al suelo y el brazo esté completamente extendido.\nMantené la contracción un segundo en la posición superior.\nBajá lentamente la mancuerna hasta la posición inicial mientras inhalás.\nRepetí el movimiento la cantidad de repeticiones indicadas.\nCambió de brazo y repetí el ejercicio.' WHERE name_en = 'Standing Bent-Over One-Arm Dumbbell Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Recostá el torso hacia adelante doblando la cintura hasta que quede casi paralelo al suelo, manteniendo la espalda recta y la cabeza arriba.\nMantené los brazos superiores pegados al torso y paralelos al suelo, con los antebrazos apuntando hacia el piso formando un ángulo de 90 grados.\nEmpujá los pesos hacia arriba usando los tríceps mientras exhalás, extendiendo los brazos hasta que los antebrazos queden paralelos al suelo.\nMantené la contracción un segundo en la posición superior.\nBajá lentamente las mancuernas hasta la posición inicial mientras inhalás.\nRepetí el movimiento la cantidad de repeticiones indicadas.' WHERE name_en = 'Standing Bent-Over Two-Arm Dumbbell Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Parate de pie con el torso erguido sosteniendo una barra de curl conectada a una polea baja.\nAgarrá la barra al ancho de los hombros y mantené los codos pegados al torso.\nDejá las palmas de las manos mirando hacia arriba.\nMantené los brazos superiores quietos y flexioná los antebrazos para subir la barra mientras contraés los bíceps y exhalás.\nMové solo los antebrazos hasta que los bíceps estén completamente contraídos y la barra llegue a la altura de los hombros.\nMantené la posición contraída durante un segundo apretando el músculo.\nBajá lentamente la barra hasta la posición inicial mientras inhalás.\nRepetí el movimiento la cantidad de veces recomendadas.' WHERE name_en = 'Standing Biceps Cable Curl';
UPDATE public.exercises SET instructions_es = 'Cruzá las manos detrás de la espalda con las palmas juntas, estirá los brazos y luego rotá los brazos para que las palmas miren hacia abajo.\nLevantá los brazos y mantené la posición hasta sentir el estiramiento en los bíceps.' WHERE name_en = 'Standing Biceps Stretch';
UPDATE public.exercises SET instructions_es = 'Colocá la barra cargada a la altura de los hombros en un soporte.\nAprendé con agarre prono a la anchura de los hombros, con la barra apoyada en la parte frontal de los hombros.\nIniciá el movimiento extendiendo los codos para empujar la barra por encima de la cabeza.\nEvitá bloquear los codos mientras llevás el peso hacia atrás de la cabeza.\nBajá la barra hasta la parte posterior de la cabeza hasta que el codo forme un ángulo recto.\nLevantá la barra por encima de la cabeza extendiendo los codos.\nBajá la barra hasta la posición inicial.\nRepetí este ciclo hasta completar las repeticiones recomendadas.' WHERE name_en = 'Standing Bradford Press';
UPDATE public.exercises SET instructions_es = 'Ajustá las poleas a la altura del pecho y elegí un peso adecuado.\nPará a un o dos pies frente a los cables, sosteniendo uno en cada mano.\nPodés separar los pies para mayor estabilidad.\nColocá el brazo superior a 90 grados con las escápulas juntas.\nEsta será tu posición inicial.\nMantené el resto del cuerpo quieto.\nExtendé los codos para empujar los mangos hacia adelante.\nJuntalos frente a vos.\nHacé una pausa en la parte superior del movimiento.\nVolvé a la posición inicial.' WHERE name_en = 'Standing Cable Chest Press';
UPDATE public.exercises SET instructions_es = 'Conectá una manija estándar en la torre y mové el cable a la posición más baja de la polea.\nColocá tu costado hacia el cable, agarrá la manija con una mano y alejate de la torre.\nDeberías estar a aproximadamente un brazo de distancia de la polea, con la tensión del peso en el cable.\nTu brazo extendido debe estar alineado con el cable.\nColocá los pies a la anchura de los hombros, agachate y agarrá la manija con ambas manos.\nMantené los brazos completamente extendidos.\nEn un solo movimiento, jalá la manija hacia arriba y a través de tu cuerpo hasta que tus brazos estén completamente extendidos sobre tu cabeza.\nMantené la espalda recta y los brazos cerca del cuerpo mientras girás el pie trasero y extendés las piernas para lograr un rango de movimiento completo.\nRetraé tus brazos y luego tu cuerpo.\nVolvé a la posición neutra de manera lenta y controlada.\nRepetí hasta el fallo.\nLuego, reubicate y repetí la misma serie de movimientos en el lado opuesto.' WHERE name_en = 'Standing Cable Lift';
UPDATE public.exercises SET instructions_es = 'Conectá una manija estándar a la torre y mové el cable a la posición más alta de la polea.\nColocá tu costado frente al cable, agarrá la manija con una mano y alejáte de la torre.\nMantené una distancia aproximada de un brazo desde la polea, con la tensión del peso en el cable y el brazo extendido alineado con el cable.\nColocá los pies separados a la anchura de los hombros, levantá la otra mano y agarrá la manija con ambas manos.\nMantené los brazos completamente extendidos.\nEn un solo movimiento, jaleá la manija hacia abajo y a través de tu cuerpo hasta la rodilla delantera mientras rotás el torso.\nMantené la espalda y los brazos rectos y el core apretado mientras pivotás el pie trasero y flexionás las rodillas para lograr un rango de movimiento completo.\nMantené tu postura y los brazos rectos.\nRegresá a la posición neutra de manera lenta y controlada.\nRepetí hasta el fallo.\nLuego, reubicáte y repetí la misma serie de movimientos en el lado opuesto.' WHERE name_en = 'Standing Cable Wood Chop';
UPDATE public.exercises SET instructions_es = 'Ajustá la palanca acolchada de la máquina de elevación de gemelos a tu altura.\nColocá tus hombros bajo las almohadillas y orientá los dedos de los pies hacia adelante.\nAsegurá las plantas de los pies sobre el bloque de gemelos dejando que los talones sobresalgan.\nEmpujá la palanca hacia arriba extendiendo caderas y rodillas hasta que el torso quede erguido.\nMantené una leve flexión en las rodillas sin bloquearlas.\nElevá los talones exhalando, extendiendo los tobillos al máximo y contrayendo los gemelos.\nMantené la posición contraída por un segundo.\nBajá los talones lentamente inhalando, flexionando los tobillos hasta estirar los gemelos.\nRepetí el movimiento la cantidad de veces recomendada.' WHERE name_en = 'Standing Calf Raises';
UPDATE public.exercises SET instructions_es = 'Tomá una mancuerna en tu mano de trabajo e inclinate hacia adelante.\nDejá que tu brazo de trabajo cuelgue perpendicular al suelo con el codo apuntando hacia afuera.\nFlexioná el codo para hacer la curl, manteniendo el brazo superior inmóvil.\nEn la parte superior de la repetición, contraé el bíceps y mantené la posición.\nBajá la mancuerna de vuelta a la posición inicial.\nRepetí el movimiento por la cantidad de repeticiones indicadas.' WHERE name_en = 'Standing Concentration Curl';
UPDATE public.exercises SET instructions_es = 'Pará con el torso erguido sosteniendo dos mancuernas a los costados.\nApoyá la punta de los pies en una tabla de madera firme de 2 a 3 pulgadas de alto, dejando que los talones queden colgando y toquen el suelo.\nOrientá los pies hacia adelante, hacia adentro o hacia afuera según quieras enfatizar la parte externa o interna del gemelo.\nSubí los talones del suelo mientras exhalás, contrayendo los gemelos.\nMantené la contracción en la posición superior durante un segundo.\nBajá los talones lentamente hacia la posición inicial mientras inhalás.\nRepetí el movimiento la cantidad de veces recomendada.' WHERE name_en = 'Standing Dumbbell Calf Raise';
UPDATE public.exercises SET instructions_es = 'Pará con los pies separados al ancho de los hombros y tomá una mancuerna en cada mano.\nLevantá las mancuernas hasta la altura de la cabeza, con los codos hacia afuera y flexionados a 90 grados.\nMantené una técnica estricta sin empujar con las piernas ni inclinar el torso hacia atrás.\nExtendé los codos para subir los pesos juntos directamente sobre la cabeza.\nHacé una pausa y bajá los pesos lentamente hasta la posición inicial.' WHERE name_en = 'Standing Dumbbell Press';
UPDATE public.exercises SET instructions_es = 'Pará de pie con una mancuerna en cada mano, palmas hacia abajo, brazos extendidos y pies separados al ancho de los hombros.\nMantené los brazos superiores fijos y flexioná los antebrazos para subir las mancuernas mientras contraés los bíceps y exhalás.\nLlevá las mancuernas hasta la altura de los hombros, mantené la contracción un segundo y apretá el músculo.\nBajá las mancuernas lentamente hasta la posición inicial mientras inhalás.\nRepetí el movimiento la cantidad de veces recomendadas.' WHERE name_en = 'Standing Dumbbell Reverse Curl';
UPDATE public.exercises SET instructions_es = 'Recostá los mancuernas frente a tus muslos, con las palmas mirando hacia ellos.\nMantené los brazos rectos con una leve flexión en los codos, pero mantenelos bloqueados. Esta será tu posición inicial.\nEmpujá los mancuernas en un movimiento semicircular hasta la extensión completa sobre la cabeza mientras exhalás.\nVolvé lentamente a la posición inicial siguiendo el mismo camino mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Standing Dumbbell Straight-Arm Front Delt Raise Above Head';
UPDATE public.exercises SET instructions_es = 'Pará de pie sosteniendo una mancuerna con ambas manos.\nSepará los pies a la anchura de los hombros.\nAgarrá la mancuerna con las palmas hacia arriba y los pulgares alrededor de la barra.\nLevantá la mancuerna por encima de la cabeza hasta que los brazos queden completamente extendidos.\nMantené los brazos superiores pegados a la cabeza y los codos perpendiculares al suelo.\nBajá la mancuerna en un movimiento semicircular detrás de la cabeza hasta que los antebrazos toquen los bíceps.\nInspirá mientras realizás este paso.\nSubí la mancuerna de vuelta a la posición inicial usando los tríceps.\nExpirá mientras realizás este paso.\nRepetí el movimiento la cantidad de veces recomendada.' WHERE name_en = 'Standing Dumbbell Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Agarrá una mancuerna en cada mano con una agarre prono (palmas hacia adelante) ligeramente más angosto que el ancho de los hombros.\nDejá las mancuernas apoyadas sobre el muslo.\nExtendé los brazos con una leve flexión en los codos y mantené la espalda recta.\nUsá los hombros laterales para levantar las mancuernas mientras exhalás.\nMantené las mancuernas cerca del cuerpo al subir y dejá que los codos impulsen el movimiento.\nLevantá las mancuernas hasta que casi toquen la barbilla.\nMantené los codos siempre más altos que los antebrazos y el torso inmóvil.\nHacé una pausa de un segundo en la parte superior del movimiento.\nBajá las mancuernas lentamente hasta la posición inicial mientras inhalás.\nRepetí el ejercicio la cantidad de repeticiones recomendadas.' WHERE name_en = 'Standing Dumbbell Upright Row';
UPDATE public.exercises SET instructions_es = 'Pará de pie con la espalda a unos 60-90 cm de un banco o escalón.\nLevantá una pierna hacia atrás y apoyá el pie en el escalón, ya sea en el empeine o en la punta, como te resulte más cómodo.\nMantené la rodilla de apoyo ligeramente flexionada y evitá que se extienda más allá de los dedos del pie.\nCambió de lado.' WHERE name_en = 'Standing Elevated Quad Stretch';
UPDATE public.exercises SET instructions_es = 'Pará de pie con la barra en las manos, con las palmas hacia abajo y un agarre más estrecho que el ancho de los hombros.\nSepará los pies al ancho de los hombros y mantené los codos ligeramente flexionados.\nLevantá la barra hasta que quede directamente sobre tu cabeza mientras exhalás.\nMantené los codos ligeramente flexionados durante cada repetición.\nBajá la barra de vuelta a la posición inicial mientras inhalás.\nRepetí el movimiento la cantidad de veces recomendada.' WHERE name_en = 'Standing Front Barbell Raise Over Head';
UPDATE public.exercises SET instructions_es = 'Recostá el talón derecho sobre un escalón con la rodilla extendida e inclinát hacia adelante para agarrarte el dedo gordo derecho con la mano derecha.\nMantené la rodilla izquierda ligeramente flexionada y la espalda recta.\nApoyá el peso en la pierna izquierda y colocá la mano izquierda sobre el muslo izquierdo.\nJalá los dedos del pie derecho hacia la rodilla hasta sentir el estiramiento en el gemelo.' WHERE name_en = 'Standing Gastrocnemius Calf Stretch';
UPDATE public.exercises SET instructions_es = 'Recostá una correa, banda o cuerda alrededor de un pie.\nMantené ese pie hacia adelante mientras estás de pie.\nDoblá la pierna trasera, manteniendo la delantera recta.\nLevantá las puntas del pie delantero del suelo e inclinát hacia adelante.\nUsá la correa para tirar de la parte superior del pie y aumentar el estiramiento del gemelo.\nMantené la posición de 10 a 20 segundos y repetí con el otro pie.' WHERE name_en = 'Standing Hamstring and Calf Stretch';
UPDATE public.exercises SET instructions_es = 'Pará sobre una pierna, sosteniéndote de un apoyo vertical.\nLevantá la rodilla de la pierna libre hasta 90 grados.\nAbrí la cadera lo más posible, intentando trazar un gran círculo con la rodilla.\nRealizá este movimiento lentamente por varias repeticiones y repetilo en el otro lado.' WHERE name_en = 'Standing Hip Circles';
UPDATE public.exercises SET instructions_es = 'Pará de pie con la espalda recta y la columna vertical, con el pie izquierdo ligeramente adelante del derecho.\nDobá ambas rodillas y levantá el talón trasero del suelo mientras empujás la cadera derecha hacia adelante.\nNo podés lograr un estiramiento profundo en esta posición, ya que es difícil relajar el flexor de la cadera y pararte sobre él al mismo tiempo.\nCambialo de lado.' WHERE name_en = 'Standing Hip Flexors';
UPDATE public.exercises SET instructions_es = 'Parate de pie con una mancuerna en cada mano, sostenidas a la altura de los brazos.\nMantene los codos pegados al torso.\nSepará las piernas a la anchura de los hombros.\nGirá las palmas de las manos hacia adentro para adoptar una posición neutra.\nEsta será tu posición inicial.\nMientras mantenés los brazos superiores fijos, flexioná los antebrazos hacia afuera contrayendo los bíceps mientras exhalás.\nGirá las muñecas para que, al elevar completamente los pesos, tengas un agarre supinado (palmas hacia arriba).\nSolo deben moverse los antebrazos.\nContinuá el movimiento hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.\nConsejo: Mantené los antebrazos alineados con los deltoides externos.\nMantené la posición contraída durante un segundo mientras apretás los bíceps.\nComenzá a llevar las mancuernas de vuelta a la posición inicial lentamente mientras inhalás.\nRecordá girar las muñecas al bajar el peso para volver al agarre neutro.\nRepetí por la cantidad de repeticiones recomendadas.' WHERE name_en = 'Standing Inner-Biceps Curl';
UPDATE public.exercises SET instructions_es = 'Tomá una postura ligeramente más ancha que la distancia de tus caderas con las rodillas levemente flexionadas.\nColocá tu mano derecha en tu cadera derecha para apoyar la columna.\nLevantá tu brazo izquierdo en línea vertical y colocá tu mano izquierda detrás de la cabeza.\nMantené la mano en esa posición mientras inclinás el torso hacia la derecha.\nMantené el peso distribuido uniformemente entre ambas piernas (no te inclines hacia la cadera izquierda).\nCambialo de lado.' WHERE name_en = 'Standing Lateral Stretch';
UPDATE public.exercises SET instructions_es = 'Ajustá la palanca de la máquina a tu altura.\nRecostá con el torso inclinado hacia adelante entre 30 y 45 grados.\nColocá el cojín de la palanca en la parte trasera de tu pierna derecha, justo debajo de los gemelos.\nApoyá la parte frontal de la pierna derecha sobre el cojín de la máquina.\nMantené el torso inclinado hacia adelante y asegurá que la pierna esté completamente estirada.\nAgarrá los mangos laterales de la máquina.\nMantené los pies rectos.\nExhalá y flexioná la pierna derecha hacia arriba lo más que puedas sin levantar la pierna superior del cojín.\nMantené la posición de contracción máxima por un segundo.\nInhalá y volvé a la posición inicial.\nRepetí el movimiento la cantidad de repeticiones recomendadas.\nRealizá el mismo ejercicio con la pierna izquierda.' WHERE name_en = 'Standing Leg Curl';
UPDATE public.exercises SET instructions_es = 'Recostá sobre arena u otra superficie blanda para amortiguar la caída.\nAsegurate de poder medir la distancia recorrida.\nParate en una posición de sentadilla parcial con los pies separados al ancho de los hombros.\nUsá un gran balanceo de brazos y un contramovimiento de las piernas para saltar hacia adelante lo más lejos que puedas.\nIntentá aterrizar con los pies extendidos hacia adelante, estirando las piernas al máximo.\nMedí la distancia desde el punto de aterrizaje hasta el punto de partida y registrá tus resultados.' WHERE name_en = 'Standing Long Jump';
UPDATE public.exercises SET instructions_es = 'Pará a la derecha de la polea baja.\nAtrapá la manija con la mano izquierda cruzando el cuerpo con agarre prono.\nDescansá el brazo frente a vos.\nAsegurate de que tu espalda esté recta y los pies separados al ancho de los hombros.\nJalá la manija cruzando el cuerpo hasta la altura de los hombros mientras exhalás.\nSentí la contracción arriba por un segundo.\nBajá la manija lentamente a la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.\nCambialo de brazo y repetí el ejercicio.' WHERE name_en = 'Standing Low-Pulley Deltoid Raise';
UPDATE public.exercises SET instructions_es = 'Agarrá una sola manija con el brazo izquierdo junto a la máquina de polea baja.\nGirá la espalda a la máquina manteniendo la manija al costado del cuerpo con el brazo completamente extendido.\nAhora usá ambas manos para elevar la manija directamente sobre la cabeza con la palma hacia adelante.\nMantené el brazo superior completamente vertical (perpendicular al suelo) y apoyá la mano derecha en el codo izquierdo para ayudarlo a mantenerse estable.\nEsta es la posición inicial.\nMantené los brazos superiores cerca de la cabeza (codos adentro) y perpendiculares al suelo, y bajá la resistencia en un movimiento semicircular detrás de la cabeza hasta que los antebrazos toquen los bíceps.\nConsejo: Los brazos superiores deben permanecer estacionarios y solo los antebrazos deben moverse.\nInspirá mientras realizás este paso.\nVolvé a la posición inicial usando los tríceps para levantar la manija.\nExpirá mientras realizás este paso.\nRepetí por la cantidad de repeticiones recomendadas.\nCambió de brazo y repetí el ejercicio.' WHERE name_en = 'Standing Low-Pulley One-Arm Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Colocá una barra en un rack a la altura del pecho.\nElegí los pesos y agarrá la barra con una pronada (palmas hacia adelante).\nAsegurate de que el agarre sea más ancho que el ancho de los hombros.\nDoblá levemente las rodillas y apoyá la barra en la clavícula.\nLevantá la barra manteniéndola apoyada en el pecho.\nDá un paso atrás y separá los pies a la anchura de los hombros.\nLevantá la barra por encima de la cabeza bloqueando los brazos.\nMantené la barra a la altura de los hombros y ligeramente adelante de la cabeza.\nBajá la barra lentamente hasta la clavícula mientras inhalás.\nLevantá la barra de vuelta a la posición inicial mientras exhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Standing Military Press';
UPDATE public.exercises SET instructions_es = 'Pará de pie con los pies separados a la anchura de los hombros.\nSujetá una placa de peso por el borde con cada mano, a la altura de los brazos, con las palmas mirándose.\nBajá las placas hasta que los dedos estén casi extendidos pero sigan sujetando el peso.\nInspirá mientras bajás las placas.\nLevantá las placas de vuelta a la posición inicial cerrando las manos.\nExpirá mientras levantás las placas.\nRepetí la cantidad de repeticiones indicadas en tu programa.' WHERE name_en = 'Standing Olympic Plate Hand Squeeze';
UPDATE public.exercises SET instructions_es = 'Agarrá la manija individual junto a la polea baja. Asegurate de estar lo suficientemente lejos de la máquina para que tu brazo soporte el peso.\nMantené el brazo superior inmóvil, perpendicular al suelo, con los codos pegados al cuerpo y las palmas hacia adelante. Tu brazo no dominante debe agarrarte la cintura para mantener el equilibrio.\nIniciá lentamente el curl hacia arriba manteniendo el brazo superior fijo hasta que tu antebrazo toque el bíceps, mientras exhalás. Recordá que solo debe moverse el antebrazo.\nMantené la posición de contracción apretando el bíceps y luego bajá la manija lentamente hasta la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.\nCambiá de brazo al realizar este ejercicio.' WHERE name_en = 'Standing One-Arm Cable Curl';
UPDATE public.exercises SET instructions_es = 'Parate detrás del banco inclinado como si fueras a asistir a alguien.\nSujetá una mancuerna en una mano con la palma hacia arriba y apoyala sobre el banco.\nApoyá la mano que no levanta en la esquina o el lateral del banco.\nPresioná el pecho contra la parte superior del banco y apoyá los pies en el suelo con una postura amplia.\nMantené el brazo superior quieto y doblá el antebrazo hacia arriba mientras contraés el bíceps y exhalás.\nMové solo el antebrazo hasta que el bíceps esté completamente contraído y la mancuerna llegue a la altura del hombro.\nMantené la posición contraída por un segundo.\nBajá lentamente la mancuerna hasta la posición inicial mientras inhalás.\nRepetí el movimiento la cantidad de veces recomendadas.\nCambiate de brazo al realizar este ejercicio.' WHERE name_en = 'Standing One-Arm Dumbbell Curl Over Incline Bench';
UPDATE public.exercises SET instructions_es = 'Pará de pie con una mancuerna en una mano, con los pies separados a la anchura de los hombros.\nExtendé completamente el brazo con la mancuerna sobre la cabeza, con el meñique mirando al techo y la palma hacia adelante.\nMantené el brazo superior pegado a la cabeza y perpendicular al suelo.\nBajá la resistencia en un movimiento semicircular detrás de la cabeza hasta que el antebrazo toque el bíceps, respirando por la nariz.\nSubí la mancuerna de vuelta a la posición inicial usando los tríceps, respirando por la boca.\nRepetí el movimiento la cantidad de veces recomendadas.\nCambió de brazo y repetí el ejercicio.' WHERE name_en = 'Standing One-Arm Dumbbell Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Pará de pie sosteniendo una barra o barra EZ con agarre prono (palmas hacia adelante) y las manos más cerca que el ancho de los hombros.\nSepará los pies a la anchura de los hombros.\nElevá la barra sobre tu cabeza hasta que los brazos estén completamente extendidos.\nMantené los codos pegados al cuerpo.\nMantené los brazos superiores cerca de la cabeza y los codos perpendiculares al suelo.\nBajá la resistencia en un movimiento semicircular detrás de la cabeza hasta que los antebrazos toquen los bíceps.\nMantené los brazos superiores estacionarios y mové solo los antebrazos.\nInspirá mientras realizás este paso.\nVolvé a la posición inicial usando los tríceps para subir la barra.\nExpirá mientras realizás este paso.\nRepetí por la cantidad de repeticiones recomendadas.' WHERE name_en = 'Standing Overhead Barbell Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Recostá tu mano libre en el banco inclinado para mantener el equilibrio.\nColocá los pies separados a la anchura de los hombros.\nExtendé el brazo con la mancuerna a un lado del cuerpo con agarre neutro.\nMantené el antebrazo perpendicular al suelo.\nSubí la mancuerna lentamente hasta que tu brazo quede completamente extendido.\nInhalá y bajá el peso hasta formar un ángulo de 90 grados con el brazo.\nSentí la contracción durante un segundo.\nExhalá y levantá el peso de vuelta a la posición inicial.\nMantené el agarre en el banco y la posición de los pies para conservar el equilibrio.\nRepetí el movimiento la cantidad de veces recomendadas.\nCambió de brazo y repetí el ejercicio.' WHERE name_en = 'Standing Palm-In One-Arm Dumbbell Press';
UPDATE public.exercises SET instructions_es = 'Recostá los pies a la anchura de los hombros y sostené una mancuerna en cada mano con el brazo extendido lateralmente y agarre neutro.\nMantené el agarre neutro durante todo el ejercicio.\nEmpujá las mancuernas hacia arriba hasta que los brazos queden completamente extendidos.\nInspirá y bajá los pesos lentamente hasta que el brazo vuelva a formar un ángulo de 90 grados.\nRepetí el movimiento la cantidad de repeticiones recomendadas.' WHERE name_en = 'Standing Palms-In Dumbbell Press';
UPDATE public.exercises SET instructions_es = 'Pará de pie con los pies separados al ancho de los hombros y mirá hacia adelante.\nSujetá la barra detrás de los glúteos a la altura de los brazos con agarre prono (palmas hacia atrás) y manos al ancho de los hombros.\nExhalá y elevá la barra lentamente flexionando la muñeca en un movimiento semicircular hacia el techo.\nMové únicamente la muñeca durante la elevación.\nMantené la contracción un segundo.\nInhalá y bajá la barra hasta la posición inicial.\nRepetí el movimiento la cantidad de repeticiones recomendadas.\nAl terminar, bajá la barra al suelo o a la rack de sentadillas flexionando las rodillas.' WHERE name_en = 'Standing Palms-Up Barbell Behind The Back Wrist Curl';
UPDATE public.exercises SET instructions_es = 'Pará con los pies separados a la anchura de las caderas.\nDoblá levemente las rodillas para mantenerlas suaves y elásticas.\nMové la pelvis hacia adelante y hacia atrás unas pocas veces antes de mantener el coxal hacia adelante en esta estirada.' WHERE name_en = 'Standing Pelvic Tilt';
UPDATE public.exercises SET instructions_es = 'Ajustá una cuerda a una polea alta y elegí un peso adecuado.\nParate de espaldas a la torre de cables. Tomá la cuerda con ambas manos por encima de los hombros, sosteniéndola contra el pecho superior. Esta será tu posición inicial.\nRealizá el movimiento flexionando la columna vertebral, bajando el peso lo más que puedas.\nMantené la contracción máxima un momento antes de volver a la posición inicial.' WHERE name_en = 'Standing Rope Crunch';
UPDATE public.exercises SET instructions_es = 'Pará con los pies separados a la distancia de las caderas, uno ligeramente adelante del otro.\nDoblá ambas rodillas, manteniendo el talón trasero en el suelo.\nCambialo de lado.' WHERE name_en = 'Standing Soleus And Achilles Stretch';
UPDATE public.exercises SET instructions_es = 'Pará con espacio libre adelante y atrás.\nIncliná el tronco hacia adelante manteniendo las piernas rectas hasta que el cuerpo superior cuelgue relajado.\nDejá que los brazos y las manos caigan de forma natural.\nMantené la posición de 10 a 20 segundos.' WHERE name_en = 'Standing Toe Touches';
UPDATE public.exercises SET instructions_es = 'Pará de pie con los brazos extendidos por encima de la cabeza, sosteniendo un extremo de la toalla con ambas manos.\nMantené los codos hacia adentro, los brazos perpendiculares al suelo y las palmas mirándose, con los pies separados a la anchura de los hombros.\nCoordiná con tu pareja para que agarre el otro extremo de la toalla y aplique resistencia.\nBajá la resistencia en un movimiento semicircular detrás de la cabeza hasta que tus antebrazos toquen tus bíceps, manteniendo los brazos superiores estacionarios y cerca de la cabeza.\nRespirá mientras realizás este paso.\nRetorná a la posición inicial usando los tríceps para levantar la toalla.\nExhalá mientras realizás este paso.\nRepetí el movimiento la cantidad de veces recomendada.' WHERE name_en = 'Standing Towel Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Pará con los pies separados a la anchura de los hombros sosteniendo una pelota medicinal con ambas manos.\nLlevá la pelota profundamente detrás de la cabeza mientras flexionás levemente las rodillas y te inclinás hacia atrás.\nLanzá la pelota hacia adelante con fuerza, flexionando la cadera y usando todo el cuerpo para completar el movimiento.\nPodés lanzar la pelota a un compañero o a una pared, y recibila cuando rebote.' WHERE name_en = 'Standing Two-Arm Overhead Throw';
UPDATE public.exercises SET instructions_es = 'Pará de pie con los pies separados a la anchura de los hombros y mantené los brazos pegados al cuerpo.\nAgachate a la mitad y saltá hacia arriba con fuerza, extendiendo todo el cuerpo y separando las piernas y los brazos.\nAl aterrizar, juntá las extremidades y absorbé el impacto con las piernas.' WHERE name_en = 'Star Jump';
UPDATE public.exercises SET instructions_es = 'Pará frente a una caja o banco de altura adecuada con los pies juntos.\nSubí colocando el pie izquierdo sobre el banco.\nExtendé la cadera y la rodilla de la pierna delantera para ponerte de pie sobre la caja.\nMientras estás de pie sobre la caja con la pierna izquierda, flexioná la rodilla y la cadera de la pierna derecha llevando la rodilla lo más alto posible.\nInvertí el movimiento para bajar de la caja.\nRepetí la secuencia con la pierna opuesta.' WHERE name_en = 'Step-up with Knee Raise';
UPDATE public.exercises SET instructions_es = 'Subí a la escalera mecánica y elegí la opción deseada del menú.\nSeleccioná una configuración manual o un programa para ejecutar.\nIngresá tu edad y peso para estimar las calorías quemadas durante el ejercicio.\nTené cuidado para no tropezar mientras subís las escaleras.\nMantené el agarre en los mangos para no caerte.' WHERE name_en = 'Step Mill';
UPDATE public.exercises SET instructions_es = 'Agarrá la barra con un agarre prono (palmas hacia abajo). Podés necesitar vendajes de muñeca si usás mucho peso.\nPará con el torso recto y las piernas separadas a la anchura de los hombros o menos. Mantené las rodillas ligeramente flexionadas. Esta es tu posición inicial.\nMantené las rodijas estacionarias y bajá la barra por encima de los pies flexionando las caderas mientras mantenés la espalda recta. Seguí moviéndote hacia adelante como si fueras a agarrar algo del suelo hasta sentir un estiramiento en los isquiotibiales. Inspirá mientras realizás este movimiento.\nComenzá a enderezar el torso extendiendo las caderas hasta volver a la posición inicial. Expirá mientras realizás este movimiento.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Stiff-Legged Barbell Deadlift';
UPDATE public.exercises SET instructions_es = 'Agarrá un par de mancuernas sosteniéndolas a los lados de tu cuerpo a la altura de los brazos.\nParate con el torso recto y las piernas separadas a la anchura de los hombros o menos. Mantené las rodillas ligeramente flexionadas. Esta es tu posición inicial.\nMantené las rodijas estacionarias y bajá las mancuernas por encima de los pies flexionando la cintura mientras mantenés la espalda recta. Seguí moviéndote hacia adelante como si fueras a tomar algo del suelo hasta que sientas un estiramiento en los isquiotibiales. Exhalá mientras realizás este movimiento.\nComenzá a enderezar el torso extendiendo las caderas y la cintura hasta volver a la posición inicial. Inhalá mientras realizás este movimiento.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Stiff-Legged Dumbbell Deadlift';
UPDATE public.exercises SET instructions_es = 'Ajustá la barra en el rack a la altura que mejor se adapte a tu estatura.\nCargá la barra y pasá por debajo de ella, apoyándola en la parte posterior de los hombros, justo debajo del cuello.\nSujetá la barra con ambas manos y levantala del rack empujando con las piernas mientras enderezás el torso.\nDale un paso hacia atrás y separá las piernas a la anchura de los hombros.\nMantené la cabeza en alto y la espalda recta para establecer tu posición inicial.\nIncliná el torso hacia adelante flexionando las caderas mientras inhalás, manteniendo las piernas fijas.\nBajá el torso hasta que quede paralelo al suelo.\nExhalá y elevá el torso de vuelta a la posición inicial.\nRepetí el movimiento la cantidad de veces recomendada.' WHERE name_en = 'Stiff Leg Barbell Good Morning';
UPDATE public.exercises SET instructions_es = 'Pará de pie con los pies separados al ancho de los hombros.\nApoyá las manos en las caderas.\nInhalá lo más posible y luego exhalá mientras metés el abdomen hacia adentro.\nMantené esta posición visualizando que tu ombligo toca la columna.\nDurante los 20 segundos de contracción, respirá con normalidad.\nInhalá y volvé el abdomen a la posición inicial.\nAumentá progresivamente la duración hasta 40-60 segundos.\nRepetí la cantidad de series recomendadas.' WHERE name_en = 'Stomach Vacuum';
UPDATE public.exercises SET instructions_es = 'Colocá una mancuerna de pie sobre un banco plano.\nAsegurate de que la mancuerna quede firme en la parte superior del banco.\nRecostate perpendicular al banco, con el torso cruzándolo formando una cruz, apoyando solo los hombros en la superficie.\nMantené las caderas por debajo del banco, las piernas flexionadas y los pies firmes en el suelo.\nDejá que la cabeza quede fuera del banco.\nAgarrá la mancuerna con ambas manos y sostenela recta sobre el pecho a la extensión de los brazos.\nPresioná las palmas contra la parte inferior de un lado de la mancuerna.\nMantené esta posición inicial.\nBajá el peso lentamente en un arco detrás de la cabeza mientras inhalás hasta sentir el estiramiento en el pecho.\nLlevá la mancuerna de vuelta a la posición inicial siguiendo el mismo arco mientras exhalás.\nMantené el peso en la posición inicial durante un segundo.\nRepetí el movimiento la cantidad de repeticiones indicadas.' WHERE name_en = 'Straight-Arm Dumbbell Pullover';
UPDATE public.exercises SET instructions_es = 'Agarrá la barra ancha desde el polea superior con un agarre prono (palmas hacia abajo) más ancho que los hombros.\nRetretá dos pies hacia atrás.\nIncliná el torso hacia adelante unos 30 grados desde la cintura, con los brazos completamente extendidos frente a vos y una leve flexión en los codos.\nSi los brazos no están totalmente extendidos, retrocedé un poco más hasta que lo estén.\nUna vez que los brazos estén extendidos y el torso ligeramente inclinado, tensá los dorsales y preparate para empezar.\nMientras mantenés los brazos rectos, empujá la barra hacia abajo contrayendo los dorsales hasta que las manos queden junto a los muslos.\nExhalá mientras realizás este paso.\nMientras mantenés los brazos rectos, volvé a la posición inicial inhalando.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Straight-Arm Pulldown';
UPDATE public.exercises SET instructions_es = 'Recostá la barra cargada en el extremo de un banco.\nParate en el banco detrás de la barra y agarre con una toma media y prona.\nMantené la cadera hacia atrás, el pecho arriba y la columna neutra como posición inicial.\nRemá la barra hacia el torso retraiendo las escápulas y flexionando los codos.\nControlá el movimiento sin dar tirones.\nHacé una pausa breve y devolvé la barra lentamente a la posición inicial bajando por completo.' WHERE name_en = 'Straight Bar Bench Mid Rows';
UPDATE public.exercises SET instructions_es = 'Colocá la barra en el suelo detrás de la cabeza de un banco inclinado.\nRecostá boca abajo en el banco.\nCon agarre prono, levantá la barra del suelo manteniendo los brazos rectos.\nDejá que la barra cuelgue recta hacia abajo.\nEsta será tu posición inicial.\nPara comenzar, levantá la barra hacia adelante de tu cabeza manteniendo los brazos extendidos.\nVolvé a la posición inicial.' WHERE name_en = 'Straight Raises on Incline Bench';
UPDATE public.exercises SET instructions_es = 'Parate al lado de la caja con el pie interno sobre ella, cerca del borde.\nComenzá balanceando los brazos hacia arriba mientras empujás con la pierna superior, saltando hacia arriba lo más alto posible. Intentá llevar la rodilla opuesta hacia arriba.\nAterrizar en la posición opuesta a la inicial, en el otro lado de la caja. El pie que estaba sobre la caja ahora estará en el suelo, con el pie opuesto ahora sobre la caja.\nRepetí el movimiento, cruzando de vuelta al otro lado.' WHERE name_en = 'Stride Jump Crossover';
UPDATE public.exercises SET instructions_es = 'Recostá la barra cargada en el suelo.\nAcercate a la barra para que cruce el medio de los pies.\nSepará los pies muy abiertos, cerca de los collares.\nDoblete las caderas para agarrar la barra.\nMantené los brazos directamente debajo de los hombros, dentro de las piernas, usando agarre prono, mixto o de gancho.\nRelajá los hombros para alargar los brazos.\nTomá aire y bajá las caderas, mirando al frente con el pecho arriba.\nEmpujá contra el suelo, separando los pies, con el peso en la parte trasera de los pies.\nExtendé las caderas y las rodillas.\nCuando la barra pase las rodillas, recostate hacia atrás y empujá las caderas contra la barra, juntando las escápulas.\nDevolvé el peso al suelo doblando las caderas y controlando la bajada.' WHERE name_en = 'Sumo Deadlift';
UPDATE public.exercises SET instructions_es = 'Envolvé las bandas cortas sobre la barra antes de empezar y entrá en ellas para ubicarte.\nAsegurate de que queden bajo la mitad trasera del pie, justo donde empujás contra el suelo.\nComenzá con la barra cargada en el suelo.\nAcercate a la barra para que cruce el centro de los pies.\nSepará los pies muy ancho, cerca de los topeadores.\nIncliná la cadera para agarrar la barra.\nMantené los brazos directamente debajo de los hombros, dentro de las piernas, y usá un agarre prono, mixto o de gancho.\nTomá aire y bajá la cadera, mirando al frente con el pecho arriba.\nEmpujá contra el suelo, separando los pies, con el peso en la mitad trasera de los pies.\nExtendé la cadera y las rodillas.\nCuando la barra pase por las rodillas, echate hacia atrás y empujá la cadera contra la barra, juntando las escápulas.\nDevolvé el peso al suelo flexionando la cadera y controlando la bajada.' WHERE name_en = 'Sumo Deadlift with Bands';
UPDATE public.exercises SET instructions_es = 'Ajustá las cadenas a las mangas de la barra o colgá el centro sobre ella para aumentar el peso al levantar.\nMantené los extremos de las cadenas alejados de las pesas para no golpearlas al bajar.\nIniciá con la barra cargada en el suelo.\nAcercate para que la barra cruce el medio de los pies.\nSepará los pies muy ancho, cerca de los topeadores.\nIncliná la cadera para agarrar la barra.\nColocá los brazos directamente debajo de los hombros, dentro de las piernas, usando agarre prono, mixto o de gancho.\nRelajá los hombros para alargar los brazos.\nRespirá y bajá la cadera mirando al frente con el pecho arriba.\nEmpujá contra el suelo separando los pies, con el peso en la parte trasera.\nExtendé la cadera y las rodillas.\nAl pasar la barra por las rodillas, echate hacia atrás y empujá la cadera contra la barra.\nJuntá las escápulas.\nVolvé la carga al suelo flexionando la cadera y controlando la bajada.' WHERE name_en = 'Sumo Deadlift with Chains';
UPDATE public.exercises SET instructions_es = 'Recostá boca abajo en el piso o la colchoneta con los brazos extendidos hacia adelante.\nLevantá simultáneamente los brazos, las piernas y el pecho del piso y mantené la contracción durante 2 segundos.\nApretá la zona lumbar y exhalá durante este movimiento.\nBajá lentamente los brazos, las piernas y el pecho hasta la posición inicial mientras inhalás.\nRepetí la cantidad de veces indicadas en tu programa.' WHERE name_en = 'Superman';
UPDATE public.exercises SET instructions_es = 'Recostá en el suelo boca arriba con las rodillas flexionadas.\nColocá la pelota sobre el pecho sosteniéndola con ambas manos por abajo.\nEmpujá hacia arriba extendiendo los codos para lanzar la pelota directamente sobre tu cabeza lo más alto posible.\nAtrapá la pelota con ambas manos cuando baje.' WHERE name_en = 'Supine Chest Throw';
UPDATE public.exercises SET instructions_es = 'Recostá en el suelo boca arriba con las rodillas flexionadas.\nSujetá la pelota con una mano y extendé el brazo por completo detrás de la cabeza.\nIniciá el movimiento desde el hombro, lanzá la pelota directamente hacia adelante mientras te sentás, buscando la máxima distancia.\nPodés lanzar la pelota a un compañero o rebotarla contra una pared.' WHERE name_en = 'Supine One-Arm Overhead Throw';
UPDATE public.exercises SET instructions_es = 'Recostá en el suelo boca arriba con las rodillas flexionadas.\nSujetá la pelota con ambas manos y extendé los brazos por completo detrás de la cabeza.\nIniciá el movimiento desde el hombro, lanzá la pelota directamente hacia adelante mientras te sentás, buscando la máxima distancia.\nPodés lanzar la pelota a un compañero o rebotarla contra una pared.' WHERE name_en = 'Supine Two-Arm Overhead Throw';
UPDATE public.exercises SET instructions_es = 'Ajustá las correas para que los agarres queden a la altura adecuada, por debajo de la cintura.\nComenzá de pie agarrando los mangos.\nIncliná el cuerpo hacia las correas hasta adoptar la posición de flexión inclinada.\nMantené los brazos rectos.\nIncliná más el cuerpo hacia las correas para acercarte al suelo.\nDejá que los hombros se extiendan y llevá los brazos por encima de la cabeza.\nMantené la columna neutra y el resto del cuerpo recto.\nMové únicamente los hombros.\nHacé una pausa en la contracción máxima.\nVolvé a la posición inicial.' WHERE name_en = 'Suspended Fallout';
UPDATE public.exercises SET instructions_es = 'Anclá las correas de suspensión de forma segura en la parte superior de una rack u otro objeto.\nIncliná el cuerpo hacia las correas, tomá un mango en cada mano y pasá a una posición de plancha para flexiones.\nDeberías estar lo más cerca posible de ser paralelo al suelo con los brazos completamente extendidos, manteniendo una buena postura.\nMantené el torso recto y rígido, y descendé lentamente permitiendo que los codos se flexionen.\nContinuá hasta que los codos superen los 90 grados, hacé una pausa antes de extender los brazos para volver a la posición inicial.' WHERE name_en = 'Suspended Push-Up';
UPDATE public.exercises SET instructions_es = 'Asegurá un juego de correas de suspensión con las asas a unos 30 cm del suelo.\nColocáte en posición de plancha para flexiones mirando hacia atrás respecto al soporte.\nIngresá los pies en las asas manteniendo la postura recta sin dejar que la cadera se hunda.\nIniciá el movimiento flexionando las rodillas y la cadera, llevando las rodillas hacia el torso.\nIncliná la pelvis hacia adelante permitiendo que la columna se flexione.\nAl llegar al punto más alto del movimiento controlado, volvé a la posición inicial.' WHERE name_en = 'Suspended Reverse Crunch';
UPDATE public.exercises SET instructions_es = 'Suspendé tus correas a la altura del pecho.\nTomá un mango en cada mano y recostá hacia atrás.\nMantené el cuerpo erguido con la cabeza y el pecho arriba.\nExtendé completamente los brazos para la posición inicial.\nFlexioná los codos para iniciar el movimiento.\nProtrayé las escápulas mientras lo hacés.\nHacé una pausa al completar el movimiento.\nVolvé a la posición inicial.' WHERE name_en = 'Suspended Row';
UPDATE public.exercises SET instructions_es = 'Ajustá las correas para que los mangos queden a 45-75 cm del suelo.\nColocá el pie trasero en el mango detrás de vos, mirá al frente, mantené el pecho arriba y la rodilla ligeramente flexionada.\nDescendé flexionando la rodilla y la cadera, bajando hacia el suelo.\nMantené el peso en el talón y la postura durante todo el movimiento.\nInvertí el movimiento extendiendo la cadera y la rodilla para volver a la posición inicial.' WHERE name_en = 'Suspended Split Squat';
UPDATE public.exercises SET instructions_es = 'Pará de pie.\nApretá dos discos livianos entre tus manos.\nMantené los discos juntos cerca del pecho para crear una contracción isométrica en los músculos del pecho.\nApuntá los dedos hacia adelante.\nApretá los discos entre las palmas y extendé los brazos directamente hacia adelante con un movimiento controlado.\nHacé una pausa en la parte superior del movimiento.\nVolvé lentamente a la posición inicial.' WHERE name_en = 'Svend Press';
UPDATE public.exercises SET instructions_es = 'Colocá la barra en una landmine o en una esquina para que no se mueva y cargá el peso adecuado en tu extremo.\nPará sobre la barra y posicioná una manija de doble D alrededor de la barra junto al tope.\nAsumí una postura amplia con las caderas hacia atrás y el pecho arriba, manteniendo los brazos extendidos como posición inicial.\nJalá el peso hacia el abdomen superior retraciendo las escápulas y flexionando los codos, sin hacer movimientos bruscos ni trampas.\nHacé una pausa breve y volvé a la posición inicial.' WHERE name_en = 'T-Bar Row with Handle';
UPDATE public.exercises SET instructions_es = 'Recostate en un banco plano con una mancuerna en cada mano sobre los muslos.\nMantené las palmas de las manos mirándose entre sí.\nUsá los muslos para ayudar a subir las mancuernas y limpiá una a la vez hasta sostenerlas frente a vos a la anchura de los hombros.\nAsegurate de que los brazos estén más separados que la anchura de los hombros con un agarre prono (palmas hacia adelante) y permití que los codos apunten hacia afuera.\nMantené los brazos superiores estacionarios y mové las mancuernas hacia adentro y abajo en un movimiento semicircular hasta que toquen el pecho superior mientras inhalás.\nMantené el control total de las mancuernas en todo momento y no movás los brazos superiores ni apoyés las mancuernas en el pecho.\nExhalá y subí las mancuernas usando los tríceps en el mismo movimiento semicircular pero en reversa.\nIntentá mantener las mancuernas juntas mientras suben.\nBloqueá los brazos en la posición contraída, mantené por un segundo y empezá a bajar lentamente de nuevo.\nAsegurate de que el descenso tome al menos el doble de tiempo que la subida.\nRepetí el movimiento por la cantidad de repeticiones prescritas en tu programa de entrenamiento.' WHERE name_en = 'Tate Press';
UPDATE public.exercises SET instructions_es = 'Sentate erguido.\nExtendé las piernas hacia adelante formando una V.\nApoyá las manos en el suelo.\nIncliná el torso hacia adelante lo más que puedas.\nMantené la posición de 10 a 20 segundos.' WHERE name_en = 'The Straddle';
UPDATE public.exercises SET instructions_es = 'Sentate en la máquina de abductores y elegí un peso con el que te sientas cómodo.\nColocá tus piernas correctamente y agarrá los mangos de cada lado.\nMantené todo tu cuerpo superior (desde la cintura hacia arriba) inmóvil.\nEmpujá lentamente contra la máquina con las piernas para separarlas mientras exhalás.\nSentí la contracción durante un segundo y volvé a llevar las piernas a la posición inicial mientras inhalás.\nRecordá mantener el cuerpo superior inmóvil para evitar lesiones.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Thigh Abductor';
UPDATE public.exercises SET instructions_es = 'Sentate en la máquina de aductores y elegí un peso con el que te sientas cómodo.\nColocá tus piernas correctamente sobre los apoyos de la máquina y agarrá los mangos de cada lado.\nMantené todo tu cuerpo superior (desde la cintura hacia arriba) inmóvil.\nEmpujá lentamente contra la máquina con las piernas para acercarlas mientras exhalás.\nSentí la contracción durante un segundo y volvé a la posición inicial mientras inhalás.\nRecordá mantener el cuerpo superior inmóvil y evitar movimientos bruscos para prevenir lesiones.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Thigh Adductor';
UPDATE public.exercises SET instructions_es = 'Agarrá la parte inferior del neumático por la banda de rodadura y separá los pies hacia atrás.\nApoyá el pecho contra el neumático.\nExtendé caderas, rodillas y tobillos para empujar el neumático hacia arriba.\nCuando el neumático llegue a un ángulo de 45 grados, avanzá un paso y empujá una rodilla contra el neumático.\nAjustá el agarre a la parte superior del neumático y empujalo hacia adelante con toda tu fuerza para completar la vuelta.\nRepetí las veces que sea necesario.' WHERE name_en = 'Tire Flip';
UPDATE public.exercises SET instructions_es = 'Recostá en el suelo o en una colchoneta con la espalda apoyada.\nExtendé los brazos a los costados con las palmas hacia abajo.\nMantené las piernas juntas.\nElevá lentamente las piernas hasta que queden casi perpendiculares al suelo con una leve flexión en las rodillas.\nMantené los pies paralelos al suelo.\nExtendé los brazos completamente a un ángulo de 45 grados respecto al suelo.\nMantené la zona lumbar presionada contra el suelo.\nElevá lentamente el torso e intentá tocar las puntas de los pies con las manos.\nExhalá mientras realizás esta parte del ejercicio.\nBajá lentamente el torso y los brazos hasta la posición inicial.\nInhalá mientras bajás.\nMantené los brazos extendidos apuntando hacia las puntas de los pies.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Toe Touchers';
UPDATE public.exercises SET instructions_es = 'Parate de pie sosteniendo la pelota de ejercicio con ambas manos.\nExtendé los brazos para que la pelota quede recta frente a vos.\nGirá el torso hacia un lado, manteniendo la mirada en la pelota.\nGirá de vuelta hacia el lado opuesto.\nRepetí de 10 a 20 veces.' WHERE name_en = 'Torso Rotation';
UPDATE public.exercises SET instructions_es = 'Calentá la sangre y acelerá el corazón corriendo o caminando por senderos.\nUsá zapatillas de buena calidad.\nSubí la colina empujando con los gemelos y los glúteos.\nAterrizar con las rodillas, articulaciones y tobillos al bajar.\nDá pasos más cortos al caminar cuesta abajo.\nMantené las rodillas flexionadas para reducir el impacto.\nBajá la velocidad para evitar caídas.' WHERE name_en = 'Trail Running/Walking';
UPDATE public.exercises SET instructions_es = 'Cargá la barra hexagonal con un peso adecuado y dejala en el suelo.\nPará en el centro del aparato y agarrá ambos mangos.\nBajá las caderas, mirá al frente y mantené el pecho arriba.\nIniciá el movimiento empujando con los talones y extendé las caderas y las rodillas.\nEvitá redondear la espalda en todo momento.\nAl completar el movimiento, bajá el peso al suelo con control.' WHERE name_en = 'Trap Bar Deadlift';
UPDATE public.exercises SET instructions_es = 'Tomá una mancuerna en cada mano con las palmas mirando hacia tu torso.\nMantené la espalda recta con una leve flexión en las rodillas.\nIncliná el torso hacia adelante desde la cintura hasta que quede casi paralelo al suelo.\nMantené la cabeza en alto.\nAcerká los brazos superiores al torso manteniéndolos paralelos al suelo.\nApuntá los antebrazos hacia el suelo sosteniendo los pesos.\nFormá un ángulo de 90 grados entre el antebrazo y el brazo superior.\nMantené los brazos superiores estacionarios.\nExhalá y usá los tríceps para empujar los pesos hasta extender completamente el brazo.\nConcentrate en mover solo el antebrazo.\nHacé una breve pausa en la contracción superior.\nInhalá y bajá lentamente las mancuernas hasta la posición inicial.\nRepetí el movimiento por la cantidad de repeticiones indicadas.' WHERE name_en = 'Tricep Dumbbell Kickback';
UPDATE public.exercises SET instructions_es = 'Recostá y cruzá el brazo derecho por encima del cuerpo hasta el hombro izquierdo.\nSujetá el codo con la mano izquierda.\nMantené la posición hasta sentir el estiramiento en el tríceps.\nRepetí el movimiento con el otro brazo.' WHERE name_en = 'Tricep Side Stretch';
UPDATE public.exercises SET instructions_es = 'Ajustá una cuerda a una polea baja.\nElegí un peso adecuado, agarrá la cuerda con ambas manos y mirá hacia atrás, alejándote del cable.\nColocá las manos detrás de la cabeza con los codos apuntando hacia arriba.\nMantené los codos flexionados, separá los pies y inclináté ligeramente hacia atrás para mayor estabilidad.\nExtendé los codos manteniendo los brazos superiores fijos, llevando las manos por encima de la cabeza.\nApretá los tríceps en la parte superior del movimiento.\nBajá el peso lentamente hasta la posición inicial.' WHERE name_en = 'Triceps Overhead Extension with Rope';
UPDATE public.exercises SET instructions_es = 'Colocá una barra recta o angulada en una polea alta y agarrala con un agarre prono (palmas hacia abajo) a la anchura de los hombros.\nPará de pie con el torso recto y una leve inclinación hacia adelante, acercá los brazos superiores al cuerpo y mantenelos perpendiculares al suelo, con los antebrazos apuntando hacia la polea.\nUsando los tríceps, bajá la barra hasta que toque la parte frontal de los muslos y los brazos queden completamente extendidos perpendiculares al suelo, manteniendo los brazos superiores fijos junto al torso y moviendo solo los antebrazos, exhalando durante el movimiento.\nMantené la posición contraída por un segundo y subí la barra lentamente hasta el punto de partida, inhalando durante este paso.\nRepetí el ejercicio por la cantidad de repeticiones recomendadas.' WHERE name_en = 'Triceps Pushdown';
UPDATE public.exercises SET instructions_es = 'Ajustá un accesorio de cuerda a una polea alta y agarralo con agarre neutro (palmas mirándose).\nParate erguido con el torso recto y una inclinación muy leve hacia adelante, acercá los brazos superiores al cuerpo y perpendiculares al suelo.\nMantené los antebrazos apuntando hacia la polea sosteniendo la cuerda con las palmas mirándose; esta es tu posición inicial.\nUsando los tríceps, bajá la cuerda llevando cada lado hacia el costado de los muslos.\nAl final del movimiento, los brazos deben estar completamente extendidos y perpendiculares al suelo.\nMantené los brazos superiores siempre estacionarios junto al torso y mové solo los antebrazos.\nExhalá mientras realizás este movimiento.\nMantené la posición contraída durante un segundo.\nSubí la cuerda lentamente hasta el punto de partida.\nInhalá mientras realizás este paso.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Triceps Pushdown - Rope Attachment';
UPDATE public.exercises SET instructions_es = 'Ajustá una barra en V a una polea alta y agarrala con agarre prono (palmas hacia abajo) a la anchura de los hombros.\nPará de pie con el torso recto y una inclinación muy leve hacia adelante, acercá los brazos superiores al cuerpo y mantenelos perpendiculares al suelo.\nDejá que los antebrazos apunten hacia arriba hacia la polea sosteniendo la barra, asegurándote de que los pulgares queden más altos que los meñiques.\nUsando los tríceps, empujá la barra hacia abajo hasta que toque la parte frontal de los muslos y los brazos queden completamente extendidos perpendiculares al suelo.\nMantené los brazos superiores siempre estacionarios junto al torso y mové solo los antebrazos, exhalando mientras realizás este movimiento.\nMantené la posición contraída durante un segundo y luego subí la barra en V lentamente hasta el punto de partida, inhalando mientras realizás esta fase.\nRepetí el ejercicio por la cantidad de repeticiones recomendadas.' WHERE name_en = 'Triceps Pushdown - V-Bar Attachment';
UPDATE public.exercises SET instructions_es = 'Llevá la mano detrás de la cabeza\nAgarrá el codo\nJalá suavemente\nMantené de 10 a 20 segundos\nCambialo de lado' WHERE name_en = 'Triceps Stretch';
UPDATE public.exercises SET instructions_es = 'Recostá sobre el suelo o una colchoneta con la espalda apoyada.\nDejá los brazos a los lados con las palmas hacia abajo.\nCruzá las piernas envolviendo un tobillo alrededor del otro.\nElevá lentamente las piernas hasta que los muslos queden perpendiculares al suelo con una leve flexión en las rodillas.\nMantené las rodillas y los pies paralelos al suelo.\nMové los brazos desde el suelo y cruzalos para que descansen sobre el pecho.\nMantené la parte baja de la espalda presionada contra el suelo.\nElevá lentamente el torso mientras exhalás.\nBajá lentamente el torso hasta la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Tuck Crunch';
UPDATE public.exercises SET instructions_es = 'Agarrá una mancuerna con cada brazo y apoyá los brazos superiores sobre el banco predicador o el banco inclinado.\nMantené las mancuernas a la altura de los hombros como posición inicial.\nMientras inhalás, bajá lentamente las mancuernas hasta que el brazo superior esté extendido y el bíceps completamente estirado.\nMientras exhalás, usá los bíceps para subir los pesos hasta que el bíceps esté completamente contraído y las mancuernas estén a la altura de los hombros.\nApretá fuerte los bíceps durante un segundo en la posición contraída y repetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Two-Arm Dumbbell Preacher Curl';
UPDATE public.exercises SET instructions_es = 'Colocá dos kettlebells entre tus pies.\nEmpujá la cadera hacia atrás y mirá al frente.\nLlevá los kettlebells a los hombros extendiendo piernas y cadera mientras los subís.\nGirá las muñecas al hacerlo.\nBajá los kettlebells a la posición inicial y repetí.' WHERE name_en = 'Two-Arm Kettlebell Clean';
UPDATE public.exercises SET instructions_es = 'Recostá las mancuernas rusas sobre tus hombros.\nEmpujá las mancuernas hacia arriba extendiendo las piernas y la cadera mientras las balanceás hacia los hombros.\nGirá las muñecas para que las palmas queden mirando hacia adelante.\nAgachate unos centímetros y revertí el movimiento rápidamente impulsando ambas mancuernas por encima de la cabeza.\nInmediatamente después del empujón inicial, agachate de nuevo y metete debajo de las mancuernas.\nMantené las mancuernas bloqueadas y parate erguido para completar el ejercicio.' WHERE name_en = 'Two-Arm Kettlebell Jerk';
UPDATE public.exercises SET instructions_es = 'Recostá los kettlebells sobre tus hombros.\nEmpujá los kettlebells hacia arriba y hacia afuera.\nMantené la contracción de tus dorsales, glúteos y abdomen para mayor estabilidad.' WHERE name_en = 'Two-Arm Kettlebell Military Press';
UPDATE public.exercises SET instructions_es = 'Colocá dos kettlebells frente a tus pies.\nDoblá levemente las rodillas y empujá la cadera hacia atrás mientras te agachás para tomar la posición inicial.\nAgarrá ambos kettlebells y jálalos hacia el estómago, retraé los omóplatos y flexioná los codos.\nMantené la espalda recta.\nBajá y repetí.' WHERE name_en = 'Two-Arm Kettlebell Row';
UPDATE public.exercises SET instructions_es = 'Sentate en la máquina de jalón con la barra ancha en el polea superior.\nAjustá el cojín de rodillas a tu altura para que tu cuerpo no se eleve con la resistencia.\nAgarrá la barra con las palmas mirando hacia tu torso y las manos más cerca que el ancho de los hombros.\nExtendé ambos brazos hacia adelante y llevá el torso hacia atrás unos 30 grados, curvando la zona lumbar y sacando el pecho.\nExhalá y jalá la barra hasta que toque el pecho superior, llevando los hombros y los brazos superiores hacia abajo y atrás.\nConcentrate en apretar los músculos de la espalda al llegar a la posición de máxima contracción y mantené los codos pegados al cuerpo.\nMantené el torso superior inmóvil y mové solo los brazos, usando los antebrazos únicamente para sostener la barra.\nEsperá un segundo en la posición contraída y, inhalando, volvé lentamente a la posición inicial con los brazos completamente extendidos.\nRepetí este movimiento por la cantidad de repeticiones indicadas.' WHERE name_en = 'Underhand Cable Pulldowns';
UPDATE public.exercises SET instructions_es = 'Recostá tu pecho hacia las rodillas con las piernas extendidas y las rodillas juntas.\nMantené el abrazo de tus muslos desde abajo con ambos brazos.\nEmpujá tu espalda media hacia atrás, alejándola de las rodillas, para estirar la zona lumbar.' WHERE name_en = 'Upper Back-Leg Grab';
UPDATE public.exercises SET instructions_es = 'Entrelazá los dedos con los pulgares hacia abajo.\nRedondeá los hombros mientras extendés las manos hacia adelante.' WHERE name_en = 'Upper Back Stretch';
UPDATE public.exercises SET instructions_es = 'Agarrá la barra con un agarre prono ligeramente más angosto que el ancho de tus hombros.\nDejá que la barra descanse sobre la parte superior de tus muslos con los brazos extendidos y una leve flexión en los codos.\nMantené la espalda recta.\nExhalá y usá los lados de tus hombros para levantar la barra, subiendo los codos hacia arriba y hacia los lados.\nMantené la barra cerca del cuerpo mientras la subís.\nContinuá levantando la barra hasta que casi toque tu barbilla.\nAsegurate de que tus codos impulsen el movimiento y estén siempre más altos que tus antebrazos.\nMantené el torso inmóvil y hacé una pausa de un segundo en la parte superior del movimiento.\nBajá la barra lentamente de vuelta a la posición inicial.\nInhalá mientras realizás esta parte del movimiento.\nRepetí por la cantidad de repeticiones recomendadas.' WHERE name_en = 'Upright Barbell Row';
UPDATE public.exercises SET instructions_es = 'Agarrá la barra recta del cable bajo con un agarre prono (palmas hacia los muslos) ligeramente más angosto que el ancho de los hombros.\nDejá que la barra descanse sobre tus muslos, con los brazos extendidos, una leve flexión en los codos y la espalda recta.\nExhalá y usá los hombros laterales para levantar la barra manteniéndola pegada al cuerpo.\nSubí la barra hasta que casi toque tu mentón, asegurándote de que los codos guíen el movimiento y se mantengan siempre por encima de los antebrazos.\nMantené el torso quieto y hacé una pausa de un segundo en la posición superior.\nExhalá y bajá la barra lentamente hasta la posición inicial.\nRepetí el movimiento la cantidad de repeticiones recomendadas.' WHERE name_en = 'Upright Cable Row';
UPDATE public.exercises SET instructions_es = 'Pará sobre la banda de ejercicio para generar tensión a la altura de los brazos.\nAgarrá los mangos con las palmas hacia los muslos, en una posición ligeramente más angosta que el ancho de los hombros.\nDejá que los mangos descansen sobre tus muslos.\nExtendé los brazos con una leve flexión en los codos y mantené la espalda recta.\nSubí los mangos usando los hombros laterales mientras exhalás.\nMantené los mangos cerca del cuerpo al subirlos.\nLlevá los mangos hasta que casi toquen tu barbilla.\nDejá que los codos impulsen el movimiento, manteniéndolos siempre más altos que los antebrazos.\nMantené el torso inmóvil y hacé una pausa de un segundo en la parte superior.\nBajá los mangos lentamente hasta la posición inicial.\nInhalá mientras realizás esta parte del movimiento.\nRepetí por la cantidad de repeticiones recomendadas.' WHERE name_en = 'Upright Row - With Bands';
UPDATE public.exercises SET instructions_es = 'Extendé ambos brazos rectos sobre tu cabeza, con las palmas tocándose.\nEmpujá lentamente tus manos hacia arriba y hacia atrás, manteniendo la espalda recta.' WHERE name_en = 'Upward Stretch';
UPDATE public.exercises SET instructions_es = 'Sentate en la máquina de jalón con la barra en V conectada al polea superior.\nAjustá el cojín de rodillas a tu altura para que tu cuerpo no se eleve con la resistencia.\nAgarrá la barra en V con las palmas mirándose (agarre neutro), sacá el pecho y recostate ligeramente hacia atrás (unos 30 grados) para activar mejor los dorsales.\nJalá la barra hacia abajo usando los dorsales y apretá las escápulas hasta que el pecho casi toque la barra, exhalando durante el movimiento.\nMantené la posición contraída un segundo y volvé lentamente a la posición inicial inhalando.\nRepetí el movimiento la cantidad de veces indicada.' WHERE name_en = 'V-Bar Pulldown';
UPDATE public.exercises SET instructions_es = 'Colocá el centro de la barra en V en el medio de la barra de dominadas.\nAsegurate de que los agarres queden hacia abajo para colgarte de la barra.\nAgarrá la barra por cada lado y colgate de ella.\nSacá el pecho y incliná el cuerpo hacia atrás para activar mejor los dorsales.\nUsando los dorsales, subí el torso mientras inclinás la cabeza hacia atrás para no golpearte con la barra.\nContinuá hasta que el pecho casi toque la barra en V.\nExhalá mientras realizás este movimiento.\nMantené la posición contraída durante un segundo.\nBajá el cuerpo lentamente hasta la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones indicadas.' WHERE name_en = 'V-Bar Pullup';
UPDATE public.exercises SET instructions_es = 'Dejá caer la mancuerna a la altura de tus brazos entre las piernas, sosteniéndola con ambas manos.\nMantené la espalda recta y la cabeza en alto.\nBalanzá la mancuerna entre las piernas, flexionando las caderas y doblando las rodillas ligeramente.\nInvertí el movimiento con potencia extendiendo las caderas, rodillas y tobillos para impulsarte hacia arriba, balanceando la mancuerna sobre la cabeza.\nAl aterrizar, absorbé el impacto a través de las piernas y llevá la mancuerna hacia el torso antes de la siguiente repetición.' WHERE name_en = 'Vertical Swing';
UPDATE public.exercises SET instructions_es = 'Subí a la cinta y elegí la opción deseada del menú.\nSeleccioná el ajuste manual o un programa de carrera.\nIngresá tu edad y peso para estimar las calorías quemadas.\nAjustá la elevación para cambiar la intensidad del entrenamiento.\nCaminá a un ritmo moderado o rápido, no a paso lento.\nMantené una postura adecuada mientras caminás.\nAguantá los apoyos solo cuando sea necesario, como al bajar o al revisar tu frecuencia cardíaca.' WHERE name_en = 'Walking, Treadmill';
UPDATE public.exercises SET instructions_es = 'Recostá sobre una pelota de ejercicio con el torso apoyado contra la pelota y paralelo al suelo.\nApoyá la punta de los pies en el piso para mantener el equilibrio.\nColocá una placa de peso bajo la barbilla o detrás del cuello.\nElevá lentamente el torso flexionando la cintura y la zona lumbar.\nExhalá durante este movimiento.\nMantené la contracción en la zona lumbar durante un segundo.\nBajá el torso de vuelta a la posición inicial inhalando.\nRepetí la cantidad de repeticiones indicadas en tu programa.' WHERE name_en = 'Weighted Ball Hyperextension';
UPDATE public.exercises SET instructions_es = 'Recostá el costado izquierdo del torso (cintura, caderas y hombro) contra la pelota de ejercicio.\nApoyá los pies en el suelo con las piernas cruzadas y colgando de la pelota.\nSujetá una placa de peso con la mano derecha justo al lado derecho de la cabeza, asegurándote de que el lado liso descanse contra ella.\nColocá el brazo izquierdo sobre el torso con la palma en los oblicuos, formando un ángulo recto entre el antebrazo y el brazo superior.\nLevantá el costado del torso flexionando lateralmente la cintura mientras exhalás.\nMantené la contracción por un segundo y bajá lentamente a la posición inicial mientras inhalás.\nRepetí la cantidad de repeticiones recomendadas.\nCambió de lado y repetí el ejercicio.' WHERE name_en = 'Weighted Ball Side Bend';
UPDATE public.exercises SET instructions_es = 'Colocá un banco detrás de tu espalda y otro frente a vos, con ambos perpendiculares a tu cuerpo.\nAsegurate de un banco por el borde, con las manos cerca del cuerpo y separadas a la anchura de los hombros.\nExtendé completamente los brazos.\nExtendé las piernas hacia adelante sobre el otro banco, manteniéndolas paralelas al suelo.\nMantené el torso perpendicular al suelo.\nPedile a tu compañero que coloque la mancuerna sobre tu regazo.\nIncliná el cuerpo hacia abajo lentamente mientras inhalás, flexionando los codos.\nBajate hasta que el ángulo entre el brazo superior y el antebrazo sea ligeramente menor a 90 grados.\nMantené los codos lo más cerca posible del cuerpo durante todo el movimiento.\nMantené los antebrazos apuntando siempre hacia abajo.\nEmpujá con los tríceps para subir el torso y volver a la posición inicial mientras exhalás.\nRepetí el movimiento la cantidad de veces recomendada.' WHERE name_en = 'Weighted Bench Dip';
UPDATE public.exercises SET instructions_es = 'Recostá boca arriba con los pies apoyados en el suelo o en un banco, con las rodillas flexionadas a 90 grados.\nSujetá un peso contra el pecho o mantenelo extendido sobre el torso como posición inicial.\nExhalá y empujá lentamente los hombros hacia arriba hasta que se eleven unos 10 centímetros del suelo, manteniendo la zona lumbar apoyada.\nEn la parte superior del movimiento, contraé los abdominales y mantené la posición por un breve instante.\nInhalá y bajá lentamente hasta volver a la posición inicial.' WHERE name_en = 'Weighted Crunches';
UPDATE public.exercises SET instructions_es = 'Colocá una barra con carga ligera sobre la parte trasera de tus hombros.\nPodés usar también un chaleco con peso, una bolsa de arena u otro tipo de resistencia.\nAsegurate de que el peso sea lo suficientemente ligero como para no frenarte significativamente.\nSepará los pies apenas más allá del ancho de tus hombros y mantené la cabeza y el pecho erguidos.\nEsta será tu posición inicial.\nUsando un movimiento contrapuesto, bajá parcialmente en sentadilla y revertí la dirección de inmediato para explotar desde el suelo.\nExtendé a través de las caderas, rodillas y tobillos.\nMantené una buena postura durante todo el salto.\nAl regresar al suelo, absorbé el impacto a través de tus piernas.' WHERE name_en = 'Weighted Jump Squat';
UPDATE public.exercises SET instructions_es = 'Ajustá un peso a un cinturón de dips y aseguralo alrededor de tu cintura.\nAgarrá la barra de dominadas con las palmas de las manos hacia adelante.\nPara un agarre medio, separá las manos a la anchura de los hombros.\nExtendé ambos brazos frente a vos sosteniendo la barra con el agarre elegido.\nLlevá el torso hacia atrás unos 30 grados creando una curvatura en la zona lumbar y sacando el pecho.\nEsta será tu posición inicial.\nExhalá y subí el torso hasta que tu cabeza quede por encima de las manos.\nConcentrate en apretar las escápulas hacia atrás y hacia abajo al llegar a la posición contráctil superior.\nDespués de un breve momento en la posición contráctil superior, inhalá y bajá lentamente el torso a la posición inicial con los brazos extendidos y los dorsales completamente estirados.' WHERE name_en = 'Weighted Pull Ups';
UPDATE public.exercises SET instructions_es = 'Pará de pie con los pies separados al ancho de los hombros y las puntas de los pies hacia arriba.\nSujetá los postes de la rack con una mano y mantené una placa sobre el pecho con el brazo opuesto.\nDoblá las rodillas y bajá el torso lentamente hacia el suelo llevando la pelvis y las rodillas hacia adelante.\nInspirá mientras bajás y detenete cuando las piernas formen casi un ángulo de 90 grados.\nMantené la posición de estiramiento durante un segundo.\nUsá los músculos de los muslos para volver al punto de partida.\nExpirá mientras subís.\nRepetí la cantidad de veces recomendada.' WHERE name_en = 'Weighted Sissy Squat';
UPDATE public.exercises SET instructions_es = 'Ajustá las bandas alrededor de la base del banco declinado.\nColocá las empuñaduras hacia el interior del banco para que puedas alcanzarlas con ambas manos al recostarte.\nPasá las piernas por la máquina declinada hasta asegurarlas.\nAlcanzá las bandas de ejercicio con ambas manos.\nAgarrá las empuñaduras con una agarre prono (palmas hacia adelante).\nPosicionálas cerca de la clavícula y rotá las muñecas hacia un agarre neutro (palmas hacia el torso).\nMantené los brazos estacionarios durante todo el ejercicio.\nEmpujá el torso hacia arriba hasta que el cuerpo superior quede perpendicular al suelo mientras exhalás.\nMantené la contracción por un segundo.\nBajá el cuerpo superior de vuelta a la posición inicial mientras inhalás.\nRepetí por la cantidad de repeticiones recomendadas.' WHERE name_en = 'Weighted Sit-Ups - With Bands';
UPDATE public.exercises SET instructions_es = 'Colocá dos bancos planos separados por el ancho de los hombros.\nPará sobre ellos y ajustate el cinturón de peso en la cintura con la carga que te resulte cómoda.\nAsegurate de que los dedos de los pies apunten hacia afuera.\nMantené el cuerpo erguido con el peso colgando entre las piernas y extendé los brazos completamente a los lados del cuerpo.\nDoblá las rodillas manteniendo la postura recta y la cabeza en alto.\nBajá hasta que el ángulo entre el muslo y la pantorrilla sea ligeramente menor a 90 grados, con los muslos por debajo de la paralela al suelo.\nInspirá mientras realizás esta parte del movimiento.\nEmpujá el suelo del banco con la punta de los pies para subir el cuerpo y estirar las piernas de vuelta a la posición inicial.\nExpirá mientras realizás esta parte del ejercicio.\nRepetí la cantidad de repeticiones recomendadas.' WHERE name_en = 'Weighted Squat';
UPDATE public.exercises SET instructions_es = 'Recostate en un banco plano con los pies firmes en el suelo.\nAgarrá la barra con una toma amplia y prona (palmas hacia adelante), aproximadamente 3 pulgadas más allá del ancho de hombros por cada mano.\nLevantá la barra del soporte y mantenela recta sobre vos con los brazos bloqueados, asegurándote de que la barra sea perpendicular al torso y al suelo.\nInspirá y bajá la barra lentamente hasta sentirla en el pecho medio.\nHacé una pausa de un segundo y empujá la barra de vuelta a la posición inicial mientras exhalás, usando los músculos del pecho.\nBloqueá los brazos y apretá el pecho en la posición contraída, mantené un segundo y empezá a bajar lentamente de nuevo.\nRecordá que la bajada debe tomar al menos el doble de tiempo que la subida.\nRepetí el movimiento por la cantidad de repeticiones indicadas.' WHERE name_en = 'Wide-Grip Barbell Bench Press';
UPDATE public.exercises SET instructions_es = 'Recostá en un banco declinado con los pies firmemente asegurados en la parte frontal.\nAgarrá la barra con las palmas hacia adelante, aproximadamente 3 pulgadas más ancho que el ancho de tus hombros.\nLevantá la barra del soporte y mantené los brazos extendidos directamente sobre tu cuerpo.\nAsegurate de que la barra quede perpendicular al torso y al suelo.\nInspirá y bajá la barra lentamente hasta que sientas el contacto en la parte inferior del pecho.\nHacé una pausa de un segundo.\nExpirá y empujá la barra de vuelta a la posición inicial usando los músculos del pecho.\nBloqueá los brazos y contraé el pecho en la posición final.\nMantené la contracción por un segundo.\nBajá la barra nuevamente de forma lenta, asegurándote de que el descenso tome al menos el doble de tiempo que la subida.\nRepetí el movimiento por la cantidad de repeticiones indicadas.' WHERE name_en = 'Wide-Grip Decline Barbell Bench Press';
UPDATE public.exercises SET instructions_es = 'Recostá en la banca declinada y asegurá bien las piernas.\nAgarrá la barra detrás de la cabeza con las palmas hacia afuera y más ancho que los hombros.\nLevantá la barra desde el suelo usando los brazos hasta que estén completamente extendidos y perpendiculares al piso.\nBajá la barra en un movimiento semicircular hasta que los brazos queden paralelos al piso, manteniéndolos siempre extendidos y moviendo solo la articulación del hombro.\nInhala mientras realizás esta parte del movimiento.\nSubí la barra mientras exhalás hasta volver a la posición inicial, controlando la barra en todo momento.\nRepetí el movimiento la cantidad de repeticiones indicadas en tu programa.\nAl terminar la serie, bajá la barra lentamente hasta la altura de la cabeza y soltala.' WHERE name_en = 'Wide-Grip Decline Barbell Pullover';
UPDATE public.exercises SET instructions_es = 'Sentate en la máquina de jalón con la barra ancha en la polea superior.\nAjustá el cojín de rodillas a tu altura para que tu cuerpo no se levante con la resistencia.\nAgarrá la barra con las palmas hacia adelante usando el agarre indicado.\nPara un agarre ancho, separá las manos más que el ancho de tus hombros.\nPara un agarre medio, separá las manos a la misma distancia que tus hombros.\nPara un agarre cerrado, separá las manos menos que el ancho de tus hombros.\nExtendé ambos brazos hacia adelante sosteniendo la barra en el ancho elegido.\nIncliná el torso hacia atrás unos 30 grados, curvando la zona lumbar y sacando el pecho.\nExhalá y bajá la barra hasta que toque el pecho superior, llevando los hombros y los brazos superiores hacia abajo y atrás.\nConcentrate en apretar los músculos de la espalda al llegar a la posición de máxima contracción.\nMantené el torso superior inmóvil y mové solo los brazos.\nEvitá usar los antebrazos para tirar de la barra; su única función es sostenerla.\nMantené la posición contraída un segundo apretando las escápulas entre sí.\nExhalá y subí lentamente la barra hasta la posición inicial con los brazos completamente extendidos y los dorsales estirados.\nRepetí este movimiento la cantidad de repeticiones indicadas.' WHERE name_en = 'Wide-Grip Lat Pulldown';
UPDATE public.exercises SET instructions_es = 'Sentate en la máquina de jalón al pecho con barra ancha y ajustá el reposapiés a tu altura para que no te levante la resistencia.\nAgarrá la barra con las palmas hacia adelante usando el agarre indicado: ancho (más que el ancho de hombros), medio (igual al ancho de hombros) o cerrado (menos que el ancho de hombros).\nExtendé ambos brazos hacia adelante sosteniendo la barra y llevá el torso y la cabeza hacia adelante, imaginando una línea desde el centro de la barra hasta la nuca.\nExhalá y bajá la barra hasta que toque la nuca, llevando los hombros y los brazos superiores hacia abajo y atrás, concentrándote en apretar los músculos de la espalda en la posición máxima de contracción.\nMantené el torso superior inmóvil y usá solo los brazos para el movimiento, evitando que los antebrazos hagan fuerza para bajar la barra.\nMantené la posición contraída un segundo apretando las escápulas y luego inhalá mientras subís la barra lentamente hasta que los brazos estén completamente extendidos y los dorsales estirados.\nRepetí el movimiento la cantidad de repeticiones indicadas.' WHERE name_en = 'Wide-Grip Pulldown Behind The Neck';
UPDATE public.exercises SET instructions_es = 'Agarrá la barra de dominadas con las palmas hacia adelante usando un agarre ancho.\nCon los brazos extendidos hacia adelante sosteniendo la barra, llevá el torso y la cabeza hacia adelante hasta que haya una línea imaginaria desde la barra hasta la parte posterior de tu cuello.\nSubí el torso hasta que la barra quede cerca de la parte posterior de tu cuello.\nPara lograrlo, bajá y llevá los hombros y los brazos superiores hacia atrás mientras inclinás ligeramente la cabeza hacia adelante.\nExhalá mientras realizás esta parte del movimiento.\nConcentrate en apretar los músculos de la espalda una vez que alcances la posición completamente contraída.\nMantené el torso superior estacionario mientras se mueve en el espacio y asegurá de que solo se muevan los brazos.\nDejá que los antebrazos no hagan ningún otro trabajo más que sostener la barra.\nDespués de un segundo en la posición contraída, empezá a inhalar y bajá lentamente el torso hasta la posición inicial cuando los brazos estén completamente extendidos y los dorsales estén completamente estirados.\nRepetí este movimiento por la cantidad de repeticiones prescritas.' WHERE name_en = 'Wide-Grip Rear Pull-Up';
UPDATE public.exercises SET instructions_es = 'Parate de pie con el torso erguido sosteniendo la barra en el agarre ancho externo.\nMantené las palmas de las manos hacia adelante y los codos pegados al torso.\nMantené los brazos superiores fijos y doblá los antebrazos hacia adelante contrayendo los bíceps mientras exhalás.\nLlevá la barra hasta la altura de los hombros hasta que los bíceps estén completamente contraídos.\nMantené la posición contraída por un segundo y apretá fuerte los bíceps.\nBajá la barra lentamente hasta la posición inicial mientras inhalás.\nRepetí el movimiento la cantidad de veces recomendadas.' WHERE name_en = 'Wide-Grip Standing Barbell Curl';
UPDATE public.exercises SET instructions_es = 'Ajustá la barra en el rack a la altura de tus hombros.\nColocá la barra sobre la parte posterior de tus hombros, justo debajo del cuello.\nApoyá ambas manos en la barra y despegala del rack empujando con las piernas mientras enderezás el torso.\nDale un paso hacia atrás y separá las piernas más que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera.\nMantené la cabeza en alto y la espalda recta.\nIncliná las rodillas para bajar la barra lentamente, manteniendo la postura erguida y la cabeza arriba.\nBajá hasta que el ángulo entre el muslo y la pantorrilla sea ligeramente menor a 90 grados.\nInspirá durante la bajada.\nVerificá que las rodillas no pasen la línea imaginaria de las puntas de los pies.\nEmpujá el suelo con los talones para subir la barra mientras enderezás las piernas.\nExpirá durante la subida.\nRepetí el movimiento la cantidad de veces indicada.' WHERE name_en = 'Wide Stance Barbell Squat';
UPDATE public.exercises SET instructions_es = 'Recostá la barra cargada en el suelo.\nAdoptá una postura amplia y doblá las caderas para agarrar la barra.\nLlevá las caderas lo más atrás posible y mantené las piernas casi rectas.\nMantené la espalda recta y la cabeza y el pecho arriba.\nIniciá el movimiento activando las caderas y empujándolas hacia adelante.\nDejá que los brazos cuelguen rectos mientras subís.\nContinuá hasta quedarte de pie completamente recto.\nRegresá lentamente el peso a la posición inicial.\nPara las repeticiones siguientes, no necesitás que el peso toque el suelo.' WHERE name_en = 'Wide Stance Stiff Legs';
UPDATE public.exercises SET instructions_es = 'Colgate de la barra de dominadas con agarre prono, manteniendo brazos y piernas extendidos.\nLevantá rápidamente una rodilla lo más alto que puedas sin balancear el cuerpo ni las piernas.\nInvertí el movimiento de inmediato, volviendo esa pierna a la posición inicial y levantando simultáneamente la rodilla opuesta lo más alto posible.\nSeguí alternando entre las piernas hasta completar la serie.' WHERE name_en = 'Wind Sprints';
UPDATE public.exercises SET instructions_es = 'Recostá boca arriba con los brazos extendidos a los lados y las piernas estiradas.\nLevantá una pierna y cruzala rápidamente sobre el cuerpo, intentando tocar el suelo cerca de la mano opuesta.\nVolvé a la posición inicial y repetí con la pierna contraria, alternando durante 10 a 20 repeticiones.' WHERE name_en = 'Windmills';
UPDATE public.exercises SET instructions_es = 'Dát un paso adelante con el pie delantero plano y el trasero apoyado en las puntas.\nAgachate con las rodillas flexionadas hasta que la rodilla casi toque el suelo.\nMantené el torso erguido y sostené esta posición durante 10 a 20 segundos.\nApoyá el brazo del mismo lado que la pierna delantera en el suelo, con el codo junto al pie.\nColocá la otra mano en el suelo, paralela a la pierna delantera, para ayudarte a sostenerte.\nDespués de 10 a 20 segundos, apoyá las manos a ambos lados del pie delantero.\nLevantá las puntas del pie delantero del suelo y estirá la pierna.\nReubicá la pierna trasera si es necesario para lograr la extensión.\nMantené esta posición durante 10 a 20 segundos y repetí toda la secuencia con el otro lado.' WHERE name_en = 'World''s Greatest Stretch';
UPDATE public.exercises SET instructions_es = 'Pará de pie con los pies separados a la anchura de los hombros.\nElevá los brazos a los lados hasta que queden completamente extendidos y paralelos al suelo, a la altura de los hombros.\nAsegurate de que el torso y los brazos formen una letra "T" y que las palmas miren hacia abajo.\nMantené el cuerpo quieto y girá las muñecas hacia adelante en un movimiento circular.\nImaginá que estás dibujando círculos usando las manos como pinceles.\nRespirá de forma normal mientras realizás el ejercicio.\nRepetí la cantidad de veces recomendada.' WHERE name_en = 'Wrist Circles';
UPDATE public.exercises SET instructions_es = 'Pará de pie con los pies separados al ancho de los hombros y agarrá el rodillo con las palmas hacia abajo.\nLevantá ambos brazos lentamente hasta que queden extendidos y paralelos al suelo, manteniendo el resto del cuerpo quieto.\nGirá una muñeca a la vez hacia arriba para subir el peso enrollando la cuerda en el rodillo.\nBajá el peso lentamente girando la muñeca hacia abajo hasta volver a la posición inicial.\nRepetí el movimiento la cantidad de veces indicada en tu programa.' WHERE name_en = 'Wrist Roller';
UPDATE public.exercises SET instructions_es = 'Sujetá la barra con ambas manos, palmas hacia abajo, separadas a la anchura de los hombros.\nExtendé la muñeca como si estuvieras enrollando un periódico, alternando entre cada mano.\nSeguí alternando el movimiento hasta el fallo.\nFlexioná la muñeca en la dirección opuesta para revertir el movimiento.\nContinuá alternando hasta el fallo.' WHERE name_en = 'Wrist Rotations with Straight Bar';
UPDATE public.exercises SET instructions_es = 'Colocá el yugo sobre la parte posterior de los hombros.\nMirá hacia adelante y arqueá la espalda.\nEmpujá a través de los talones para levantar el yugo.\nCaminá lo más rápido posible usando pasos cortos y rápidos.\nPodés sostener los postes laterales del yugo para estabilizarlo y mantenerlo en su posición.\nContinuá a la máxima velocidad durante la distancia indicada, generalmente de 75 a 100 pies.' WHERE name_en = 'Yoke Walk';
UPDATE public.exercises SET instructions_es = 'Colocá la barra en un soporte a la altura del pecho o ligeramente por encima de la cintura.\nCruzá los brazos y apoyá la barra sobre las partes superiores de los antebrazos.\nAlejate del soporte y separá las piernas a la anchura de los hombros con los pies ligeramente hacia afuera.\nMantené la cabeza erguida y la espalda recta.\nIncliná la cadera hacia atrás y doblá las rodillas para bajar la barra hasta que los muslos queden por debajo de la paralela al suelo.\nExhalá y empujá el suelo con la parte delantera de los pies para extender las piernas y volver a la posición inicial.\nRepetí el movimiento la cantidad de veces indicada.' WHERE name_en = 'Zercher Squats';
UPDATE public.exercises SET instructions_es = 'Parate con el torso recto y una mancuerna en cada mano, sostenidas a la altura de los hombros con los codos pegados al cuerpo.\nAsegurate de que las palmas de las manos se miren entre sí; esta es tu posición inicial.\nMientras mantenés el brazo superior quieto, flexioná los antebrazos hacia arriba contrayendo los bíceps y exhalando.\nMové solo los antebrazos y rotá la muñeca para pasar a un agarre supinado (palmas hacia arriba) hasta que los bíceps estén completamente contraídos y las mancuernas lleguen a la altura de los hombros.\nMantené la posición contraída durante un segundo apretando los bíceps.\nAhora, en la posición contraída, rotá la muñeca hasta tener un agarre pronado (palmas hacia abajo) con el pulgar más alto que el meñique.\nBajá lentamente las mancuernas manteniendo el agarre pronado.\nCuando las mancuernas estén cerca de los muslos, rotá la muñeca para volver a un agarre neutro (palmas hacia el cuerpo).\nRepetí el movimiento la cantidad de veces recomendada.' WHERE name_en = 'Zottman Curl';
UPDATE public.exercises SET instructions_es = 'Agarrá una mancuerna en cada mano y apoyá los brazos superiores sobre el banco predicador o el banco inclinado.\nMantené las mancuernas a la altura de los hombros con los codos flexionados y las palmas hacia abajo.\nMientras inhalás, bajá lentamente las mancuernas manteniendo las palmas hacia abajo hasta que el brazo superior esté extendido y el bíceps completamente estirado.\nAl llegar al punto más bajo, rotá las muñecas para que las palmas queden mirando hacia arriba.\nMientras exhalás, usá los bíceps para subir los pesos hasta que estén completamente contraídos y a la altura de los hombros.\nLlevá el dedo meñique más alto que el pulgar para asegurar la contracción completa.\nApretá fuerte los bíceps durante un segundo en la posición contraída y rotá las muñecas para que las palmas vuelvan a mirar hacia abajo.\nRepetí el movimiento la cantidad de repeticiones recomendadas.' WHERE name_en = 'Zottman Preacher Curl';
